fn linux_hot_shadow_values(
    element: &crate::ast::ViewElement,
    signatures: &Signatures,
) -> Option<(String, i64, i64, i64)> {
    let color = match view_property(element, "shadow_color") {
        Some(property) => static_expr_str(&property.value, signatures)?,
        None => "shadow".to_string(),
    };
    if !valid_ui_color(&color) {
        return None;
    }
    let color = gtk_ui_color_css(&color)
        .unwrap_or(color.as_str())
        .to_string();
    let blur = match view_property(element, "shadow_blur") {
        Some(property) => static_expr_i64(&property.value, signatures)?,
        None => 0,
    };
    let offset_x = match view_property(element, "shadow_offset_x") {
        Some(property) => static_expr_i64(&property.value, signatures)?,
        None => 0,
    };
    let offset_y = match view_property(element, "shadow_offset_y") {
        Some(property) => static_expr_i64(&property.value, signatures)?,
        None => 0,
    };
    if !(0..=i64::from(i32::MAX)).contains(&blur)
        || !(i64::from(i32::MIN)..=i64::from(i32::MAX)).contains(&offset_x)
        || !(i64::from(i32::MIN)..=i64::from(i32::MAX)).contains(&offset_y)
    {
        return None;
    }
    Some((color, blur, offset_x, offset_y))
}

fn view_layout_transition_duration(
    view: &crate::ast::ViewDef,
    signatures: &Signatures,
) -> Result<Option<i64>, Diagnostic> {
    let mut duration = None;
    for element in &view.elements {
        let Some(value) =
            static_non_negative_style_i64(element, "layout_transition_ms", signatures)?
        else {
            continue;
        };
        if let Some(existing) = duration
            && existing != value
        {
            let span = view_property(element, "layout_transition_ms")
                .expect("layout transition value exists")
                .value
                .span;
            return Err(diag(
                span,
                "layoutTransitionMs must use one duration per view so native layout reflow stays deterministic across platforms",
            ));
        }
        duration = Some(value);
    }
    if duration.is_some() {
        for element in &view.elements {
            let Some(visible) = view_property(element, "visible") else {
                continue;
            };
            if static_expr_bool(&visible.value, signatures).is_none()
                && view_property(element, "layout_transition_ms").is_none()
            {
                return Err(
                    diag(
                        visible.name_span,
                        "state-driven visible elements must declare layoutTransitionMs when their view enables layout transitions",
                    )
                    .with_note(
                        "Android applies native layout reflow animation at the flat root grid; requiring every dynamic visibility participant to opt in prevents unrelated elements from being animated implicitly",
                    ),
                );
            }
        }
    }
    Ok(duration)
}

fn fold_ui_primitive_expr(
    expr: &Expr,
    signatures: &Signatures,
) -> Result<Option<ConstantValue>, Diagnostic> {
    match &expr.kind {
        ExprKind::Var(name) => {
            if let Some(value) = typecheck::semantic_ui_i64_token(name) {
                Ok(Some(ConstantValue::I64(value)))
            } else {
                fold_primitive_expr(expr, &HashMap::new(), signatures)
            }
        }
        ExprKind::Unary { op, expr: inner } => {
            let Some(inner) = fold_ui_primitive_expr(inner, signatures)? else {
                return Ok(None);
            };
            Ok(Some(match (op, inner) {
                (UnaryOp::Neg, ConstantValue::I64(value)) => {
                    ConstantValue::I64(value.checked_neg().ok_or_else(|| {
                        diag(expr.span, "constant integer negation overflows i64")
                    })?)
                }
                (UnaryOp::Not, ConstantValue::Bool(value)) => ConstantValue::Bool(!value),
                _ => return Ok(None),
            }))
        }
        ExprKind::Binary { left, op, right } => {
            let Some(left) = fold_ui_primitive_expr(left, signatures)? else {
                return Ok(None);
            };
            if matches!(op, BinOp::And) && left == ConstantValue::Bool(false) {
                return Ok(Some(ConstantValue::Bool(false)));
            }
            if matches!(op, BinOp::Or) && left == ConstantValue::Bool(true) {
                return Ok(Some(ConstantValue::Bool(true)));
            }
            let Some(right) = fold_ui_primitive_expr(right, signatures)? else {
                return Ok(None);
            };
            Ok(Some(fold_primitive_binary(expr.span, *op, left, right)?))
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            let Some(condition) = fold_ui_primitive_expr(cond, signatures)? else {
                return Ok(None);
            };
            match condition {
                ConstantValue::Bool(true) => fold_ui_primitive_expr(then_expr, signatures),
                ConstantValue::Bool(false) => fold_ui_primitive_expr(else_expr, signatures),
                _ => Ok(None),
            }
        }
        _ => fold_primitive_expr(expr, &HashMap::new(), signatures),
    }
}

fn static_expr_i64(expr: &Expr, signatures: &Signatures) -> Option<i64> {
    match fold_ui_primitive_expr(expr, signatures).ok().flatten()? {
        ConstantValue::I64(value) => Some(value),
        _ => None,
    }
}

fn static_expr_str(expr: &Expr, signatures: &Signatures) -> Option<String> {
    match fold_primitive_expr(expr, &HashMap::new(), signatures)
        .ok()
        .flatten()?
    {
        ConstantValue::Str(value) => Some(value),
        _ => None,
    }
}

fn static_string_list(
    expr: &Expr,
    signatures: &Signatures,
    subject: &str,
) -> Result<Vec<String>, Diagnostic> {
    let ExprKind::List(values) = &expr.kind else {
        return Err(diag(
            expr.span,
            &format!("{subject} must be a compile-time list literal of string values"),
        ));
    };
    if values.is_empty() {
        return Err(diag(
            expr.span,
            &format!("{subject} must contain at least one label"),
        ));
    }
    let mut labels = Vec::with_capacity(values.len());
    for value in values {
        let Some(label) = static_expr_str(value, signatures) else {
            return Err(diag(
                value.span,
                &format!("{subject} must be a compile-time list of string values"),
            ));
        };
        if label.is_empty() {
            return Err(diag(
                value.span,
                &format!("{subject} labels must not be empty"),
            ));
        }
        labels.push(label);
    }
    Ok(labels)
}

fn static_context_menu_items(
    element: &crate::ast::ViewElement,
    signatures: &Signatures,
) -> Result<Option<Vec<String>>, Diagnostic> {
    let Some(property) = view_property(element, "context_menu_items") else {
        return Ok(None);
    };
    let ExprKind::List(values) = &property.value.kind else {
        return Err(diag(
            property.value.span,
            "contextMenuItems must be a compile-time list literal of string values",
        ));
    };
    if values.is_empty() {
        return Err(diag(
            property.value.span,
            "contextMenuItems must contain at least one menu label",
        ));
    }
    let mut labels = Vec::with_capacity(values.len());
    for value in values {
        let Some(label) = static_expr_str(value, signatures) else {
            return Err(diag(
                value.span,
                "contextMenuItems must be a compile-time list of string values",
            ));
        };
        if label.is_empty() {
            return Err(diag(
                value.span,
                "contextMenuItems labels must not be empty",
            ));
        }
        labels.push(label);
    }
    Ok(Some(labels))
}

pub(crate) fn gtk_shortcut_trigger(value: &str) -> Option<String> {
    let (control, shift, alt, key) = crate::typecheck::parse_ui_shortcut(value)?;
    let key = match key.as_str() {
        "Enter" => "Return".to_string(),
        "Space" => "space".to_string(),
        key if key.len() == 1 && key.as_bytes()[0].is_ascii_alphanumeric() => {
            key.to_ascii_lowercase()
        }
        key => key.to_string(),
    };
    let mut trigger = String::new();
    if control {
        trigger.push_str("<Control>");
    }
    if shift {
        trigger.push_str("<Shift>");
    }
    if alt {
        trigger.push_str("<Alt>");
    }
    trigger.push_str(&key);
    Some(trigger)
}

fn android_shortcut_trigger(value: &str) -> Option<String> {
    let (control, shift, alt, key) = crate::typecheck::parse_ui_shortcut(value)?;
    let mut trigger = String::new();
    if control {
        trigger.push_str("Ctrl+");
    }
    if shift {
        trigger.push_str("Shift+");
    }
    if alt {
        trigger.push_str("Alt+");
    }
    trigger.push_str(&key);
    Some(trigger)
}

fn is_semantic_ui_color(value: &str) -> bool {
    crate::typecheck::SEMANTIC_UI_COLOR_TOKENS.contains(&value)
}

fn valid_ui_color(value: &str) -> bool {
    crate::typecheck::valid_ui_color(value)
}

fn gtk_ui_color_css(value: &str) -> Option<&str> {
    match value {
        "surface" => Some("@flux_surface"),
        "surfaceRaised" => Some("@flux_surface_raised"),
        "text" => Some("@flux_text"),
        "textMuted" => Some("@flux_text_muted"),
        "accent" => Some("@flux_accent"),
        "onAccent" => Some("@flux_on_accent"),
        "outline" => Some("@flux_outline"),
        "danger" => Some("@flux_danger"),
        "success" => Some("@flux_success"),
        "warning" => Some("@flux_warning"),
        "shadow" => Some("@flux_shadow"),
        "transparent" => Some("transparent"),
        _ => None,
    }
}

fn parse_hex_rgba(value: &str) -> Option<(u16, u16, u16, Option<u16>)> {
    let hex = value.strip_prefix('#')?;
    if !matches!(hex.len(), 6 | 8) || !hex.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return None;
    }
    let red = u8::from_str_radix(&hex[0..2], 16).ok()?;
    let green = u8::from_str_radix(&hex[2..4], 16).ok()?;
    let blue = u8::from_str_radix(&hex[4..6], 16).ok()?;
    let alpha = (hex.len() == 8)
        .then(|| u8::from_str_radix(&hex[6..8], 16).ok())
        .flatten();
    Some((
        u16::from(red) * 257,
        u16::from(green) * 257,
        u16::from(blue) * 257,
        alpha.map(|value| u16::from(value) * 257),
    ))
}

fn windows_colorref(value: &str) -> Option<String> {
    let (red, green, blue) = match value {
        "surface" => (248, 249, 250),
        "surfaceRaised" => (255, 255, 255),
        "text" => (31, 35, 40),
        "textMuted" => (87, 96, 106),
        "accent" => (9, 105, 218),
        "onAccent" => (255, 255, 255),
        "outline" => (208, 215, 222),
        "danger" => (207, 34, 46),
        "success" => (26, 127, 55),
        "warning" => (154, 103, 0),
        "shadow" => (31, 35, 40),
        "transparent" => (255, 255, 255),
        _ => {
            let (red, green, blue, _) = parse_hex_rgba(value)?;
            (red / 257, green / 257, blue / 257)
        }
    };
    Some(format!("RGB({}, {}, {})", red, green, blue))
}

fn static_expr_bool(expr: &Expr, signatures: &Signatures) -> Option<bool> {
    match fold_ui_primitive_expr(expr, signatures).ok().flatten()? {
        ConstantValue::Bool(value) => Some(value),
        _ => None,
    }
}

fn ui_expr_is_str(expr: &Expr, view: &crate::ast::ViewDef, signatures: &Signatures) -> bool {
    match &expr.kind {
        ExprKind::Str(_) => true,
        ExprKind::Var(name) => {
            view.states
                .iter()
                .find(|state| state.name == *name)
                .is_some_and(|state| signatures.canonical_type(&state.ty) == Type::Str)
                || view
                    .derived
                    .iter()
                    .find(|derived| derived.name == *name)
                    .is_some_and(|derived| signatures.canonical_type(&derived.ty) == Type::Str)
                || view
                    .params
                    .iter()
                    .find(|param| param.name == *name)
                    .is_some_and(|param| signatures.canonical_type(&param.ty) == Type::Str)
                || signatures
                    .constant(name)
                    .is_some_and(|constant| matches!(constant.value, ConstantValue::Str(_)))
        }
        ExprKind::Conditional {
            then_expr,
            else_expr,
            ..
        } => {
            ui_expr_is_str(then_expr, view, signatures)
                && ui_expr_is_str(else_expr, view, signatures)
        }
        _ => false,
    }
}

fn ui_expr_c(
    expr: &Expr,
    view: &crate::ast::ViewDef,
    signatures: &Signatures,
) -> Result<String, Diagnostic> {
    if let Some(value) = fold_ui_primitive_expr(expr, signatures)? {
        return Ok(constant_c_value(&value));
    }
    match &expr.kind {
        ExprKind::Bool(value) => Ok(if *value { "true" } else { "false" }.to_string()),
        ExprKind::Int(value) => Ok(format!("INT64_C({value})")),
        ExprKind::Str(value) => Ok(c_string(value)),
        ExprKind::Var(name) => {
            let environment = match name.as_str() {
                "windowWidth" | "window_width" => Some("flux__ui_window_width"),
                "windowHeight" | "window_height" => Some("flux__ui_window_height"),
                "windowIsLandscape" | "window_is_landscape" => {
                    Some("(flux__ui_window_width > flux__ui_window_height)")
                }
                "windowIsPortrait" | "window_is_portrait" => {
                    Some("(flux__ui_window_height >= flux__ui_window_width)")
                }
                "windowIsCompact" | "window_is_compact" => {
                    Some("(flux__ui_window_width < INT64_C(600))")
                }
                "windowIsMedium" | "window_is_medium" => Some(
                    "(flux__ui_window_width >= INT64_C(600) && flux__ui_window_width < INT64_C(840))",
                ),
                "windowIsExpanded" | "window_is_expanded" => {
                    Some("(flux__ui_window_width >= INT64_C(840))")
                }
                "displayScale" | "display_scale" => Some("flux__ui_display_scale"),
                _ => None,
            };
            if let Some(environment) = environment {
                return Ok(environment.to_string());
            }
            if let Some(value) = typecheck::semantic_ui_i64_token(name) {
                return Ok(format!("INT64_C({value})"));
            }
            if view.states.iter().any(|state| state.name == *name) {
                return Ok(ui_state_c_name(name));
            }
            if view.derived.iter().any(|derived| derived.name == *name) {
                return Ok(ui_derived_c_name(name));
            }
            let Some(constant) = signatures.constant(name) else {
                return Err(diag(
                    expr.span,
                    "bootstrap dynamic UI expression may reference only view environment, view state, derived view values, or compile-time constants",
                ));
            };
            match &constant.value {
                ConstantValue::Bool(value) => Ok(if *value { "true" } else { "false" }.to_string()),
                ConstantValue::I64(value) => Ok(format!("INT64_C({value})")),
                ConstantValue::Str(value) => Ok(c_string(value)),
            }
        }
        ExprKind::Unary { op, expr: inner } => {
            if matches!(op, UnaryOp::Not) {
                if let ExprKind::Unary {
                    op: UnaryOp::Not,
                    expr: double_negated,
                } = &inner.kind
                {
                    return ui_expr_c(double_negated, view, signatures);
                }
            }
            if matches!(op, UnaryOp::Neg) {
                if let ExprKind::Unary {
                    op: UnaryOp::Neg,
                    expr: double_negated,
                } = &inner.kind
                {
                    let inner = ui_expr_c(double_negated, view, signatures)?;
                    return Ok(format!("(-flux_neg_i64({inner}))"));
                }
                if i64_expr_result_excludes_min(inner, signatures) {
                    let inner = ui_expr_c(inner, view, signatures)?;
                    return Ok(format!("(-({inner}))"));
                }
            }
            let inner = ui_expr_c(inner, view, signatures)?;
            Ok(match op {
                UnaryOp::Neg => format!("flux_neg_i64({inner})"),
                UnaryOp::Not => format!("(!({inner}))"),
                UnaryOp::Borrow => inner,
            })
        }
        ExprKind::Binary { left, op, right } => {
            let string_comparison =
                matches!(op, BinOp::Eq | BinOp::Ne) && ui_expr_is_str(left, view, signatures);
            let left_code = ui_expr_c(left, view, signatures)?;
            let right_code = ui_expr_c(right, view, signatures)?;
            if let Some(code) =
                same_checked_negated_binding_comparison_c(*op, left, right, &left_code)
            {
                return Ok(code);
            }
            if let Some(code) =
                same_checked_i64_expression_comparison_c(*op, left, right, &left_code, signatures)
            {
                return Ok(code);
            }
            if let Some(code) = same_binding_comparison_c(*op, left, right) {
                return Ok(code.to_string());
            }
            if let Some(code) =
                boolean_identity_c(*op, left, right, &left_code, &right_code, signatures)
            {
                return Ok(code);
            }
            if let Some(other) = boolean_resolution_other(*op, left, right, signatures) {
                let other_code = ui_expr_c(other, view, signatures)?;
                return Ok(format!("({left_code} {} {other_code})", c_operator(*op)));
            }
            if let Some(other) = boolean_left_resolution_other(*op, left, right, signatures) {
                let other_code = ui_expr_c(other, view, signatures)?;
                return Ok(format!("({right_code} {} {other_code})", c_operator(*op)));
            }
            if let Some(code) =
                same_checked_i64_expression_arithmetic_c(*op, left, right, &left_code, signatures)
            {
                return Ok(code);
            }
            if let Some(code) =
                checked_i64_identity_c(*op, left, right, &left_code, &right_code, signatures)
            {
                return Ok(code);
            }
            let left = left_code;
            let right = right_code;
            match op {
                BinOp::Add => Ok(format!("flux_add_i64({left}, {right})")),
                BinOp::Sub => Ok(format!("flux_sub_i64({left}, {right})")),
                BinOp::Mul => Ok(format!("flux_mul_i64({left}, {right})")),
                BinOp::Div => Ok(format!("flux_div_i64({left}, {right})")),
                BinOp::Eq if string_comparison => Ok(format!("(strcmp({left}, {right}) == 0)")),
                BinOp::Ne if string_comparison => Ok(format!("(strcmp({left}, {right}) != 0)")),
                _ => Ok(format!("({left} {} {right})", c_operator(*op))),
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => Ok(format!(
            "(({}) ? ({}) : ({}))",
            ui_expr_c(cond, view, signatures)?,
            ui_expr_c(then_expr, view, signatures)?,
            ui_expr_c(else_expr, view, signatures)?,
        )),
        _ => Err(diag(
            expr.span,
            "bootstrap dynamic UI expression currently supports primitive literals, view environment/state/constants, primitive operators, and conditional expressions",
        )),
    }
}

fn emit_ui_refresh(
    out: &mut String,
    view: &crate::ast::ViewDef,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    let runtime_dependencies = ui_runtime_dependency_map(view);
    out.push_str("static void flux__ui_refresh_changed(int changed_state) {\n    flux__profile_timeline_emit(\"frame\", \"ui-refresh\", \"begin\", changed_state);\n    flux__profile_timeline_emit(\"layout\", \"ui-refresh\", \"begin\", changed_state);\n#ifdef FLUX_PROFILE_TIMELINE\n    struct timespec flux__profile_refresh_started = {0};\n    bool flux__profile_refresh_timed = flux__profile_overlay_label != NULL && clock_gettime(CLOCK_MONOTONIC, &flux__profile_refresh_started) == 0;\n#endif\n");
    for derived in &view.derived {
        let value = ui_expr_c(&derived.value, view, signatures)?;
        let dependencies = runtime_dependencies
            .get(&derived.name)
            .expect("derived runtime dependency metadata exists");
        let condition = ui_refresh_condition(dependencies);
        out.push_str(&format!(
            "    if ({condition}) {} = {value};\n",
            ui_derived_c_name(&derived.name)
        ));
    }
    for element in &view.elements {
        let dependencies = ui_element_refresh_dependencies(element, &runtime_dependencies);
        let condition = ui_refresh_condition(&dependencies);
        out.push_str(&format!("    if ({condition}) {{\n"));
        let content_widget = ui_widget_c_name(&element.name);
        let widget = linux_ui_host_c_name(element);
        if let Some(property) = view_property(element, "visible") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            if view_property(element, "layout_transition_ms").is_some() {
                let layout = linux_ui_layout_c_name(element);
                out.push_str(&format!(
                    "    if ({layout} != NULL) gtk_revealer_set_reveal_child(GTK_REVEALER({layout}), {value});\n"
                ));
            } else {
                let layout = linux_ui_revealer_c_name(element);
                out.push_str(&format!(
                    "#ifdef FLUX_DEVELOPMENT_RELOAD\n    if ({layout} != NULL) gtk_revealer_set_reveal_child(GTK_REVEALER({layout}), {value});\n#else\n    if ({widget} != NULL) gtk_widget_set_visible({widget}, {value});\n#endif\n"
                ));
            }
        }
        if let Some(property) = view_property(element, "clip") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_widget_set_overflow({widget}, ({value}) ? GTK_OVERFLOW_HIDDEN : GTK_OVERFLOW_VISIBLE);\n"
            ));
        }
        if let Some(property) = view_property(element, "tooltip") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_widget_set_tooltip_text({widget}, {value});\n"
            ));
        }
        if element.kind == "TextInput"
            && let Some(property) = view_property(element, "validation_state")
        {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({content_widget} != NULL) {{ gtk_widget_remove_css_class({content_widget}, \"flux-input-error\"); gtk_widget_remove_css_class({content_widget}, \"flux-input-success\"); gtk_widget_remove_css_class({content_widget}, \"flux-input-warning\"); const char *validation = flux__ui_validation_state({value}); if (strcmp(validation, \"normal\") != 0) {{ gchar *validation_class = g_strdup_printf(\"flux-input-%s\", validation); gtk_widget_add_css_class({content_widget}, validation_class); g_free(validation_class); }} }}\n"
            ));
        }
        if element.kind == "TextInput"
            && let Some(property) = view_property(element, "validation_message")
        {
            let value = ui_expr_c(&property.value, view, signatures)?;
            let multiline = view_property(element, "multiline")
                .and_then(|property| static_expr_bool(&property.value, signatures))
                .unwrap_or(false);
            out.push_str(&format!(
                "    if ({content_widget} != NULL) {{ const char *message = {value}; gtk_widget_set_tooltip_text({content_widget}, (message != NULL && message[0] != '\\0') ? message : NULL); gtk_accessible_update_property(GTK_ACCESSIBLE({content_widget}), GTK_ACCESSIBLE_PROPERTY_DESCRIPTION, message, -1); }}\n"
            ));
            if !multiline {
                out.push_str(&format!(
                    "    if ({content_widget} != NULL) {{ const char *message = {value}; gtk_entry_set_icon_from_icon_name(GTK_ENTRY({content_widget}), GTK_ENTRY_ICON_SECONDARY, (message != NULL && message[0] != '\\0') ? \"dialog-information-symbolic\" : NULL); gtk_entry_set_icon_tooltip_text(GTK_ENTRY({content_widget}), GTK_ENTRY_ICON_SECONDARY, message); }}\n"
                ));
            }
        }
        if let Some(property) = view_property(element, "accessibility_label") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_accessible_update_property(GTK_ACCESSIBLE({widget}), GTK_ACCESSIBLE_PROPERTY_LABEL, {value}, -1);\n"
            ));
        }
        if let Some(property) = view_property(element, "accessibility_description") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_accessible_update_property(GTK_ACCESSIBLE({widget}), GTK_ACCESSIBLE_PROPERTY_DESCRIPTION, {value}, -1);\n"
            ));
        } else if let Some(property) = view_property(element, "accessibility_action_label")
            .or_else(|| view_property(element, "accessibility_long_press_label"))
        {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_accessible_update_property(GTK_ACCESSIBLE({widget}), GTK_ACCESSIBLE_PROPERTY_DESCRIPTION, {value}, -1);\n"
            ));
        }
        if let Some(property) = view_property(element, "accessibility_value") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_accessible_update_property(GTK_ACCESSIBLE({widget}), GTK_ACCESSIBLE_PROPERTY_VALUE_TEXT, {value}, -1);\n"
            ));
        }
        if let Some(property) = view_property(element, "accessibility_hidden") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_accessible_update_state(GTK_ACCESSIBLE({widget}), GTK_ACCESSIBLE_STATE_HIDDEN, {value}, -1);\n"
            ));
        }
        if let Some(property) = view_property(element, "focusable") {
            let value = ui_expr_c(&property.value, view, signatures)?;
            out.push_str(&format!(
                "    if ({widget} != NULL) gtk_widget_set_focusable({widget}, {value});\n"
            ));
        }
        for (property_name, setter) in [("align_x", "halign"), ("align_y", "valign")] {
            let Some(property) = view_property(element, property_name) else {
                continue;
            };
            if static_expr_str(&property.value, signatures).is_some() {
                continue;
            }
            let value = ui_expr_c(&property.value, view, signatures)?;
            let local = format!("refresh_{property_name}_{}", element.name);
            out.push_str(&format!(
                "    const char *{local}_name = {value};\n    GtkAlign {local};\n    if (strcmp({local}_name, \"start\") == 0) {local} = GTK_ALIGN_START; else if (strcmp({local}_name, \"center\") == 0) {local} = GTK_ALIGN_CENTER; else if (strcmp({local}_name, \"end\") == 0) {local} = GTK_ALIGN_END; else if (strcmp({local}_name, \"fill\") == 0) {local} = GTK_ALIGN_FILL; else {{ fputs(\"Flux runtime error: {property_name} must be one of 'start', 'center', 'end', or 'fill'\\n\", stderr); abort(); }}\n    if ({widget} != NULL) gtk_widget_set_{setter}({widget}, {local});\n"
            ));
        }
        let dynamic_min_width = view_property(element, "min_width")
            .filter(|property| static_expr_i64(&property.value, signatures).is_none());
        let dynamic_min_height = view_property(element, "min_height")
            .filter(|property| static_expr_i64(&property.value, signatures).is_none());
        if dynamic_min_width.is_some() || dynamic_min_height.is_some() {
            let layout_widget = if view_property(element, "layout_transition_ms").is_some() {
                linux_ui_layout_c_name(element)
            } else {
                widget.clone()
            };
            let fixed_width = view
                .grid
                .columns
                .get(element.column.saturating_sub(1) as usize)
                .and_then(|track| match track {
                    crate::ast::GridTrack::Units(value) => Some(i64::from(*value)),
                    _ => None,
                });
            let fixed_height = view
                .grid
                .rows
                .get(element.row.saturating_sub(1) as usize)
                .and_then(|track| match track {
                    crate::ast::GridTrack::Units(value) => Some(i64::from(*value)),
                    _ => None,
                });
            let width = if let Some(property) = dynamic_min_width {
                let value = ui_expr_c(&property.value, view, signatures)?;
                out.push_str(&format!(
                    "    int64_t refresh_min_width_{} = {value};\n    if (refresh_min_width_{} < 1 || refresh_min_width_{} > INT32_MAX) {{ fputs(\"Flux runtime error: minWidth must be between 1 and 2147483647\\n\", stderr); abort(); }}\n",
                    element.name, element.name, element.name
                ));
                if let Some(maximum) = view_property(element, "max_width") {
                    let maximum = ui_expr_c(&maximum.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if (refresh_min_width_{} > ({maximum})) {{ fputs(\"Flux runtime error: minWidth must be less than or equal to maxWidth\\n\", stderr); abort(); }}\n",
                        element.name
                    ));
                }
                match fixed_width {
                    Some(fixed) => format!(
                        "(refresh_min_width_{} > INT64_C({fixed}) ? refresh_min_width_{} : INT64_C({fixed}))",
                        element.name, element.name
                    ),
                    None => format!("refresh_min_width_{}", element.name),
                }
            } else {
                static_minimum_size(element, "min_width", signatures)?
                    .map(|minimum| fixed_width.map_or(minimum, |fixed| fixed.max(minimum)))
                    .or(fixed_width)
                    .map_or_else(|| "-1".to_string(), |value| value.to_string())
            };
            let height = if let Some(property) = dynamic_min_height {
                let value = ui_expr_c(&property.value, view, signatures)?;
                out.push_str(&format!(
                    "    int64_t refresh_min_height_{} = {value};\n    if (refresh_min_height_{} < 1 || refresh_min_height_{} > INT32_MAX) {{ fputs(\"Flux runtime error: minHeight must be between 1 and 2147483647\\n\", stderr); abort(); }}\n",
                    element.name, element.name, element.name
                ));
                if let Some(maximum) = view_property(element, "max_height") {
                    let maximum = ui_expr_c(&maximum.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if (refresh_min_height_{} > ({maximum})) {{ fputs(\"Flux runtime error: minHeight must be less than or equal to maxHeight\\n\", stderr); abort(); }}\n",
                        element.name
                    ));
                }
                match fixed_height {
                    Some(fixed) => format!(
                        "(refresh_min_height_{} > INT64_C({fixed}) ? refresh_min_height_{} : INT64_C({fixed}))",
                        element.name, element.name
                    ),
                    None => format!("refresh_min_height_{}", element.name),
                }
            } else {
                let minimum =
                    static_minimum_size(element, "min_height", signatures)?.or_else(|| {
                        (fixed_height.is_none()
                            && view_property(element, "max_height").is_none()
                            && matches!(
                                element.kind.as_str(),
                                "Button" | "TextInput" | "Toggle" | "Radio"
                            ))
                        .then_some(40)
                    });
                minimum
                    .map(|minimum| fixed_height.map_or(minimum, |fixed| fixed.max(minimum)))
                    .or(fixed_height)
                    .map_or_else(|| "-1".to_string(), |value| value.to_string())
            };
            out.push_str(&format!(
                "    if ({layout_widget} != NULL) gtk_widget_set_size_request({layout_widget}, {width}, {height});\n"
            ));
        }
        let dynamic_max_width = view_property(element, "max_width")
            .filter(|property| static_expr_i64(&property.value, signatures).is_none());
        let dynamic_max_height = view_property(element, "max_height")
            .filter(|property| static_expr_i64(&property.value, signatures).is_none());
        if dynamic_max_width.is_some() || dynamic_max_height.is_some() {
            let constraint = linux_ui_constraint_c_name(element);
            let max_width = if let Some(property) = view_property(element, "max_width") {
                let value = ui_expr_c(&property.value, view, signatures)?;
                let local = format!("refresh_max_width_{}", element.name);
                out.push_str(&format!(
                    "    int64_t {local} = {value};\n    if ({local} < 1 || {local} > INT32_MAX) {{ fputs(\"Flux runtime error: maxWidth must be between 1 and 2147483647\\n\", stderr); abort(); }}\n"
                ));
                if let Some(minimum) = view_property(element, "min_width") {
                    let minimum = ui_expr_c(&minimum.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({local} < ({minimum})) {{ fputs(\"Flux runtime error: maxWidth must be greater than or equal to minWidth\\n\", stderr); abort(); }}\n"
                    ));
                }
                local
            } else {
                "-1".to_string()
            };
            let max_height = if let Some(property) = view_property(element, "max_height") {
                let value = ui_expr_c(&property.value, view, signatures)?;
                let local = format!("refresh_max_height_{}", element.name);
                out.push_str(&format!(
                    "    int64_t {local} = {value};\n    if ({local} < 1 || {local} > INT32_MAX) {{ fputs(\"Flux runtime error: maxHeight must be between 1 and 2147483647\\n\", stderr); abort(); }}\n"
                ));
                if let Some(minimum) = view_property(element, "min_height") {
                    let minimum = ui_expr_c(&minimum.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({local} < ({minimum})) {{ fputs(\"Flux runtime error: maxHeight must be greater than or equal to minHeight\\n\", stderr); abort(); }}\n"
                    ));
                }
                local
            } else {
                "-1".to_string()
            };
            out.push_str(&format!(
                "    if ({constraint} != NULL) flux_size_constraint_set_limits({constraint}, (int)({max_width}), (int)({max_height}));\n"
            ));
        }
        emit_dynamic_transform_refresh(out, element, view, signatures)?;
        let widget = content_widget;
        match element.kind.as_str() {
            "Text" => {
                if let Some(property) = view_property(element, "text") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_label_set_text(GTK_LABEL({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "selectable") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_label_set_selectable(GTK_LABEL({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "wrap") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_label_set_wrap(GTK_LABEL({widget}), {value});\n"
                    ));
                }
            }
            "TextInput" => {
                if let Some(property) = view_property(element, "placeholder") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    let multiline = view_property(element, "multiline")
                        .and_then(|property| static_expr_bool(&property.value, signatures))
                        .unwrap_or(false);
                    if multiline {
                        out.push_str(&format!(
                            "    if ({widget} != NULL && flux__ui_placeholder_{} != NULL) {{ const char *placeholder = {value}; gtk_label_set_text(GTK_LABEL(flux__ui_placeholder_{}), placeholder); GtkTextBuffer *buffer = gtk_text_view_get_buffer(GTK_TEXT_VIEW({widget})); gtk_widget_set_visible(flux__ui_placeholder_{}, placeholder != NULL && placeholder[0] != '\\0' && gtk_text_buffer_get_char_count(buffer) == 0); }}\n",
                            element.name,
                            element.name,
                            element.name,
                        ));
                    } else {
                        out.push_str(&format!(
                            "    if ({widget} != NULL) gtk_entry_set_placeholder_text(GTK_ENTRY({widget}), {value});\n"
                        ));
                    }
                }
                if let Some(property) = view_property(element, "enabled") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_widget_set_sensitive({widget}, {value});\n"
                    ));
                }
            }
            "Image" => {
                if let Some(property) = view_property(element, "source") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) {{ gchar *flux__image_source = flux__ui_bounded_image_source_path({value}); gtk_picture_set_filename(GTK_PICTURE({widget}), flux__image_source); g_free(flux__image_source); }}\n"
                    ));
                }
                if let Some(property) = view_property(element, "alt") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_picture_set_alternative_text(GTK_PICTURE({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "can_shrink") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_picture_set_can_shrink(GTK_PICTURE({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "fit")
                    && static_expr_str(&property.value, signatures).is_none()
                {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    const char *refresh_image_fit_value = {value};\n    GtkContentFit refresh_image_fit;\n    if (strcmp(refresh_image_fit_value, \"fill\") == 0) refresh_image_fit = GTK_CONTENT_FIT_FILL;\n    else if (strcmp(refresh_image_fit_value, \"contain\") == 0) refresh_image_fit = GTK_CONTENT_FIT_CONTAIN;\n    else if (strcmp(refresh_image_fit_value, \"cover\") == 0) refresh_image_fit = GTK_CONTENT_FIT_COVER;\n    else if (strcmp(refresh_image_fit_value, \"scaleDown\") == 0 || strcmp(refresh_image_fit_value, \"scale_down\") == 0) refresh_image_fit = GTK_CONTENT_FIT_SCALE_DOWN;\n    else {{ fputs(\"Flux runtime error: Image.fit must be one of 'fill', 'contain', 'cover', or 'scaleDown'\\n\", stderr); abort(); }}\n    if ({widget} != NULL) gtk_picture_set_content_fit(GTK_PICTURE({widget}), refresh_image_fit);\n"
                    ));
                }
            }
            "Radio" => {
                if let Some(property) = view_property(element, "label") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_check_button_set_label(GTK_CHECK_BUTTON({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "selected") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_check_button_set_active(GTK_CHECK_BUTTON({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "enabled") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_widget_set_sensitive({widget}, {value});\n"
                    ));
                }
            }
            "Toggle" => {
                if let Some(property) = view_property(element, "label") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_check_button_set_label(GTK_CHECK_BUTTON({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "checked") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_check_button_set_active(GTK_CHECK_BUTTON({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "enabled") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_widget_set_sensitive({widget}, {value});\n"
                    ));
                }
            }
            "Nav" | "Chart" | "Card" | "Header" | "Content" => {
                let text_property = match element.kind.as_str() {
                    "Nav" | "Chart" | "Content" => "label",
                    "Card" => "title",
                    "Header" => "text",
                    _ => unreachable!("semantic text element kind"),
                };
                if let Some(property) = view_property(element, text_property) {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_label_set_text(GTK_LABEL({widget}), {value});\n"
                    ));
                }
            }
            "Button" => {
                if let Some(property) = view_property(element, "text") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_button_set_label(GTK_BUTTON({widget}), {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "enabled") {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) gtk_widget_set_sensitive({widget}, {value});\n"
                    ));
                }
                if let Some(property) = view_property(element, "primary")
                    && static_expr_bool(&property.value, signatures).is_none()
                {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    out.push_str(&format!(
                        "    if ({widget} != NULL) {{ if ({value}) gtk_widget_add_css_class({widget}, \"suggested-action\"); else gtk_widget_remove_css_class({widget}, \"suggested-action\"); }}\n"
                    ));
                }
                if let Some(property) = view_property(element, "size")
                    && static_expr_i64(&property.value, signatures).is_none()
                {
                    let value = ui_expr_c(&property.value, view, signatures)?;
                    let label = format!("refresh_button_label_{}", element.name);
                    let attrs = format!("refresh_button_attrs_{}", element.name);
                    let size = format!("refresh_button_size_{}", element.name);
                    out.push_str(&format!(
                        "    int64_t {size} = {value};\n    if ({size} <= 0 || {size} > INT32_MAX) {{ fputs(\"Flux runtime error: Button.size must be greater than zero and fit within a 32-bit signed integer\\n\", stderr); abort(); }}\n    if ({widget} != NULL) {{ GtkWidget *{label} = gtk_button_get_child(GTK_BUTTON({widget})); if (GTK_IS_LABEL({label})) {{ PangoAttrList *{attrs} = pango_attr_list_new(); pango_attr_list_insert({attrs}, pango_attr_size_new((int){size} * PANGO_SCALE)); gtk_label_set_attributes(GTK_LABEL({label}), {attrs}); pango_attr_list_unref({attrs}); }} }}\n"
                    ));
                }
            }
            _ => {}
        }
        out.push_str("    }\n");
    }
    out.push_str("#ifdef FLUX_PROFILE_TIMELINE\n    if (flux__profile_refresh_timed) {\n        struct timespec flux__profile_refresh_finished = {0};\n        if (clock_gettime(CLOCK_MONOTONIC, &flux__profile_refresh_finished) == 0) {\n            int64_t flux__profile_refresh_us = (int64_t)(flux__profile_refresh_finished.tv_sec - flux__profile_refresh_started.tv_sec) * INT64_C(1000000) + (int64_t)(flux__profile_refresh_finished.tv_nsec - flux__profile_refresh_started.tv_nsec) / INT64_C(1000);\n            char flux__profile_overlay_text[96];\n            snprintf(flux__profile_overlay_text, sizeof(flux__profile_overlay_text), \"Flux refresh %.2f ms | state %d\", (double)flux__profile_refresh_us / 1000.0, changed_state);\n            gtk_label_set_text(GTK_LABEL(flux__profile_overlay_label), flux__profile_overlay_text);\n        }\n    }\n#endif\n    flux__profile_timeline_emit(\"layout\", \"ui-refresh\", \"end\", changed_state);\n    flux__profile_timeline_emit(\"frame\", \"ui-refresh\", \"end\", changed_state);\n}\n\n");
    out.push_str("static inline void flux__ui_refresh(void) { flux__ui_refresh_changed(-1); }\n\n");
    Ok(())
}

const TEXT_SEMANTIC_VARIANTS: &[(&str, i64, bool, i64, i64)] = &[
    ("body", 16, false, 140, 72),
    ("caption", 13, false, 135, 72),
    ("heading", 20, true, 125, 52),
    ("title", 28, true, 120, 44),
    ("display", 36, true, 115, 36),
];

fn text_semantic_typography(
    element: &crate::ast::ViewElement,
    signatures: &Signatures,
) -> Result<(i64, bool, i64, i64), Diagnostic> {
    let variant = match view_property(element, "variant") {
        Some(property) => static_expr_str(&property.value, signatures).ok_or_else(|| {
            diag(
                property.value.span,
                "Text.variant must be a compile-time string",
            )
        })?,
        None => "body".to_string(),
    };
    TEXT_SEMANTIC_VARIANTS
        .iter()
        .find(|(name, ..)| *name == variant)
        .map(|(_, size, bold, line_height_percent, max_width_chars)| {
            (*size, *bold, *line_height_percent, *max_width_chars)
        })
        .ok_or_else(|| {
            diag(
                view_property(element, "variant")
                    .expect("non-default variant has a source property")
                    .value
                    .span,
                "Text.variant must be one of 'body', 'caption', 'heading', 'title', or 'display'",
            )
        })
}

pub(crate) fn bootstrap_window_size(view: &crate::ast::ViewDef) -> (u32, u32) {
    fn tracks_size(tracks: &[crate::ast::GridTrack], fallback: u32) -> u32 {
        let fixed = tracks
            .iter()
            .map(|track| match track {
                crate::ast::GridTrack::Units(value) => *value,
                crate::ast::GridTrack::Fraction(_) | crate::ast::GridTrack::Auto => fallback,
            })
            .sum::<u32>();
        fixed.max(fallback)
    }
    (
        tracks_size(&view.grid.columns, 220)
            .saturating_add(view.grid.padding.unwrap_or(20).saturating_mul(2)),
        tracks_size(&view.grid.rows, 90)
            .saturating_add(view.grid.padding.unwrap_or(20).saturating_mul(2)),
    )
}

fn emit_element_alignment(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    for (property_name, setter) in [("align_x", "halign"), ("align_y", "valign")] {
        let Some(property) = view_property(element, property_name) else {
            continue;
        };
        let Some(value) = static_expr_str(&property.value, signatures) else {
            continue;
        };
        let alignment = match value.as_str() {
            "start" => "GTK_ALIGN_START",
            "center" => "GTK_ALIGN_CENTER",
            "end" => "GTK_ALIGN_END",
            "fill" => "GTK_ALIGN_FILL",
            _ => {
                return Err(diag(
                    property.value.span,
                    &format!("{property_name} must be one of 'start', 'center', 'end', or 'fill'"),
                ));
            }
        };
        out.push_str(&format!(
            "    gtk_widget_set_{setter}({variable}, {alignment});\n"
        ));
    }
    Ok(())
}

fn emit_lifecycle_padding_style_setup(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    for property_name in [
        "padding",
        "padding_top",
        "padding_bottom",
        "padding_start",
        "padding_end",
    ] {
        let css_names = linux_hot_css_i64_properties(element, property_name);
        if css_names.is_empty() {
            continue;
        }
        let provider = linux_ui_hot_style_provider_c_name(element, property_name);
        out.push_str(&format!(
            "    if ({provider} == NULL) {{ {provider} = gtk_css_provider_new(); if ({provider} != NULL) gtk_style_context_add_provider_for_display(gtk_widget_get_display({variable}), GTK_STYLE_PROVIDER({provider}), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION); }}\n"
        ));
        let Some(value) = static_non_negative_style_i64(element, property_name, signatures)? else {
            continue;
        };
        let declarations = css_names
            .iter()
            .map(|css_name| format!("{css_name}: {value}px;"))
            .collect::<Vec<_>>()
            .join(" ");
        let css = format!("#flux-ui-{} {{ {declarations} }}", element.name);
        out.push_str(&format!(
            "    if ({provider} != NULL) gtk_css_provider_load_from_data({provider}, {}, -1);\n",
            c_string(&css)
        ));
    }
    Ok(())
}

