fn emit_lifecycle_border_style_setup(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    for property_name in [
        "border_width",
        "border_top_width",
        "border_bottom_width",
        "border_start_width",
        "border_end_width",
    ] {
        let css_names = linux_hot_css_i64_properties(element, property_name);
        if css_names.is_empty() {
            continue;
        }
        let provider = linux_ui_hot_style_provider_c_name(element, property_name);
        out.push_str(&format!(
            "    if ({provider} == NULL) {{ {provider} = gtk_css_provider_new(); if ({provider} != NULL) gtk_style_context_add_provider_for_display(gtk_widget_get_display({variable}), GTK_STYLE_PROVIDER({provider}), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION); }}\n"
        ));
        let Some(value) = static_non_negative_style_i64(element, property_name, signatures)? else {
            continue;
        };
        let mut declarations = css_names
            .iter()
            .map(|css_name| format!("{css_name}: {value}px;"))
            .collect::<Vec<_>>();
        if value > 0 {
            declarations.push("border-style: solid;".to_string());
        }
        let css = format!("#flux-ui-{} {{ {} }}", element.name, declarations.join(" "));
        out.push_str(&format!(
            "    if ({provider} != NULL) gtk_css_provider_load_from_data({provider}, {}, -1);\n",
            c_string(&css)
        ));
    }

    let provider = linux_ui_hot_style_provider_c_name(element, "border_style");
    out.push_str(&format!(
        "    if ({provider} == NULL) {{ {provider} = gtk_css_provider_new(); if ({provider} != NULL) gtk_style_context_add_provider_for_display(gtk_widget_get_display({variable}), GTK_STYLE_PROVIDER({provider}), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION); }}\n"
    ));
    if let Some(property) = view_property(element, "border_style") {
        let Some(value) = static_expr_str(&property.value, signatures) else {
            return Err(diag(
                property.value.span,
                "border_style must be a compile-time string",
            ));
        };
        if !matches!(
            value.as_str(),
            "none" | "solid" | "dashed" | "dotted" | "double"
        ) {
            return Err(diag(
                property.value.span,
                "border_style must be one of 'none', 'solid', 'dashed', 'dotted', or 'double'",
            ));
        }
        let css = format!("#flux-ui-{} {{ border-style: {value}; }}", element.name);
        out.push_str(&format!(
            "    if ({provider} != NULL) gtk_css_provider_load_from_data({provider}, {}, -1);\n",
            c_string(&css)
        ));
    }
    Ok(())
}

fn emit_lifecycle_color_style_setup(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    for property_name in [
        "background_color",
        "border_color",
        "border_top_color",
        "border_bottom_color",
        "border_start_color",
        "border_end_color",
        "color",
    ] {
        if property_name == "color" && element.kind != "Text" {
            continue;
        }
        let css_names = linux_hot_css_color_properties(element, property_name);
        if css_names.is_empty() {
            continue;
        }
        let provider = linux_ui_hot_style_provider_c_name(element, property_name);
        out.push_str(&format!(
            "    if ({provider} == NULL) {{ {provider} = gtk_css_provider_new(); if ({provider} != NULL) gtk_style_context_add_provider_for_display(gtk_widget_get_display({variable}), GTK_STYLE_PROVIDER({provider}), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION); }}\n"
        ));
        let Some(property) = view_property(element, property_name) else {
            continue;
        };
        let Some(value) = static_expr_str(&property.value, signatures) else {
            return Err(diag(
                property.value.span,
                &format!("{property_name} must be a compile-time string"),
            ));
        };
        if !valid_ui_color(&value) {
            return Err(diag(
                property.value.span,
                &format!(
                    "{property_name} must use '#RRGGBB', '#RRGGBBAA', or a semantic Flux color token"
                ),
            ));
        }
        let css_value = gtk_ui_color_css(&value).unwrap_or(value.as_str());
        let declarations = css_names
            .iter()
            .map(|css_name| format!("{css_name}: {css_value};"))
            .collect::<Vec<_>>()
            .join(" ");
        let css = format!("#flux-ui-{} {{ {declarations} }}", element.name);
        out.push_str(&format!(
            "    if ({provider} != NULL) gtk_css_provider_load_from_data({provider}, {}, -1);\n",
            c_string(&css)
        ));
    }
    Ok(())
}

fn emit_element_style(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    let widget_name = format!("flux-ui-{}", element.name);
    out.push_str(&format!(
        "    gtk_widget_set_name({variable}, {});\n",
        c_string(&widget_name)
    ));
    let mut declarations = Vec::new();
    let shadow_color = view_property(element, "shadow_color")
        .map(|property| {
            let Some(value) = static_expr_str(&property.value, signatures) else {
                return Err(diag(
                    property.value.span,
                    "shadow_color must be a compile-time string",
                ));
            };
            if !valid_ui_color(&value) {
                return Err(diag(
                    property.value.span,
                    "shadow_color must use '#RRGGBB', '#RRGGBBAA', or a semantic Flux color token",
                ));
            }
            Ok(value)
        })
        .transpose()?;
    let shadow_blur = static_style_i64(element, "shadow_blur", signatures)?.unwrap_or(0);
    let shadow_offset_x = static_style_i64(element, "shadow_offset_x", signatures)?.unwrap_or(0);
    let shadow_offset_y = static_style_i64(element, "shadow_offset_y", signatures)?.unwrap_or(0);
    if shadow_blur < 0 {
        let span = view_property(element, "shadow_blur")
            .expect("shadow blur exists when negative")
            .value
            .span;
        return Err(diag(span, "shadow_blur must be non-negative"));
    }
    if shadow_color.is_some() || shadow_blur != 0 || shadow_offset_x != 0 || shadow_offset_y != 0 {
        declarations.push(format!(
            "box-shadow: {shadow_offset_x}px {shadow_offset_y}px {shadow_blur}px {};",
            gtk_ui_color_css(shadow_color.as_deref().unwrap_or("shadow"))
                .unwrap_or_else(|| shadow_color.as_deref().unwrap_or("#00000080"))
        ));
    }
    let has_transform = element_has_transform(element);
    if has_transform && !element_has_dynamic_transform(element, signatures) {
        let translate_x = static_style_i64(element, "translate_x", signatures)?.unwrap_or(0);
        let translate_y = static_style_i64(element, "translate_y", signatures)?.unwrap_or(0);
        let rotate_degrees = static_style_i64(element, "rotate_degrees", signatures)?.unwrap_or(0);
        let scale_percent = static_style_i64(element, "scale_percent", signatures)?.unwrap_or(100);
        let scale_x_percent =
            static_style_i64(element, "scale_x_percent", signatures)?.unwrap_or(scale_percent);
        let scale_y_percent =
            static_style_i64(element, "scale_y_percent", signatures)?.unwrap_or(scale_percent);
        let skew_x_degrees = static_style_i64(element, "skew_x_degrees", signatures)?.unwrap_or(0);
        let skew_y_degrees = static_style_i64(element, "skew_y_degrees", signatures)?.unwrap_or(0);
        declarations.push(format!(
            "transform: translate({translate_x}px, {translate_y}px) rotate({rotate_degrees}deg) scale({:.2}, {:.2}) skewX({skew_x_degrees}deg) skewY({skew_y_degrees}deg);",
            scale_x_percent as f64 / 100.0,
            scale_y_percent as f64 / 100.0,
        ));
        if view_property(element, "transform_origin_x_percent").is_some()
            || view_property(element, "transform_origin_y_percent").is_some()
        {
            let origin_x =
                static_style_i64(element, "transform_origin_x_percent", signatures)?.unwrap_or(50);
            let origin_y =
                static_style_i64(element, "transform_origin_y_percent", signatures)?.unwrap_or(50);
            declarations.push(format!("transform-origin: {origin_x}% {origin_y}%;"));
        }
    }
    let transition_ms = static_non_negative_style_i64(element, "transition_ms", signatures)?;
    let transition_delay_ms =
        static_non_negative_style_i64(element, "transition_delay_ms", signatures)?;
    let transition_easing = view_property(element, "transition_easing")
        .map(|property| {
            let Some(value) = static_expr_str(&property.value, signatures) else {
                return Err(diag(
                    property.value.span,
                    "transition_easing must be a compile-time string",
                ));
            };
            let Some(css_value) = typecheck::transition_easing_css_value(&value) else {
                return Err(diag(
                    property.value.span,
                    &format!(
                        "transitionEasing must be one of {}",
                        typecheck::TRANSITION_EASINGS
                            .iter()
                            .map(|value| format!("'{value}'"))
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                ));
            };
            Ok(css_value)
        })
        .transpose()?;
    if (transition_delay_ms.is_some() || transition_easing.is_some()) && transition_ms.is_none() {
        let property = view_property(element, "transition_delay_ms")
            .or_else(|| view_property(element, "transition_easing"))
            .expect("a transition option exists");
        return Err(diag(
            property.value.span,
            "transition_delay_ms and transition_easing require transition_ms",
        ));
    }
    if let Some(duration) = transition_ms {
        declarations.push("transition-property: all;".to_string());
        declarations.push(format!("transition-duration: {duration}ms;"));
        if let Some(delay) = transition_delay_ms {
            declarations.push(format!("transition-delay: {delay}ms;"));
        }
        declarations.push(format!(
            "transition-timing-function: {};",
            transition_easing.unwrap_or("ease")
        ));
    }
    if declarations.is_empty() {
        return Ok(());
    }
    let provider = format!("flux__style_{}", element.name);
    let css = if transition_ms.is_some() {
        format!(
            "#{widget_name} {{ {} }} @media (prefers-reduced-motion: reduce) {{ #{widget_name} {{ transition-duration: 0ms; transition-delay: 0ms; }} }}",
            declarations.join(" ")
        )
    } else {
        format!("#{widget_name} {{ {} }}", declarations.join(" "))
    };
    out.push_str(&format!(
        "    GtkCssProvider *{provider} = gtk_css_provider_new();\n    gtk_css_provider_load_from_data({provider}, {}, -1);\n    gtk_style_context_add_provider_for_display(gtk_widget_get_display({variable}), GTK_STYLE_PROVIDER({provider}), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);\n",
        c_string(&css),
    ));
    if transition_ms.is_some() {
        let settings = format!("flux__settings_{}", element.name);
        out.push_str(&format!(
            "    GtkSettings *{settings} = gtk_settings_get_default();\n    if ({settings} != NULL) g_object_bind_property({settings}, \"gtk-interface-reduced-motion\", {provider}, \"prefers-reduced-motion\", G_BINDING_SYNC_CREATE);\n"
        ));
    }
    out.push_str(&format!("    g_object_unref({provider});\n"));
    Ok(())
}

const TRANSFORM_VIEW_PROPERTIES: &[&str] = &[
    "translate_x",
    "translate_y",
    "rotate_degrees",
    "scale_percent",
    "scale_x_percent",
    "scale_y_percent",
    "skew_x_degrees",
    "skew_y_degrees",
    "transform_origin_x_percent",
    "transform_origin_y_percent",
];

fn element_has_transform(element: &crate::ast::ViewElement) -> bool {
    TRANSFORM_VIEW_PROPERTIES
        .iter()
        .any(|name| view_property(element, name).is_some())
        || view_property(element, "drag_translate").is_some()
        || view_property(element, "pinch_scale").is_some()
}

fn static_gesture_transform_enabled(
    element: &crate::ast::ViewElement,
    property_name: &str,
    signatures: &Signatures,
) -> Result<bool, Diagnostic> {
    let Some(property) = view_property(element, property_name) else {
        return Ok(false);
    };
    static_expr_bool(&property.value, signatures).ok_or_else(|| {
        diag(
            property.value.span,
            &format!("{property_name} must be a compile-time bool value"),
        )
    })
}

fn ui_gesture_translate_enabled_c_name(name: &str) -> String {
    format!("flux__gesture_translate_enabled_{name}")
}

fn ui_gesture_translate_x_c_name(name: &str) -> String {
    format!("flux__gesture_translate_x_{name}")
}

fn ui_gesture_translate_y_c_name(name: &str) -> String {
    format!("flux__gesture_translate_y_{name}")
}

fn ui_gesture_scale_enabled_c_name(name: &str) -> String {
    format!("flux__gesture_scale_enabled_{name}")
}

fn ui_gesture_scale_c_name(name: &str) -> String {
    format!("flux__gesture_scale_{name}")
}

fn linux_ui_retains_gesture_transform_lifecycle(
    element: &crate::ast::ViewElement,
    signatures: &Signatures,
) -> bool {
    view_property(element, "drag_translate").is_none()
        && view_property(element, "pinch_scale").is_none()
        && !element_has_dynamic_transform(element, signatures)
}

fn linux_ui_hot_gesture_transform_apply_c_name(name: &str) -> String {
    format!("flux__ui_hot_gesture_transform_apply_{name}")
}

fn element_has_dynamic_transform(
    element: &crate::ast::ViewElement,
    signatures: &Signatures,
) -> bool {
    TRANSFORM_VIEW_PROPERTIES
        .iter()
        .filter_map(|name| view_property(element, name))
        .any(|property| static_expr_i64(&property.value, signatures).is_none())
        || view_property(element, "drag_translate").is_some()
        || view_property(element, "pinch_scale").is_some()
}

fn ui_transform_provider_c_name(name: &str) -> String {
    format!("flux__transform_style_{name}")
}

fn emit_dynamic_transform_setup(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    if !element_has_dynamic_transform(element, signatures) {
        return Ok(());
    }
    let widget_name = format!("flux-ui-{}", element.name);
    let provider = ui_transform_provider_c_name(&element.name);
    out.push_str(&format!(
        "    gtk_widget_set_name({variable}, {});\n    if ({provider} == NULL) {{\n        {provider} = gtk_css_provider_new();\n        gtk_style_context_add_provider_for_display(gtk_widget_get_display({variable}), GTK_STYLE_PROVIDER({provider}), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);\n    }}\n",
        c_string(&widget_name),
    ));
    Ok(())
}

fn emit_dynamic_transform_refresh(
    out: &mut String,
    element: &crate::ast::ViewElement,
    view: &crate::ast::ViewDef,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    if !element_has_dynamic_transform(element, signatures) {
        return Ok(());
    }
    let value = |property_name: &str, fallback: &str| -> Result<String, Diagnostic> {
        view_property(element, property_name)
            .map(|property| ui_expr_c(&property.value, view, signatures))
            .unwrap_or_else(|| Ok(fallback.to_string()))
    };
    let mut translate_x = value("translate_x", "0")?;
    let mut translate_y = value("translate_y", "0")?;
    let rotate_degrees = value("rotate_degrees", "0")?;
    let scale_percent = value("scale_percent", "100")?;
    let mut scale_x_percent = view_property(element, "scale_x_percent")
        .map(|property| ui_expr_c(&property.value, view, signatures))
        .unwrap_or_else(|| Ok(scale_percent.clone()))?;
    let mut scale_y_percent = view_property(element, "scale_y_percent")
        .map(|property| ui_expr_c(&property.value, view, signatures))
        .unwrap_or_else(|| Ok(scale_percent.clone()))?;
    if view_property(element, "drag_translate").is_some() {
        let enabled = ui_gesture_translate_enabled_c_name(&element.name);
        translate_x = format!(
            "({translate_x}) + ({enabled} ? {} : INT64_C(0))",
            ui_gesture_translate_x_c_name(&element.name)
        );
        translate_y = format!(
            "({translate_y}) + ({enabled} ? {} : INT64_C(0))",
            ui_gesture_translate_y_c_name(&element.name)
        );
    }
    if view_property(element, "pinch_scale").is_some() {
        let enabled = ui_gesture_scale_enabled_c_name(&element.name);
        let gesture_scale = ui_gesture_scale_c_name(&element.name);
        scale_x_percent = format!(
            "((double)({scale_x_percent}) * (double)({enabled} ? {gesture_scale} : INT64_C(100)) / 100.0)"
        );
        scale_y_percent = format!(
            "((double)({scale_y_percent}) * (double)({enabled} ? {gesture_scale} : INT64_C(100)) / 100.0)"
        );
    }
    let skew_x_degrees = value("skew_x_degrees", "0")?;
    let skew_y_degrees = value("skew_y_degrees", "0")?;
    let origin_x = value("transform_origin_x_percent", "50")?;
    let origin_y = value("transform_origin_y_percent", "50")?;
    let provider = ui_transform_provider_c_name(&element.name);
    let widget_name = format!("flux-ui-{}", element.name);
    let css_var = format!("flux__transform_css_{}", element.name);
    out.push_str(&format!(
        "    if ({provider} != NULL) {{\n        gchar *{css_var} = g_strdup_printf(\"#{} {{ transform: translate(%lldpx, %lldpx) rotate(%llddeg) scale(%.2f, %.2f) skewX(%llddeg) skewY(%llddeg); transform-origin: %lld%% %lld%%; }}\", (long long)({translate_x}), (long long)({translate_y}), (long long)({rotate_degrees}), ((double)({scale_x_percent}) / 100.0), ((double)({scale_y_percent}) / 100.0), (long long)({skew_x_degrees}), (long long)({skew_y_degrees}), (long long)({origin_x}), (long long)({origin_y}));\n        gtk_css_provider_load_from_data({provider}, {css_var}, -1);\n        g_free({css_var});\n    }}\n",
        widget_name,
    ));
    Ok(())
}

fn static_non_negative_style_i64(
    element: &crate::ast::ViewElement,
    property_name: &str,
    signatures: &Signatures,
) -> Result<Option<i64>, Diagnostic> {
    let value = static_style_i64(element, property_name, signatures)?;
    if let Some(value) = value
        && value < 0
    {
        let span = view_property(element, property_name)
            .expect("style value exists when validation runs")
            .value
            .span;
        return Err(diag(span, &format!("{property_name} must be non-negative")));
    }
    Ok(value)
}

fn static_style_i64(
    element: &crate::ast::ViewElement,
    property_name: &str,
    signatures: &Signatures,
) -> Result<Option<i64>, Diagnostic> {
    let Some(property) = view_property(element, property_name) else {
        return Ok(None);
    };
    let Some(value) = static_expr_i64(&property.value, signatures) else {
        return Err(diag(
            property.value.span,
            &format!("{property_name} must be a compile-time i64 value"),
        ));
    };
    if !(i64::from(i32::MIN)..=i64::from(i32::MAX)).contains(&value) {
        return Err(diag(
            property.value.span,
            &format!("{property_name} must fit within a 32-bit signed integer"),
        ));
    }
    Ok(Some(value))
}

fn emit_element_margins(
    out: &mut String,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    let base = view_property(element, "margin")
        .map(|property| element_margin_value(property, "margin", signatures))
        .transpose()?;
    for (property_name, setter) in [
        ("margin_top", "top"),
        ("margin_bottom", "bottom"),
        ("margin_start", "start"),
        ("margin_end", "end"),
    ] {
        let value = if let Some(property) = view_property(element, property_name) {
            Some(element_margin_value(property, property_name, signatures)?)
        } else {
            base
        };
        if let Some(value) = value {
            out.push_str(&format!(
                "    gtk_widget_set_margin_{setter}({variable}, {value});\n"
            ));
        }
    }
    Ok(())
}

fn element_margin_value(
    property: &crate::ast::ViewProperty,
    property_name: &str,
    signatures: &Signatures,
) -> Result<i64, Diagnostic> {
    let Some(value) = static_expr_i64(&property.value, signatures) else {
        return Err(diag(
            property.value.span,
            &format!("{property_name} must be a compile-time i64 value"),
        ));
    };
    if !(0..=i64::from(i32::MAX)).contains(&value) {
        return Err(diag(
            property.value.span,
            &format!("{property_name} must be between 0 and 2147483647"),
        ));
    }
    Ok(value)
}

fn emit_grid_sizing(
    out: &mut String,
    view: &crate::ast::ViewDef,
    element: &crate::ast::ViewElement,
    variable: &str,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    let column_index = element.column.saturating_sub(1) as usize;
    let row_index = element.row.saturating_sub(1) as usize;
    if view
        .grid
        .columns
        .get(column_index)
        .is_some_and(|track| matches!(track, crate::ast::GridTrack::Fraction(_)))
    {
        out.push_str(&format!("    gtk_widget_set_hexpand({variable}, TRUE);\n"));
    }
    if view
        .grid
        .rows
        .get(row_index)
        .is_some_and(|track| matches!(track, crate::ast::GridTrack::Fraction(_)))
    {
        out.push_str(&format!("    gtk_widget_set_vexpand({variable}, TRUE);\n"));
    }
    let fixed_width = view
        .grid
        .columns
        .get(column_index)
        .and_then(|track| match track {
            crate::ast::GridTrack::Units(value) => Some(i64::from(*value)),
            _ => None,
        });
    let fixed_height = view.grid.rows.get(row_index).and_then(|track| match track {
        crate::ast::GridTrack::Units(value) => Some(i64::from(*value)),
        _ => None,
    });
    let min_width_property = view_property(element, "min_width");
    let min_height_property = view_property(element, "min_height");
    let dynamic_min_width = min_width_property
        .filter(|property| static_expr_i64(&property.value, signatures).is_none());
    let dynamic_min_height = min_height_property
        .filter(|property| static_expr_i64(&property.value, signatures).is_none());
    let min_width = if dynamic_min_width.is_some() {
        None
    } else {
        static_minimum_size(element, "min_width", signatures)?
    };
    let min_height = if dynamic_min_height.is_some() {
        None
    } else {
        static_minimum_size(element, "min_height", signatures)?.or_else(|| {
            (fixed_height.is_none()
                && matches!(
                    element.kind.as_str(),
                    "Button" | "TextInput" | "Toggle" | "Radio"
                ))
            .then_some(40)
        })
    };
    let static_width = match (fixed_width, min_width) {
        (Some(fixed), Some(minimum)) => Some(fixed.max(minimum)),
        (fixed, minimum) => fixed.or(minimum),
    };
    let static_height = match (fixed_height, min_height) {
        (Some(fixed), Some(minimum)) => Some(fixed.max(minimum)),
        (fixed, minimum) => fixed.or(minimum),
    };
    if dynamic_min_width.is_none() && dynamic_min_height.is_none() {
        if static_width.is_some() || static_height.is_some() {
            out.push_str(&format!(
                "    gtk_widget_set_size_request({variable}, {}, {});\n",
                static_width.unwrap_or(-1),
                static_height.unwrap_or(-1),
            ));
        }
        return Ok(());
    }

    let width = if let Some(property) = dynamic_min_width {
        let value = ui_expr_c(&property.value, view, signatures)?;
        let local = format!("flux__min_width_{}", element.name);
        out.push_str(&format!(
            "    int64_t {local} = {value};\n    if ({local} < 1 || {local} > INT32_MAX) {{ fputs(\"Flux runtime error: minWidth must be between 1 and 2147483647\\n\", stderr); abort(); }}\n"
        ));
        fixed_width.map_or_else(
            || local.clone(),
            |fixed| format!("({local} > INT64_C({fixed}) ? {local} : INT64_C({fixed}))"),
        )
    } else {
        static_width.map_or_else(|| "-1".to_string(), |value| value.to_string())
    };
    let height = if let Some(property) = dynamic_min_height {
        let value = ui_expr_c(&property.value, view, signatures)?;
        let local = format!("flux__min_height_{}", element.name);
        out.push_str(&format!(
            "    int64_t {local} = {value};\n    if ({local} < 1 || {local} > INT32_MAX) {{ fputs(\"Flux runtime error: minHeight must be between 1 and 2147483647\\n\", stderr); abort(); }}\n"
        ));
        fixed_height.map_or_else(
            || local.clone(),
            |fixed| format!("({local} > INT64_C({fixed}) ? {local} : INT64_C({fixed}))"),
        )
    } else {
        static_height.map_or_else(|| "-1".to_string(), |value| value.to_string())
    };
    out.push_str(&format!(
        "    gtk_widget_set_size_request({variable}, {width}, {height});\n"
    ));
    Ok(())
}

pub(crate) fn valid_portable_rich_text(markup: &str) -> bool {
    let bytes = markup.as_bytes();
    let mut index = 0;
    let mut stack: Vec<&str> = Vec::new();
    while index < bytes.len() {
        if bytes[index] == b'<' {
            let Some(relative_end) = markup[index + 1..].find('>') else {
                return false;
            };
            let end = index + 1 + relative_end;
            let token = &markup[index + 1..end];
            let (closing, tag) = token
                .strip_prefix('/')
                .map_or((false, token), |tag| (true, tag));
            if !matches!(tag, "b" | "i" | "u") {
                return false;
            }
            if closing {
                if stack.pop() != Some(tag) {
                    return false;
                }
            } else {
                stack.push(tag);
            }
            index = end + 1;
        } else if bytes[index] == b'&' {
            let remainder = &markup[index..];
            if remainder.starts_with("&lt;") || remainder.starts_with("&gt;") {
                index += 4;
            } else if remainder.starts_with("&amp;") {
                index += 5;
            } else {
                return false;
            }
        } else {
            index += 1;
        }
    }
    stack.is_empty()
}

fn static_rich_text_markup(
    element: &crate::ast::ViewElement,
    signatures: &Signatures,
) -> Result<Option<String>, Diagnostic> {
    let Some(property) = view_property(element, "rich_text") else {
        return Ok(None);
    };
    if view_property(element, "text").is_some() {
        return Err(diag(
            property.value.span,
            "Text.richText cannot be combined with Text.text",
        ));
    }
    let Some(markup) = static_expr_str(&property.value, signatures) else {
        return Err(diag(
            property.value.span,
            "Text.richText must be a compile-time string value",
        ));
    };
    if !valid_portable_rich_text(&markup) {
        return Err(diag(
            property.value.span,
            "Text.richText supports balanced <b>, <i>, and <u> tags plus &lt;, &gt;, and &amp; entities",
        ));
    }
    Ok(Some(markup))
}

fn windows_layout_margin_value(
    element: &crate::ast::ViewElement,
    property_name: &str,
    source_name: &str,
    view: &crate::ast::ViewDef,
    signatures: &Signatures,
) -> Result<Option<String>, Diagnostic> {
    let Some(property) = view_property(element, property_name) else {
        return Ok(None);
    };
    if let Some(value) = static_expr_i64(&property.value, signatures) {
        if !(0..=i64::from(i32::MAX)).contains(&value) {
            return Err(diag(
                property.value.span,
                &format!("{source_name} must be between 0 and {}", i32::MAX),
            ));
        }
        return Ok(Some(format!("INT64_C({value})")));
    }
    let value = ui_expr_c(&property.value, view, signatures)?;
    Ok(Some(format!(
        "flux__win_checked_margin(({value}), \"{source_name}\")"
    )))
}

