fn function_params_c(function: &Function, signatures: &Signatures) -> String {
    if function.params.is_empty() {
        "void".to_string()
    } else {
        function
            .params
            .iter()
            .map(|param| {
                format!(
                    "{} {}",
                    c_type(&param.ty, signatures),
                    local_c_name(&param.name)
                )
            })
            .collect::<Vec<_>>()
            .join(", ")
    }
}

fn async_body_prototype(function: &Function, signatures: &Signatures) -> String {
    format!(
        "static {} {}({})",
        c_function_return_type(function, signatures),
        async_body_c_name(&function.name),
        function_params_c(function, signatures)
    )
}

fn async_start_prototype(function: &Function, signatures: &Signatures) -> String {
    format!(
        "static struct {} *{}({})",
        async_task_c_name(&function.name),
        async_start_c_name(&function.name),
        function_params_c(function, signatures)
    )
}

fn async_await_prototype(function: &Function, signatures: &Signatures) -> String {
    format!(
        "static {} {}(struct {} *flux__task)",
        c_function_return_type(function, signatures),
        async_await_c_name(&function.name),
        async_task_c_name(&function.name)
    )
}

fn async_start_cont_prototype(function: &Function, signatures: &Signatures) -> String {
    let visible = if function.params.is_empty() {
        String::new()
    } else {
        format!("{}, ", function_params_c(function, signatures))
    };
    format!(
        "static struct {} *{}({visible}void (*flux__continuation)(void *, void *), void *flux__context)",
        async_task_c_name(&function.name),
        async_start_cont_c_name(&function.name)
    )
}

fn async_resume_prototype(function: &Function) -> String {
    format!(
        "static void {}(void *flux__context, void *flux__completed_child)",
        async_resume_c_name(&function.name)
    )
}

fn async_run_prototype(function: &Function) -> String {
    format!(
        "static void *{}(void *flux__opaque)",
        async_run_c_name(&function.name)
    )
}

fn async_finish_prototype(function: &Function) -> String {
    format!(
        "static void {}(struct {} *flux__task)",
        async_finish_c_name(&function.name),
        async_task_c_name(&function.name)
    )
}

fn async_release_prototype(function: &Function) -> String {
    format!(
        "static void {}(struct {} *flux__task)",
        async_release_c_name(&function.name),
        async_task_c_name(&function.name)
    )
}

#[derive(Clone)]
struct AsyncContinuationPlan {
    cfg_rewrite_facts: CfgRewriteFacts,
    locals: Vec<(String, Type)>,
    resume_locals: Vec<(String, Type)>,
    mutable: HashSet<String>,
    branch_await: Option<AsyncBranchAwaitPlan>,
    nested_branch_await: Option<AsyncNestedBranchAwaitPlan>,
    while_await: Option<AsyncWhileAwaitPlan>,
    for_range_await: Option<AsyncForRangeAwaitPlan>,
    match_await: Option<AsyncMatchAwaitPlan>,
    list_match_await: Option<AsyncListMatchAwaitPlan>,
    coalescing_await: Option<AsyncCoalescingAwaitPlan>,
}

#[derive(Clone)]
struct AsyncBranchAwaitPlan {
    statement_index: usize,
    condition_await: bool,
    then_await_indices: Vec<usize>,
    else_await_indices: Vec<usize>,
}

#[derive(Clone)]
struct AsyncNestedBranchAwaitPlan {
    statement_index: usize,
    then_await_indices: Vec<usize>,
    else_await_indices: Vec<usize>,
}

#[derive(Clone)]
struct AsyncWhileAwaitPlan {
    statement_index: usize,
    condition_await: bool,
    body_await_indices: Vec<usize>,
}

#[derive(Clone)]
struct AsyncForRangeAwaitPlan {
    statement_index: usize,
    start_await: bool,
    end_await: bool,
    body_await_indices: Vec<usize>,
}

#[derive(Clone)]
struct AsyncMatchAwaitPlan {
    statement_index: usize,
    scrutinee_await: bool,
    arm_await_indices: Vec<Vec<usize>>,
}

#[derive(Clone)]
struct AsyncListMatchAwaitPlan {
    statement_index: usize,
    arm_await_indices: Vec<Vec<usize>>,
}

#[derive(Clone)]
struct AsyncCoalescingAwaitPlan {
    statement_indices: Vec<usize>,
}

fn expr_contains_await(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Await(_) => true,
        ExprKind::AnonymousFunction { body, .. }
        | ExprKind::ListSpread { value: body, .. }
        | ExprKind::ListOptional { value: body, .. }
        | ExprKind::Field { base: body, .. }
        | ExprKind::Unary { expr: body, .. } => expr_contains_await(body),
        ExprKind::Call {
            args, named_args, ..
        }
        | ExprKind::QualifiedCall {
            args, named_args, ..
        } => {
            args.iter().any(expr_contains_await)
                || named_args
                    .iter()
                    .any(|argument| expr_contains_await(&argument.value))
        }
        ExprKind::ShellCall { args, .. } => args.iter().any(expr_contains_await),
        ExprKind::Pipe { input, args, .. } => {
            expr_contains_await(input) || args.iter().any(expr_contains_await)
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            items.iter().any(expr_contains_await)
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            expr_contains_await(condition)
                || expr_contains_await(value)
                || else_value.as_deref().is_some_and(expr_contains_await)
        }
        ExprKind::Index { base, index, .. } => {
            expr_contains_await(base) || expr_contains_await(index)
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            expr_contains_await(base)
                || start.as_deref().is_some_and(expr_contains_await)
                || end.as_deref().is_some_and(expr_contains_await)
                || step.as_deref().is_some_and(expr_contains_await)
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            ..
        } => {
            expr_contains_await(value)
                || expr_contains_await(iterable)
                || condition.as_deref().is_some_and(expr_contains_await)
        }
        ExprKind::RecordLiteral { fields } => {
            fields.iter().any(|field| expr_contains_await(&field.value))
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            base.as_deref().is_some_and(expr_contains_await)
                || fields.iter().any(|field| expr_contains_await(&field.value))
        }
        ExprKind::Match { value, arms } => {
            expr_contains_await(value)
                || arms.iter().any(|arm| {
                    arm.guard.as_ref().is_some_and(expr_contains_await)
                        || expr_contains_await(&arm.value)
                })
        }
        ExprKind::ListMatch { value, arms } => {
            expr_contains_await(value)
                || arms.iter().any(|arm| {
                    arm.guard.as_ref().is_some_and(expr_contains_await)
                        || expr_contains_await(&arm.value)
                })
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            expr_contains_await(then_expr)
                || expr_contains_await(cond)
                || expr_contains_await(else_expr)
        }
        ExprKind::Binary { left, right, .. } => {
            expr_contains_await(left) || expr_contains_await(right)
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => false,
    }
}

fn stmt_contains_await(stmt: &Stmt) -> bool {
    match &stmt.kind {
        StmtKind::Let { expr, .. }
        | StmtKind::Var { expr, .. }
        | StmtKind::Assign { expr, .. }
        | StmtKind::AssignMultiDestructure { expr, .. }
        | StmtKind::AssignListDestructure { expr, .. }
        | StmtKind::AssignStructDestructure { expr, .. }
        | StmtKind::LetDestructure { expr, .. }
        | StmtKind::LetMultiDestructure { expr, .. }
        | StmtKind::LetListDestructure { expr, .. }
        | StmtKind::LetStructDestructure { expr, .. }
        | StmtKind::Expr(expr) => expr_contains_await(expr),
        StmtKind::Return(values) => values.iter().any(expr_contains_await),
        StmtKind::Shell { expr, redirect, .. } => {
            expr_contains_await(expr)
                || redirect
                    .as_ref()
                    .is_some_and(|redirect| expr_contains_await(&redirect.path))
        }
        StmtKind::If {
            cond,
            body,
            else_body,
            ..
        } => {
            expr_contains_await(cond)
                || body.iter().any(stmt_contains_await)
                || else_body.iter().any(stmt_contains_await)
        }
        StmtKind::ForRange {
            start, end, body, ..
        } => {
            expr_contains_await(start)
                || expr_contains_await(end)
                || body.iter().any(stmt_contains_await)
        }
        StmtKind::ForEach { iterable, body, .. } => {
            expr_contains_await(iterable) || body.iter().any(stmt_contains_await)
        }
        StmtKind::While { cond, body } => {
            expr_contains_await(cond) || body.iter().any(stmt_contains_await)
        }
        StmtKind::Match { value, arms } => {
            expr_contains_await(value)
                || arms.iter().any(|arm| {
                    arm.guard.as_ref().is_some_and(expr_contains_await)
                        || arm.body.iter().any(stmt_contains_await)
                })
        }
        StmtKind::ListMatch { value, arms } => {
            expr_contains_await(value)
                || arms.iter().any(|arm| {
                    arm.guard.as_ref().is_some_and(expr_contains_await)
                        || arm.body.iter().any(stmt_contains_await)
                })
        }
        StmtKind::Break | StmtKind::Continue => false,
    }
}

fn cfg_direct_await_expr<'a>(
    expr: &Expr,
    rewrite_facts: &'a CfgRewriteFacts,
) -> Option<&'a CfgScalarExpr> {
    let span = source_span_key(expr.span);
    rewrite_facts
        .scalar_exprs
        .get(&span)
        .or_else(|| rewrite_facts.multi_exprs.get(&span))
        .filter(|value| matches!(value.kind, CfgScalarExprKind::Await { .. }))
}

fn direct_await_candidate(stmt: &Stmt) -> Option<&Expr> {
    match &stmt.kind {
        StmtKind::Let { expr, .. }
        | StmtKind::Var { expr, .. }
        | StmtKind::LetStructDestructure { expr, .. }
        | StmtKind::AssignStructDestructure { expr, .. }
        | StmtKind::Assign {
            expr,
            coalescing: false,
            ..
        }
        | StmtKind::LetDestructure {
            expr,
            else_return: false,
            ..
        }
        | StmtKind::LetMultiDestructure {
            expr,
            else_return: false,
            ..
        }
        | StmtKind::AssignMultiDestructure { expr, .. }
        | StmtKind::Expr(expr) => Some(expr),
        StmtKind::Return(values) if values.len() == 1 => Some(&values[0]),
        _ => None,
    }
}

fn direct_await_expr(stmt: &Stmt) -> Option<&Expr> {
    let expr = direct_await_candidate(stmt)?;
    matches!(&expr.kind, ExprKind::Await(_)).then_some(expr)
}

fn direct_await_expr_with_facts<'a>(
    stmt: &'a Stmt,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<&'a Expr> {
    let expr = direct_await_candidate(stmt)?;
    (matches!(&expr.kind, ExprKind::Await(_))
        || cfg_direct_await_expr(expr, rewrite_facts).is_some())
    .then_some(expr)
}

fn expr_contains_await_with_facts(expr: &Expr, rewrite_facts: &CfgRewriteFacts) -> bool {
    expr_contains_await(expr) || cfg_direct_await_expr(expr, rewrite_facts).is_some()
}

fn stmt_contains_await_with_facts(stmt: &Stmt, rewrite_facts: &CfgRewriteFacts) -> bool {
    match &stmt.kind {
        StmtKind::Let { expr, .. }
        | StmtKind::Var { expr, .. }
        | StmtKind::Assign { expr, .. }
        | StmtKind::AssignMultiDestructure { expr, .. }
        | StmtKind::AssignListDestructure { expr, .. }
        | StmtKind::AssignStructDestructure { expr, .. }
        | StmtKind::LetDestructure { expr, .. }
        | StmtKind::LetMultiDestructure { expr, .. }
        | StmtKind::LetListDestructure { expr, .. }
        | StmtKind::LetStructDestructure { expr, .. }
        | StmtKind::Expr(expr) => expr_contains_await_with_facts(expr, rewrite_facts),
        StmtKind::Return(values) => values
            .iter()
            .any(|value| expr_contains_await_with_facts(value, rewrite_facts)),
        StmtKind::Shell { expr, redirect, .. } => {
            expr_contains_await_with_facts(expr, rewrite_facts)
                || redirect.as_ref().is_some_and(|redirect| {
                    expr_contains_await_with_facts(&redirect.path, rewrite_facts)
                })
        }
        StmtKind::If {
            cond,
            body,
            else_body,
            ..
        } => {
            expr_contains_await_with_facts(cond, rewrite_facts)
                || body
                    .iter()
                    .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
                || else_body
                    .iter()
                    .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
        }
        StmtKind::ForRange {
            start, end, body, ..
        } => {
            expr_contains_await_with_facts(start, rewrite_facts)
                || expr_contains_await_with_facts(end, rewrite_facts)
                || body
                    .iter()
                    .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
        }
        StmtKind::ForEach { iterable, body, .. } => {
            expr_contains_await_with_facts(iterable, rewrite_facts)
                || body
                    .iter()
                    .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
        }
        StmtKind::While { cond, body } => {
            expr_contains_await_with_facts(cond, rewrite_facts)
                || body
                    .iter()
                    .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
        }
        StmtKind::Match { value, arms } => {
            expr_contains_await_with_facts(value, rewrite_facts)
                || arms.iter().any(|arm| {
                    arm.guard
                        .as_ref()
                        .is_some_and(|guard| expr_contains_await_with_facts(guard, rewrite_facts))
                        || arm
                            .body
                            .iter()
                            .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
                })
        }
        StmtKind::ListMatch { value, arms } => {
            expr_contains_await_with_facts(value, rewrite_facts)
                || arms.iter().any(|arm| {
                    arm.guard
                        .as_ref()
                        .is_some_and(|guard| expr_contains_await_with_facts(guard, rewrite_facts))
                        || arm
                            .body
                            .iter()
                            .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
                })
        }
        StmtKind::Break | StmtKind::Continue => false,
    }
}

fn coalescing_assignment_await_expr(stmt: &Stmt) -> Option<&Expr> {
    let StmtKind::Assign {
        name,
        expr,
        coalescing: true,
        ..
    } = &stmt.kind
    else {
        return None;
    };
    let ExprKind::Binary { left, op, right } = &expr.kind else {
        return None;
    };
    if !matches!(op, BinOp::Coalesce)
        || !matches!(&left.kind, ExprKind::Var(left_name) if left_name == name)
        || !matches!(&right.kind, ExprKind::Await(_))
    {
        return None;
    }
    Some(right)
}

fn continuation_await_expr(stmt: &Stmt) -> Option<&Expr> {
    direct_await_expr(stmt).or_else(|| coalescing_assignment_await_expr(stmt))
}

fn direct_await_call(expr: &Expr) -> Option<(&str, &[Expr], &[NamedArg])> {
    let ExprKind::Await(awaited) = &expr.kind else {
        return None;
    };
    let ExprKind::Call {
        name,
        args,
        named_args,
    } = &awaited.kind
    else {
        return None;
    };
    if args.iter().any(expr_contains_await)
        || named_args
            .iter()
            .any(|argument| expr_contains_await(&argument.value))
    {
        return None;
    }
    Some((name, args, named_args))
}

fn direct_await_callee<'a>(expr: &'a Expr, rewrite_facts: &'a CfgRewriteFacts) -> Option<&'a str> {
    if let Some(item) = cfg_direct_await_expr(expr, rewrite_facts) {
        if let CfgScalarExprKind::Await { value } = &item.kind {
            return match &value.kind {
                CfgScalarExprKind::Call { callee, .. } => Some(callee.as_str()),
                CfgScalarExprKind::NamedCall { callee, .. } => Some(callee.as_str()),
                _ => None,
            };
        }
    }
    direct_await_call(expr).map(|(name, _, _)| name)
}

fn block_branch_await_indices(
    block: &[Stmt],
    allow_await_after_coalescing: bool,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<Vec<usize>> {
    let mut await_indices = Vec::new();
    let mut saw_coalescing_await = false;
    for (index, stmt) in block.iter().enumerate() {
        if !stmt_contains_await_with_facts(stmt, rewrite_facts) {
            continue;
        }
        if let Some(await_expr) = direct_await_expr_with_facts(stmt, rewrite_facts) {
            if saw_coalescing_await && !allow_await_after_coalescing {
                return None;
            }
            direct_await_callee(await_expr, rewrite_facts)?;
            await_indices.push(index);
            continue;
        }
        let await_expr = coalescing_assignment_await_expr(stmt)?;
        direct_await_call(await_expr)?;
        if saw_coalescing_await && !allow_await_after_coalescing {
            return None;
        }
        saw_coalescing_await = true;
        await_indices.push(index);
    }
    Some(await_indices)
}

fn async_branch_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncBranchAwaitPlan> {
    let await_statements = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    let [statement_index] = await_statements.as_slice() else {
        return None;
    };
    let statement_index = *statement_index;
    let StmtKind::If {
        cond,
        binding: _,
        body,
        else_body,
        ..
    } = &function.body[statement_index].kind
    else {
        return None;
    };
    let condition_await = expr_contains_await_with_facts(cond, rewrite_facts);
    if condition_await {
        direct_await_callee(cond, rewrite_facts)?;
    }
    let then_await_indices = block_branch_await_indices(body, true, rewrite_facts)?;
    let else_await_indices = block_branch_await_indices(else_body, true, rewrite_facts)?;
    if !condition_await && then_await_indices.is_empty() && else_await_indices.is_empty() {
        None
    } else {
        Some(AsyncBranchAwaitPlan {
            statement_index,
            condition_await,
            then_await_indices,
            else_await_indices,
        })
    }
}

fn async_nested_branch_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncNestedBranchAwaitPlan> {
    let await_statements = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    let [statement_index] = await_statements.as_slice() else {
        return None;
    };
    let statement_index = *statement_index;
    let StmtKind::If {
        cond,
        binding,
        body,
        else_body,
        ..
    } = &function.body[statement_index].kind
    else {
        return None;
    };
    if binding.is_some()
        || expr_contains_await_with_facts(cond, rewrite_facts)
        || body
            .iter()
            .any(|stmt| stmt_contains_await_with_facts(stmt, rewrite_facts))
        || else_body.len() != 1
    {
        return None;
    }
    let StmtKind::If {
        cond: nested_cond,
        body: nested_body,
        else_body: nested_else_body,
        ..
    } = &else_body[0].kind
    else {
        return None;
    };
    if !expr_contains_await_with_facts(nested_cond, rewrite_facts) {
        return None;
    }
    direct_await_callee(nested_cond, rewrite_facts)?;
    let then_await_indices = block_branch_await_indices(nested_body, true, rewrite_facts)?;
    let else_await_indices = block_branch_await_indices(nested_else_body, true, rewrite_facts)?;
    Some(AsyncNestedBranchAwaitPlan {
        statement_index,
        then_await_indices,
        else_await_indices,
    })
}

fn async_while_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncWhileAwaitPlan> {
    let await_statements = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    let [statement_index] = await_statements.as_slice() else {
        return None;
    };
    let statement_index = *statement_index;
    let StmtKind::While { cond, body } = &function.body[statement_index].kind else {
        return None;
    };
    let condition_await = expr_contains_await_with_facts(cond, rewrite_facts);
    if condition_await {
        direct_await_callee(cond, rewrite_facts)?;
    }
    let body_await_indices = block_branch_await_indices(body, true, rewrite_facts)?;
    if !condition_await && body_await_indices.is_empty() {
        None
    } else {
        Some(AsyncWhileAwaitPlan {
            statement_index,
            condition_await,
            body_await_indices,
        })
    }
}

fn async_for_range_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncForRangeAwaitPlan> {
    let await_statements = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    let [statement_index] = await_statements.as_slice() else {
        return None;
    };
    let statement_index = *statement_index;
    let StmtKind::ForRange {
        start, end, body, ..
    } = &function.body[statement_index].kind
    else {
        return None;
    };
    let start_await = expr_contains_await_with_facts(start, rewrite_facts);
    if start_await {
        direct_await_callee(start, rewrite_facts)?;
    }
    let end_await = expr_contains_await_with_facts(end, rewrite_facts);
    if end_await {
        direct_await_callee(end, rewrite_facts)?;
    }
    let body_await_indices = block_branch_await_indices(body, true, rewrite_facts)?;
    if !start_await && !end_await && body_await_indices.is_empty() {
        None
    } else {
        Some(AsyncForRangeAwaitPlan {
            statement_index,
            start_await,
            end_await,
            body_await_indices,
        })
    }
}

fn async_coalescing_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncCoalescingAwaitPlan> {
    let statement_indices = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    statement_indices.first()?;
    let mut saw_coalescing = false;
    for &statement_index in &statement_indices {
        let stmt = &function.body[statement_index];
        let await_expr = direct_await_expr_with_facts(stmt, rewrite_facts)
            .or_else(|| coalescing_assignment_await_expr(stmt))?;
        direct_await_callee(await_expr, rewrite_facts)?;
        saw_coalescing |= coalescing_assignment_await_expr(stmt).is_some();
    }
    saw_coalescing.then_some(AsyncCoalescingAwaitPlan { statement_indices })
}

fn async_match_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncMatchAwaitPlan> {
    let await_statements = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    let [statement_index] = await_statements.as_slice() else {
        return None;
    };
    let statement_index = *statement_index;
    let StmtKind::Match { value, arms } = &function.body[statement_index].kind else {
        return None;
    };
    if arms.is_empty() {
        return None;
    }
    let scrutinee_await = expr_contains_await_with_facts(value, rewrite_facts);
    if scrutinee_await {
        direct_await_callee(value, rewrite_facts)?;
    }
    let mut arm_await_indices = Vec::with_capacity(arms.len());
    let mut any_await = scrutinee_await;
    for arm in arms {
        if arm
            .guard
            .as_ref()
            .is_some_and(|guard| expr_contains_await_with_facts(guard, rewrite_facts))
        {
            return None;
        }
        let await_indices = block_branch_await_indices(&arm.body, true, rewrite_facts)?;
        any_await |= !await_indices.is_empty();
        arm_await_indices.push(await_indices);
    }
    any_await.then_some(AsyncMatchAwaitPlan {
        statement_index,
        scrutinee_await,
        arm_await_indices,
    })
}

fn async_list_match_await_plan(
    function: &Function,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<AsyncListMatchAwaitPlan> {
    let await_statements = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| {
            stmt_contains_await_with_facts(stmt, rewrite_facts).then_some(index)
        })
        .collect::<Vec<_>>();
    let [statement_index] = await_statements.as_slice() else {
        return None;
    };
    let statement_index = *statement_index;
    let StmtKind::ListMatch { value, arms } = &function.body[statement_index].kind else {
        return None;
    };
    if expr_contains_await_with_facts(value, rewrite_facts) || arms.is_empty() {
        return None;
    }
    let mut arm_await_indices = Vec::with_capacity(arms.len());
    let mut any_await = false;
    for arm in arms {
        if arm
            .guard
            .as_ref()
            .is_some_and(|guard| expr_contains_await_with_facts(guard, rewrite_facts))
        {
            return None;
        }
        let await_indices = block_branch_await_indices(&arm.body, true, rewrite_facts)?;
        any_await |= !await_indices.is_empty();
        arm_await_indices.push(await_indices);
    }
    any_await.then_some(AsyncListMatchAwaitPlan {
        statement_index,
        arm_await_indices,
    })
}

fn async_continuation_state_type(signatures: &Signatures, ty: &Type) -> bool {
    signatures.is_copy_type(ty) && signatures.is_send_type(ty)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AsyncLocalTailEffect {
    None,
    Overwritten,
    Read,
}

fn async_struct_assignment_targets_name(
    fields: &[crate::ast::StructPatternField],
    name: &str,
) -> bool {
    fields.iter().any(|field| {
        field.binding.name == name
            || field
                .nested
                .as_ref()
                .is_some_and(|nested| async_struct_assignment_targets_name(&nested.fields, name))
    })
}

fn async_block_local_tail_effect(block: &[Stmt], name: &str) -> AsyncLocalTailEffect {
    for stmt in block {
        match async_stmt_local_tail_effect(stmt, name) {
            AsyncLocalTailEffect::None => {}
            effect => return effect,
        }
    }
    AsyncLocalTailEffect::None
}

fn async_stmt_local_tail_effect(stmt: &Stmt, name: &str) -> AsyncLocalTailEffect {
    let expr_effect = |expr: &Expr| {
        let mut reads = HashSet::new();
        typecheck::collect_expr_reads(expr, &mut reads);
        reads
            .contains(name)
            .then_some(AsyncLocalTailEffect::Read)
            .unwrap_or(AsyncLocalTailEffect::None)
    };

    match &stmt.kind {
        StmtKind::Assign {
            name: target,
            expr,
            coalescing,
            ..
        } if target == name => {
            if *coalescing || expr_effect(expr) == AsyncLocalTailEffect::Read {
                AsyncLocalTailEffect::Read
            } else {
                AsyncLocalTailEffect::Overwritten
            }
        }
        StmtKind::AssignMultiDestructure { bindings, expr } => {
            if expr_effect(expr) == AsyncLocalTailEffect::Read {
                AsyncLocalTailEffect::Read
            } else if bindings.iter().any(|binding| binding.name == name) {
                AsyncLocalTailEffect::Overwritten
            } else {
                AsyncLocalTailEffect::None
            }
        }
        StmtKind::AssignListDestructure {
            bindings,
            rest,
            expr,
        } => {
            if expr_effect(expr) == AsyncLocalTailEffect::Read {
                AsyncLocalTailEffect::Read
            } else if bindings.iter().any(|binding| binding.name == name)
                || rest.as_ref().is_some_and(|rest| rest.binding.name == name)
            {
                AsyncLocalTailEffect::Overwritten
            } else {
                AsyncLocalTailEffect::None
            }
        }
        StmtKind::AssignStructDestructure { fields, expr, .. } => {
            if expr_effect(expr) == AsyncLocalTailEffect::Read {
                AsyncLocalTailEffect::Read
            } else if async_struct_assignment_targets_name(fields, name) {
                AsyncLocalTailEffect::Overwritten
            } else {
                AsyncLocalTailEffect::None
            }
        }
        StmtKind::If {
            cond,
            body,
            else_body,
            ..
        } => {
            if expr_effect(cond) == AsyncLocalTailEffect::Read {
                return AsyncLocalTailEffect::Read;
            }
            let then_effect = async_block_local_tail_effect(body, name);
            let else_effect = async_block_local_tail_effect(else_body, name);
            if then_effect == AsyncLocalTailEffect::Read
                || else_effect == AsyncLocalTailEffect::Read
            {
                AsyncLocalTailEffect::Read
            } else if !else_body.is_empty()
                && then_effect == AsyncLocalTailEffect::Overwritten
                && else_effect == AsyncLocalTailEffect::Overwritten
            {
                AsyncLocalTailEffect::Overwritten
            } else {
                AsyncLocalTailEffect::None
            }
        }
        _ => {
            let mut reads = HashSet::new();
            typecheck::collect_block_reads(std::slice::from_ref(stmt), &mut reads);
            if reads.contains(name) {
                AsyncLocalTailEffect::Read
            } else {
                AsyncLocalTailEffect::None
            }
        }
    }
}

fn async_local_crosses_straight_line_suspend(
    function: &Function,
    declaration_index: usize,
    name: &str,
) -> bool {
    for await_index in declaration_index + 1..function.body.len() {
        if !stmt_contains_await(&function.body[await_index]) {
            continue;
        }
        if async_block_local_tail_effect(&function.body[await_index + 1..], name)
            == AsyncLocalTailEffect::Read
        {
            return true;
        }
    }
    false
}

fn collect_async_saved_locals(
    block: &[Stmt],
    through_index: usize,
    outer_env: &HashMap<String, Type>,
    signatures: &Signatures,
    locals: &mut BTreeMap<String, Type>,
    mutable: &mut HashSet<String>,
) -> Option<()> {
    let mut env = outer_env.clone();
    for stmt in block.iter().take(through_index + 1) {
        match &stmt.kind {
            StmtKind::Let { name, ty, .. } => {
                let ty = signatures.canonical_type(ty);
                if !async_continuation_state_type(signatures, &ty) {
                    return None;
                }
                if locals.get(name).is_some_and(|existing| existing != &ty) {
                    return None;
                }
                env.insert(name.clone(), ty.clone());
                locals.insert(name.clone(), ty);
            }
            StmtKind::Var { name, ty, .. } => {
                let ty = signatures.canonical_type(ty);
                if !async_continuation_state_type(signatures, &ty) {
                    return None;
                }
                if locals.get(name).is_some_and(|existing| existing != &ty) {
                    return None;
                }
                env.insert(name.clone(), ty.clone());
                locals.insert(name.clone(), ty);
                mutable.insert(name.clone());
            }
            StmtKind::LetDestructure {
                bindings,
                mutable: is_mutable,
                ..
            } => {
                for binding in bindings {
                    if binding.name == "_" {
                        continue;
                    }
                    let ty = signatures.canonical_type(&binding.ty);
                    if !async_continuation_state_type(signatures, &ty)
                        || locals
                            .get(&binding.name)
                            .is_some_and(|existing| existing != &ty)
                    {
                        return None;
                    }
                    env.insert(binding.name.clone(), ty.clone());
                    locals.insert(binding.name.clone(), ty);
                    if *is_mutable {
                        mutable.insert(binding.name.clone());
                    }
                }
            }
            StmtKind::LetMultiDestructure {
                bindings,
                expr,
                mutable: is_mutable,
                ..
            } => {
                let (actuals, _) =
                    typecheck::positional_destructure_types_of_expr(expr, &env, signatures).ok()?;
                if actuals.len() != bindings.len() {
                    return None;
                }
                for (binding, ty) in bindings.iter().zip(actuals) {
                    if binding.name == "_" {
                        continue;
                    }
                    let ty = signatures.canonical_type(&ty);
                    if !async_continuation_state_type(signatures, &ty)
                        || locals
                            .get(&binding.name)
                            .is_some_and(|existing| existing != &ty)
                    {
                        return None;
                    }
                    env.insert(binding.name.clone(), ty.clone());
                    locals.insert(binding.name.clone(), ty);
                    if *is_mutable {
                        mutable.insert(binding.name.clone());
                    }
                }
            }
            StmtKind::LetStructDestructure {
                struct_name,
                fields,
                mutable: is_mutable,
                ..
            } => {
                collect_async_struct_fields_bindings(
                    struct_name,
                    fields,
                    signatures,
                    &mut env,
                    locals,
                )?;
                if *is_mutable {
                    mark_async_struct_pattern_mutable(fields, mutable);
                }
            }
            StmtKind::LetListDestructure { .. } => return None,
            _ => {}
        }
    }
    Some(())
}

fn collect_async_struct_fields_bindings(
    struct_name: &str,
    fields: &[crate::ast::StructPatternField],
    signatures: &Signatures,
    env: &mut HashMap<String, Type>,
    locals: &mut BTreeMap<String, Type>,
) -> Option<()> {
    let definition = signatures.struct_type(struct_name)?;
    for field in fields {
        let field_signature = definition.field(&field.field)?;
        if let Some(nested) = &field.nested {
            collect_async_struct_pattern_bindings(nested, signatures, env, locals)?;
            continue;
        }
        if field.binding.name == "_" {
            continue;
        }
        let ty = signatures.canonical_type(&field_signature.ty);
        if !async_continuation_state_type(signatures, &ty)
            || locals
                .get(&field.binding.name)
                .is_some_and(|existing| existing != &ty)
        {
            return None;
        }
        env.insert(field.binding.name.clone(), ty.clone());
        locals.insert(field.binding.name.clone(), ty);
    }
    Some(())
}

fn collect_async_struct_pattern_bindings(
    pattern: &crate::ast::StructPattern,
    signatures: &Signatures,
    env: &mut HashMap<String, Type>,
    locals: &mut BTreeMap<String, Type>,
) -> Option<()> {
    collect_async_struct_fields_bindings(
        &pattern.struct_name,
        &pattern.fields,
        signatures,
        env,
        locals,
    )
}

fn mark_async_struct_pattern_mutable(
    fields: &[crate::ast::StructPatternField],
    mutable: &mut HashSet<String>,
) {
    for field in fields {
        if let Some(nested) = &field.nested {
            mark_async_struct_pattern_mutable(&nested.fields, mutable);
        } else if field.binding.name != "_" {
            mutable.insert(field.binding.name.clone());
        }
    }
}

fn collect_async_list_match_arm_bindings(
    arm: &crate::ast::ListMatchArm,
    element: &Type,
    signatures: &Signatures,
    env: &mut HashMap<String, Type>,
    locals: &mut BTreeMap<String, Type>,
) -> Option<()> {
    let ListMatchPattern::List { bindings, rest, .. } = &arm.pattern else {
        return Some(());
    };
    let element = signatures.canonical_type(element);
    if !async_continuation_state_type(signatures, &element) {
        return None;
    }
    for binding in bindings {
        if binding.name == "_" {
            continue;
        }
        if locals
            .get(&binding.name)
            .is_some_and(|existing| existing != &element)
        {
            return None;
        }
        env.insert(binding.name.clone(), element.clone());
        locals.insert(binding.name.clone(), element.clone());
    }
    if let Some(rest) = rest
        && rest.binding.name != "_"
    {
        return None;
    }
    Some(())
}

fn collect_async_match_arm_bindings(
    arm: &crate::ast::MatchArm,
    signatures: &Signatures,
    env: &mut HashMap<String, Type>,
    locals: &mut BTreeMap<String, Type>,
) -> Option<()> {
    let definition = signatures.enum_type(&arm.enum_name)?;
    let variant = definition.variant(&arm.variant)?;
    if variant.payloads.len() != arm.patterns.len() {
        return None;
    }
    for (pattern, payload_ty) in arm.patterns.iter().zip(&variant.payloads) {
        match pattern {
            MatchPattern::Binding(binding) => {
                if binding.name == "_" {
                    continue;
                }
                let ty = signatures.canonical_type(payload_ty);
                if !async_continuation_state_type(signatures, &ty)
                    || locals
                        .get(&binding.name)
                        .is_some_and(|existing| existing != &ty)
                {
                    return None;
                }
                env.insert(binding.name.clone(), ty.clone());
                locals.insert(binding.name.clone(), ty);
            }
            MatchPattern::Struct(pattern) => {
                collect_async_struct_pattern_bindings(pattern, signatures, env, locals)?;
            }
            MatchPattern::Relational(_) | MatchPattern::Logical { .. } => {}
        }
    }
    Some(())
}

fn async_continuation_plan(
    function: &Function,
    signatures: &Signatures,
    cfg: &crate::ir::ControlFlowGraph,
) -> Option<AsyncContinuationPlan> {
    let cfg_rewrite_facts = cfg_rewrite_facts(cfg);
    if !function.asynchronous
        || !function
            .body
            .iter()
            .any(|stmt| stmt_contains_await_with_facts(stmt, &cfg_rewrite_facts))
    {
        return None;
    }
    if function
        .params
        .iter()
        .any(|param| !async_continuation_state_type(signatures, &param.ty))
    {
        return None;
    }
    let last_await_statement_index = function
        .body
        .iter()
        .rposition(|stmt| stmt_contains_await_with_facts(stmt, &cfg_rewrite_facts))?;

    let mut env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    env.insert("flux__async_context".to_string(), Type::Bool);
    let mut locals = BTreeMap::<String, Type>::new();
    let mut resume_locals = BTreeMap::<String, Type>::new();
    let mut mutable = HashSet::new();
    let branch_await = async_branch_await_plan(function, &cfg_rewrite_facts);
    let nested_branch_await = branch_await
        .is_none()
        .then(|| async_nested_branch_await_plan(function, &cfg_rewrite_facts))
        .flatten();
    let while_await = branch_await
        .is_none()
        .then_some(())
        .filter(|_| nested_branch_await.is_none())
        .and_then(|_| async_while_await_plan(function, &cfg_rewrite_facts));
    let for_range_await = branch_await
        .is_none()
        .then_some(())
        .filter(|_| while_await.is_none())
        .and_then(|_| async_for_range_await_plan(function, &cfg_rewrite_facts));
    let match_await = branch_await
        .is_none()
        .then_some(())
        .filter(|_| while_await.is_none() && for_range_await.is_none())
        .and_then(|_| async_match_await_plan(function, &cfg_rewrite_facts));
    let list_match_await = branch_await
        .is_none()
        .then_some(())
        .filter(|_| while_await.is_none() && for_range_await.is_none() && match_await.is_none())
        .and_then(|_| async_list_match_await_plan(function, &cfg_rewrite_facts));
    let coalescing_await = branch_await
        .is_none()
        .then_some(())
        .filter(|_| {
            while_await.is_none()
                && for_range_await.is_none()
                && match_await.is_none()
                && list_match_await.is_none()
        })
        .and_then(|_| async_coalescing_await_plan(function, &cfg_rewrite_facts));
    let straight_line_awaits = branch_await.is_none()
        && nested_branch_await.is_none()
        && while_await.is_none()
        && for_range_await.is_none()
        && match_await.is_none()
        && list_match_await.is_none()
        && coalescing_await.is_none();
    if function.body.iter().any(|stmt| {
        stmt_contains_await_with_facts(stmt, &cfg_rewrite_facts)
            && direct_await_expr_with_facts(stmt, &cfg_rewrite_facts).is_none()
    }) && branch_await.is_none()
        && nested_branch_await.is_none()
        && while_await.is_none()
        && for_range_await.is_none()
        && match_await.is_none()
        && list_match_await.is_none()
        && coalescing_await.is_none()
    {
        return None;
    }

    for (stmt_index, stmt) in function.body.iter().enumerate() {
        let specially_lowered = branch_await
            .as_ref()
            .is_some_and(|branch| branch.statement_index == stmt_index)
            || nested_branch_await
                .as_ref()
                .is_some_and(|branch| branch.statement_index == stmt_index)
            || while_await
                .as_ref()
                .is_some_and(|while_plan| while_plan.statement_index == stmt_index)
            || for_range_await
                .as_ref()
                .is_some_and(|for_plan| for_plan.statement_index == stmt_index)
            || match_await
                .as_ref()
                .is_some_and(|match_plan| match_plan.statement_index == stmt_index)
            || list_match_await
                .as_ref()
                .is_some_and(|match_plan| match_plan.statement_index == stmt_index)
            || coalescing_await.as_ref().is_some_and(|coalescing_plan| {
                coalescing_plan.statement_indices.contains(&stmt_index)
            });
        if stmt_contains_await_with_facts(stmt, &cfg_rewrite_facts) && !specially_lowered {
            let await_expr = direct_await_expr_with_facts(stmt, &cfg_rewrite_facts)?;
            let callee = direct_await_callee(await_expr, &cfg_rewrite_facts)?;
            let signature = signatures.get(callee)?;
            if !signature.asynchronous {
                return None;
            }
        }

        if nested_branch_await
            .as_ref()
            .is_some_and(|branch| branch.statement_index == stmt_index)
        {
            let StmtKind::If {
                cond, else_body, ..
            } = &stmt.kind
            else {
                return None;
            };
            let mut nested_outer_env = env.clone();
            if let Some((name, inner, false)) =
                optional_presence_promotion(cond, &env, &mutable, signatures)
            {
                nested_outer_env.insert(name, inner);
            }
            let [nested_stmt] = else_body.as_slice() else {
                return None;
            };
            let StmtKind::If {
                cond: nested_cond,
                binding: nested_binding,
                body: nested_body,
                else_body: nested_else_body,
                ..
            } = &nested_stmt.kind
            else {
                return None;
            };
            let mut nested_then_env = nested_outer_env.clone();
            if let Some(binding) = nested_binding {
                let Type::Optional(inner) = signatures.canonical_type(
                    &typecheck::type_of_expr(nested_cond, &nested_outer_env, signatures).ok()?,
                ) else {
                    return None;
                };
                let inner = signatures.canonical_type(&inner);
                if !async_continuation_state_type(signatures, &inner) {
                    return None;
                }
                if binding.name != "_" {
                    if locals
                        .get(&binding.name)
                        .is_some_and(|existing| existing != &inner)
                    {
                        return None;
                    }
                    nested_then_env.insert(binding.name.clone(), inner.clone());
                    locals.insert(binding.name.clone(), inner);
                }
            }
            let nested_plan = nested_branch_await.as_ref()?;
            if let Some(last_await) = nested_plan.then_await_indices.last().copied() {
                collect_async_saved_locals(
                    nested_body,
                    last_await,
                    &nested_then_env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
            if let Some(last_await) = nested_plan.else_await_indices.last().copied() {
                collect_async_saved_locals(
                    nested_else_body,
                    last_await,
                    &nested_outer_env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
        }
        if let Some(branch) = branch_await
            .as_ref()
            .filter(|branch| branch.statement_index == stmt_index)
        {
            let StmtKind::If {
                cond,
                binding,
                body,
                else_body,
                ..
            } = &stmt.kind
            else {
                return None;
            };
            let mut then_env = env.clone();
            if let Some(binding) = binding
                && binding.name != "_"
            {
                let condition_ty = typecheck::type_of_expr(cond, &env, signatures).ok()?;
                let Type::Optional(inner) = signatures.canonical_type(&condition_ty) else {
                    return None;
                };
                let inner = signatures.canonical_type(&inner);
                if !async_continuation_state_type(signatures, &inner)
                    || locals
                        .get(&binding.name)
                        .is_some_and(|existing| existing != &inner)
                {
                    return None;
                }
                then_env.insert(binding.name.clone(), inner.clone());
                locals.insert(binding.name.clone(), inner);
            }
            if let Some(last_await) = branch.then_await_indices.last().copied() {
                collect_async_saved_locals(
                    body,
                    last_await,
                    &then_env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
            if let Some(last_await) = branch.else_await_indices.last().copied() {
                collect_async_saved_locals(
                    else_body,
                    last_await,
                    &env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
        }
        if let Some(while_plan) = while_await
            .as_ref()
            .filter(|while_plan| while_plan.statement_index == stmt_index)
        {
            let StmtKind::While { body, .. } = &stmt.kind else {
                return None;
            };
            if let Some(last_await) = while_plan.body_await_indices.last().copied() {
                collect_async_saved_locals(
                    body,
                    last_await,
                    &env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
        }
        if let Some(for_plan) = for_range_await
            .as_ref()
            .filter(|for_plan| for_plan.statement_index == stmt_index)
        {
            let StmtKind::ForRange { name, body, .. } = &stmt.kind else {
                return None;
            };
            let mut body_env = env.clone();
            body_env.insert(name.clone(), Type::I64);
            locals.insert(name.clone(), Type::I64);
            if let Some(last_await) = for_plan.body_await_indices.last().copied() {
                collect_async_saved_locals(
                    body,
                    last_await,
                    &body_env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
        }
        if let Some(match_plan) = match_await
            .as_ref()
            .filter(|match_plan| match_plan.statement_index == stmt_index)
        {
            let StmtKind::Match { arms, .. } = &stmt.kind else {
                return None;
            };
            for (arm, await_indices) in arms.iter().zip(&match_plan.arm_await_indices) {
                let Some(last_await) = await_indices.last().copied() else {
                    continue;
                };
                let mut arm_env = env.clone();
                collect_async_match_arm_bindings(arm, signatures, &mut arm_env, &mut locals)?;
                collect_async_saved_locals(
                    &arm.body,
                    last_await,
                    &arm_env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
        }
        if let Some(match_plan) = list_match_await
            .as_ref()
            .filter(|match_plan| match_plan.statement_index == stmt_index)
        {
            let StmtKind::ListMatch { value, arms } = &stmt.kind else {
                return None;
            };
            let Type::List(element) = typecheck::type_of_expr(value, &env, signatures).ok()? else {
                return None;
            };
            for (arm, await_indices) in arms.iter().zip(&match_plan.arm_await_indices) {
                let Some(last_await) = await_indices.last().copied() else {
                    continue;
                };
                let mut arm_env = env.clone();
                collect_async_list_match_arm_bindings(
                    arm,
                    &element,
                    signatures,
                    &mut arm_env,
                    &mut locals,
                )?;
                collect_async_saved_locals(
                    &arm.body,
                    last_await,
                    &arm_env,
                    signatures,
                    &mut locals,
                    &mut mutable,
                )?;
            }
        }

        if stmt_index > last_await_statement_index {
            continue;
        }

        match &stmt.kind {
            StmtKind::Let { name, ty, .. } => {
                let ty = signatures.canonical_type(ty);
                let save = async_continuation_state_type(signatures, &ty);
                if !save
                    && (!straight_line_awaits
                        || async_local_crosses_straight_line_suspend(function, stmt_index, name))
                {
                    return None;
                }
                env.insert(name.clone(), ty.clone());
                if save {
                    locals.insert(name.clone(), ty);
                }
            }
            StmtKind::Var { name, ty, .. } => {
                let ty = signatures.canonical_type(ty);
                let save = async_continuation_state_type(signatures, &ty);
                if !save
                    && (!straight_line_awaits
                        || async_local_crosses_straight_line_suspend(function, stmt_index, name))
                {
                    return None;
                }
                env.insert(name.clone(), ty.clone());
                if save {
                    locals.insert(name.clone(), ty);
                    mutable.insert(name.clone());
                } else {
                    resume_locals.insert(name.clone(), ty);
                }
            }
            StmtKind::LetDestructure {
                bindings,
                mutable: is_mutable,
                ..
            } => {
                for binding in bindings {
                    if binding.name == "_" {
                        continue;
                    }
                    let ty = signatures.canonical_type(&binding.ty);
                    let save = async_continuation_state_type(signatures, &ty);
                    if !save
                        && (!straight_line_awaits
                            || async_local_crosses_straight_line_suspend(
                                function,
                                stmt_index,
                                &binding.name,
                            ))
                    {
                        return None;
                    }
                    env.insert(binding.name.clone(), ty.clone());
                    if save {
                        locals.insert(binding.name.clone(), ty);
                        if *is_mutable {
                            mutable.insert(binding.name.clone());
                        }
                    }
                }
            }
            StmtKind::LetMultiDestructure {
                bindings,
                expr,
                mutable: is_mutable,
                ..
            } => {
                let (actuals, _) =
                    typecheck::positional_destructure_types_of_expr(expr, &env, signatures).ok()?;
                if actuals.len() != bindings.len() {
                    return None;
                }
                for (binding, ty) in bindings.iter().zip(actuals) {
                    if binding.name == "_" {
                        continue;
                    }
                    let ty = signatures.canonical_type(&ty);
                    let save = async_continuation_state_type(signatures, &ty);
                    if !save
                        && (!straight_line_awaits
                            || async_local_crosses_straight_line_suspend(
                                function,
                                stmt_index,
                                &binding.name,
                            ))
                    {
                        return None;
                    }
                    env.insert(binding.name.clone(), ty.clone());
                    if save {
                        locals.insert(binding.name.clone(), ty);
                        if *is_mutable {
                            mutable.insert(binding.name.clone());
                        }
                    }
                }
            }
            StmtKind::LetStructDestructure {
                struct_name,
                fields,
                mutable: is_mutable,
                ..
            } => {
                collect_async_struct_fields_bindings(
                    struct_name,
                    fields,
                    signatures,
                    &mut env,
                    &mut locals,
                )?;
                if *is_mutable {
                    mark_async_struct_pattern_mutable(fields, &mut mutable);
                }
            }
            StmtKind::LetListDestructure { .. } => return None,
            _ => {}
        }
    }

    Some(AsyncContinuationPlan {
        cfg_rewrite_facts,
        locals: locals.into_iter().collect(),
        resume_locals: resume_locals.into_iter().collect(),
        mutable,
        branch_await,
        nested_branch_await,
        while_await,
        for_range_await,
        match_await,
        list_match_await,
        coalescing_await,
    })
}

fn function_prototype(function: &Function, signatures: &Signatures) -> String {
    let ret = if function.name == "main" {
        "int".to_string()
    } else {
        c_function_return_type(function, signatures)
    };
    let params = function_params_c(function, signatures);
    if let Some(symbol) = &function.foreign_symbol {
        return format!("extern {ret} {symbol}({params})");
    }
    let linkage = if function.name != "main" && !function.public {
        "static inline "
    } else {
        ""
    };
    format!(
        "{linkage}{ret} {}({params})",
        function_c_name(&function.name)
    )
}

fn anonymous_function_c_name(span: SourceSpan) -> String {
    format!(
        "flux__lambda_{}_{}_{}",
        span.source_id.value(),
        span.line,
        span.column
    )
}

fn partial_application_c_name(span: SourceSpan) -> String {
    format!(
        "flux__bind_{}_{}_{}",
        span.source_id.value(),
        span.line,
        span.column
    )
}

fn partial_application_prototype(
    expr: &Expr,
    signatures: &Signatures,
) -> Result<String, Diagnostic> {
    let ExprKind::Call {
        name,
        args,
        named_args,
    } = &expr.kind
    else {
        return Err(diag(
            expr.span,
            "expected bind expression during code generation",
        ));
    };
    if name != "bind" || !named_args.is_empty() || args.len() < 2 {
        return Err(diag(
            expr.span,
            "invalid bind expression reached code generation",
        ));
    }
    let ty = type_of_expr(expr, &HashMap::new(), signatures)?;
    let Type::Function { params, returns } = ty else {
        return Err(diag(expr.span, "bind did not produce a function type"));
    };
    let ret = returns
        .first()
        .map(|ty| c_type(ty, signatures))
        .unwrap_or_else(|| "void".to_string());
    let params_text = if params.is_empty() {
        "void".to_string()
    } else {
        params
            .iter()
            .enumerate()
            .map(|(index, ty)| format!("{} flux__bound_arg_{index}", c_type(ty, signatures)))
            .collect::<Vec<_>>()
            .join(", ")
    };
    Ok(format!(
        "static {ret} {}({params_text})",
        partial_application_c_name(expr.span)
    ))
}

fn function_helper_prototype(expr: &Expr, signatures: &Signatures) -> Result<String, Diagnostic> {
    match &expr.kind {
        ExprKind::AnonymousFunction { .. } => anonymous_function_prototype(expr, signatures),
        ExprKind::Call { name, .. } if name == "bind" => {
            partial_application_prototype(expr, signatures)
        }
        _ => Err(diag(
            expr.span,
            "expected function helper during code generation",
        )),
    }
}

fn anonymous_function_prototype(
    expr: &Expr,
    signatures: &Signatures,
) -> Result<String, Diagnostic> {
    let ExprKind::AnonymousFunction { params, .. } = &expr.kind else {
        return Err(diag(
            expr.span,
            "expected anonymous function during code generation",
        ));
    };
    let ty = type_of_expr(expr, &HashMap::new(), signatures)?;
    let Type::Function {
        params: param_types,
        returns,
    } = ty
    else {
        return Err(diag(
            expr.span,
            "anonymous function did not produce a function type",
        ));
    };
    if returns.len() > 1 {
        return Err(diag(
            expr.span,
            "anonymous functions currently support zero or one return value",
        ));
    }
    let ret = returns
        .first()
        .map(|ty| c_type(ty, signatures))
        .unwrap_or_else(|| "void".to_string());
    let params_text = if params.is_empty() {
        "void".to_string()
    } else {
        params
            .iter()
            .zip(param_types.iter())
            .map(|(param, ty)| format!("{} {}", c_type(ty, signatures), local_c_name(&param.name)))
            .collect::<Vec<_>>()
            .join(", ")
    };
    Ok(format!(
        "static {ret} {}({params_text})",
        anonymous_function_c_name(expr.span)
    ))
}

fn emit_partial_application(
    out: &mut String,
    expr: &Expr,
    signatures: &Signatures,
    source_paths: &HashMap<SourceId, String>,
) -> Result<(), Diagnostic> {
    let ExprKind::Call {
        name,
        args,
        named_args,
    } = &expr.kind
    else {
        return Err(diag(
            expr.span,
            "expected bind expression during code generation",
        ));
    };
    if name != "bind" || !named_args.is_empty() || args.len() < 2 {
        return Err(diag(
            expr.span,
            "invalid bind expression reached code generation",
        ));
    }
    let ExprKind::Var(target_name) = &args[0].kind else {
        return Err(diag(expr.span, "bind target must be a named function"));
    };
    let signature = signatures.get(target_name).ok_or_else(|| {
        diag(
            expr.span,
            "bind target function disappeared during code generation",
        )
    })?;
    let bound_count = args.len() - 1;
    let mut call_args = Vec::with_capacity(signature.params.len());
    for arg in &args[1..] {
        let Some(value) = fold_primitive_expr(arg, &HashMap::new(), signatures)? else {
            return Err(diag(
                arg.span,
                "non-constant bind argument reached code generation",
            ));
        };
        call_args.push(constant_c_value(&value));
    }
    for index in 0..signature.params.len().saturating_sub(bound_count) {
        call_args.push(format!("flux__bound_arg_{index}"));
    }
    emit_source_line(out, expr.span, source_paths);
    out.push_str(&partial_application_prototype(expr, signatures)?);
    out.push_str(" {\n");
    let call = format!("{}({})", function_c_name(target_name), call_args.join(", "));
    if signature.returns.is_empty() {
        out.push_str(&format!("    {call};\n"));
    } else {
        out.push_str(&format!("    return {call};\n"));
    }
    out.push_str("}\n");
    Ok(())
}

fn emit_function_helper(
    out: &mut String,
    expr: &Expr,
    signatures: &Signatures,
    source_paths: &HashMap<SourceId, String>,
) -> Result<(), Diagnostic> {
    match &expr.kind {
        ExprKind::AnonymousFunction { .. } => {
            emit_anonymous_function(out, expr, signatures, source_paths)
        }
        ExprKind::Call { name, .. } if name == "bind" => {
            emit_partial_application(out, expr, signatures, source_paths)
        }
        _ => Err(diag(
            expr.span,
            "expected function helper during code generation",
        )),
    }
}

fn emit_anonymous_function(
    out: &mut String,
    expr: &Expr,
    signatures: &Signatures,
    source_paths: &HashMap<SourceId, String>,
) -> Result<(), Diagnostic> {
    let ExprKind::AnonymousFunction { params, body, .. } = &expr.kind else {
        return Err(diag(
            expr.span,
            "expected anonymous function during code generation",
        ));
    };
    let ty = type_of_expr(expr, &HashMap::new(), signatures)?;
    let Type::Function { returns, .. } = ty else {
        return Err(diag(
            expr.span,
            "anonymous function did not produce a function type",
        ));
    };
    emit_source_line(out, expr.span, source_paths);
    out.push_str(&anonymous_function_prototype(expr, signatures)?);
    out.push_str(" {\n");
    let mut env = HashMap::new();
    for param in params {
        env.insert(param.name.clone(), signatures.canonical_type(&param.ty));
    }
    let body = emit_lambda_body_with_cfg(body, params, returns.first(), &env, signatures)?;
    if returns.is_empty() {
        out.push_str(&format!("    {};\n", body));
    } else {
        out.push_str(&format!("    return {};\n", body));
    }
    out.push_str("}\n");
    Ok(())
}

fn emit_lambda_body_with_cfg(
    body: &Expr,
    params: &[Param],
    expected: Option<&Type>,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
) -> Result<String, Diagnostic> {
    // Inline sequence callbacks and emitted anonymous helpers have no
    // source-level Function declaration, but their bodies are still ordinary
    // typed Flux expressions. Build the same normalized CFG used by named
    // functions so backend constant/proof consumption does not silently fall
    // back to the checked AST at this boundary.
    let synthetic = Function {
        public: false,
        foreign_symbol: None,
        unsafe_foreign: false,
        pure: false,
        asynchronous: false,
        name: format!("flux__lambda_cfg_{}_{}", body.span.line, body.span.column),
        name_span: body.span,
        keyword_span: body.span,
        params: params.to_vec(),
        returns: expected.into_iter().cloned().collect(),
        return_span: body.span,
        return_type_spans: Vec::new(),
        body: vec![Stmt {
            line: body.line,
            span: body.span,
            keyword_span: body.span,
            kind: StmtKind::Return(vec![body.clone()]),
        }],
        expression_body: true,
        line: body.line,
        span: body.span,
    };
    let cfg = crate::ir::ControlFlowGraph::from_function(&synthetic, signatures);
    let rewrite_facts = cfg_rewrite_facts(&cfg);
    let proofs = cfg_checked_i64_proofs(&cfg);
    let body_type = match expected {
        Some(expected) => signatures.canonical_type(expected),
        None => signatures.canonical_type(&type_of_expr(body, env, signatures)?),
    };
    emit_expr_for_expected_with_cfg_proofs(
        body,
        &body_type,
        env,
        signatures,
        &proofs,
        &rewrite_facts,
    )
}

type FunctionIrCache = HashMap<String, crate::ir::ControlFlowGraph>;

fn build_function_ir_cache(
    program: &Program,
    signatures: &Signatures,
    source_paths: &HashMap<SourceId, String>,
    mut cache: Option<&mut FunctionCodegenCache>,
    stats: &mut FunctionCodegenStats,
) -> FunctionIrCache {
    let mut used_identities = HashSet::with_capacity(program.functions.len());
    let mut ir = HashMap::with_capacity(program.functions.len());

    for function in &program.functions {
        let identity = function_codegen_cache_identity(function, source_paths);
        used_identities.insert(identity.clone());
        let cfg = if let Some(cached) = cache
            .as_deref()
            .and_then(|cache| cache.ir_entries.get(&identity))
            .cloned()
        {
            stats.reused_ir_functions += 1;
            cached
        } else {
            stats.regenerated_ir_functions += 1;
            let cfg = crate::ir::ControlFlowGraph::from_function(function, signatures);
            if let Some(cache) = cache.as_deref_mut() {
                cache.ir_entries.insert(identity, cfg.clone());
            }
            cfg
        };
        ir.insert(function.name.clone(), cfg);
    }

    if let Some(cache) = cache {
        cache
            .ir_entries
            .retain(|identity, _| used_identities.contains(identity));
    }
    ir
}

fn runtime_views(program: &Program) -> impl Iterator<Item = &crate::ast::ViewDef> {
    program.application.iter().filter_map(|application| {
        program
            .views
            .iter()
            .find(|view| view.name == application.view_name)
    })
}

fn collect_interface_names_from_ir(
    function: &Function,
    signatures: &Signatures,
    function_ir: &FunctionIrCache,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    let Some(cfg) = function_ir.get(&function.name) else {
        return;
    };
    for node in cfg.nodes().iter().filter(|node| cfg.is_reachable(node.id)) {
        for definition in &node.definitions {
            collect_interface_names_from_type(&definition.ty, signatures, reachable, pending);
        }
    }
    for value in cfg
        .values()
        .iter()
        .filter(|value| cfg.is_value_reachable(value.id))
    {
        collect_interface_names_from_type(&value.ty, signatures, reachable, pending);
        if let crate::ir::ControlFlowValueKind::InterfaceDispatch { interface, .. }
        | crate::ir::ControlFlowValueKind::NamedInterfaceDispatch { interface, .. } = &value.kind
        {
            enqueue_interface_name(interface, signatures, reachable, pending);
        }
    }
}

fn reachable_interface_names(
    program: &Program,
    signatures: &Signatures,
    reachable_functions: &HashSet<String>,
    reachable_value_types: &HashSet<String>,
    function_ir: &FunctionIrCache,
) -> HashSet<String> {
    let mut reachable = HashSet::new();
    let mut pending = Vec::new();

    for definition in &program.interfaces {
        if definition.public {
            enqueue_interface_name(&definition.name, signatures, &mut reachable, &mut pending);
        }
    }
    for alias in &program.aliases {
        if alias.public {
            collect_interface_names_from_type(
                &alias.target,
                signatures,
                &mut reachable,
                &mut pending,
            );
        }
    }
    for definition in &program.structs {
        if !reachable_value_types.contains(&definition.name) {
            continue;
        }
        for field in &definition.fields {
            collect_interface_names_from_type(&field.ty, signatures, &mut reachable, &mut pending);
        }
    }
    for definition in &program.enums {
        if !reachable_value_types.contains(&definition.name) {
            continue;
        }
        for variant in &definition.variants {
            for payload in &variant.payloads {
                collect_interface_names_from_type(
                    &payload.ty,
                    signatures,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
    }
    if let Some(application) = &program.application {
        for field in &application.metadata {
            collect_interface_names_from_expr(
                &field.value,
                signatures,
                &mut reachable,
                &mut pending,
            );
        }
    }
    for view in runtime_views(program) {
        for param in &view.params {
            collect_interface_names_from_type(&param.ty, signatures, &mut reachable, &mut pending);
            if let Some(default) = &param.default {
                collect_interface_names_from_expr(
                    default,
                    signatures,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
        for state in &view.states {
            collect_interface_names_from_type(&state.ty, signatures, &mut reachable, &mut pending);
            collect_interface_names_from_expr(
                &state.initial,
                signatures,
                &mut reachable,
                &mut pending,
            );
        }
        for derived in &view.derived {
            collect_interface_names_from_type(
                &derived.ty,
                signatures,
                &mut reachable,
                &mut pending,
            );
            collect_interface_names_from_expr(
                &derived.value,
                signatures,
                &mut reachable,
                &mut pending,
            );
        }
        for element in &view.elements {
            for property in &element.properties {
                collect_interface_names_from_expr(
                    &property.value,
                    signatures,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
    }
    for function in &program.functions {
        if !reachable_functions.contains(&function.name) {
            continue;
        }
        for param in &function.params {
            collect_interface_names_from_type(&param.ty, signatures, &mut reachable, &mut pending);
            if let Some(default) = &param.default {
                collect_interface_names_from_expr(
                    default,
                    signatures,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
        for ty in &function.returns {
            collect_interface_names_from_type(ty, signatures, &mut reachable, &mut pending);
        }
        collect_interface_names_from_ir(
            function,
            signatures,
            function_ir,
            &mut reachable,
            &mut pending,
        );
    }

    while let Some(name) = pending.pop() {
        let Some(definition) = program
            .interfaces
            .iter()
            .find(|definition| definition.name == name)
        else {
            continue;
        };
        for parent in &definition.parents {
            enqueue_interface_name(&parent.name, signatures, &mut reachable, &mut pending);
        }
        for function in &definition.functions {
            for param in &function.params {
                collect_interface_names_from_type(
                    &param.ty,
                    signatures,
                    &mut reachable,
                    &mut pending,
                );
            }
            for ty in &function.returns {
                collect_interface_names_from_type(ty, signatures, &mut reachable, &mut pending);
            }
        }
    }

    reachable
}

fn enqueue_interface_name(
    name: &str,
    signatures: &Signatures,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    if signatures.interface(name).is_some() && reachable.insert(name.to_string()) {
        pending.push(name.to_string());
    }
}

fn collect_interface_names_from_type(
    ty: &Type,
    signatures: &Signatures,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    match signatures.canonical_type(ty) {
        Type::Named(name) => {
            enqueue_interface_name(&name, signatures, reachable, pending);
        }
        Type::List(element) | Type::Set(element) | Type::Optional(element) => {
            collect_interface_names_from_type(&element, signatures, reachable, pending);
        }
        Type::Map(key, value) => {
            collect_interface_names_from_type(&key, signatures, reachable, pending);
            collect_interface_names_from_type(&value, signatures, reachable, pending);
        }
        Type::Record(fields) => {
            for field in fields {
                collect_interface_names_from_type(&field.ty, signatures, reachable, pending);
            }
        }
        Type::Function { params, returns } => {
            for ty in params.iter().chain(&returns) {
                collect_interface_names_from_type(ty, signatures, reachable, pending);
            }
        }
        Type::I64 | Type::Bool | Type::Str | Type::Error | Type::Void => {}
    }
}

fn collect_interface_names_from_expr(
    expr: &Expr,
    signatures: &Signatures,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    match &expr.kind {
        ExprKind::AnonymousFunction {
            params,
            return_type,
            body,
        } => {
            for param in params {
                collect_interface_names_from_type(&param.ty, signatures, reachable, pending);
            }
            if let Some(return_type) = return_type {
                collect_interface_names_from_type(return_type, signatures, reachable, pending);
            }
            collect_interface_names_from_expr(body, signatures, reachable, pending);
        }
        ExprKind::Call {
            name,
            args,
            named_args,
        } => {
            enqueue_interface_name(name, signatures, reachable, pending);
            for arg in args {
                collect_interface_names_from_expr(arg, signatures, reachable, pending);
            }
            for arg in named_args {
                collect_interface_names_from_expr(&arg.value, signatures, reachable, pending);
            }
        }
        ExprKind::QualifiedCall {
            args, named_args, ..
        } => {
            for arg in args {
                collect_interface_names_from_expr(arg, signatures, reachable, pending);
            }
            for arg in named_args {
                collect_interface_names_from_expr(&arg.value, signatures, reachable, pending);
            }
        }
        ExprKind::ShellCall { args, .. } => {
            for arg in args {
                collect_interface_names_from_expr(arg, signatures, reachable, pending);
            }
        }
        ExprKind::Pipe { input, args, .. } => {
            collect_interface_names_from_expr(input, signatures, reachable, pending);
            for arg in args {
                collect_interface_names_from_expr(arg, signatures, reachable, pending);
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_interface_names_from_expr(item, signatures, reachable, pending);
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_interface_names_from_expr(value, signatures, reachable, pending);
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_interface_names_from_expr(condition, signatures, reachable, pending);
            collect_interface_names_from_expr(value, signatures, reachable, pending);
            if let Some(else_value) = else_value {
                collect_interface_names_from_expr(else_value, signatures, reachable, pending);
            }
        }
        ExprKind::Index { base, index, .. } => {
            collect_interface_names_from_expr(base, signatures, reachable, pending);
            collect_interface_names_from_expr(index, signatures, reachable, pending);
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_interface_names_from_expr(base, signatures, reachable, pending);
            for part in [start, end, step].into_iter().flatten() {
                collect_interface_names_from_expr(part, signatures, reachable, pending);
            }
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            ..
        } => {
            collect_interface_names_from_expr(value, signatures, reachable, pending);
            collect_interface_names_from_expr(iterable, signatures, reachable, pending);
            if let Some(condition) = condition {
                collect_interface_names_from_expr(condition, signatures, reachable, pending);
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_interface_names_from_expr(&field.value, signatures, reachable, pending);
            }
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            if let Some(base) = base {
                collect_interface_names_from_expr(base, signatures, reachable, pending);
            }
            for field in fields {
                collect_interface_names_from_expr(&field.value, signatures, reachable, pending);
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => {
            collect_interface_names_from_expr(base, signatures, reachable, pending);
        }
        ExprKind::Match { value, arms } => {
            collect_interface_names_from_expr(value, signatures, reachable, pending);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_interface_names_from_expr(guard, signatures, reachable, pending);
                }
                collect_interface_names_from_expr(&arm.value, signatures, reachable, pending);
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_interface_names_from_expr(value, signatures, reachable, pending);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_interface_names_from_expr(guard, signatures, reachable, pending);
                }
                collect_interface_names_from_expr(&arm.value, signatures, reachable, pending);
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            collect_interface_names_from_expr(then_expr, signatures, reachable, pending);
            collect_interface_names_from_expr(cond, signatures, reachable, pending);
            collect_interface_names_from_expr(else_expr, signatures, reachable, pending);
        }
        ExprKind::Binary { left, right, .. } => {
            collect_interface_names_from_expr(left, signatures, reachable, pending);
            collect_interface_names_from_expr(right, signatures, reachable, pending);
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => {}
    }
}

fn reachable_enum_variant_helpers(
    program: &Program,
    signatures: &Signatures,
    reachable_functions: &HashSet<String>,
    function_ir: &FunctionIrCache,
) -> HashSet<(String, String)> {
    let mut variants = HashSet::new();
    if let Some(application) = &program.application {
        for field in &application.metadata {
            collect_enum_variant_refs_from_expr(&field.value, signatures, &mut variants);
        }
    }
    for view in runtime_views(program) {
        for param in &view.params {
            if let Some(default) = &param.default {
                collect_enum_variant_refs_from_expr(default, signatures, &mut variants);
            }
        }
        for state in &view.states {
            collect_enum_variant_refs_from_expr(&state.initial, signatures, &mut variants);
        }
        for derived in &view.derived {
            collect_enum_variant_refs_from_expr(&derived.value, signatures, &mut variants);
        }
        for element in &view.elements {
            for property in &element.properties {
                collect_enum_variant_refs_from_expr(&property.value, signatures, &mut variants);
            }
        }
    }
    for function in &program.functions {
        if !reachable_functions.contains(&function.name) {
            continue;
        }
        for param in &function.params {
            if let Some(default) = &param.default {
                collect_enum_variant_refs_from_expr(default, signatures, &mut variants);
            }
        }
        if let Some(cfg) = function_ir.get(&function.name) {
            for value in cfg
                .values()
                .iter()
                .filter(|value| cfg.is_value_reachable(value.id))
            {
                if let crate::ir::ControlFlowValueKind::QualifiedCall {
                    namespace, name, ..
                } = &value.kind
                    && signatures.enum_type(namespace).is_some()
                {
                    variants.insert((namespace.clone(), name.clone()));
                }
            }
        }
    }
    variants
}

fn collect_enum_variant_refs_from_expr(
    expr: &Expr,
    signatures: &Signatures,
    variants: &mut HashSet<(String, String)>,
) {
    match &expr.kind {
        ExprKind::QualifiedCall {
            namespace,
            name,
            args,
            named_args,
            ..
        } => {
            if signatures.enum_type(namespace).is_some() {
                variants.insert((namespace.clone(), name.clone()));
            }
            for arg in args {
                collect_enum_variant_refs_from_expr(arg, signatures, variants);
            }
            for arg in named_args {
                collect_enum_variant_refs_from_expr(&arg.value, signatures, variants);
            }
        }
        ExprKind::AnonymousFunction { body, .. } => {
            collect_enum_variant_refs_from_expr(body, signatures, variants);
        }
        ExprKind::Call {
            args, named_args, ..
        } => {
            for arg in args {
                collect_enum_variant_refs_from_expr(arg, signatures, variants);
            }
            for arg in named_args {
                collect_enum_variant_refs_from_expr(&arg.value, signatures, variants);
            }
        }
        ExprKind::ShellCall { args, .. } => {
            for arg in args {
                collect_enum_variant_refs_from_expr(arg, signatures, variants);
            }
        }
        ExprKind::Pipe { input, args, .. } => {
            collect_enum_variant_refs_from_expr(input, signatures, variants);
            for arg in args {
                collect_enum_variant_refs_from_expr(arg, signatures, variants);
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_enum_variant_refs_from_expr(item, signatures, variants);
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_enum_variant_refs_from_expr(value, signatures, variants);
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_enum_variant_refs_from_expr(condition, signatures, variants);
            collect_enum_variant_refs_from_expr(value, signatures, variants);
            if let Some(else_value) = else_value {
                collect_enum_variant_refs_from_expr(else_value, signatures, variants);
            }
        }
        ExprKind::Index { base, index, .. } => {
            collect_enum_variant_refs_from_expr(base, signatures, variants);
            collect_enum_variant_refs_from_expr(index, signatures, variants);
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_enum_variant_refs_from_expr(base, signatures, variants);
            for part in [start, end, step].into_iter().flatten() {
                collect_enum_variant_refs_from_expr(part, signatures, variants);
            }
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            ..
        } => {
            collect_enum_variant_refs_from_expr(value, signatures, variants);
            collect_enum_variant_refs_from_expr(iterable, signatures, variants);
            if let Some(condition) = condition {
                collect_enum_variant_refs_from_expr(condition, signatures, variants);
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_enum_variant_refs_from_expr(&field.value, signatures, variants);
            }
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            if let Some(base) = base {
                collect_enum_variant_refs_from_expr(base, signatures, variants);
            }
            for field in fields {
                collect_enum_variant_refs_from_expr(&field.value, signatures, variants);
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => {
            collect_enum_variant_refs_from_expr(base, signatures, variants);
        }
        ExprKind::Match { value, arms } => {
            collect_enum_variant_refs_from_expr(value, signatures, variants);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_enum_variant_refs_from_expr(guard, signatures, variants);
                }
                collect_enum_variant_refs_from_expr(&arm.value, signatures, variants);
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_enum_variant_refs_from_expr(value, signatures, variants);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_enum_variant_refs_from_expr(guard, signatures, variants);
                }
                collect_enum_variant_refs_from_expr(&arm.value, signatures, variants);
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            collect_enum_variant_refs_from_expr(then_expr, signatures, variants);
            collect_enum_variant_refs_from_expr(cond, signatures, variants);
            collect_enum_variant_refs_from_expr(else_expr, signatures, variants);
        }
        ExprKind::Binary { left, right, .. } => {
            collect_enum_variant_refs_from_expr(left, signatures, variants);
            collect_enum_variant_refs_from_expr(right, signatures, variants);
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => {}
    }
}

fn collect_value_type_names_from_ir(
    function: &Function,
    signatures: &Signatures,
    function_ir: &FunctionIrCache,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    let Some(cfg) = function_ir.get(&function.name) else {
        return;
    };
    for node in cfg.nodes().iter().filter(|node| cfg.is_reachable(node.id)) {
        for definition in &node.definitions {
            collect_value_type_names_from_type(
                &definition.ty,
                signatures,
                known,
                reachable,
                pending,
            );
        }
    }
    for value in cfg
        .values()
        .iter()
        .filter(|value| cfg.is_value_reachable(value.id))
    {
        collect_value_type_names_from_type(&value.ty, signatures, known, reachable, pending);
    }
}

fn reachable_value_type_names(
    program: &Program,
    signatures: &Signatures,
    reachable_functions: &HashSet<String>,
    reachable_interfaces: &HashSet<String>,
    function_ir: &FunctionIrCache,
) -> HashSet<String> {
    let known = program
        .structs
        .iter()
        .map(|definition| definition.name.clone())
        .chain(
            program
                .enums
                .iter()
                .map(|definition| definition.name.clone()),
        )
        .collect::<HashSet<_>>();
    let mut reachable = HashSet::new();
    let mut pending = Vec::new();

    for definition in &program.structs {
        if definition.public {
            enqueue_value_type_name(&definition.name, &known, &mut reachable, &mut pending);
        }
    }
    for definition in &program.enums {
        if definition.public {
            enqueue_value_type_name(&definition.name, &known, &mut reachable, &mut pending);
        }
    }
    for definition in &program.interfaces {
        if !reachable_interfaces.contains(&definition.name) {
            continue;
        }
        for function in &definition.functions {
            for param in &function.params {
                collect_value_type_names_from_type(
                    &param.ty,
                    signatures,
                    &known,
                    &mut reachable,
                    &mut pending,
                );
            }
            for ty in &function.returns {
                collect_value_type_names_from_type(
                    ty,
                    signatures,
                    &known,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
    }

    if let Some(application) = &program.application {
        for field in &application.metadata {
            collect_value_type_names_from_expr(
                &field.value,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
        }
    }
    for view in runtime_views(program) {
        for param in &view.params {
            collect_value_type_names_from_type(
                &param.ty,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
            if let Some(default) = &param.default {
                collect_value_type_names_from_expr(
                    default,
                    signatures,
                    &known,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
        for state in &view.states {
            collect_value_type_names_from_type(
                &state.ty,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
            collect_value_type_names_from_expr(
                &state.initial,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
        }
        for derived in &view.derived {
            collect_value_type_names_from_type(
                &derived.ty,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
            collect_value_type_names_from_expr(
                &derived.value,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
        }
        for element in &view.elements {
            for property in &element.properties {
                collect_value_type_names_from_expr(
                    &property.value,
                    signatures,
                    &known,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
    }

    for function in &program.functions {
        if !reachable_functions.contains(&function.name) {
            continue;
        }
        for param in &function.params {
            collect_value_type_names_from_type(
                &param.ty,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
            if let Some(default) = &param.default {
                collect_value_type_names_from_expr(
                    default,
                    signatures,
                    &known,
                    &mut reachable,
                    &mut pending,
                );
            }
        }
        for ty in &function.returns {
            collect_value_type_names_from_type(
                ty,
                signatures,
                &known,
                &mut reachable,
                &mut pending,
            );
        }
        collect_value_type_names_from_ir(
            function,
            signatures,
            function_ir,
            &known,
            &mut reachable,
            &mut pending,
        );
    }

    while let Some(name) = pending.pop() {
        if let Some(definition) = program
            .structs
            .iter()
            .find(|definition| definition.name == name)
        {
            for field in &definition.fields {
                collect_value_type_names_from_type(
                    &field.ty,
                    signatures,
                    &known,
                    &mut reachable,
                    &mut pending,
                );
            }
            continue;
        }
        if let Some(definition) = program
            .enums
            .iter()
            .find(|definition| definition.name == name)
        {
            for variant in &definition.variants {
                for payload in &variant.payloads {
                    collect_value_type_names_from_type(
                        &payload.ty,
                        signatures,
                        &known,
                        &mut reachable,
                        &mut pending,
                    );
                }
            }
        }
    }

    reachable
}

fn enqueue_value_type_name(
    name: &str,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    if known.contains(name) && reachable.insert(name.to_string()) {
        pending.push(name.to_string());
    }
}

fn collect_value_type_names_from_type(
    ty: &Type,
    signatures: &Signatures,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    match signatures.canonical_type(ty) {
        Type::Named(name) => enqueue_value_type_name(&name, known, reachable, pending),
        Type::List(element) | Type::Set(element) | Type::Optional(element) => {
            collect_value_type_names_from_type(&element, signatures, known, reachable, pending)
        }
        Type::Map(key, value) => {
            collect_value_type_names_from_type(&key, signatures, known, reachable, pending);
            collect_value_type_names_from_type(&value, signatures, known, reachable, pending);
        }
        Type::Record(fields) => {
            for field in fields {
                collect_value_type_names_from_type(
                    &field.ty, signatures, known, reachable, pending,
                );
            }
        }
        Type::Function { params, returns } => {
            for ty in params.iter().chain(&returns) {
                collect_value_type_names_from_type(ty, signatures, known, reachable, pending);
            }
        }
        Type::I64 | Type::Bool | Type::Str | Type::Error | Type::Void => {}
    }
}

fn collect_value_type_names_from_struct_pattern(
    pattern: &crate::ast::StructPattern,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    enqueue_value_type_name(&pattern.struct_name, known, reachable, pending);
    for field in &pattern.fields {
        if let Some(nested) = &field.nested {
            collect_value_type_names_from_struct_pattern(nested, known, reachable, pending);
        }
    }
}

fn collect_value_type_names_from_match_pattern(
    pattern: &MatchPattern,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    if let MatchPattern::Struct(pattern) = pattern {
        collect_value_type_names_from_struct_pattern(pattern, known, reachable, pending);
    }
}

fn collect_value_type_names_from_expr(
    expr: &Expr,
    signatures: &Signatures,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    match &expr.kind {
        ExprKind::AnonymousFunction {
            params,
            return_type,
            body,
        } => {
            for param in params {
                collect_value_type_names_from_type(
                    &param.ty, signatures, known, reachable, pending,
                );
            }
            if let Some(return_type) = return_type {
                collect_value_type_names_from_type(
                    return_type,
                    signatures,
                    known,
                    reachable,
                    pending,
                );
            }
            collect_value_type_names_from_expr(body, signatures, known, reachable, pending);
        }
        ExprKind::Call {
            args, named_args, ..
        }
        | ExprKind::QualifiedCall {
            args, named_args, ..
        } => {
            if let ExprKind::QualifiedCall { namespace, .. } = &expr.kind {
                enqueue_value_type_name(namespace, known, reachable, pending);
            }
            for arg in args {
                collect_value_type_names_from_expr(arg, signatures, known, reachable, pending);
            }
            for arg in named_args {
                collect_value_type_names_from_expr(
                    &arg.value, signatures, known, reachable, pending,
                );
            }
        }
        ExprKind::ShellCall { args, .. } => {
            for arg in args {
                collect_value_type_names_from_expr(arg, signatures, known, reachable, pending);
            }
        }
        ExprKind::Pipe { input, args, .. } => {
            collect_value_type_names_from_expr(input, signatures, known, reachable, pending);
            for arg in args {
                collect_value_type_names_from_expr(arg, signatures, known, reachable, pending);
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_value_type_names_from_expr(item, signatures, known, reachable, pending);
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_value_type_names_from_expr(value, signatures, known, reachable, pending);
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_value_type_names_from_expr(condition, signatures, known, reachable, pending);
            collect_value_type_names_from_expr(value, signatures, known, reachable, pending);
            if let Some(else_value) = else_value {
                collect_value_type_names_from_expr(
                    else_value, signatures, known, reachable, pending,
                );
            }
        }
        ExprKind::Index { base, index, .. } => {
            collect_value_type_names_from_expr(base, signatures, known, reachable, pending);
            collect_value_type_names_from_expr(index, signatures, known, reachable, pending);
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_value_type_names_from_expr(base, signatures, known, reachable, pending);
            for part in [start, end, step].into_iter().flatten() {
                collect_value_type_names_from_expr(part, signatures, known, reachable, pending);
            }
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            ..
        } => {
            collect_value_type_names_from_expr(value, signatures, known, reachable, pending);
            collect_value_type_names_from_expr(iterable, signatures, known, reachable, pending);
            if let Some(condition) = condition {
                collect_value_type_names_from_expr(
                    condition, signatures, known, reachable, pending,
                );
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_value_type_names_from_expr(
                    &field.value,
                    signatures,
                    known,
                    reachable,
                    pending,
                );
            }
        }
        ExprKind::StructLiteral {
            name, base, fields, ..
        } => {
            enqueue_value_type_name(name, known, reachable, pending);
            if let Some(base) = base {
                collect_value_type_names_from_expr(base, signatures, known, reachable, pending);
            }
            for field in fields {
                collect_value_type_names_from_expr(
                    &field.value,
                    signatures,
                    known,
                    reachable,
                    pending,
                );
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => {
            collect_value_type_names_from_expr(base, signatures, known, reachable, pending);
        }
        ExprKind::Match { value, arms } => {
            collect_value_type_names_from_expr(value, signatures, known, reachable, pending);
            for arm in arms {
                enqueue_value_type_name(&arm.enum_name, known, reachable, pending);
                for pattern in &arm.patterns {
                    collect_value_type_names_from_match_pattern(pattern, known, reachable, pending);
                }
                if let Some(guard) = &arm.guard {
                    collect_value_type_names_from_expr(
                        guard, signatures, known, reachable, pending,
                    );
                }
                collect_value_type_names_from_expr(
                    &arm.value, signatures, known, reachable, pending,
                );
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_value_type_names_from_expr(value, signatures, known, reachable, pending);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_value_type_names_from_expr(
                        guard, signatures, known, reachable, pending,
                    );
                }
                collect_value_type_names_from_expr(
                    &arm.value, signatures, known, reachable, pending,
                );
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            collect_value_type_names_from_expr(then_expr, signatures, known, reachable, pending);
            collect_value_type_names_from_expr(cond, signatures, known, reachable, pending);
            collect_value_type_names_from_expr(else_expr, signatures, known, reachable, pending);
        }
        ExprKind::Binary { left, right, .. } => {
            collect_value_type_names_from_expr(left, signatures, known, reachable, pending);
            collect_value_type_names_from_expr(right, signatures, known, reachable, pending);
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => {}
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct InterfacePackFacts {
    targets: HashMap<String, HashSet<String>>,
    open_interfaces: HashSet<String>,
}

impl InterfacePackFacts {
    fn external_roots(program: &Program, signatures: &Signatures) -> Self {
        let mut facts = Self::default();
        for function in &program.functions {
            if !function.public {
                continue;
            }
            for param in &function.params {
                facts.mark_open_type(&param.ty, signatures);
            }
        }
        facts
    }

    fn from_reachable_functions(
        program: &Program,
        signatures: &Signatures,
        reachable_functions: &HashSet<String>,
        function_ir: &FunctionIrCache,
    ) -> Self {
        let mut facts = Self::external_roots(program, signatures);
        let empty_env = HashMap::new();

        if let Some(application) = &program.application {
            for field in &application.metadata {
                collect_interface_pack_facts_from_expr(
                    &field.value,
                    &empty_env,
                    signatures,
                    &mut facts,
                );
            }
        }

        for view in runtime_views(program) {
            let env =
                view.params
                    .iter()
                    .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
                    .chain(
                        view.states.iter().map(|state| {
                            (state.name.clone(), signatures.canonical_type(&state.ty))
                        }),
                    )
                    .chain(view.derived.iter().map(|derived| {
                        (derived.name.clone(), signatures.canonical_type(&derived.ty))
                    }))
                    .collect::<HashMap<_, _>>();
            for param in &view.params {
                if let Some(default) = &param.default {
                    collect_interface_pack_facts_from_expr(default, &env, signatures, &mut facts);
                }
            }
            for state in &view.states {
                collect_interface_pack_facts_from_expr(
                    &state.initial,
                    &env,
                    signatures,
                    &mut facts,
                );
            }
            for derived in &view.derived {
                collect_interface_pack_facts_from_expr(
                    &derived.value,
                    &env,
                    signatures,
                    &mut facts,
                );
            }
            for element in &view.elements {
                for property in &element.properties {
                    collect_interface_pack_facts_from_expr(
                        &property.value,
                        &env,
                        signatures,
                        &mut facts,
                    );
                }
            }
        }

        for function in &program.functions {
            if !reachable_functions.contains(&function.name) {
                continue;
            }
            let Some(cfg) = function_ir.get(&function.name) else {
                continue;
            };
            for value in cfg
                .values()
                .iter()
                .filter(|value| cfg.is_value_reachable(value.id))
            {
                if let crate::ir::ControlFlowValueKind::InterfacePack {
                    interface, target, ..
                } = &value.kind
                {
                    facts.record_target(interface, target.clone());
                }
            }
        }

        facts
    }

    fn mark_open_type(&mut self, ty: &Type, signatures: &Signatures) {
        match signatures.canonical_type(ty) {
            Type::Named(name) if signatures.interface(&name).is_some() => {
                self.open_interfaces.insert(name);
            }
            Type::List(element) | Type::Set(element) | Type::Optional(element) => {
                self.mark_open_type(&element, signatures)
            }
            Type::Map(key, value) => {
                self.mark_open_type(&key, signatures);
                self.mark_open_type(&value, signatures);
            }
            Type::Record(fields) => {
                for field in fields {
                    self.mark_open_type(&field.ty, signatures);
                }
            }
            Type::Function { params, returns } => {
                for ty in params.iter().chain(&returns) {
                    self.mark_open_type(ty, signatures);
                }
            }
            Type::I64 | Type::Bool | Type::Str | Type::Error | Type::Void | Type::Named(_) => {}
        }
    }

    fn record_target(&mut self, interface_name: &str, target_name: String) {
        self.targets
            .entry(interface_name.to_string())
            .or_default()
            .insert(target_name);
    }

    fn mark_open(&mut self, interface_name: &str) {
        self.open_interfaces.insert(interface_name.to_string());
    }

    fn allows(&self, interface_name: &str, target_name: &str) -> bool {
        self.open_interfaces.contains(interface_name)
            || self
                .targets
                .get(interface_name)
                .is_some_and(|targets| targets.contains(target_name))
    }
}

fn collect_interface_pack_facts_from_expr(
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    facts: &mut InterfacePackFacts,
) {
    if let ExprKind::Call {
        name,
        args,
        named_args,
    } = &expr.kind
        && signatures.interface(name).is_some()
        && named_args.is_empty()
        && args.len() == 1
    {
        match type_of_expr(&args[0], env, signatures)
            .ok()
            .map(|ty| signatures.canonical_type(&ty))
        {
            Some(Type::Named(target_name))
                if target_name != *name
                    && signatures.implementation(name, &target_name).is_some() =>
            {
                facts.record_target(name, target_name);
            }
            _ => facts.mark_open(name),
        }
    }

    match &expr.kind {
        ExprKind::AnonymousFunction { params, body, .. } => {
            let mut body_env = env.clone();
            for param in params {
                body_env.insert(param.name.clone(), signatures.canonical_type(&param.ty));
            }
            collect_interface_pack_facts_from_expr(body, &body_env, signatures, facts);
        }
        ExprKind::Call {
            args, named_args, ..
        }
        | ExprKind::QualifiedCall {
            args, named_args, ..
        } => {
            for arg in args {
                collect_interface_pack_facts_from_expr(arg, env, signatures, facts);
            }
            for arg in named_args {
                collect_interface_pack_facts_from_expr(&arg.value, env, signatures, facts);
            }
        }
        ExprKind::ShellCall { args, .. } => {
            for arg in args {
                collect_interface_pack_facts_from_expr(arg, env, signatures, facts);
            }
        }
        ExprKind::Pipe { input, args, .. } => {
            collect_interface_pack_facts_from_expr(input, env, signatures, facts);
            for arg in args {
                collect_interface_pack_facts_from_expr(arg, env, signatures, facts);
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_interface_pack_facts_from_expr(item, env, signatures, facts);
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_interface_pack_facts_from_expr(value, env, signatures, facts)
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_interface_pack_facts_from_expr(condition, env, signatures, facts);
            collect_interface_pack_facts_from_expr(value, env, signatures, facts);
            if let Some(else_value) = else_value {
                collect_interface_pack_facts_from_expr(else_value, env, signatures, facts);
            }
        }
        ExprKind::Index { base, index, .. } => {
            collect_interface_pack_facts_from_expr(base, env, signatures, facts);
            collect_interface_pack_facts_from_expr(index, env, signatures, facts);
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_interface_pack_facts_from_expr(base, env, signatures, facts);
            for part in [start, end, step].into_iter().flatten() {
                collect_interface_pack_facts_from_expr(part, env, signatures, facts);
            }
        }
        ExprKind::ListComprehension {
            value,
            binding,
            iterable,
            condition,
            ..
        } => {
            collect_interface_pack_facts_from_expr(iterable, env, signatures, facts);
            let mut item_env = env.clone();
            if let Ok(Type::List(element)) = type_of_expr(iterable, env, signatures) {
                item_env.insert(binding.clone(), signatures.canonical_type(&element));
            }
            collect_interface_pack_facts_from_expr(value, &item_env, signatures, facts);
            if let Some(condition) = condition {
                collect_interface_pack_facts_from_expr(condition, &item_env, signatures, facts);
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_interface_pack_facts_from_expr(&field.value, env, signatures, facts);
            }
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            if let Some(base) = base {
                collect_interface_pack_facts_from_expr(base, env, signatures, facts);
            }
            for field in fields {
                collect_interface_pack_facts_from_expr(&field.value, env, signatures, facts);
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => {
            collect_interface_pack_facts_from_expr(base, env, signatures, facts);
        }
        ExprKind::Match { value, arms } => {
            collect_interface_pack_facts_from_expr(value, env, signatures, facts);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_interface_pack_facts_from_expr(guard, env, signatures, facts);
                }
                collect_interface_pack_facts_from_expr(&arm.value, env, signatures, facts);
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_interface_pack_facts_from_expr(value, env, signatures, facts);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_interface_pack_facts_from_expr(guard, env, signatures, facts);
                }
                collect_interface_pack_facts_from_expr(&arm.value, env, signatures, facts);
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            collect_interface_pack_facts_from_expr(then_expr, env, signatures, facts);
            collect_interface_pack_facts_from_expr(cond, env, signatures, facts);
            collect_interface_pack_facts_from_expr(else_expr, env, signatures, facts);
        }
        ExprKind::Binary { left, right, .. } => {
            collect_interface_pack_facts_from_expr(left, env, signatures, facts);
            collect_interface_pack_facts_from_expr(right, env, signatures, facts);
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => {}
    }
}

fn collect_function_reachability_from_ir(
    function: &Function,
    function_ir: &FunctionIrCache,
    known_functions: &HashSet<String>,
    direct_functions: &mut HashSet<String>,
    dynamic_capabilities: &mut HashSet<(String, String)>,
) {
    let Some(cfg) = function_ir.get(&function.name) else {
        return;
    };
    for value in cfg.values().iter().filter(|value| {
        cfg.is_value_reachable(value.id)
            || (value.result_index.is_none()
                && cfg.is_reachable(value.producer)
                && cfg.uses_of(value.id).next().is_none())
    }) {
        match &value.kind {
            crate::ir::ControlFlowValueKind::NameRead { name, definitions }
                if definitions.is_empty() && known_functions.contains(name) =>
            {
                direct_functions.insert(name.clone());
            }
            crate::ir::ControlFlowValueKind::Call { callee, .. }
            | crate::ir::ControlFlowValueKind::NamedCall { callee, .. }
            | crate::ir::ControlFlowValueKind::OptionalCascadeCall { callee, .. }
                if known_functions.contains(callee) =>
            {
                direct_functions.insert(callee.clone());
            }
            crate::ir::ControlFlowValueKind::InterfaceDispatch {
                interface,
                capability,
                mapped_function,
                ..
            }
            | crate::ir::ControlFlowValueKind::NamedInterfaceDispatch {
                interface,
                capability,
                mapped_function,
                ..
            } => {
                if let Some(mapped) = mapped_function {
                    direct_functions.insert(mapped.clone());
                } else {
                    dynamic_capabilities.insert((interface.clone(), capability.clone()));
                }
            }
            _ => {}
        }
    }
}

fn reachable_function_names(
    program: &Program,
    signatures: &Signatures,
    reachable_interfaces: &HashSet<String>,
    interface_pack_facts: &InterfacePackFacts,
    function_ir: &FunctionIrCache,
) -> HashSet<String> {
    let known = program
        .functions
        .iter()
        .map(|function| function.name.clone())
        .collect::<HashSet<_>>();
    let mut reachable = HashSet::new();
    let mut pending = Vec::new();

    for function in &program.functions {
        if function.name == "main" || function.public {
            enqueue_function(&function.name, &known, &mut reachable, &mut pending);
        }
    }
    let mut roots = HashSet::new();
    let mut interface_capabilities = HashSet::new();
    let empty_env = HashMap::new();
    if let Some(application) = &program.application {
        for field in &application.metadata {
            collect_named_function_refs_from_expr(&field.value, &known, &mut roots);
            collect_interface_dispatch_refs_from_expr(
                &field.value,
                &empty_env,
                signatures,
                &mut roots,
                &mut interface_capabilities,
            );
        }
    }
    for view in runtime_views(program) {
        for param in &view.params {
            if let Some(default) = &param.default {
                collect_named_function_refs_from_expr(default, &known, &mut roots);
                collect_interface_dispatch_refs_from_expr(
                    default,
                    &empty_env,
                    signatures,
                    &mut roots,
                    &mut interface_capabilities,
                );
            }
        }
        for state in &view.states {
            collect_named_function_refs_from_expr(&state.initial, &known, &mut roots);
            collect_interface_dispatch_refs_from_expr(
                &state.initial,
                &empty_env,
                signatures,
                &mut roots,
                &mut interface_capabilities,
            );
        }
        for derived in &view.derived {
            collect_named_function_refs_from_expr(&derived.value, &known, &mut roots);
            collect_interface_dispatch_refs_from_expr(
                &derived.value,
                &empty_env,
                signatures,
                &mut roots,
                &mut interface_capabilities,
            );
        }
        for element in &view.elements {
            for property in &element.properties {
                collect_named_function_refs_from_expr(&property.value, &known, &mut roots);
                collect_interface_dispatch_refs_from_expr(
                    &property.value,
                    &empty_env,
                    signatures,
                    &mut roots,
                    &mut interface_capabilities,
                );
            }
        }
    }
    for name in roots {
        enqueue_function(&name, &known, &mut reachable, &mut pending);
    }
    enqueue_interface_capability_mappings(
        program,
        reachable_interfaces,
        &interface_capabilities,
        interface_pack_facts,
        &known,
        &mut reachable,
        &mut pending,
    );

    while let Some(name) = pending.pop() {
        let Some(function) = program
            .functions
            .iter()
            .find(|function| function.name == name)
        else {
            continue;
        };
        let mut references = HashSet::new();
        let mut capabilities = HashSet::new();
        let env = function
            .params
            .iter()
            .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
            .collect::<HashMap<_, _>>();
        for param in &function.params {
            if let Some(default) = &param.default {
                collect_named_function_refs_from_expr(default, &known, &mut references);
                collect_interface_dispatch_refs_from_expr(
                    default,
                    &env,
                    signatures,
                    &mut references,
                    &mut capabilities,
                );
            }
        }
        collect_function_reachability_from_ir(
            function,
            function_ir,
            &known,
            &mut references,
            &mut capabilities,
        );
        if function.asynchronous {
            collect_named_function_refs_from_block(&function.body, &known, &mut references);
        }
        for reference in references {
            enqueue_function(&reference, &known, &mut reachable, &mut pending);
        }
        enqueue_interface_capability_mappings(
            program,
            reachable_interfaces,
            &capabilities,
            interface_pack_facts,
            &known,
            &mut reachable,
            &mut pending,
        );
    }

    reachable
}

fn enqueue_interface_capability_mappings(
    program: &Program,
    reachable_interfaces: &HashSet<String>,
    capabilities: &HashSet<(String, String)>,
    interface_pack_facts: &InterfacePackFacts,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    for (interface_name, capability_name) in capabilities {
        if !reachable_interfaces.contains(interface_name) {
            continue;
        }
        for implementation in &program.implementations {
            if implementation.interface_name != *interface_name
                || !interface_pack_facts.allows(interface_name, &implementation.target_name)
            {
                continue;
            }
            if let Some(mapping) = implementation
                .mappings
                .iter()
                .find(|mapping| mapping.member == *capability_name)
            {
                enqueue_function(&mapping.function, known, reachable, pending);
            }
        }
    }
}

fn enqueue_function(
    name: &str,
    known: &HashSet<String>,
    reachable: &mut HashSet<String>,
    pending: &mut Vec<String>,
) {
    if known.contains(name) && reachable.insert(name.to_string()) {
        pending.push(name.to_string());
    }
}

fn collect_interface_dispatch_refs_from_expr(
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    direct_functions: &mut HashSet<String>,
    dynamic_capabilities: &mut HashSet<(String, String)>,
) {
    if let ExprKind::QualifiedCall {
        namespace,
        name,
        args,
        ..
    } = &expr.kind
        && signatures.interface(namespace).is_some()
    {
        let direct_target = args.first().and_then(|receiver| {
            let receiver_ty = type_of_expr(receiver, env, signatures).ok()?;
            let Type::Named(target_name) = signatures.canonical_type(&receiver_ty) else {
                return None;
            };
            if target_name == *namespace && signatures.interface(&target_name).is_some() {
                return None;
            }
            signatures
                .implementation(namespace, &target_name)
                .and_then(|implementation| implementation.functions.get(name))
                .cloned()
        });
        if let Some(mapped) = direct_target {
            direct_functions.insert(mapped);
        } else {
            dynamic_capabilities.insert((namespace.clone(), name.clone()));
        }
    }

    match &expr.kind {
        ExprKind::AnonymousFunction { params, body, .. } => {
            let mut body_env = env.clone();
            for param in params {
                body_env.insert(param.name.clone(), signatures.canonical_type(&param.ty));
            }
            collect_interface_dispatch_refs_from_expr(
                body,
                &body_env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
        }
        ExprKind::Call {
            args, named_args, ..
        }
        | ExprKind::QualifiedCall {
            args, named_args, ..
        } => {
            for arg in args {
                collect_interface_dispatch_refs_from_expr(
                    arg,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
            for arg in named_args {
                collect_interface_dispatch_refs_from_expr(
                    &arg.value,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::ShellCall { args, .. } => {
            for arg in args {
                collect_interface_dispatch_refs_from_expr(
                    arg,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Pipe { input, args, .. } => {
            collect_interface_dispatch_refs_from_expr(
                input,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            for arg in args {
                collect_interface_dispatch_refs_from_expr(
                    arg,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_interface_dispatch_refs_from_expr(
                    item,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_interface_dispatch_refs_from_expr(
                value,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            )
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_interface_dispatch_refs_from_expr(
                condition,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            collect_interface_dispatch_refs_from_expr(
                value,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            if let Some(else_value) = else_value {
                collect_interface_dispatch_refs_from_expr(
                    else_value,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Index { base, index, .. } => {
            for item in [base.as_ref(), index.as_ref()] {
                collect_interface_dispatch_refs_from_expr(
                    item,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_interface_dispatch_refs_from_expr(
                base,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            for part in [start, end, step].into_iter().flatten() {
                collect_interface_dispatch_refs_from_expr(
                    part,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            binding,
            ..
        } => {
            collect_interface_dispatch_refs_from_expr(
                iterable,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            let mut item_env = env.clone();
            if let Ok(Type::List(element)) = type_of_expr(iterable, env, signatures) {
                item_env.insert(binding.clone(), signatures.canonical_type(&element));
            }
            collect_interface_dispatch_refs_from_expr(
                value,
                &item_env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            if let Some(condition) = condition {
                collect_interface_dispatch_refs_from_expr(
                    condition,
                    &item_env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_interface_dispatch_refs_from_expr(
                    &field.value,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            if let Some(base) = base {
                collect_interface_dispatch_refs_from_expr(
                    base,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
            for field in fields {
                collect_interface_dispatch_refs_from_expr(
                    &field.value,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => {
            collect_interface_dispatch_refs_from_expr(
                base,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
        }
        ExprKind::Match { value, arms } => {
            collect_interface_dispatch_refs_from_expr(
                value,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_interface_dispatch_refs_from_expr(
                        guard,
                        env,
                        signatures,
                        direct_functions,
                        dynamic_capabilities,
                    );
                }
                collect_interface_dispatch_refs_from_expr(
                    &arm.value,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_interface_dispatch_refs_from_expr(
                value,
                env,
                signatures,
                direct_functions,
                dynamic_capabilities,
            );
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_interface_dispatch_refs_from_expr(
                        guard,
                        env,
                        signatures,
                        direct_functions,
                        dynamic_capabilities,
                    );
                }
                collect_interface_dispatch_refs_from_expr(
                    &arm.value,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            for item in [then_expr.as_ref(), cond.as_ref(), else_expr.as_ref()] {
                collect_interface_dispatch_refs_from_expr(
                    item,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Binary { left, right, .. } => {
            for item in [left.as_ref(), right.as_ref()] {
                collect_interface_dispatch_refs_from_expr(
                    item,
                    env,
                    signatures,
                    direct_functions,
                    dynamic_capabilities,
                );
            }
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => {}
    }
}

fn collect_named_function_refs_from_block(
    body: &[Stmt],
    known: &HashSet<String>,
    references: &mut HashSet<String>,
) {
    for stmt in body {
        match &stmt.kind {
            StmtKind::Let { expr, .. }
            | StmtKind::Var { expr, .. }
            | StmtKind::Assign { expr, .. }
            | StmtKind::AssignMultiDestructure { expr, .. }
            | StmtKind::AssignListDestructure { expr, .. }
            | StmtKind::AssignStructDestructure { expr, .. }
            | StmtKind::LetDestructure { expr, .. }
            | StmtKind::LetMultiDestructure { expr, .. }
            | StmtKind::LetListDestructure { expr, .. }
            | StmtKind::LetStructDestructure { expr, .. }
            | StmtKind::Expr(expr) => {
                collect_named_function_refs_from_expr(expr, known, references)
            }
            StmtKind::Return(values) => {
                for value in values {
                    collect_named_function_refs_from_expr(value, known, references);
                }
            }
            StmtKind::Shell { expr, redirect, .. } => {
                collect_named_function_refs_from_expr(expr, known, references);
                if let Some(redirect) = redirect {
                    collect_named_function_refs_from_expr(&redirect.path, known, references);
                }
            }
            StmtKind::If {
                cond,
                body,
                else_body,
                ..
            } => {
                collect_named_function_refs_from_expr(cond, known, references);
                collect_named_function_refs_from_block(body, known, references);
                collect_named_function_refs_from_block(else_body, known, references);
            }
            StmtKind::ForRange {
                start, end, body, ..
            } => {
                collect_named_function_refs_from_expr(start, known, references);
                collect_named_function_refs_from_expr(end, known, references);
                collect_named_function_refs_from_block(body, known, references);
            }
            StmtKind::ForEach { iterable, body, .. } => {
                collect_named_function_refs_from_expr(iterable, known, references);
                collect_named_function_refs_from_block(body, known, references);
            }
            StmtKind::While { cond, body } => {
                collect_named_function_refs_from_expr(cond, known, references);
                collect_named_function_refs_from_block(body, known, references);
            }
            StmtKind::Match { value, arms } => {
                collect_named_function_refs_from_expr(value, known, references);
                for arm in arms {
                    if let Some(guard) = &arm.guard {
                        collect_named_function_refs_from_expr(guard, known, references);
                    }
                    collect_named_function_refs_from_block(&arm.body, known, references);
                }
            }
            StmtKind::ListMatch { value, arms } => {
                collect_named_function_refs_from_expr(value, known, references);
                for arm in arms {
                    if let Some(guard) = &arm.guard {
                        collect_named_function_refs_from_expr(guard, known, references);
                    }
                    collect_named_function_refs_from_block(&arm.body, known, references);
                }
            }
            StmtKind::Break | StmtKind::Continue => {}
        }
    }
}

fn collect_named_function_refs_from_expr(
    expr: &Expr,
    known: &HashSet<String>,
    references: &mut HashSet<String>,
) {
    match &expr.kind {
        ExprKind::Var(name) => {
            if known.contains(name) {
                references.insert(name.clone());
            }
        }
        ExprKind::AnonymousFunction { body, .. } => {
            collect_named_function_refs_from_expr(body, known, references);
        }
        ExprKind::Call {
            name,
            args,
            named_args,
        } => {
            if known.contains(name) {
                references.insert(name.clone());
            }
            for arg in args {
                collect_named_function_refs_from_expr(arg, known, references);
            }
            for arg in named_args {
                collect_named_function_refs_from_expr(&arg.value, known, references);
            }
        }
        ExprKind::ShellCall { name, args, .. } => {
            if known.contains(name) {
                references.insert(name.clone());
            }
            for arg in args {
                collect_named_function_refs_from_expr(arg, known, references);
            }
        }
        ExprKind::Pipe {
            input, name, args, ..
        } => {
            if known.contains(name) {
                references.insert(name.clone());
            }
            collect_named_function_refs_from_expr(input, known, references);
            for arg in args {
                collect_named_function_refs_from_expr(arg, known, references);
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_named_function_refs_from_expr(item, known, references);
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_named_function_refs_from_expr(value, known, references);
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_named_function_refs_from_expr(condition, known, references);
            collect_named_function_refs_from_expr(value, known, references);
            if let Some(else_value) = else_value {
                collect_named_function_refs_from_expr(else_value, known, references);
            }
        }
        ExprKind::Index { base, index, .. } => {
            collect_named_function_refs_from_expr(base, known, references);
            collect_named_function_refs_from_expr(index, known, references);
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_named_function_refs_from_expr(base, known, references);
            for part in [start, end, step].into_iter().flatten() {
                collect_named_function_refs_from_expr(part, known, references);
            }
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            ..
        } => {
            collect_named_function_refs_from_expr(value, known, references);
            collect_named_function_refs_from_expr(iterable, known, references);
            if let Some(condition) = condition {
                collect_named_function_refs_from_expr(condition, known, references);
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_named_function_refs_from_expr(&field.value, known, references);
            }
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            if let Some(base) = base {
                collect_named_function_refs_from_expr(base, known, references);
            }
            for field in fields {
                collect_named_function_refs_from_expr(&field.value, known, references);
            }
        }
        ExprKind::QualifiedCall {
            name,
            args,
            named_args,
            ..
        } => {
            if known.contains(name) {
                references.insert(name.clone());
            }
            for arg in args {
                collect_named_function_refs_from_expr(arg, known, references);
            }
            for arg in named_args {
                collect_named_function_refs_from_expr(&arg.value, known, references);
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => {
            collect_named_function_refs_from_expr(base, known, references);
        }
        ExprKind::Match { value, arms } => {
            collect_named_function_refs_from_expr(value, known, references);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_named_function_refs_from_expr(guard, known, references);
                }
                collect_named_function_refs_from_expr(&arm.value, known, references);
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_named_function_refs_from_expr(value, known, references);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_named_function_refs_from_expr(guard, known, references);
                }
                collect_named_function_refs_from_expr(&arm.value, known, references);
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            collect_named_function_refs_from_expr(then_expr, known, references);
            collect_named_function_refs_from_expr(cond, known, references);
            collect_named_function_refs_from_expr(else_expr, known, references);
        }
        ExprKind::Binary { left, right, .. } => {
            collect_named_function_refs_from_expr(left, known, references);
            collect_named_function_refs_from_expr(right, known, references);
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None => {}
    }
}

fn collect_function_helpers<'a>(
    program: &'a Program,
    reachable_functions: &HashSet<String>,
    function_ir: &FunctionIrCache,
) -> Vec<&'a Expr> {
    let mut functions = Vec::new();
    for function in &program.functions {
        if !reachable_functions.contains(&function.name) {
            continue;
        }
        let mut candidates = Vec::new();
        collect_function_helpers_from_block(&function.body, &mut candidates);
        let Some(cfg) = function_ir.get(&function.name) else {
            functions.extend(candidates);
            continue;
        };
        let reachable_spans = cfg
            .values()
            .iter()
            .filter(|value| cfg.is_value_reachable(value.id))
            .filter(|value| {
                matches!(
                    &value.kind,
                    crate::ir::ControlFlowValueKind::AnonymousFunction { .. }
                ) || matches!(
                    &value.kind,
                    crate::ir::ControlFlowValueKind::Call { callee, .. } if callee == "bind"
                )
            })
            .map(|value| source_span_key(value.span))
            .collect::<HashSet<_>>();
        functions.extend(
            candidates
                .into_iter()
                .filter(|expr| reachable_spans.contains(&source_span_key(expr.span))),
        );
    }
    functions
}

fn collect_function_helpers_from_block<'a>(body: &'a [Stmt], functions: &mut Vec<&'a Expr>) {
    for stmt in body {
        match &stmt.kind {
            StmtKind::Let { expr, .. }
            | StmtKind::Var { expr, .. }
            | StmtKind::Assign { expr, .. }
            | StmtKind::AssignMultiDestructure { expr, .. }
            | StmtKind::AssignListDestructure { expr, .. }
            | StmtKind::AssignStructDestructure { expr, .. }
            | StmtKind::LetDestructure { expr, .. }
            | StmtKind::LetMultiDestructure { expr, .. }
            | StmtKind::LetListDestructure { expr, .. }
            | StmtKind::LetStructDestructure { expr, .. }
            | StmtKind::Expr(expr) => collect_function_helpers_from_expr(expr, functions),
            StmtKind::Return(values) => {
                for value in values {
                    collect_function_helpers_from_expr(value, functions);
                }
            }
            StmtKind::Shell { expr, redirect, .. } => {
                collect_function_helpers_from_expr(expr, functions);
                if let Some(redirect) = redirect {
                    collect_function_helpers_from_expr(&redirect.path, functions);
                }
            }
            StmtKind::If {
                cond,
                body,
                else_body,
                ..
            } => {
                collect_function_helpers_from_expr(cond, functions);
                collect_function_helpers_from_block(body, functions);
                collect_function_helpers_from_block(else_body, functions);
            }
            StmtKind::ForRange {
                start, end, body, ..
            } => {
                collect_function_helpers_from_expr(start, functions);
                collect_function_helpers_from_expr(end, functions);
                collect_function_helpers_from_block(body, functions);
            }
            StmtKind::ForEach { iterable, body, .. } => {
                collect_function_helpers_from_expr(iterable, functions);
                collect_function_helpers_from_block(body, functions);
            }
            StmtKind::While { cond, body } => {
                collect_function_helpers_from_expr(cond, functions);
                collect_function_helpers_from_block(body, functions);
            }
            StmtKind::Match { value, arms } => {
                collect_function_helpers_from_expr(value, functions);
                for arm in arms {
                    if let Some(guard) = &arm.guard {
                        collect_function_helpers_from_expr(guard, functions);
                    }
                    collect_function_helpers_from_block(&arm.body, functions);
                }
            }
            StmtKind::ListMatch { value, arms } => {
                collect_function_helpers_from_expr(value, functions);
                for arm in arms {
                    if let Some(guard) = &arm.guard {
                        collect_function_helpers_from_expr(guard, functions);
                    }
                    collect_function_helpers_from_block(&arm.body, functions);
                }
            }
            StmtKind::Break | StmtKind::Continue => {}
        }
    }
}

fn collect_function_helpers_from_expr<'a>(expr: &'a Expr, functions: &mut Vec<&'a Expr>) {
    match &expr.kind {
        ExprKind::AnonymousFunction { body, .. } => {
            functions.push(expr);
            collect_function_helpers_from_expr(body, functions);
        }
        ExprKind::Call {
            name,
            args,
            named_args,
        } => {
            if name == "bind" {
                functions.push(expr);
            }
            for (index, arg) in args.iter().enumerate() {
                let inline_sequence_callback = named_args.is_empty()
                    && match name.as_str() {
                        "map" | "filter" | "where" => args.len() == 2 && index == 1,
                        "fold" => args.len() == 3 && index == 2,
                        "reduce" => args.len() == 2 && index == 1,
                        _ => false,
                    }
                    && matches!(arg.kind, ExprKind::AnonymousFunction { .. });
                if inline_sequence_callback {
                    if let ExprKind::AnonymousFunction { body, .. } = &arg.kind {
                        collect_function_helpers_from_expr(body, functions);
                    }
                } else {
                    collect_function_helpers_from_expr(arg, functions);
                }
            }
            for arg in named_args {
                collect_function_helpers_from_expr(&arg.value, functions);
            }
        }
        ExprKind::QualifiedCall {
            args, named_args, ..
        } => {
            for arg in args {
                collect_function_helpers_from_expr(arg, functions);
            }
            for arg in named_args {
                collect_function_helpers_from_expr(&arg.value, functions);
            }
        }
        ExprKind::ShellCall { args, .. } => {
            for arg in args {
                collect_function_helpers_from_expr(arg, functions);
            }
        }
        ExprKind::Pipe {
            input, name, args, ..
        } => {
            collect_function_helpers_from_expr(input, functions);
            for (index, arg) in args.iter().enumerate() {
                let inline_sequence_callback =
                    match name.as_str() {
                        "map" | "filter" | "where" => args.len() == 1 && index == 0,
                        "fold" => args.len() == 2 && index == 1,
                        "reduce" => args.len() == 1 && index == 0,
                        _ => false,
                    } && matches!(arg.kind, ExprKind::AnonymousFunction { .. });
                if inline_sequence_callback {
                    if let ExprKind::AnonymousFunction { body, .. } = &arg.kind {
                        collect_function_helpers_from_expr(body, functions);
                    }
                } else {
                    collect_function_helpers_from_expr(arg, functions);
                }
            }
        }
        ExprKind::List(items) | ExprKind::Set(items) | ExprKind::Map(items) => {
            for item in items {
                collect_function_helpers_from_expr(item, functions);
            }
        }
        ExprKind::ListSpread { value, .. } | ExprKind::ListOptional { value, .. } => {
            collect_function_helpers_from_expr(value, functions)
        }
        ExprKind::ListIf {
            condition,
            value,
            else_value,
            ..
        } => {
            collect_function_helpers_from_expr(condition, functions);
            collect_function_helpers_from_expr(value, functions);
            if let Some(else_value) = else_value {
                collect_function_helpers_from_expr(else_value, functions);
            }
        }
        ExprKind::Index { base, index, .. } => {
            collect_function_helpers_from_expr(base, functions);
            collect_function_helpers_from_expr(index, functions);
        }
        ExprKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            collect_function_helpers_from_expr(base, functions);
            for part in [start, end, step].into_iter().flatten() {
                collect_function_helpers_from_expr(part, functions);
            }
        }
        ExprKind::ListComprehension {
            value,
            iterable,
            condition,
            ..
        } => {
            collect_function_helpers_from_expr(value, functions);
            collect_function_helpers_from_expr(iterable, functions);
            if let Some(condition) = condition {
                collect_function_helpers_from_expr(condition, functions);
            }
        }
        ExprKind::RecordLiteral { fields } => {
            for field in fields {
                collect_function_helpers_from_expr(&field.value, functions);
            }
        }
        ExprKind::StructLiteral { base, fields, .. } => {
            if let Some(base) = base {
                collect_function_helpers_from_expr(base, functions);
            }
            for field in fields {
                collect_function_helpers_from_expr(&field.value, functions);
            }
        }
        ExprKind::Field { base, .. }
        | ExprKind::Unary { expr: base, .. }
        | ExprKind::Await(base) => collect_function_helpers_from_expr(base, functions),
        ExprKind::Match { value, arms } => {
            collect_function_helpers_from_expr(value, functions);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_function_helpers_from_expr(guard, functions);
                }
                collect_function_helpers_from_expr(&arm.value, functions);
            }
        }
        ExprKind::ListMatch { value, arms } => {
            collect_function_helpers_from_expr(value, functions);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    collect_function_helpers_from_expr(guard, functions);
                }
                collect_function_helpers_from_expr(&arm.value, functions);
            }
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            collect_function_helpers_from_expr(then_expr, functions);
            collect_function_helpers_from_expr(cond, functions);
            collect_function_helpers_from_expr(else_expr, functions);
        }
        ExprKind::Binary { left, right, .. } => {
            collect_function_helpers_from_expr(left, functions);
            collect_function_helpers_from_expr(right, functions);
        }
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::InterpolatedString(_)
        | ExprKind::Nil
        | ExprKind::None
        | ExprKind::Var(_) => {}
    }
}

fn source_span_key(span: SourceSpan) -> (u32, usize, usize, usize) {
    (span.source_id.value(), span.line, span.column, span.length)
}

fn source_span_from_key(key: (u32, usize, usize, usize)) -> SourceSpan {
    let (source_id, line, column, length) = key;
    SourceSpan::new(line, column, length).with_source(SourceId::new(source_id))
}

fn emit_source_line(out: &mut String, span: SourceSpan, source_paths: &HashMap<SourceId, String>) {
    let path = source_paths
        .get(&span.source_id)
        .cloned()
        .unwrap_or_else(|| {
            if span.source_id == SourceId::UNKNOWN {
                "flux.flux".to_string()
            } else {
                format!("flux-source-{}.flux", span.source_id.value())
            }
        });
    let escaped = path.replace('\\', "\\\\").replace('"', "\\\"");
    out.push_str(&format!("#line {} \"{}\"\n", span.line.max(1), escaped));
}

fn emit_async_task_runtime(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    continuation_lowered: bool,
) {
    let task_name = async_task_c_name(&function.name);
    let runner_name = async_run_c_name(&function.name);
    let start_name = async_start_c_name(&function.name);
    let start_cont_name = async_start_cont_c_name(&function.name);
    let await_name = async_await_c_name(&function.name);
    let body_name = async_body_c_name(&function.name);
    let resume_name = async_resume_c_name(&function.name);
    let finish_name = async_finish_c_name(&function.name);
    let release_name = async_release_c_name(&function.name);
    let args = (0..function.params.len())
        .map(|index| format!("flux__task->arg_{index}"))
        .collect::<Vec<_>>()
        .join(", ");

    out.push_str(&format!("{} {{\n", async_release_prototype(function)));
    out.push_str("    if (flux__task == NULL) return;\n");
    out.push_str("#ifdef FLUX_DEBUG_METADATA\n    flux__debug_task_unregister(&flux__task->debug_record);\n#endif\n");
    out.push_str("    pthread_cond_destroy(&flux__task->completed);\n");
    out.push_str("    pthread_mutex_destroy(&flux__task->mutex);\n");
    out.push_str("    free(flux__task);\n}\n");

    out.push_str(&format!("{} {{\n", async_finish_prototype(function)));
    out.push_str(&format!(
        "    flux__profile_timeline_emit(\"task\", \"{}\", \"finish\", flux__task->state);\n",
        function.name.replace('\\', "\\\\").replace('"', "\\\"")
    ));
    out.push_str("    const char *flux__scope_error = flux__async_scope_finish();\n");
    out.push_str(
        "    if (flux__task->scope_error == NULL) flux__task->scope_error = flux__scope_error;\n",
    );
    out.push_str("    if (flux__task->continuation != NULL) {\n");
    out.push_str(
        "        void (*flux__continuation)(void *, void *) = flux__task->continuation;\n",
    );
    out.push_str("        void *flux__context = flux__task->continuation_context;\n");
    out.push_str("        flux__continuation(flux__context, flux__task);\n");
    out.push_str("        return;\n    }\n");
    out.push_str("    pthread_mutex_lock(&flux__task->mutex);\n");
    out.push_str("    flux__task->done = true;\n");
    out.push_str("    pthread_cond_signal(&flux__task->completed);\n");
    out.push_str("    pthread_mutex_unlock(&flux__task->mutex);\n}\n");

    out.push_str(&format!(
        "{} {{\n    struct {task_name} *flux__task = (struct {task_name} *)flux__opaque;\n",
        async_run_prototype(function)
    ));
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    if continuation_lowered {
        out.push_str(&format!("    {resume_name}(flux__task, NULL);\n"));
    } else {
        match function.returns.as_slice() {
            [] => out.push_str(&format!("    {body_name}({args});\n")),
            _ => out.push_str(&format!("    flux__task->result = {body_name}({args});\n")),
        }
        out.push_str(&format!("    {finish_name}(flux__task);\n"));
    }
    out.push_str("    return NULL;\n}\n");

    out.push_str(&format!(
        "{} {{\n",
        async_start_cont_prototype(function, signatures)
    ));
    out.push_str(&format!(
        "    struct {task_name} *flux__task = malloc(sizeof(*flux__task));\n    if (flux__task == NULL) {{ fputs(\"Flux runtime error: unable to allocate async task state\\n\", stderr); abort(); }}\n"
    ));
    out.push_str("    if (pthread_mutex_init(&flux__task->mutex, NULL) != 0) { free(flux__task); fputs(\"Flux runtime error: unable to initialize async task mutex\\n\", stderr); abort(); }\n");
    out.push_str("    if (pthread_cond_init(&flux__task->completed, NULL) != 0) { pthread_mutex_destroy(&flux__task->mutex); free(flux__task); fputs(\"Flux runtime error: unable to initialize async task condition\\n\", stderr); abort(); }\n");
    out.push_str("    flux__task->done = false;\n    flux__task->state = 0;\n");
    out.push_str(&format!(
        "    flux__profile_timeline_emit(\"task\", \"{}\", \"start\", 0);\n",
        function.name.replace('\\', "\\\\").replace('"', "\\\"")
    ));
    out.push_str("    flux__task->continuation = flux__continuation;\n    flux__task->continuation_context = flux__context;\n");
    out.push_str("    flux__task->worker_scope_id = flux__async_scope_create();\n    flux__task->scope_error = NULL;\n");
    out.push_str(&format!(
        "#ifdef FLUX_DEBUG_METADATA\n    flux__debug_task_register(&flux__task->debug_record, \"{}\", flux__task, &flux__task->state, &flux__task->done, &flux__task->worker_scope_id);\n#endif\n",
        function.name.replace('\\', "\\\\").replace('"', "\\\"")
    ));
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "    flux__task->arg_{index} = {};\n",
            local_c_name(&param.name)
        ));
    }
    out.push_str(&format!(
        "    pthread_t flux__thread;\n    if (pthread_create(&flux__thread, NULL, {runner_name}, flux__task) != 0) {{ {release_name}(flux__task); fputs(\"Flux runtime error: unable to start async task\\n\", stderr); abort(); }}\n    if (pthread_detach(flux__thread) != 0) {{ fputs(\"Flux runtime error: unable to detach async task\\n\", stderr); abort(); }}\n    return flux__task;\n}}\n"
    ));

    out.push_str(&format!(
        "{} {{\n",
        async_start_prototype(function, signatures)
    ));
    let forwarded = function
        .params
        .iter()
        .map(|param| local_c_name(&param.name))
        .collect::<Vec<_>>();
    let mut start_args = forwarded;
    start_args.push("NULL".to_string());
    start_args.push("NULL".to_string());
    out.push_str(&format!(
        "    return {start_cont_name}({});\n}}\n",
        start_args.join(", ")
    ));

    out.push_str(&format!(
        "{} {{\n",
        async_await_prototype(function, signatures)
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async task\\n\", stderr); abort(); }\n");
    out.push_str("    pthread_mutex_lock(&flux__task->mutex);\n");
    out.push_str("    while (!flux__task->done) pthread_cond_wait(&flux__task->completed, &flux__task->mutex);\n");
    out.push_str("    pthread_mutex_unlock(&flux__task->mutex);\n");
    out.push_str("    if (flux__task->scope_error != NULL) { fputs(\"Flux async worker scope error: \", stderr); fputs(flux__task->scope_error, stderr); fputc('\\n', stderr); abort(); }\n");
    match function.returns.as_slice() {
        [] => out.push_str(&format!("    {release_name}(flux__task);\n}}\n")),
        [ty] => {
            out.push_str(&format!(
                "    {} flux__result = flux__task->result;\n    {release_name}(flux__task);\n    return flux__result;\n}}\n",
                c_type(ty, signatures)
            ));
        }
        _ => {
            out.push_str(&format!(
                "    struct {} flux__result = flux__task->result;\n    {release_name}(flux__task);\n    return flux__result;\n}}\n",
                multi_return_struct_name(&function.name)
            ));
        }
    }

    if function.name == "main" {
        out.push_str(&format!(
            "int main(void) {{\n    return flux__finish_main((int){await_name}({start_name}()));\n}}\n"
        ));
    }
}

fn emit_async_completed_await(
    out: &mut String,
    pad: &str,
    stmt: &Stmt,
    current_function: &Function,
    env: &mut HashMap<String, Type>,
    mutable: &mut HashSet<String>,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<(), Diagnostic> {
    let await_expr = continuation_await_expr(stmt).ok_or_else(|| {
        diag(
            stmt.span,
            "async continuation lowering requires a direct await statement",
        )
    })?;
    let (callee, _, _) = direct_await_call(await_expr).ok_or_else(|| {
        diag(
            await_expr.span,
            "async continuation lowering requires a direct async function call",
        )
    })?;
    let signature = signatures.get(callee).ok_or_else(|| {
        diag(
            await_expr.span,
            &format!("unknown async function '{callee}' during continuation lowering"),
        )
    })?;
    let child = format!("flux__completed_task_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct {} *{child} = (struct {} *)flux__completed_child;\n",
        async_task_c_name(callee),
        async_task_c_name(callee)
    ));
    out.push_str(&format!(
        "{pad}if ({child} == NULL) {{ fputs(\"Flux runtime error: missing completed async child\\n\", stderr); abort(); }}\n"
    ));
    out.push_str(&format!(
        "{pad}if ({child}->scope_error != NULL) {{ flux__task->scope_error = {child}->scope_error; {}({child}); {}(flux__task); return; }}\n",
        async_release_c_name(callee),
        async_finish_c_name(&current_function.name)
    ));

    let mut completes_current = false;
    match &stmt.kind {
        StmtKind::Let { name, ty, .. } | StmtKind::Var { name, ty, .. } => {
            let [actual] = signature.returns.as_slice() else {
                return Err(diag(
                    await_expr.span,
                    "single-value await changed return arity after type checking",
                ));
            };
            let declared = signatures.canonical_type(ty);
            let actual = signatures.canonical_type(actual);
            if declared != actual {
                return Err(diag(
                    stmt.span,
                    "await binding type changed after type checking",
                ));
            }
            out.push_str(&format!(
                "{pad}{} {} = {child}->result;\n",
                c_type(&declared, signatures),
                local_c_name(name)
            ));
            env.insert(name.clone(), declared);
            if matches!(stmt.kind, StmtKind::Var { .. }) {
                mutable.insert(name.clone());
            }
        }
        StmtKind::Assign {
            name,
            coalescing: false,
            ..
        } => {
            let [actual] = signature.returns.as_slice() else {
                return Err(diag(
                    await_expr.span,
                    "assignment await changed return arity after type checking",
                ));
            };
            let Some(expected) = env.get(name).map(|ty| signatures.canonical_type(ty)) else {
                return Err(diag(
                    stmt.span,
                    "async continuation assignment target disappeared after type checking",
                ));
            };
            let actual = signatures.canonical_type(actual);
            if expected != actual || !mutable.contains(name) {
                return Err(diag(
                    stmt.span,
                    "async continuation assignment contract changed after type checking",
                ));
            }
            out.push_str(&format!("{pad}{} = {child}->result;\n", local_c_name(name)));
        }
        StmtKind::Assign {
            name,
            coalescing: true,
            ..
        } => {
            let [actual] = signature.returns.as_slice() else {
                return Err(diag(
                    await_expr.span,
                    "coalescing assignment await changed return arity after type checking",
                ));
            };
            let Some(expected) = env.get(name).map(|ty| signatures.canonical_type(ty)) else {
                return Err(diag(
                    stmt.span,
                    "async continuation coalescing target disappeared after type checking",
                ));
            };
            let Type::Optional(inner) = &expected else {
                return Err(diag(
                    stmt.span,
                    "async continuation coalescing target stopped being optional after type checking",
                ));
            };
            if !mutable.contains(name) {
                return Err(diag(
                    stmt.span,
                    "async continuation coalescing target stopped being mutable after type checking",
                ));
            }
            let actual = signatures.canonical_type(actual);
            let inner = signatures.canonical_type(inner);
            if actual == inner {
                out.push_str(&format!(
                    "{pad}{}.has_value = true;\n{pad}{}.value = {child}->result;\n",
                    local_c_name(name),
                    local_c_name(name)
                ));
            } else if actual == expected {
                out.push_str(&format!("{pad}{} = {child}->result;\n", local_c_name(name)));
            } else {
                return Err(diag(
                    stmt.span,
                    "async continuation coalescing fallback type changed after type checking",
                ));
            }
        }
        StmtKind::AssignMultiDestructure { bindings, .. } => {
            if let [record_ty] = signature.returns.as_slice()
                && let Type::Record(fields) = signatures.canonical_type(record_ty)
            {
                if fields.len() != bindings.len() {
                    return Err(diag(
                        stmt.span,
                        "record assignment await changed arity after type checking",
                    ));
                }
                for (index, (binding, field)) in bindings.iter().zip(&fields).enumerate() {
                    if binding.name == "_" {
                        continue;
                    }
                    let Some(expected) = env
                        .get(&binding.name)
                        .map(|ty| signatures.canonical_type(ty))
                    else {
                        return Err(diag(
                            binding.span,
                            "async continuation assignment target disappeared after type checking",
                        ));
                    };
                    let actual = signatures.canonical_type(&field.ty);
                    if expected != actual || !mutable.contains(&binding.name) {
                        return Err(diag(
                            binding.span,
                            "async continuation assignment contract changed after type checking",
                        ));
                    }
                    out.push_str(&format!(
                        "{pad}{} = {child}->result.{};\n",
                        local_c_name(&binding.name),
                        record_field_c_name(field.name.as_deref(), index)
                    ));
                }
            } else {
                if signature.returns.len() != bindings.len() || signature.returns.len() < 2 {
                    return Err(diag(
                        stmt.span,
                        "multi-value assignment await changed return arity after type checking",
                    ));
                }
                for (index, (binding, actual)) in
                    bindings.iter().zip(&signature.returns).enumerate()
                {
                    if binding.name == "_" {
                        continue;
                    }
                    let Some(expected) = env
                        .get(&binding.name)
                        .map(|ty| signatures.canonical_type(ty))
                    else {
                        return Err(diag(
                            binding.span,
                            "async continuation assignment target disappeared after type checking",
                        ));
                    };
                    let actual = signatures.canonical_type(actual);
                    if expected != actual || !mutable.contains(&binding.name) {
                        return Err(diag(
                            binding.span,
                            "async continuation assignment contract changed after type checking",
                        ));
                    }
                    out.push_str(&format!(
                        "{pad}{} = {child}->result.v{index};\n",
                        local_c_name(&binding.name)
                    ));
                }
            }
        }
        StmtKind::LetDestructure {
            bindings,
            mutable: is_mutable,
            ..
        } => {
            if signature.returns.len() != bindings.len() || signature.returns.len() < 2 {
                return Err(diag(
                    stmt.span,
                    "typed multi-value await changed return arity after type checking",
                ));
            }
            let value = format!("flux__completed_result_{}", *temp_counter);
            *temp_counter += 1;
            out.push_str(&format!(
                "{pad}struct {} {value} = {child}->result;\n",
                multi_return_struct_name(callee)
            ));
            for (index, (binding, actual)) in bindings.iter().zip(&signature.returns).enumerate() {
                if binding.name == "_" {
                    continue;
                }
                let declared = signatures.canonical_type(&binding.ty);
                let actual = signatures.canonical_type(actual);
                if declared != actual {
                    return Err(diag(
                        binding.name_span,
                        "typed multi-value await binding changed type after type checking",
                    ));
                }
                out.push_str(&format!(
                    "{pad}{} {} = {value}.v{index};\n",
                    c_type(&declared, signatures),
                    local_c_name(&binding.name)
                ));
                env.insert(binding.name.clone(), declared);
                if *is_mutable {
                    mutable.insert(binding.name.clone());
                }
            }
        }
        StmtKind::LetMultiDestructure {
            bindings,
            mutable: is_mutable,
            ..
        } => {
            if let [record_ty] = signature.returns.as_slice()
                && let Type::Record(fields) = signatures.canonical_type(record_ty)
            {
                if fields.len() != bindings.len() {
                    return Err(diag(
                        stmt.span,
                        "record destructuring await changed arity after type checking",
                    ));
                }
                for (index, (binding, field)) in bindings.iter().zip(&fields).enumerate() {
                    if binding.name == "_" {
                        continue;
                    }
                    let ty = signatures.canonical_type(&field.ty);
                    out.push_str(&format!(
                        "{pad}{} {} = {child}->result.{};\n",
                        c_type(&ty, signatures),
                        local_c_name(&binding.name),
                        record_field_c_name(field.name.as_deref(), index)
                    ));
                    env.insert(binding.name.clone(), ty);
                    if *is_mutable {
                        mutable.insert(binding.name.clone());
                    }
                }
            } else {
                if signature.returns.len() != bindings.len() || signature.returns.len() < 2 {
                    return Err(diag(
                        stmt.span,
                        "multi-value await changed return arity after type checking",
                    ));
                }
                let value = format!("flux__completed_result_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}struct {} {value} = {child}->result;\n",
                    multi_return_struct_name(callee)
                ));
                for (index, (binding, ty)) in bindings.iter().zip(&signature.returns).enumerate() {
                    if binding.name == "_" {
                        continue;
                    }
                    let ty = signatures.canonical_type(ty);
                    out.push_str(&format!(
                        "{pad}{} {} = {value}.v{index};\n",
                        c_type(&ty, signatures),
                        local_c_name(&binding.name)
                    ));
                    env.insert(binding.name.clone(), ty);
                    if *is_mutable {
                        mutable.insert(binding.name.clone());
                    }
                }
            }
        }
        StmtKind::AssignStructDestructure {
            struct_name,
            fields,
            ..
        } => {
            let [actual] = signature.returns.as_slice() else {
                return Err(diag(
                    stmt.span,
                    "struct assignment await changed return arity after type checking",
                ));
            };
            let actual = signatures.canonical_type(actual);
            if actual != Type::Named(struct_name.clone()) {
                return Err(diag(
                    stmt.span,
                    "struct assignment await type changed after type checking",
                ));
            }
            let value = format!("flux__completed_struct_assign_{}", *temp_counter);
            *temp_counter += 1;
            out.push_str(&format!(
                "{pad}{} {value} = {child}->result;\n",
                c_type(&actual, signatures)
            ));
            emit_struct_pattern_assignments(
                out,
                pad,
                fields,
                struct_name,
                &value,
                signatures,
                None,
            )?;
        }
        StmtKind::LetStructDestructure {
            struct_name,
            fields,
            mutable: is_mutable,
            ..
        } => {
            let [actual] = signature.returns.as_slice() else {
                return Err(diag(
                    stmt.span,
                    "struct destructuring await changed return arity after type checking",
                ));
            };
            let actual = signatures.canonical_type(actual);
            if actual != Type::Named(struct_name.clone()) {
                return Err(diag(
                    stmt.span,
                    "struct destructuring await type changed after type checking",
                ));
            }
            let value = format!("flux__completed_struct_{}", *temp_counter);
            *temp_counter += 1;
            out.push_str(&format!(
                "{pad}{} {value} = {child}->result;\n",
                c_type(&actual, signatures)
            ));
            emit_struct_pattern_bindings(
                out,
                pad,
                fields,
                struct_name,
                &value,
                &mut PatternBindingEmitContext {
                    env,
                    signatures,
                    dead_definitions: None,
                },
            )?;
            if *is_mutable {
                mark_async_struct_pattern_mutable(fields, mutable);
            }
        }
        StmtKind::Expr(_) => {
            if !signature.returns.is_empty() {
                return Err(diag(
                    stmt.span,
                    "discarded await changed return arity after type checking",
                ));
            }
        }
        StmtKind::Return(_) => {
            let actual = signature
                .returns
                .iter()
                .map(|ty| signatures.canonical_type(ty))
                .collect::<Vec<_>>();
            let expected = current_function
                .returns
                .iter()
                .map(|ty| signatures.canonical_type(ty))
                .collect::<Vec<_>>();
            if actual != expected {
                return Err(diag(
                    stmt.span,
                    "return await shape changed after type checking",
                ));
            }
            match signature.returns.as_slice() {
                [] => {}
                [_] => out.push_str(&format!("{pad}flux__task->result = {child}->result;\n")),
                _ => {
                    for index in 0..signature.returns.len() {
                        out.push_str(&format!(
                            "{pad}flux__task->result.v{index} = {child}->result.v{index};\n"
                        ));
                    }
                }
            }
            completes_current = true;
        }
        _ => {
            return Err(diag(
                stmt.span,
                "unsupported statement reached async continuation completion lowering",
            ));
        }
    }
    out.push_str(&format!(
        "{pad}{}({child});\n",
        async_release_c_name(callee)
    ));
    if completes_current {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&current_function.name)
        ));
    }
    Ok(())
}

fn emit_async_save_locals(
    out: &mut String,
    pad: &str,
    saved_locals: &[(String, Type)],
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    span: SourceSpan,
) -> Result<(), Diagnostic> {
    for (name, saved_ty) in saved_locals {
        let Some(current_ty) = env.get(name) else {
            continue;
        };
        let saved_ty = signatures.canonical_type(saved_ty);
        let current_ty = signatures.canonical_type(current_ty);
        let field = async_saved_local_field_name(name);
        if saved_ty == current_ty {
            out.push_str(&format!(
                "{pad}flux__task->{field} = {};\n",
                local_c_name(name)
            ));
        } else if let Type::Optional(inner) = &saved_ty
            && signatures.canonical_type(inner) == current_ty
        {
            out.push_str(&format!(
                "{pad}flux__task->{field}.has_value = true;\n{pad}flux__task->{field}.value = {};\n",
                local_c_name(name)
            ));
        } else {
            return Err(diag(
                span,
                "async continuation local type changed across suspension",
            ));
        }
    }
    Ok(())
}

fn emit_async_restore_locals(
    out: &mut String,
    pad: &str,
    saved_locals: &[(String, Type)],
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    span: SourceSpan,
) -> Result<(), Diagnostic> {
    for (name, saved_ty) in saved_locals {
        let Some(current_ty) = env.get(name) else {
            continue;
        };
        let saved_ty = signatures.canonical_type(saved_ty);
        let current_ty = signatures.canonical_type(current_ty);
        let field = async_saved_local_field_name(name);
        let value = if current_ty == saved_ty {
            format!("flux__task->{field}")
        } else if let Type::Optional(inner) = &saved_ty
            && signatures.canonical_type(inner) == current_ty
        {
            format!("flux__task->{field}.value")
        } else {
            return Err(diag(
                span,
                "async continuation local type changed while restoring loop-control state",
            ));
        };
        out.push_str(&format!(
            "{pad}{} {} = {value};\n",
            c_type(&current_ty, signatures),
            local_c_name(name)
        ));
    }
    Ok(())
}

fn emit_async_suspend_expr(
    out: &mut String,
    pad: &str,
    await_expr: &Expr,
    span: SourceSpan,
    next_state: usize,
    function: &Function,
    plan: &AsyncContinuationPlan,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    let rewritten_await = cfg_direct_await_expr(await_expr, &plan.cfg_rewrite_facts)
        .map(cfg_scalar_expr_as_ast)
        .unwrap_or_else(|| {
            substitute_nested_ir_constant_arguments(await_expr, &plan.cfg_rewrite_facts)
        });
    let (callee, args, named_args) = direct_await_call(&rewritten_await).ok_or_else(|| {
        diag(
            await_expr.span,
            "async continuation lowering requires a direct async function call",
        )
    })?;
    let signature = signatures.get(callee).ok_or_else(|| {
        diag(
            await_expr.span,
            &format!("unknown async function '{callee}' during continuation lowering"),
        )
    })?;
    emit_async_save_locals(out, pad, &plan.locals, env, signatures, span)?;
    out.push_str(&format!("{pad}flux__task->state = {next_state};\n"));
    out.push_str(&format!(
        "{pad}flux__profile_timeline_emit(\"task\", \"{}\", \"suspend\", {next_state});\n",
        function.name.replace('\\', "\\\\").replace('"', "\\\"")
    ));
    let rendered = emit_call_arguments(signature, args, named_args, env, signatures)?;
    let mut start_args = rendered;
    start_args.push(async_resume_c_name(&function.name));
    start_args.push("flux__task".to_string());
    out.push_str(&format!(
        "{pad}(void){}({});\n",
        async_start_cont_c_name(callee),
        start_args.join(", ")
    ));
    out.push_str(&format!("{pad}return;\n"));
    Ok(())
}

fn emit_async_suspend(
    out: &mut String,
    pad: &str,
    stmt: &Stmt,
    next_state: usize,
    function: &Function,
    plan: &AsyncContinuationPlan,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
) -> Result<(), Diagnostic> {
    let await_expr = continuation_await_expr(stmt).ok_or_else(|| {
        diag(
            stmt.span,
            "async continuation lowering requires a direct await statement",
        )
    })?;
    emit_async_suspend_expr(
        out, pad, await_expr, stmt.span, next_state, function, plan, env, signatures,
    )
}

fn emit_async_completed_optional_await(
    out: &mut String,
    pad: &str,
    await_expr: &Expr,
    current_function: &Function,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<(String, Type), Diagnostic> {
    let (callee, _, _) = direct_await_call(await_expr).ok_or_else(|| {
        diag(
            await_expr.span,
            "async continuation lowering requires a direct async function call",
        )
    })?;
    let signature = signatures.get(callee).ok_or_else(|| {
        diag(
            await_expr.span,
            &format!("unknown async function '{callee}' during continuation lowering"),
        )
    })?;
    let [result_ty] = signature.returns.as_slice() else {
        return Err(diag(
            await_expr.span,
            "async optional if condition changed return arity after type checking",
        ));
    };
    let result_ty = signatures.canonical_type(result_ty);
    let Type::Optional(inner) = &result_ty else {
        return Err(diag(
            await_expr.span,
            "async optional if condition changed type after type checking",
        ));
    };
    let inner = signatures.canonical_type(inner);
    let child = format!("flux__completed_task_{}", *temp_counter);
    *temp_counter += 1;
    let result = format!("flux__async_optional_condition_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct {} *{child} = (struct {} *)flux__completed_child;\n",
        async_task_c_name(callee),
        async_task_c_name(callee)
    ));
    out.push_str(&format!(
        "{pad}if ({child} == NULL) {{ fputs(\"Flux runtime error: missing completed async child\\n\", stderr); abort(); }}\n"
    ));
    out.push_str(&format!(
        "{pad}if ({child}->scope_error != NULL) {{ flux__task->scope_error = {child}->scope_error; {}({child}); {}(flux__task); return; }}\n",
        async_release_c_name(callee),
        async_finish_c_name(&current_function.name)
    ));
    out.push_str(&format!(
        "{pad}{} {result} = {child}->result;\n",
        c_type(&result_ty, signatures)
    ));
    out.push_str(&format!(
        "{pad}{}({child});\n",
        async_release_c_name(callee)
    ));
    Ok((result, inner))
}

fn emit_async_completed_single_await(
    out: &mut String,
    pad: &str,
    await_expr: &Expr,
    current_function: &Function,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<(String, Type), Diagnostic> {
    let (callee, _, _) = direct_await_call(await_expr).ok_or_else(|| {
        diag(
            await_expr.span,
            "async continuation lowering requires a direct async function call",
        )
    })?;
    let signature = signatures.get(callee).ok_or_else(|| {
        diag(
            await_expr.span,
            &format!("unknown async function '{callee}' during continuation lowering"),
        )
    })?;
    let [result_ty] = signature.returns.as_slice() else {
        return Err(diag(
            await_expr.span,
            "async continuation expression changed return arity after type checking",
        ));
    };
    let result_ty = signatures.canonical_type(result_ty);
    let child = format!("flux__completed_task_{}", *temp_counter);
    *temp_counter += 1;
    let result = format!("flux__async_result_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct {} *{child} = (struct {} *)flux__completed_child;\n",
        async_task_c_name(callee),
        async_task_c_name(callee)
    ));
    out.push_str(&format!(
        "{pad}if ({child} == NULL) {{ fputs(\"Flux runtime error: missing completed async child\\n\", stderr); abort(); }}\n"
    ));
    out.push_str(&format!(
        "{pad}if ({child}->scope_error != NULL) {{ flux__task->scope_error = {child}->scope_error; {}({child}); {}(flux__task); return; }}\n",
        async_release_c_name(callee),
        async_finish_c_name(&current_function.name)
    ));
    out.push_str(&format!(
        "{pad}{} {result} = {child}->result;\n",
        c_type(&result_ty, signatures)
    ));
    out.push_str(&format!(
        "{pad}{}({child});\n",
        async_release_c_name(callee)
    ));
    Ok((result, result_ty))
}

fn emit_async_completed_bool_await(
    out: &mut String,
    pad: &str,
    await_expr: &Expr,
    current_function: &Function,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<String, Diagnostic> {
    let (callee, _, _) = direct_await_call(await_expr).ok_or_else(|| {
        diag(
            await_expr.span,
            "async continuation lowering requires a direct async function call",
        )
    })?;
    let signature = signatures.get(callee).ok_or_else(|| {
        diag(
            await_expr.span,
            &format!("unknown async function '{callee}' during continuation lowering"),
        )
    })?;
    let [result_ty] = signature.returns.as_slice() else {
        return Err(diag(
            await_expr.span,
            "async condition changed return arity after type checking",
        ));
    };
    if signatures.canonical_type(result_ty) != Type::Bool {
        return Err(diag(
            await_expr.span,
            "async condition changed type after type checking",
        ));
    }
    let child = format!("flux__completed_task_{}", *temp_counter);
    *temp_counter += 1;
    let result = format!("flux__async_condition_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct {} *{child} = (struct {} *)flux__completed_child;\n",
        async_task_c_name(callee),
        async_task_c_name(callee)
    ));
    out.push_str(&format!(
        "{pad}if ({child} == NULL) {{ fputs(\"Flux runtime error: missing completed async child\\n\", stderr); abort(); }}\n"
    ));
    out.push_str(&format!(
        "{pad}if ({child}->scope_error != NULL) {{ flux__task->scope_error = {child}->scope_error; {}({child}); {}(flux__task); return; }}\n",
        async_release_c_name(callee),
        async_finish_c_name(&current_function.name)
    ));
    out.push_str(&format!("{pad}bool {result} = {child}->result;\n"));
    out.push_str(&format!(
        "{pad}{}({child});\n",
        async_release_c_name(callee)
    ));
    Ok(result)
}

fn emit_async_branch_suspend(
    out: &mut String,
    pad: &str,
    stmt: &Stmt,
    next_state: usize,
    function: &Function,
    plan: &AsyncContinuationPlan,
    env: &HashMap<String, Type>,
    mutable: &HashSet<String>,
    signatures: &Signatures,
) -> Result<bool, Diagnostic> {
    let Some(_) = coalescing_assignment_await_expr(stmt) else {
        emit_async_suspend(out, pad, stmt, next_state, function, plan, env, signatures)?;
        return Ok(false);
    };
    let StmtKind::Assign {
        name,
        coalescing: true,
        ..
    } = &stmt.kind
    else {
        return Err(diag(
            stmt.span,
            "async coalescing branch continuation plan changed after type checking",
        ));
    };
    let Some(target_ty) = env.get(name).map(|ty| signatures.canonical_type(ty)) else {
        return Err(diag(
            stmt.span,
            "async coalescing branch target disappeared after type checking",
        ));
    };
    if !matches!(target_ty, Type::Optional(_)) || !mutable.contains(name) {
        return Err(diag(
            stmt.span,
            "async coalescing branch target contract changed after type checking",
        ));
    }
    out.push_str(&format!("{pad}if (!{}.has_value) {{\n", local_c_name(name)));
    let nested_pad = format!("{pad}    ");
    emit_async_suspend(
        out,
        &nested_pad,
        stmt,
        next_state,
        function,
        plan,
        env,
        signatures,
    )?;
    out.push_str(&format!("{pad}}}\n"));
    Ok(true)
}

fn emit_async_conditional_present_sequence(
    out: &mut String,
    pad: &str,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    block: &[Stmt],
    await_indices: &[usize],
    current_offset: usize,
    first_state: usize,
    env: &mut HashMap<String, Type>,
    mutable: &mut HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<bool, Diagnostic> {
    let mut segment_start = await_indices[current_offset] + 1;
    let depth = pad.len() / 4;
    for next_offset in current_offset + 1..await_indices.len() {
        let await_index = await_indices[next_offset];
        emit_block(
            out,
            &block[segment_start..await_index],
            depth,
            env,
            mutable,
            signatures,
            temp_counter,
            context,
        )?;
        let stmt = &block[await_index];
        emit_source_line(out, stmt.span, context.source_paths);
        let conditional_suspend = emit_async_branch_suspend(
            out,
            pad,
            stmt,
            first_state + next_offset,
            function,
            plan,
            env,
            mutable,
            signatures,
        )?;
        if !conditional_suspend {
            return Ok(false);
        }
        segment_start = await_index + 1;
    }
    emit_block(
        out,
        &block[segment_start..],
        depth,
        env,
        mutable,
        signatures,
        temp_counter,
        context,
    )?;
    Ok(true)
}

fn emit_async_branch_resume_states(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    await_block: &[Stmt],
    await_indices: &[usize],
    first_state: usize,
    tail_start: usize,
    mut branch_env: HashMap<String, Type>,
    mut branch_mutable: HashSet<String>,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let Some(first_await) = await_indices.first().copied() else {
        return Ok(());
    };
    let pad = "            ";
    let mut state_context = context;
    state_context.async_state_machine = true;
    let mut previous_await = first_await;
    let mut segment_start = first_await + 1;

    for offset in 0..await_indices.len() {
        let state = first_state + offset;
        out.push_str(&format!("        case {state}: {{\n"));
        for (index, param) in function.params.iter().enumerate() {
            let original_ty = signatures.canonical_type(&param.ty);
            let restored_ty = branch_env
                .get(&param.name)
                .map(|ty| signatures.canonical_type(ty))
                .unwrap_or_else(|| original_ty.clone());
            let value = if restored_ty == original_ty {
                format!("flux__task->arg_{index}")
            } else if let Type::Optional(inner) = &original_ty
                && signatures.canonical_type(inner) == restored_ty
            {
                format!("flux__task->arg_{index}.value")
            } else {
                return Err(diag(
                    function.span,
                    "async continuation parameter type changed across suspension",
                ));
            };
            out.push_str(&format!(
                "{pad}{} {} = {value};\n",
                c_type(&restored_ty, signatures),
                local_c_name(&param.name)
            ));
        }
        for (name, saved_ty) in &plan.locals {
            let Some(current_ty) = branch_env.get(name) else {
                continue;
            };
            let saved_ty = signatures.canonical_type(saved_ty);
            let current_ty = signatures.canonical_type(current_ty);
            let field = async_saved_local_field_name(name);
            let value = if current_ty == saved_ty {
                format!("flux__task->{field}")
            } else if let Type::Optional(inner) = &saved_ty
                && signatures.canonical_type(inner) == current_ty
            {
                format!("flux__task->{field}.value")
            } else {
                return Err(diag(
                    function.span,
                    "async continuation local type changed while restoring suspension state",
                ));
            };
            out.push_str(&format!(
                "{pad}{} {} = {value};\n",
                c_type(&current_ty, signatures),
                local_c_name(name)
            ));
        }
        out.push_str(&format!("{pad}{{\n"));
        let awaited_stmt = &await_block[previous_await];
        emit_async_completed_await(
            out,
            "                ",
            awaited_stmt,
            function,
            &mut branch_env,
            &mut branch_mutable,
            signatures,
            temp_counter,
        )?;
        let next_await = await_indices.get(offset + 1).copied();
        let segment_end = next_await.unwrap_or(await_block.len());
        emit_block(
            out,
            &await_block[segment_start..segment_end],
            4,
            &mut branch_env,
            &mut branch_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
        if let Some(await_index) = next_await {
            let next_stmt = &await_block[await_index];
            emit_source_line(out, next_stmt.span, context.source_paths);
            let conditional_suspend = emit_async_branch_suspend(
                out,
                "                ",
                next_stmt,
                state + 1,
                function,
                plan,
                &branch_env,
                &branch_mutable,
                signatures,
            )?;
            if conditional_suspend {
                let mut present_env = branch_env.clone();
                let mut present_mutable = branch_mutable.clone();
                let reaches_tail = emit_async_conditional_present_sequence(
                    out,
                    "                ",
                    function,
                    signatures,
                    plan,
                    await_block,
                    await_indices,
                    offset + 1,
                    first_state,
                    &mut present_env,
                    &mut present_mutable,
                    temp_counter,
                    state_context,
                )?;
                if reaches_tail {
                    let mut present_fallthrough_env = outer_env.clone();
                    let mut present_fallthrough_mutable = outer_mutable.clone();
                    emit_block(
                        out,
                        &function.body[tail_start..],
                        3,
                        &mut present_fallthrough_env,
                        &mut present_fallthrough_mutable,
                        signatures,
                        temp_counter,
                        state_context,
                    )?;
                    if function.returns.is_empty() {
                        out.push_str(&format!(
                            "{pad}{}(flux__task);\n{pad}return;\n",
                            async_finish_c_name(&function.name)
                        ));
                    } else {
                        out.push_str(&format!(
                            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
                        ));
                    }
                }
            }
            previous_await = await_index;
            segment_start = await_index + 1;
        }
        out.push_str(&format!("{pad}}}\n"));

        if next_await.is_none() {
            let mut resumed_fallthrough_env = outer_env.clone();
            let mut resumed_fallthrough_mutable = outer_mutable.clone();
            emit_block(
                out,
                &function.body[tail_start..],
                3,
                &mut resumed_fallthrough_env,
                &mut resumed_fallthrough_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            if function.returns.is_empty() {
                out.push_str(&format!(
                    "{pad}{}(flux__task);\n{pad}return;\n",
                    async_finish_c_name(&function.name)
                ));
            } else {
                out.push_str(&format!(
                    "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
                ));
            }
        }
        out.push_str("        }\n");
    }
    Ok(())
}

fn emit_async_nested_branch_tail(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    branch: &AsyncNestedBranchAwaitPlan,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
    depth: usize,
) -> Result<(), Diagnostic> {
    let pad = "    ".repeat(depth);
    let mut tail_env = outer_env.clone();
    let mut tail_mutable = outer_mutable.clone();
    emit_block(
        out,
        &function.body[branch.statement_index + 1..],
        depth,
        &mut tail_env,
        &mut tail_mutable,
        signatures,
        temp_counter,
        context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    Ok(())
}

fn emit_async_nested_branch_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    branch: &AsyncNestedBranchAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let StmtKind::If {
        cond,
        binding: None,
        body,
        else_body,
        ..
    } = &function.body[branch.statement_index].kind
    else {
        return Err(diag(
            function.body[branch.statement_index].span,
            "async nested-branch continuation plan no longer points at a plain if statement",
        ));
    };
    let [nested_stmt] = else_body.as_slice() else {
        return Err(diag(
            function.body[branch.statement_index].span,
            "async nested-branch continuation plan lost its nested branch",
        ));
    };
    let StmtKind::If {
        cond: nested_cond,
        binding: nested_binding,
        body: nested_body,
        else_body: nested_else_body,
        ..
    } = &nested_stmt.kind
    else {
        return Err(diag(
            nested_stmt.span,
            "async nested-branch continuation plan no longer points at a nested if statement",
        ));
    };

    let task_name = async_task_c_name(&function.name);
    let mut state_context = context;
    state_context.async_state_machine = true;
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut mutable = plan.mutable.clone();
    let pad = "            ";
    out.push_str("        case 0: {\n");
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..branch.statement_index],
        3,
        &mut env,
        &mut mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    let outer_env = env.clone();
    let outer_mutable = mutable.clone();
    let promotion = optional_presence_promotion(cond, &env, &mutable, signatures).map(
        |(name, inner, present_in_then)| {
            let temp = format!("flux__optional_promotion_{}", *temp_counter);
            *temp_counter += 1;
            (name, inner, present_in_then, temp)
        },
    );
    let condition = if let Some((name, inner, present_in_then, temp)) = &promotion {
        let optional_ty = Type::Optional(Box::new(inner.clone()));
        out.push_str(&format!(
            "{pad}{} {temp} = {};\n",
            c_type(&optional_ty, signatures),
            local_c_name(name)
        ));
        if *present_in_then {
            format!("{temp}.has_value")
        } else {
            format!("!{temp}.has_value")
        }
    } else {
        let condition = emit_expr(cond, &env, signatures)?;
        if signatures.canonical_type(&condition.ty) != Type::Bool {
            return Err(diag(
                cond.span,
                "async nested branch requires a boolean outer condition",
            ));
        }
        c_condition(&condition.code)
    };
    out.push_str(&format!("{pad}if ({condition}) {{\n"));
    let mut then_env = outer_env.clone();
    let mut then_mutable = outer_mutable.clone();
    if let Some((name, inner, true, temp)) = &promotion {
        out.push_str(&format!(
            "{pad}    {} {} = {temp}.value;\n",
            c_type(inner, signatures),
            local_c_name(name)
        ));
        then_env.insert(name.clone(), inner.clone());
    }
    emit_block(
        out,
        body,
        4,
        &mut then_env,
        &mut then_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    emit_async_nested_branch_tail(
        out,
        function,
        signatures,
        branch,
        &outer_env,
        &outer_mutable,
        temp_counter,
        state_context,
        4,
    )?;
    out.push_str(&format!("{pad}}} else {{\n"));
    let mut nested_outer_env = outer_env.clone();
    if let Some((name, inner, false, temp)) = &promotion {
        out.push_str(&format!(
            "{pad}    {} {} = {temp}.value;\n",
            c_type(inner, signatures),
            local_c_name(name)
        ));
        nested_outer_env.insert(name.clone(), inner.clone());
    }
    emit_source_line(out, nested_cond.span, context.source_paths);
    emit_async_suspend_expr(
        out,
        "                ",
        nested_cond,
        nested_cond.span,
        1,
        function,
        plan,
        &nested_outer_env,
        signatures,
    )?;
    out.push_str(&format!("{pad}}}\n"));
    out.push_str("        }\n");

    out.push_str("        case 1: {\n");
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_async_restore_locals(
        out,
        pad,
        &plan.locals,
        &outer_env,
        signatures,
        nested_cond.span,
    )?;
    let first_nested_state = 2;
    let mut nested_resume_scope = false;
    let mut nested_outer_env = outer_env.clone();
    if let Some((name, inner, false, _)) = &promotion {
        let promoted_temp = format!("flux__optional_resume_promotion_{}", *temp_counter);
        *temp_counter += 1;
        out.push_str(&format!(
            "{pad}{} {promoted_temp} = {}.value;\n{pad}{{\n{pad}    {} {} = {promoted_temp};\n",
            c_type(inner, signatures),
            local_c_name(name),
            c_type(inner, signatures),
            local_c_name(name)
        ));
        nested_outer_env.insert(name.clone(), inner.clone());
        nested_resume_scope = true;
    }
    let mut nested_then_env = nested_outer_env.clone();
    let mut nested_then_mutable = outer_mutable.clone();
    let mut nested_else_env = nested_outer_env.clone();
    let mut nested_else_mutable = outer_mutable.clone();
    let nested_condition = if let Some(binding) = nested_binding {
        let (temp, inner) = emit_async_completed_optional_await(
            out,
            pad,
            nested_cond,
            function,
            signatures,
            temp_counter,
        )?;
        if binding.name != "_" {
            out.push_str(&format!(
                "{pad}if ({temp}.has_value) {{\n{pad}    {} {} = {temp}.value;\n",
                c_type(&inner, signatures),
                local_c_name(&binding.name)
            ));
            nested_then_env.insert(binding.name.clone(), inner);
            None
        } else {
            Some(format!("{temp}.has_value"))
        }
    } else {
        Some(emit_async_completed_bool_await(
            out,
            pad,
            nested_cond,
            function,
            signatures,
            temp_counter,
        )?)
    };
    if let Some(nested_condition) = nested_condition {
        out.push_str(&format!("{pad}if ({nested_condition}) {{\n"));
    }
    if let Some(first_await) = branch.then_await_indices.first().copied() {
        emit_block(
            out,
            &nested_body[..first_await],
            4,
            &mut nested_then_env,
            &mut nested_then_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
        let awaited_stmt = &nested_body[first_await];
        emit_source_line(out, awaited_stmt.span, context.source_paths);
        let conditional_suspend = emit_async_branch_suspend(
            out,
            "                ",
            awaited_stmt,
            first_nested_state,
            function,
            plan,
            &nested_then_env,
            &nested_then_mutable,
            signatures,
        )?;
        if conditional_suspend {
            let mut present_env = nested_then_env.clone();
            let mut present_mutable = nested_then_mutable.clone();
            let _ = emit_async_conditional_present_sequence(
                out,
                "                ",
                function,
                signatures,
                plan,
                nested_body,
                &branch.then_await_indices,
                0,
                first_nested_state,
                &mut present_env,
                &mut present_mutable,
                temp_counter,
                state_context,
            )?;
        }
    } else {
        emit_block(
            out,
            nested_body,
            4,
            &mut nested_then_env,
            &mut nested_then_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
    }
    out.push_str(&format!("{pad}}}"));
    if nested_else_body.is_empty() {
        out.push('\n');
    } else {
        out.push_str(" else {\n");
        if let Some(first_await) = branch.else_await_indices.first().copied() {
            emit_block(
                out,
                &nested_else_body[..first_await],
                4,
                &mut nested_else_env,
                &mut nested_else_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            let awaited_stmt = &nested_else_body[first_await];
            emit_source_line(out, awaited_stmt.span, context.source_paths);
            let conditional_suspend = emit_async_branch_suspend(
                out,
                "                ",
                awaited_stmt,
                first_nested_state + branch.then_await_indices.len(),
                function,
                plan,
                &nested_else_env,
                &nested_else_mutable,
                signatures,
            )?;
            if conditional_suspend {
                let mut present_env = nested_else_env.clone();
                let mut present_mutable = nested_else_mutable.clone();
                let _ = emit_async_conditional_present_sequence(
                    out,
                    "                ",
                    function,
                    signatures,
                    plan,
                    nested_else_body,
                    &branch.else_await_indices,
                    0,
                    first_nested_state + branch.then_await_indices.len(),
                    &mut present_env,
                    &mut present_mutable,
                    temp_counter,
                    state_context,
                )?;
            }
        } else {
            emit_block(
                out,
                nested_else_body,
                4,
                &mut nested_else_env,
                &mut nested_else_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
        }
        out.push_str(&format!("{pad}}}\n"));
    }
    if nested_resume_scope {
        out.push_str(&format!("{pad}}}\n"));
    }
    emit_async_nested_branch_tail(
        out,
        function,
        signatures,
        branch,
        &outer_env,
        &outer_mutable,
        temp_counter,
        state_context,
        3,
    )?;
    out.push_str("        }\n");

    emit_async_branch_resume_states(
        out,
        function,
        signatures,
        plan,
        nested_body,
        &branch.then_await_indices,
        first_nested_state,
        branch.statement_index + 1,
        nested_then_env,
        nested_then_mutable,
        &outer_env,
        &outer_mutable,
        temp_counter,
        context,
    )?;
    emit_async_branch_resume_states(
        out,
        function,
        signatures,
        plan,
        nested_else_body,
        &branch.else_await_indices,
        first_nested_state + branch.then_await_indices.len(),
        branch.statement_index + 1,
        nested_else_env,
        nested_else_mutable,
        &outer_env,
        &outer_mutable,
        temp_counter,
        context,
    )?;

    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_branch_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    branch: &AsyncBranchAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let StmtKind::If {
        cond,
        binding,
        body,
        else_body,
        ..
    } = &function.body[branch.statement_index].kind
    else {
        return Err(diag(
            function.body[branch.statement_index].span,
            "async branch continuation plan no longer points at an if statement",
        ));
    };
    let task_name = async_task_c_name(&function.name);
    let mut state_context = context;
    state_context.async_state_machine = true;

    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut mutable = plan.mutable.clone();
    out.push_str("        case 0: {\n");
    let pad = "            ";
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..branch.statement_index],
        3,
        &mut env,
        &mut mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    let outer_env = env.clone();
    let outer_mutable = mutable.clone();
    let first_branch_state = if branch.condition_await { 2 } else { 1 };
    let mut completed_optional_binding = None;
    let completed_condition = if branch.condition_await {
        emit_source_line(out, cond.span, context.source_paths);
        emit_async_suspend_expr(
            out, pad, cond, cond.span, 1, function, plan, &env, signatures,
        )?;
        out.push_str("        }\n");
        out.push_str("        case 1: {\n");
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        emit_async_restore_locals(out, pad, &plan.locals, &outer_env, signatures, cond.span)?;
        if let Some(binding) = binding {
            let (temp, inner) = emit_async_completed_optional_await(
                out,
                pad,
                cond,
                function,
                signatures,
                temp_counter,
            )?;
            completed_optional_binding = Some((binding.name.clone(), inner, temp));
            None
        } else {
            Some(emit_async_completed_bool_await(
                out,
                pad,
                cond,
                function,
                signatures,
                temp_counter,
            )?)
        }
    } else {
        None
    };
    let promotion = (!branch.condition_await && binding.is_none())
        .then(|| optional_presence_promotion(cond, &env, &mutable, signatures))
        .flatten()
        .map(|(name, inner, present_in_then)| {
            let temp = format!("flux__optional_promotion_{}", *temp_counter);
            *temp_counter += 1;
            (name, inner, present_in_then, temp)
        });
    let mut optional_binding = completed_optional_binding;
    let condition = if let Some(condition) = completed_condition {
        condition
    } else if let Some((_, _, temp)) = &optional_binding {
        format!("{temp}.has_value")
    } else if let Some(binding) = binding {
        let optional = emit_expr(cond, &env, signatures)?;
        let Type::Optional(inner) = signatures.canonical_type(&optional.ty) else {
            return Err(diag(
                cond.span,
                "non-optional value reached async optional pattern code generation",
            ));
        };
        let inner = signatures.canonical_type(&inner);
        let temp = format!("flux__optional_pattern_{}", *temp_counter);
        *temp_counter += 1;
        out.push_str(&format!(
            "{pad}{} {temp} = {};\n",
            c_type(&Type::Optional(Box::new(inner.clone())), signatures),
            optional.code
        ));
        optional_binding = Some((binding.name.clone(), inner, temp.clone()));
        format!("{temp}.has_value")
    } else if let Some((name, inner, present_in_then, temp)) = &promotion {
        let optional_ty = Type::Optional(Box::new(inner.clone()));
        out.push_str(&format!(
            "{pad}{} {temp} = {};\n",
            c_type(&optional_ty, signatures),
            local_c_name(name)
        ));
        if *present_in_then {
            format!("{temp}.has_value")
        } else {
            format!("!{temp}.has_value")
        }
    } else {
        let condition = emit_expr(cond, &env, signatures)?;
        c_condition(&condition.code)
    };
    out.push_str(&format!("{pad}if ({condition}) {{\n"));

    let mut then_env = outer_env.clone();
    let mut then_mutable = outer_mutable.clone();
    let mut else_env = outer_env.clone();
    let mut else_mutable = outer_mutable.clone();
    if let Some((name, inner, temp)) = &optional_binding
        && name != "_"
    {
        out.push_str(&format!(
            "{pad}    {} {} = {temp}.value;\n",
            c_type(inner, signatures),
            local_c_name(name)
        ));
        then_env.insert(name.clone(), inner.clone());
    } else if let Some((name, inner, true, temp)) = &promotion {
        out.push_str(&format!(
            "{pad}    {} {} = {temp}.value;\n",
            c_type(inner, signatures),
            local_c_name(name)
        ));
        then_env.insert(name.clone(), inner.clone());
    }
    if let Some(first_await) = branch.then_await_indices.first().copied() {
        emit_block(
            out,
            &body[..first_await],
            4,
            &mut then_env,
            &mut then_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
        let awaited_stmt = &body[first_await];
        emit_source_line(out, awaited_stmt.span, context.source_paths);
        let conditional_suspend = emit_async_branch_suspend(
            out,
            "                ",
            awaited_stmt,
            first_branch_state,
            function,
            plan,
            &then_env,
            &then_mutable,
            signatures,
        )?;
        if conditional_suspend {
            let mut present_env = then_env.clone();
            let mut present_mutable = then_mutable.clone();
            let _ = emit_async_conditional_present_sequence(
                out,
                "                ",
                function,
                signatures,
                plan,
                body,
                &branch.then_await_indices,
                0,
                first_branch_state,
                &mut present_env,
                &mut present_mutable,
                temp_counter,
                state_context,
            )?;
        }
    } else {
        emit_block(
            out,
            body,
            4,
            &mut then_env,
            &mut then_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
    }

    if else_body.is_empty() {
        out.push_str(&format!("{pad}}}\n"));
    } else {
        out.push_str(&format!("{pad}}} else {{\n"));
        if let Some((name, inner, false, temp)) = &promotion {
            out.push_str(&format!(
                "{pad}    {} {} = {temp}.value;\n",
                c_type(inner, signatures),
                local_c_name(name)
            ));
            else_env.insert(name.clone(), inner.clone());
        }
        if let Some(first_await) = branch.else_await_indices.first().copied() {
            emit_block(
                out,
                &else_body[..first_await],
                4,
                &mut else_env,
                &mut else_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            let awaited_stmt = &else_body[first_await];
            emit_source_line(out, awaited_stmt.span, context.source_paths);
            let conditional_suspend = emit_async_branch_suspend(
                out,
                "                ",
                awaited_stmt,
                first_branch_state + branch.then_await_indices.len(),
                function,
                plan,
                &else_env,
                &else_mutable,
                signatures,
            )?;
            if conditional_suspend {
                let mut present_env = else_env.clone();
                let mut present_mutable = else_mutable.clone();
                let _ = emit_async_conditional_present_sequence(
                    out,
                    "                ",
                    function,
                    signatures,
                    plan,
                    else_body,
                    &branch.else_await_indices,
                    0,
                    first_branch_state + branch.then_await_indices.len(),
                    &mut present_env,
                    &mut present_mutable,
                    temp_counter,
                    state_context,
                )?;
            }
        } else {
            emit_block(
                out,
                else_body,
                4,
                &mut else_env,
                &mut else_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
        }
        out.push_str(&format!("{pad}}}\n"));
    }

    let mut fallthrough_env = outer_env.clone();
    let mut fallthrough_mutable = outer_mutable.clone();
    emit_block(
        out,
        &function.body[branch.statement_index + 1..],
        3,
        &mut fallthrough_env,
        &mut fallthrough_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    out.push_str("        }\n");

    emit_async_branch_resume_states(
        out,
        function,
        signatures,
        plan,
        body,
        &branch.then_await_indices,
        first_branch_state,
        branch.statement_index + 1,
        then_env,
        then_mutable,
        &outer_env,
        &outer_mutable,
        temp_counter,
        context,
    )?;

    emit_async_branch_resume_states(
        out,
        function,
        signatures,
        plan,
        else_body,
        &branch.else_await_indices,
        first_branch_state + branch.then_await_indices.len(),
        branch.statement_index + 1,
        else_env,
        else_mutable,
        &outer_env,
        &outer_mutable,
        temp_counter,
        context,
    )?;

    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_while_tail(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    while_plan: &AsyncWhileAwaitPlan,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    let mut tail_env = outer_env.clone();
    let mut tail_mutable = outer_mutable.clone();
    emit_block(
        out,
        &function.body[while_plan.statement_index + 1..],
        3,
        &mut tail_env,
        &mut tail_mutable,
        signatures,
        temp_counter,
        context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    Ok(())
}

fn emit_async_while_condition_body(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    while_plan: &AsyncWhileAwaitPlan,
    condition: &str,
    body: &[Stmt],
    first_body_state: usize,
    continue_state: usize,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(HashMap<String, Type>, HashSet<String>), Diagnostic> {
    let pad = "            ";
    out.push_str(&format!("{pad}if ({condition}) {{\n"));
    let mut body_env = outer_env.clone();
    let mut body_mutable = outer_mutable.clone();
    if let Some(first_await) = while_plan.body_await_indices.first().copied() {
        emit_block(
            out,
            &body[..first_await],
            4,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
            context,
        )?;
        let awaited_stmt = &body[first_await];
        emit_source_line(out, awaited_stmt.span, context.source_paths);
        let conditional_suspend = emit_async_branch_suspend(
            out,
            "                ",
            awaited_stmt,
            first_body_state,
            function,
            plan,
            &body_env,
            &body_mutable,
            signatures,
        )?;
        if conditional_suspend {
            let reaches_continue = emit_async_conditional_present_sequence(
                out,
                "                ",
                function,
                signatures,
                plan,
                body,
                &while_plan.body_await_indices,
                0,
                first_body_state,
                &mut body_env,
                &mut body_mutable,
                temp_counter,
                context,
            )?;
            if reaches_continue {
                emit_async_save_locals(
                    out,
                    "                ",
                    &plan.locals,
                    &body_env,
                    signatures,
                    awaited_stmt.span,
                )?;
                out.push_str(&format!(
                    "{pad}    flux__task->state = {continue_state};\n{pad}    continue;\n"
                ));
            }
        }
    } else {
        emit_block(
            out,
            body,
            4,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
            context,
        )?;
        emit_async_save_locals(
            out,
            "                ",
            &plan.locals,
            &body_env,
            signatures,
            function.body[while_plan.statement_index].span,
        )?;
        out.push_str(&format!(
            "{pad}    flux__task->state = {continue_state};\n{pad}    continue;\n"
        ));
    }
    out.push_str(&format!("{pad}}}\n"));

    emit_async_while_tail(
        out,
        function,
        signatures,
        while_plan,
        outer_env,
        outer_mutable,
        temp_counter,
        context,
    )?;
    Ok((body_env, body_mutable))
}

fn emit_async_while_iteration(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    while_plan: &AsyncWhileAwaitPlan,
    cond: &Expr,
    body: &[Stmt],
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(HashMap<String, Type>, HashSet<String>), Diagnostic> {
    if while_plan.condition_await {
        emit_source_line(out, cond.span, context.source_paths);
        emit_async_suspend_expr(
            out,
            "            ",
            cond,
            cond.span,
            1,
            function,
            plan,
            outer_env,
            signatures,
        )?;
        return Ok((outer_env.clone(), outer_mutable.clone()));
    }
    let condition = emit_expr(cond, outer_env, signatures)?;
    let first_body_state = 1;
    let continue_state = first_body_state + while_plan.body_await_indices.len();
    emit_async_while_condition_body(
        out,
        function,
        signatures,
        plan,
        while_plan,
        &c_condition(&condition.code),
        body,
        first_body_state,
        continue_state,
        outer_env,
        outer_mutable,
        temp_counter,
        context,
    )
}

fn emit_async_while_resume_states(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    while_plan: &AsyncWhileAwaitPlan,
    cond: &Expr,
    body: &[Stmt],
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    mut body_env: HashMap<String, Type>,
    mut body_mutable: HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    let mut state_context = context;
    state_context.async_state_machine = true;
    let await_indices = &while_plan.body_await_indices;
    let Some(mut previous_await) = await_indices.first().copied() else {
        return Ok(());
    };
    let mut segment_start = previous_await + 1;
    let first_state = if while_plan.condition_await { 2 } else { 1 };
    let continue_state = first_state + await_indices.len();

    for offset in 0..await_indices.len() {
        let state = first_state + offset;
        out.push_str(&format!("        case {state}: {{\n"));
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        for (name, ty) in &plan.locals {
            if body_env.contains_key(name) {
                out.push_str(&format!(
                    "{pad}{} {} = flux__task->{};\n",
                    c_type(ty, signatures),
                    local_c_name(name),
                    async_saved_local_field_name(name)
                ));
            }
        }
        let awaited_stmt = &body[previous_await];
        emit_async_completed_await(
            out,
            pad,
            awaited_stmt,
            function,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
        )?;
        let next_await = await_indices.get(offset + 1).copied();
        let segment_end = next_await.unwrap_or(body.len());
        emit_block(
            out,
            &body[segment_start..segment_end],
            3,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
        if let Some(next_await_index) = next_await {
            let next_stmt = &body[next_await_index];
            emit_source_line(out, next_stmt.span, context.source_paths);
            let conditional_suspend = emit_async_branch_suspend(
                out,
                pad,
                next_stmt,
                state + 1,
                function,
                plan,
                &body_env,
                &body_mutable,
                signatures,
            )?;
            if conditional_suspend {
                let mut present_env = body_env.clone();
                let mut present_mutable = body_mutable.clone();
                let reaches_continue = emit_async_conditional_present_sequence(
                    out,
                    pad,
                    function,
                    signatures,
                    plan,
                    body,
                    await_indices,
                    offset + 1,
                    first_state,
                    &mut present_env,
                    &mut present_mutable,
                    temp_counter,
                    state_context,
                )?;
                if reaches_continue {
                    emit_async_save_locals(
                        out,
                        pad,
                        &plan.locals,
                        &present_env,
                        signatures,
                        next_stmt.span,
                    )?;
                    out.push_str(&format!(
                        "{pad}flux__task->state = {continue_state};\n{pad}continue;\n"
                    ));
                }
            }
            previous_await = next_await_index;
            segment_start = next_await_index + 1;
        } else {
            let _ = emit_async_while_iteration(
                out,
                function,
                signatures,
                plan,
                while_plan,
                cond,
                body,
                outer_env,
                outer_mutable,
                temp_counter,
                state_context,
            )?;
        }
        out.push_str("        }\n");
    }
    Ok(())
}

fn emit_async_while_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    while_plan: &AsyncWhileAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let StmtKind::While { cond, body } = &function.body[while_plan.statement_index].kind else {
        return Err(diag(
            function.body[while_plan.statement_index].span,
            "async while continuation plan no longer points at a while statement",
        ));
    };
    let task_name = async_task_c_name(&function.name);
    let first_body_state = if while_plan.condition_await { 2 } else { 1 };
    let continue_state = first_body_state + while_plan.body_await_indices.len();
    let break_state = continue_state + 1;
    let mut state_context = context;
    state_context.async_state_machine = true;
    let mut loop_context = state_context;
    loop_context.async_loop_control = Some(AsyncLoopControlContext {
        continue_state,
        break_state,
        saved_locals: &plan.locals,
    });
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    for (;;) {\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut outer_env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut outer_mutable = plan.mutable.clone();
    out.push_str("        case 0: {\n");
    let pad = "            ";
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..while_plan.statement_index],
        3,
        &mut outer_env,
        &mut outer_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    let initial_body_state = emit_async_while_iteration(
        out,
        function,
        signatures,
        plan,
        while_plan,
        cond,
        body,
        &outer_env,
        &outer_mutable,
        temp_counter,
        loop_context,
    )?;
    out.push_str("        }\n");

    let (body_env, body_mutable) = if while_plan.condition_await {
        out.push_str("        case 1: {\n");
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        emit_async_restore_locals(out, pad, &plan.locals, &outer_env, signatures, cond.span)?;
        let completed_condition =
            emit_async_completed_bool_await(out, pad, cond, function, signatures, temp_counter)?;
        let body_state = emit_async_while_condition_body(
            out,
            function,
            signatures,
            plan,
            while_plan,
            &completed_condition,
            body,
            first_body_state,
            continue_state,
            &outer_env,
            &outer_mutable,
            temp_counter,
            loop_context,
        )?;
        out.push_str("        }\n");
        body_state
    } else {
        initial_body_state
    };

    emit_async_while_resume_states(
        out,
        function,
        signatures,
        plan,
        while_plan,
        cond,
        body,
        &outer_env,
        &outer_mutable,
        body_env,
        body_mutable,
        temp_counter,
        loop_context,
    )?;

    out.push_str(&format!("        case {continue_state}: {{\n"));
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_async_restore_locals(
        out,
        pad,
        &plan.locals,
        &outer_env,
        signatures,
        function.span,
    )?;
    let _ = emit_async_while_iteration(
        out,
        function,
        signatures,
        plan,
        while_plan,
        cond,
        body,
        &outer_env,
        &outer_mutable,
        temp_counter,
        loop_context,
    )?;
    out.push_str("        }\n");

    out.push_str(&format!("        case {break_state}: {{\n"));
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_async_restore_locals(
        out,
        pad,
        &plan.locals,
        &outer_env,
        signatures,
        function.span,
    )?;
    emit_async_while_tail(
        out,
        function,
        signatures,
        while_plan,
        &outer_env,
        &outer_mutable,
        temp_counter,
        state_context,
    )?;
    out.push_str("        }\n");
    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_for_range_tail(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    for_plan: &AsyncForRangeAwaitPlan,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    let mut tail_env = outer_env.clone();
    let mut tail_mutable = outer_mutable.clone();
    emit_block(
        out,
        &function.body[for_plan.statement_index + 1..],
        3,
        &mut tail_env,
        &mut tail_mutable,
        signatures,
        temp_counter,
        context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    Ok(())
}

fn emit_async_for_range_iteration(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    for_plan: &AsyncForRangeAwaitPlan,
    name: &str,
    body: &[Stmt],
    inclusive: bool,
    end_code: &str,
    advance: bool,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(HashMap<String, Type>, HashSet<String>), Diagnostic> {
    let first_body_state = 1 + usize::from(for_plan.start_await) + usize::from(for_plan.end_await);
    let continue_state = first_body_state + for_plan.body_await_indices.len();
    let pad = "            ";
    let c_name = local_c_name(name);
    if advance {
        if inclusive {
            out.push_str(&format!("{pad}if ({c_name} != {end_code}) {{\n"));
            out.push_str(&format!("{pad}    ++{c_name};\n"));
        } else {
            out.push_str(&format!("{pad}++{c_name};\n"));
            out.push_str(&format!("{pad}if ({c_name} < {end_code}) {{\n"));
        }
    } else {
        let comparison = if inclusive { "<=" } else { "<" };
        out.push_str(&format!("{pad}if ({c_name} {comparison} {end_code}) {{\n"));
    }

    let mut body_env = outer_env.clone();
    body_env.insert(name.to_string(), Type::I64);
    let mut body_mutable = outer_mutable.clone();
    if let Some(first_await) = for_plan.body_await_indices.first().copied() {
        emit_block(
            out,
            &body[..first_await],
            4,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
            context,
        )?;
        let awaited_stmt = &body[first_await];
        emit_source_line(out, awaited_stmt.span, context.source_paths);
        let conditional_suspend = emit_async_branch_suspend(
            out,
            "                ",
            awaited_stmt,
            first_body_state,
            function,
            plan,
            &body_env,
            &body_mutable,
            signatures,
        )?;
        if conditional_suspend {
            let reaches_continue = emit_async_conditional_present_sequence(
                out,
                "                ",
                function,
                signatures,
                plan,
                body,
                &for_plan.body_await_indices,
                0,
                first_body_state,
                &mut body_env,
                &mut body_mutable,
                temp_counter,
                context,
            )?;
            if reaches_continue {
                emit_async_save_locals(
                    out,
                    "                ",
                    &plan.locals,
                    &body_env,
                    signatures,
                    awaited_stmt.span,
                )?;
                out.push_str(&format!(
                    "{pad}    flux__task->state = {continue_state};\n{pad}    continue;\n"
                ));
            }
        }
    } else {
        emit_block(
            out,
            body,
            4,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
            context,
        )?;
        emit_async_save_locals(
            out,
            "                ",
            &plan.locals,
            &body_env,
            signatures,
            function.body[for_plan.statement_index].span,
        )?;
        out.push_str(&format!(
            "{pad}    flux__task->state = {continue_state};\n{pad}    continue;\n"
        ));
    }
    out.push_str(&format!("{pad}}}\n"));
    emit_async_for_range_tail(
        out,
        function,
        signatures,
        for_plan,
        outer_env,
        outer_mutable,
        temp_counter,
        context,
    )?;
    Ok((body_env, body_mutable))
}

fn emit_async_for_range_resume_states(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    for_plan: &AsyncForRangeAwaitPlan,
    name: &str,
    body: &[Stmt],
    inclusive: bool,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    mut body_env: HashMap<String, Type>,
    mut body_mutable: HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    let mut state_context = context;
    state_context.async_state_machine = true;
    let await_indices = &for_plan.body_await_indices;
    let Some(mut previous_await) = await_indices.first().copied() else {
        return Ok(());
    };
    let mut segment_start = previous_await + 1;
    let first_body_state = 1 + usize::from(for_plan.start_await) + usize::from(for_plan.end_await);
    let continue_state = first_body_state + await_indices.len();

    for offset in 0..await_indices.len() {
        let state = first_body_state + offset;
        out.push_str(&format!("        case {state}: {{\n"));
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        for (saved_name, ty) in &plan.locals {
            if body_env.contains_key(saved_name) {
                out.push_str(&format!(
                    "{pad}{} {} = flux__task->{};\n",
                    c_type(ty, signatures),
                    local_c_name(saved_name),
                    async_saved_local_field_name(saved_name)
                ));
            }
        }
        let awaited_stmt = &body[previous_await];
        emit_async_completed_await(
            out,
            pad,
            awaited_stmt,
            function,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
        )?;
        let next_await = await_indices.get(offset + 1).copied();
        let segment_end = next_await.unwrap_or(body.len());
        emit_block(
            out,
            &body[segment_start..segment_end],
            3,
            &mut body_env,
            &mut body_mutable,
            signatures,
            temp_counter,
            state_context,
        )?;
        if let Some(next_await_index) = next_await {
            let next_stmt = &body[next_await_index];
            emit_source_line(out, next_stmt.span, context.source_paths);
            let conditional_suspend = emit_async_branch_suspend(
                out,
                pad,
                next_stmt,
                state + 1,
                function,
                plan,
                &body_env,
                &body_mutable,
                signatures,
            )?;
            if conditional_suspend {
                let mut present_env = body_env.clone();
                let mut present_mutable = body_mutable.clone();
                let reaches_continue = emit_async_conditional_present_sequence(
                    out,
                    pad,
                    function,
                    signatures,
                    plan,
                    body,
                    await_indices,
                    offset + 1,
                    first_body_state,
                    &mut present_env,
                    &mut present_mutable,
                    temp_counter,
                    state_context,
                )?;
                if reaches_continue {
                    emit_async_save_locals(
                        out,
                        pad,
                        &plan.locals,
                        &present_env,
                        signatures,
                        next_stmt.span,
                    )?;
                    out.push_str(&format!(
                        "{pad}flux__task->state = {continue_state};\n{pad}continue;\n"
                    ));
                }
            }
            previous_await = next_await_index;
            segment_start = next_await_index + 1;
        } else {
            let _ = emit_async_for_range_iteration(
                out,
                function,
                signatures,
                plan,
                for_plan,
                name,
                body,
                inclusive,
                "flux__task->saved_flux__async_range_end",
                true,
                outer_env,
                outer_mutable,
                temp_counter,
                state_context,
            )?;
        }
        out.push_str("        }\n");
    }
    Ok(())
}

fn emit_async_for_range_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    for_plan: &AsyncForRangeAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let StmtKind::ForRange {
        name,
        start,
        end,
        inclusive,
        body,
        ..
    } = &function.body[for_plan.statement_index].kind
    else {
        return Err(diag(
            function.body[for_plan.statement_index].span,
            "async for-range continuation plan no longer points at a range loop",
        ));
    };
    let task_name = async_task_c_name(&function.name);
    let first_body_state = 1 + usize::from(for_plan.start_await) + usize::from(for_plan.end_await);
    let continue_state = first_body_state + for_plan.body_await_indices.len();
    let break_state = continue_state + 1;
    let mut state_context = context;
    state_context.async_state_machine = true;
    let mut loop_context = state_context;
    loop_context.async_loop_control = Some(AsyncLoopControlContext {
        continue_state,
        break_state,
        saved_locals: &plan.locals,
    });
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    for (;;) {\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut outer_env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut outer_mutable = plan.mutable.clone();
    out.push_str("        case 0: {\n");
    let pad = "            ";
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..for_plan.statement_index],
        3,
        &mut outer_env,
        &mut outer_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;

    let mut range_env = outer_env.clone();
    range_env.insert(name.clone(), Type::I64);
    let mut initial_body_state = None;
    if for_plan.start_await {
        emit_source_line(out, start.span, context.source_paths);
        emit_async_suspend_expr(
            out, pad, start, start.span, 1, function, plan, &outer_env, signatures,
        )?;
    } else {
        let start_value = emit_expr(start, &outer_env, signatures)?;
        out.push_str(&format!(
            "{pad}int64_t {} = {};\n",
            local_c_name(name),
            start_value.code
        ));
        if for_plan.end_await {
            emit_source_line(out, end.span, context.source_paths);
            emit_async_suspend_expr(
                out, pad, end, end.span, 1, function, plan, &range_env, signatures,
            )?;
        } else {
            let end_value = emit_expr(end, &outer_env, signatures)?;
            out.push_str(&format!(
                "{pad}int64_t flux__async_range_end = {};\n",
                end_value.code
            ));
            out.push_str(
                "            flux__task->saved_flux__async_range_end = flux__async_range_end;\n",
            );
            initial_body_state = Some(emit_async_for_range_iteration(
                out,
                function,
                signatures,
                plan,
                for_plan,
                name,
                body,
                *inclusive,
                "flux__async_range_end",
                false,
                &outer_env,
                &outer_mutable,
                temp_counter,
                loop_context,
            )?);
        }
    }
    out.push_str("        }\n");

    if for_plan.start_await {
        out.push_str("        case 1: {\n");
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        emit_async_restore_locals(out, pad, &plan.locals, &outer_env, signatures, start.span)?;
        let (completed_start, completed_ty) =
            emit_async_completed_single_await(out, pad, start, function, signatures, temp_counter)?;
        if completed_ty != Type::I64 {
            return Err(diag(
                start.span,
                "async range start changed type after type checking",
            ));
        }
        out.push_str(&format!(
            "{pad}int64_t {} = {completed_start};\n",
            local_c_name(name)
        ));
        if for_plan.end_await {
            emit_source_line(out, end.span, context.source_paths);
            emit_async_suspend_expr(
                out, pad, end, end.span, 2, function, plan, &range_env, signatures,
            )?;
        } else {
            let end_value = emit_expr(end, &outer_env, signatures)?;
            out.push_str(&format!(
                "{pad}int64_t flux__async_range_end = {};\n",
                end_value.code
            ));
            out.push_str(
                "            flux__task->saved_flux__async_range_end = flux__async_range_end;\n",
            );
            initial_body_state = Some(emit_async_for_range_iteration(
                out,
                function,
                signatures,
                plan,
                for_plan,
                name,
                body,
                *inclusive,
                "flux__async_range_end",
                false,
                &outer_env,
                &outer_mutable,
                temp_counter,
                loop_context,
            )?);
        }
        out.push_str("        }\n");
    }

    if for_plan.end_await {
        let end_state = 1 + usize::from(for_plan.start_await);
        out.push_str(&format!("        case {end_state}: {{\n"));
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        emit_async_restore_locals(out, pad, &plan.locals, &range_env, signatures, end.span)?;
        let (completed_end, completed_ty) =
            emit_async_completed_single_await(out, pad, end, function, signatures, temp_counter)?;
        if completed_ty != Type::I64 {
            return Err(diag(
                end.span,
                "async range end changed type after type checking",
            ));
        }
        out.push_str(&format!(
            "{pad}int64_t flux__async_range_end = {completed_end};\n"
        ));
        out.push_str(
            "            flux__task->saved_flux__async_range_end = flux__async_range_end;\n",
        );
        initial_body_state = Some(emit_async_for_range_iteration(
            out,
            function,
            signatures,
            plan,
            for_plan,
            name,
            body,
            *inclusive,
            "flux__async_range_end",
            false,
            &outer_env,
            &outer_mutable,
            temp_counter,
            loop_context,
        )?);
        out.push_str("        }\n");
    }

    let (body_env, body_mutable) = initial_body_state.ok_or_else(|| {
        diag(
            function.body[for_plan.statement_index].span,
            "async range continuation failed to initialize loop state",
        )
    })?;

    emit_async_for_range_resume_states(
        out,
        function,
        signatures,
        plan,
        for_plan,
        name,
        body,
        *inclusive,
        &outer_env,
        &outer_mutable,
        body_env,
        body_mutable,
        temp_counter,
        loop_context,
    )?;

    out.push_str(&format!("        case {continue_state}: {{\n"));
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    let mut continue_env = outer_env.clone();
    continue_env.insert(name.clone(), Type::I64);
    emit_async_restore_locals(
        out,
        pad,
        &plan.locals,
        &continue_env,
        signatures,
        function.span,
    )?;
    let _ = emit_async_for_range_iteration(
        out,
        function,
        signatures,
        plan,
        for_plan,
        name,
        body,
        *inclusive,
        "flux__task->saved_flux__async_range_end",
        true,
        &outer_env,
        &outer_mutable,
        temp_counter,
        loop_context,
    )?;
    out.push_str("        }\n");

    out.push_str(&format!("        case {break_state}: {{\n"));
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_async_restore_locals(
        out,
        pad,
        &plan.locals,
        &outer_env,
        signatures,
        function.span,
    )?;
    emit_async_for_range_tail(
        out,
        function,
        signatures,
        for_plan,
        &outer_env,
        &outer_mutable,
        temp_counter,
        state_context,
    )?;
    out.push_str("        }\n");
    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_match_tail(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    match_plan: &AsyncMatchAwaitPlan,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    let mut tail_env = outer_env.clone();
    let mut tail_mutable = outer_mutable.clone();
    emit_block(
        out,
        &function.body[match_plan.statement_index + 1..],
        3,
        &mut tail_env,
        &mut tail_mutable,
        signatures,
        temp_counter,
        context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    Ok(())
}

fn emit_async_match_arm_bindings(
    out: &mut String,
    pad: &str,
    temp: &str,
    arm: &crate::ast::MatchArm,
    signatures: &Signatures,
    env: &mut HashMap<String, Type>,
    checked_i64_cfg_proofs: &HashMap<(u32, usize, usize, usize), CfgCheckedI64Proof>,
    cfg_rewrite_facts: &CfgRewriteFacts,
) -> Result<Vec<String>, Diagnostic> {
    let definition = signatures.enum_type(&arm.enum_name).ok_or_else(|| {
        diag(
            arm.enum_span,
            "async match continuation enum disappeared after type checking",
        )
    })?;
    let variant = definition.variant(&arm.variant).ok_or_else(|| {
        diag(
            arm.variant_span,
            "async match continuation variant disappeared after type checking",
        )
    })?;
    let mut conditions = Vec::new();
    for (index, (pattern, payload_ty)) in arm.patterns.iter().zip(&variant.payloads).enumerate() {
        let payload_access = format!(
            "{temp}.payload.{}.v{index}",
            enum_payload_member_name(&arm.variant)
        );
        match pattern {
            MatchPattern::Binding(binding) => {
                if binding.name == "_" {
                    continue;
                }
                out.push_str(&format!(
                    "{pad}{} {} = {payload_access};\n",
                    c_type(payload_ty, signatures),
                    local_c_name(&binding.name)
                ));
                env.insert(binding.name.clone(), payload_ty.clone());
            }
            MatchPattern::Struct(pattern) => {
                let Type::Named(struct_name) = signatures.canonical_type(payload_ty) else {
                    return Err(diag(
                        pattern.struct_span,
                        "async match struct pattern requires a struct payload",
                    ));
                };
                emit_struct_pattern_bindings(
                    out,
                    pad,
                    &pattern.fields,
                    &struct_name,
                    &payload_access,
                    &mut PatternBindingEmitContext {
                        env,
                        signatures,
                        dead_definitions: None,
                    },
                )?;
            }
            MatchPattern::Relational(_) | MatchPattern::Logical { .. } => {
                if let Some(condition) = emit_match_pattern_condition(
                    pattern,
                    &payload_access,
                    payload_ty,
                    env,
                    signatures,
                )? {
                    conditions.push(condition);
                }
            }
        }
    }
    if let Some(guard) = &arm.guard {
        let guard = emit_expr_for_expected_with_cfg_proofs(
            guard,
            &Type::Bool,
            env,
            signatures,
            checked_i64_cfg_proofs,
            cfg_rewrite_facts,
        )?;
        conditions.push(c_condition(&guard));
    }
    Ok(conditions)
}

fn emit_async_match_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    match_plan: &AsyncMatchAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let StmtKind::Match { value, arms } = &function.body[match_plan.statement_index].kind else {
        return Err(diag(
            function.body[match_plan.statement_index].span,
            "async match continuation plan no longer points at a match statement",
        ));
    };
    let task_name = async_task_c_name(&function.name);
    let mut state_context = context;
    state_context.async_state_machine = true;
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut outer_env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut outer_mutable = plan.mutable.clone();
    out.push_str("        case 0: {\n");
    let pad = "            ";
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..match_plan.statement_index],
        3,
        &mut outer_env,
        &mut outer_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    let emitted_value = if match_plan.scrutinee_await {
        emit_source_line(out, value.span, context.source_paths);
        emit_async_suspend_expr(
            out, pad, value, value.span, 1, function, plan, &outer_env, signatures,
        )?;
        out.push_str("        }\n");
        out.push_str("        case 1: {\n");
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        emit_async_restore_locals(out, pad, &plan.locals, &outer_env, signatures, value.span)?;
        let (code, ty) =
            emit_async_completed_single_await(out, pad, value, function, signatures, temp_counter)?;
        EmittedExpr { code, ty }
    } else {
        let value_ty = type_of_expr(value, &outer_env, signatures)?;
        EmittedExpr {
            code: emit_expr_for_expected_with_cfg_proofs(
                value,
                &value_ty,
                &outer_env,
                signatures,
                context.checked_i64_cfg_proofs,
                context.cfg_rewrite_facts,
            )?,
            ty: value_ty,
        }
    };
    let Type::Named(enum_name) = &emitted_value.ty else {
        return Err(diag(
            value.span,
            "async match continuation requires an enum value",
        ));
    };
    let definition = signatures.enum_type(enum_name).ok_or_else(|| {
        diag(
            value.span,
            "async match continuation enum disappeared after type checking",
        )
    })?;
    let temp = format!("flux__async_match_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct {} {temp} = {};\n",
        struct_c_name(enum_name),
        emitted_value.code
    ));
    out.push_str(&format!("{pad}switch ({temp}.tag) {{\n"));

    let mut next_state = if match_plan.scrutinee_await { 2 } else { 1 };
    let mut resume_envs = Vec::with_capacity(arms.len());
    for variant in &definition.variants {
        let variant_arms = arms
            .iter()
            .enumerate()
            .filter(|(_, arm)| arm.variant == variant.name)
            .collect::<Vec<_>>();
        if variant_arms.is_empty() {
            continue;
        }
        out.push_str(&format!(
            "{pad}    case {}: {{\n",
            enum_tag_value_name(enum_name, &variant.name)
        ));
        for (arm_index, arm) in variant_arms {
            let await_indices = &match_plan.arm_await_indices[arm_index];
            out.push_str(&format!("{pad}        {{\n"));
            let mut arm_env = outer_env.clone();
            let mut arm_mutable = outer_mutable.clone();
            let conditions = emit_async_match_arm_bindings(
                out,
                &format!("{pad}            "),
                &temp,
                arm,
                signatures,
                &mut arm_env,
                state_context.checked_i64_cfg_proofs,
                state_context.cfg_rewrite_facts,
            )?;
            let guarded = !conditions.is_empty();
            if guarded {
                out.push_str(&format!(
                    "{pad}            if ({}) {{\n",
                    conditions.join(" && ")
                ));
            }
            let body_depth = if guarded { 6 } else { 5 };
            if let Some(first_await) = await_indices.first().copied() {
                emit_block(
                    out,
                    &arm.body[..first_await],
                    body_depth,
                    &mut arm_env,
                    &mut arm_mutable,
                    signatures,
                    temp_counter,
                    state_context,
                )?;
                let awaited_stmt = &arm.body[first_await];
                emit_source_line(out, awaited_stmt.span, context.source_paths);
                let suspend_pad = "    ".repeat(body_depth);
                let conditional_suspend = emit_async_branch_suspend(
                    out,
                    &suspend_pad,
                    awaited_stmt,
                    next_state,
                    function,
                    plan,
                    &arm_env,
                    &arm_mutable,
                    signatures,
                )?;
                if conditional_suspend {
                    let mut present_env = arm_env.clone();
                    let mut present_mutable = arm_mutable.clone();
                    let reaches_tail = emit_async_conditional_present_sequence(
                        out,
                        &suspend_pad,
                        function,
                        signatures,
                        plan,
                        &arm.body,
                        await_indices,
                        0,
                        next_state,
                        &mut present_env,
                        &mut present_mutable,
                        temp_counter,
                        state_context,
                    )?;
                    if reaches_tail {
                        emit_async_match_tail(
                            out,
                            function,
                            signatures,
                            match_plan,
                            &outer_env,
                            &outer_mutable,
                            temp_counter,
                            state_context,
                        )?;
                    }
                }
                resume_envs.push((arm_index, next_state, arm_env, arm_mutable));
                next_state += await_indices.len();
            } else {
                emit_block(
                    out,
                    &arm.body,
                    body_depth,
                    &mut arm_env,
                    &mut arm_mutable,
                    signatures,
                    temp_counter,
                    state_context,
                )?;
                emit_async_match_tail(
                    out,
                    function,
                    signatures,
                    match_plan,
                    &outer_env,
                    &outer_mutable,
                    temp_counter,
                    state_context,
                )?;
            }
            if guarded {
                out.push_str(&format!("{pad}            }}\n"));
            }
            out.push_str(&format!("{pad}        }}\n"));
        }
        out.push_str(&format!(
            "{pad}        fputs(\"Flux runtime error: async match arm dispatch failed\\n\", stderr); abort();\n"
        ));
        out.push_str(&format!("{pad}    }}\n"));
    }
    out.push_str(&format!(
        "{pad}    default: fputs(\"Flux runtime error: invalid async match tag\\n\", stderr); abort();\n"
    ));
    out.push_str(&format!("{pad}}}\n"));
    out.push_str("        }\n");

    for (arm_index, first_state, mut arm_env, mut arm_mutable) in resume_envs {
        let arm = &arms[arm_index];
        let await_indices = &match_plan.arm_await_indices[arm_index];
        let mut previous_await = await_indices[0];
        let mut segment_start = previous_await + 1;
        for offset in 0..await_indices.len() {
            let state = first_state + offset;
            out.push_str(&format!("        case {state}: {{\n"));
            for (index, param) in function.params.iter().enumerate() {
                out.push_str(&format!(
                    "{pad}{} {} = flux__task->arg_{index};\n",
                    c_type(&param.ty, signatures),
                    local_c_name(&param.name)
                ));
            }
            for (name, ty) in &plan.locals {
                if arm_env.contains_key(name) {
                    out.push_str(&format!(
                        "{pad}{} {} = flux__task->{};\n",
                        c_type(ty, signatures),
                        local_c_name(name),
                        async_saved_local_field_name(name)
                    ));
                }
            }
            let awaited_stmt = &arm.body[previous_await];
            emit_async_completed_await(
                out,
                pad,
                awaited_stmt,
                function,
                &mut arm_env,
                &mut arm_mutable,
                signatures,
                temp_counter,
            )?;
            let next_await = await_indices.get(offset + 1).copied();
            let segment_end = next_await.unwrap_or(arm.body.len());
            emit_block(
                out,
                &arm.body[segment_start..segment_end],
                3,
                &mut arm_env,
                &mut arm_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            if let Some(next_await_index) = next_await {
                let next_stmt = &arm.body[next_await_index];
                emit_source_line(out, next_stmt.span, context.source_paths);
                let conditional_suspend = emit_async_branch_suspend(
                    out,
                    pad,
                    next_stmt,
                    state + 1,
                    function,
                    plan,
                    &arm_env,
                    &arm_mutable,
                    signatures,
                )?;
                if conditional_suspend {
                    let mut present_env = arm_env.clone();
                    let mut present_mutable = arm_mutable.clone();
                    let reaches_tail = emit_async_conditional_present_sequence(
                        out,
                        pad,
                        function,
                        signatures,
                        plan,
                        &arm.body,
                        await_indices,
                        offset + 1,
                        first_state,
                        &mut present_env,
                        &mut present_mutable,
                        temp_counter,
                        state_context,
                    )?;
                    if reaches_tail {
                        emit_async_match_tail(
                            out,
                            function,
                            signatures,
                            match_plan,
                            &outer_env,
                            &outer_mutable,
                            temp_counter,
                            state_context,
                        )?;
                    }
                }
                previous_await = next_await_index;
                segment_start = next_await_index + 1;
            } else {
                emit_async_match_tail(
                    out,
                    function,
                    signatures,
                    match_plan,
                    &outer_env,
                    &outer_mutable,
                    temp_counter,
                    state_context,
                )?;
            }
            out.push_str("        }\n");
        }
    }

    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_list_match_tail(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    match_plan: &AsyncListMatchAwaitPlan,
    outer_env: &HashMap<String, Type>,
    outer_mutable: &HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    let mut tail_env = outer_env.clone();
    let mut tail_mutable = outer_mutable.clone();
    emit_block(
        out,
        &function.body[match_plan.statement_index + 1..],
        3,
        &mut tail_env,
        &mut tail_mutable,
        signatures,
        temp_counter,
        context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    Ok(())
}

fn emit_async_list_match_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    match_plan: &AsyncListMatchAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let StmtKind::ListMatch { value, arms } = &function.body[match_plan.statement_index].kind
    else {
        return Err(diag(
            function.body[match_plan.statement_index].span,
            "async list-match continuation plan no longer points at a list match statement",
        ));
    };
    let task_name = async_task_c_name(&function.name);
    let mut state_context = context;
    state_context.async_state_machine = true;
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut outer_env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut outer_mutable = plan.mutable.clone();
    out.push_str("        case 0: {\n");
    let pad = "            ";
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..match_plan.statement_index],
        3,
        &mut outer_env,
        &mut outer_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    let value_ty = type_of_expr(value, &outer_env, signatures)?;
    let emitted_value = EmittedExpr {
        code: emit_expr_for_expected_with_cfg_proofs(
            value,
            &value_ty,
            &outer_env,
            signatures,
            context.checked_i64_cfg_proofs,
            context.cfg_rewrite_facts,
        )?,
        ty: value_ty,
    };
    let Type::List(element) = &emitted_value.ty else {
        return Err(diag(
            value.span,
            "async list-match continuation requires a list value",
        ));
    };
    let temp = format!("flux__async_list_match_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct flux__list {temp} = {};\n",
        emitted_value.code
    ));

    let mut next_state = 1usize;
    let mut resume_envs = Vec::with_capacity(arms.len());
    for (arm_index, arm) in arms.iter().enumerate() {
        let await_indices = &match_plan.arm_await_indices[arm_index];
        let condition = list_match_condition(&arm.pattern, &temp);
        out.push_str(&format!("{pad}if ({condition}) {{\n"));
        let mut arm_env = outer_env.clone();
        let mut arm_mutable = outer_mutable.clone();
        emit_list_match_pattern_bindings(
            out,
            &format!("{pad}    "),
            &arm.pattern,
            &temp,
            element,
            &mut PatternBindingEmitContext {
                env: &mut arm_env,
                signatures,
                dead_definitions: None,
            },
        )?;
        let guarded = if let Some(guard) = &arm.guard {
            let guard = emit_expr_for_expected_with_cfg_proofs(
                guard,
                &Type::Bool,
                &arm_env,
                signatures,
                context.checked_i64_cfg_proofs,
                context.cfg_rewrite_facts,
            )?;
            out.push_str(&format!("{pad}    if ({}) {{\n", c_condition(&guard)));
            true
        } else {
            false
        };
        let body_depth = if guarded { 5 } else { 4 };
        if let Some(first_await) = await_indices.first().copied() {
            emit_block(
                out,
                &arm.body[..first_await],
                body_depth,
                &mut arm_env,
                &mut arm_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            let awaited_stmt = &arm.body[first_await];
            emit_source_line(out, awaited_stmt.span, context.source_paths);
            let suspend_pad = "    ".repeat(body_depth);
            let conditional_suspend = emit_async_branch_suspend(
                out,
                &suspend_pad,
                awaited_stmt,
                next_state,
                function,
                plan,
                &arm_env,
                &arm_mutable,
                signatures,
            )?;
            if conditional_suspend {
                let mut present_env = arm_env.clone();
                let mut present_mutable = arm_mutable.clone();
                let reaches_tail = emit_async_conditional_present_sequence(
                    out,
                    &suspend_pad,
                    function,
                    signatures,
                    plan,
                    &arm.body,
                    await_indices,
                    0,
                    next_state,
                    &mut present_env,
                    &mut present_mutable,
                    temp_counter,
                    state_context,
                )?;
                if reaches_tail {
                    emit_async_list_match_tail(
                        out,
                        function,
                        signatures,
                        match_plan,
                        &outer_env,
                        &outer_mutable,
                        temp_counter,
                        state_context,
                    )?;
                }
            }
            resume_envs.push((arm_index, next_state, arm_env, arm_mutable));
            next_state += await_indices.len();
        } else {
            emit_block(
                out,
                &arm.body,
                body_depth,
                &mut arm_env,
                &mut arm_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            emit_async_list_match_tail(
                out,
                function,
                signatures,
                match_plan,
                &outer_env,
                &outer_mutable,
                temp_counter,
                state_context,
            )?;
        }
        if guarded {
            out.push_str(&format!("{pad}    }}\n"));
        }
        out.push_str(&format!("{pad}}}\n"));
    }
    out.push_str(&format!(
        "{pad}fputs(\"Flux runtime error: async list match arm dispatch failed\\n\", stderr); abort();\n"
    ));
    out.push_str("        }\n");

    for (arm_index, first_state, mut arm_env, mut arm_mutable) in resume_envs {
        let arm = &arms[arm_index];
        let await_indices = &match_plan.arm_await_indices[arm_index];
        let mut previous_await = await_indices[0];
        let mut segment_start = previous_await + 1;
        for offset in 0..await_indices.len() {
            let state = first_state + offset;
            out.push_str(&format!("        case {state}: {{\n"));
            for (index, param) in function.params.iter().enumerate() {
                out.push_str(&format!(
                    "{pad}{} {} = flux__task->arg_{index};\n",
                    c_type(&param.ty, signatures),
                    local_c_name(&param.name)
                ));
            }
            for (name, ty) in &plan.locals {
                if arm_env.contains_key(name) {
                    out.push_str(&format!(
                        "{pad}{} {} = flux__task->{};\n",
                        c_type(ty, signatures),
                        local_c_name(name),
                        async_saved_local_field_name(name)
                    ));
                }
            }
            let awaited_stmt = &arm.body[previous_await];
            emit_async_completed_await(
                out,
                pad,
                awaited_stmt,
                function,
                &mut arm_env,
                &mut arm_mutable,
                signatures,
                temp_counter,
            )?;
            let next_await = await_indices.get(offset + 1).copied();
            let segment_end = next_await.unwrap_or(arm.body.len());
            emit_block(
                out,
                &arm.body[segment_start..segment_end],
                3,
                &mut arm_env,
                &mut arm_mutable,
                signatures,
                temp_counter,
                state_context,
            )?;
            if let Some(next_await_index) = next_await {
                let next_stmt = &arm.body[next_await_index];
                emit_source_line(out, next_stmt.span, context.source_paths);
                let conditional_suspend = emit_async_branch_suspend(
                    out,
                    pad,
                    next_stmt,
                    state + 1,
                    function,
                    plan,
                    &arm_env,
                    &arm_mutable,
                    signatures,
                )?;
                if conditional_suspend {
                    let mut present_env = arm_env.clone();
                    let mut present_mutable = arm_mutable.clone();
                    let reaches_tail = emit_async_conditional_present_sequence(
                        out,
                        pad,
                        function,
                        signatures,
                        plan,
                        &arm.body,
                        await_indices,
                        offset + 1,
                        first_state,
                        &mut present_env,
                        &mut present_mutable,
                        temp_counter,
                        state_context,
                    )?;
                    if reaches_tail {
                        emit_async_list_match_tail(
                            out,
                            function,
                            signatures,
                            match_plan,
                            &outer_env,
                            &outer_mutable,
                            temp_counter,
                            state_context,
                        )?;
                    }
                }
                previous_await = next_await_index;
                segment_start = next_await_index + 1;
            } else {
                emit_async_list_match_tail(
                    out,
                    function,
                    signatures,
                    match_plan,
                    &outer_env,
                    &outer_mutable,
                    temp_counter,
                    state_context,
                )?;
            }
            out.push_str("        }\n");
        }
    }

    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_coalescing_sequence(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    coalescing_plan: &AsyncCoalescingAwaitPlan,
    start_order: usize,
    mut segment_start: usize,
    env: &mut HashMap<String, Type>,
    mutable: &mut HashSet<String>,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let pad = "            ";
    for order in start_order..coalescing_plan.statement_indices.len() {
        let statement_index = coalescing_plan.statement_indices[order];
        emit_block(
            out,
            &function.body[segment_start..statement_index],
            3,
            env,
            mutable,
            signatures,
            temp_counter,
            context,
        )?;
        let stmt = &function.body[statement_index];
        if let StmtKind::Assign {
            name,
            coalescing: true,
            ..
        } = &stmt.kind
        {
            let Some(target_ty) = env.get(name).map(|ty| signatures.canonical_type(ty)) else {
                return Err(diag(
                    stmt.span,
                    "async coalescing continuation target disappeared after type checking",
                ));
            };
            if !matches!(target_ty, Type::Optional(_)) || !mutable.contains(name) {
                return Err(diag(
                    stmt.span,
                    "async coalescing continuation target contract changed after type checking",
                ));
            }
            out.push_str(&format!("{pad}if (!{}.has_value) {{\n", local_c_name(name)));
            emit_source_line(out, stmt.span, context.source_paths);
            emit_async_suspend(
                out,
                "                ",
                stmt,
                order + 1,
                function,
                plan,
                env,
                signatures,
            )?;
            out.push_str(&format!("{pad}}}\n"));
            segment_start = statement_index + 1;
            continue;
        }

        emit_source_line(out, stmt.span, context.source_paths);
        emit_async_suspend(out, pad, stmt, order + 1, function, plan, env, signatures)?;
        return Ok(());
    }

    emit_block(
        out,
        &function.body[segment_start..],
        3,
        env,
        mutable,
        signatures,
        temp_counter,
        context,
    )?;
    if function.returns.is_empty() {
        out.push_str(&format!(
            "{pad}{}(flux__task);\n{pad}return;\n",
            async_finish_c_name(&function.name)
        ));
    } else {
        out.push_str(&format!(
            "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
        ));
    }
    Ok(())
}

fn emit_async_coalescing_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    coalescing_plan: &AsyncCoalescingAwaitPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let Some(&first_statement_index) = coalescing_plan.statement_indices.first() else {
        return Err(diag(
            function.span,
            "async coalescing continuation plan has no suspension points",
        ));
    };
    let task_name = async_task_c_name(&function.name);
    let mut state_context = context;
    state_context.async_state_machine = true;
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut prefix_env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut prefix_mutable = plan.mutable.clone();
    let pad = "            ";
    out.push_str("        case 0: {\n");
    for (index, param) in function.params.iter().enumerate() {
        out.push_str(&format!(
            "{pad}{} {} = flux__task->arg_{index};\n",
            c_type(&param.ty, signatures),
            local_c_name(&param.name)
        ));
    }
    emit_block(
        out,
        &function.body[..first_statement_index],
        3,
        &mut prefix_env,
        &mut prefix_mutable,
        signatures,
        temp_counter,
        state_context,
    )?;
    emit_async_coalescing_sequence(
        out,
        function,
        signatures,
        plan,
        coalescing_plan,
        0,
        first_statement_index,
        &mut prefix_env,
        &mut prefix_mutable,
        temp_counter,
        state_context,
    )?;
    out.push_str("        }\n");

    for (order, &statement_index) in coalescing_plan.statement_indices.iter().enumerate() {
        let state = order + 1;
        out.push_str(&format!("        case {state}: {{\n"));
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        let mut state_env = function
            .params
            .iter()
            .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
            .collect::<HashMap<_, _>>();
        let mut state_mutable = HashSet::new();
        if statement_index > 0 {
            let mut prior_locals = BTreeMap::new();
            collect_async_saved_locals(
                &function.body[..statement_index],
                statement_index - 1,
                &state_env,
                signatures,
                &mut prior_locals,
                &mut state_mutable,
            )
            .ok_or_else(|| {
                diag(
                    function.body[statement_index].span,
                    "async coalescing continuation locals changed after planning",
                )
            })?;
            state_env.extend(prior_locals);
        }
        for (local_name, ty) in &plan.locals {
            if state_env.contains_key(local_name) {
                out.push_str(&format!(
                    "{pad}{} {} = flux__task->{};\n",
                    c_type(ty, signatures),
                    local_c_name(local_name),
                    async_saved_local_field_name(local_name)
                ));
            }
        }
        let stmt = &function.body[statement_index];
        emit_async_completed_await(
            out,
            pad,
            stmt,
            function,
            &mut state_env,
            &mut state_mutable,
            signatures,
            temp_counter,
        )?;
        emit_async_coalescing_sequence(
            out,
            function,
            signatures,
            plan,
            coalescing_plan,
            order + 1,
            statement_index + 1,
            &mut state_env,
            &mut state_mutable,
            temp_counter,
            state_context,
        )?;
        out.push_str("        }\n");
    }
    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n}\n");
    Ok(())
}

fn emit_async_continuation_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    plan: &AsyncContinuationPlan,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    if let Some(branch) = &plan.branch_await {
        return emit_async_branch_continuation_function(
            out,
            function,
            signatures,
            plan,
            branch,
            temp_counter,
            context,
        );
    }
    if let Some(branch) = &plan.nested_branch_await {
        return emit_async_nested_branch_continuation_function(
            out,
            function,
            signatures,
            plan,
            branch,
            temp_counter,
            context,
        );
    }
    if let Some(while_plan) = &plan.while_await {
        return emit_async_while_continuation_function(
            out,
            function,
            signatures,
            plan,
            while_plan,
            temp_counter,
            context,
        );
    }
    if let Some(for_plan) = &plan.for_range_await {
        return emit_async_for_range_continuation_function(
            out,
            function,
            signatures,
            plan,
            for_plan,
            temp_counter,
            context,
        );
    }
    if let Some(match_plan) = &plan.match_await {
        return emit_async_match_continuation_function(
            out,
            function,
            signatures,
            plan,
            match_plan,
            temp_counter,
            context,
        );
    }
    if let Some(match_plan) = &plan.list_match_await {
        return emit_async_list_match_continuation_function(
            out,
            function,
            signatures,
            plan,
            match_plan,
            temp_counter,
            context,
        );
    }
    if let Some(coalescing_plan) = &plan.coalescing_await {
        return emit_async_coalescing_continuation_function(
            out,
            function,
            signatures,
            plan,
            coalescing_plan,
            temp_counter,
            context,
        );
    }
    let await_indices = function
        .body
        .iter()
        .enumerate()
        .filter_map(|(index, stmt)| stmt_contains_await(stmt).then_some(index))
        .collect::<Vec<_>>();
    let task_name = async_task_c_name(&function.name);
    out.push_str(&async_resume_prototype(function));
    out.push_str(" {\n");
    out.push_str(&format!(
        "    struct {task_name} *flux__task = (struct {task_name} *)flux__context;\n"
    ));
    out.push_str("    if (flux__task == NULL) { fputs(\"Flux runtime error: invalid async continuation context\\n\", stderr); abort(); }\n");
    out.push_str("    flux__async_scope_enter(flux__task->worker_scope_id);\n");
    out.push_str("    switch (flux__task->state) {\n");

    let mut env = function
        .params
        .iter()
        .map(|param| (param.name.clone(), signatures.canonical_type(&param.ty)))
        .collect::<HashMap<_, _>>();
    let mut mutable = plan.mutable.clone();
    let mut segment_start = 0usize;
    let mut previous_await: Option<&Stmt> = None;
    let mut state_context = context;
    state_context.async_state_machine = true;

    for state in 0..=await_indices.len() {
        out.push_str(&format!("        case {state}: {{\n"));
        let pad = "            ";
        for (index, param) in function.params.iter().enumerate() {
            out.push_str(&format!(
                "{pad}{} {} = flux__task->arg_{index};\n",
                c_type(&param.ty, signatures),
                local_c_name(&param.name)
            ));
        }
        if state > 0 {
            for (name, ty) in &plan.resume_locals {
                if env.contains_key(name) {
                    out.push_str(&format!(
                        "{pad}{} {};\n",
                        c_type(ty, signatures),
                        local_c_name(name)
                    ));
                }
            }
        }
        for (name, ty) in &plan.locals {
            if env.contains_key(name) {
                out.push_str(&format!(
                    "{pad}{} {} = flux__task->{};\n",
                    c_type(ty, signatures),
                    local_c_name(name),
                    async_saved_local_field_name(name)
                ));
            }
        }
        if let Some(awaited_stmt) = previous_await {
            emit_async_completed_await(
                out,
                pad,
                awaited_stmt,
                function,
                &mut env,
                &mut mutable,
                signatures,
                temp_counter,
            )?;
        }

        let next_await = await_indices.get(state).copied();
        let segment_end = next_await.unwrap_or(function.body.len());
        emit_block(
            out,
            &function.body[segment_start..segment_end],
            3,
            &mut env,
            &mut mutable,
            signatures,
            temp_counter,
            state_context,
        )?;

        if let Some(await_index) = next_await {
            let awaited_stmt = &function.body[await_index];
            emit_source_line(out, awaited_stmt.span, context.source_paths);
            emit_async_suspend(
                out,
                pad,
                awaited_stmt,
                state + 1,
                function,
                plan,
                &env,
                signatures,
            )?;
            previous_await = Some(awaited_stmt);
            segment_start = await_index + 1;
        } else if function.returns.is_empty() {
            out.push_str(&format!(
                "{pad}{}(flux__task);\n{pad}return;\n",
                async_finish_c_name(&function.name)
            ));
        } else {
            out.push_str(&format!(
                "{pad}fputs(\"Flux runtime error: async continuation reached end without return\\n\", stderr);\n{pad}abort();\n"
            ));
        }
        out.push_str("        }\n");
    }
    out.push_str("        default: fputs(\"Flux runtime error: invalid async continuation state\\n\", stderr); abort();\n");
    out.push_str("    }\n}\n");
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CfgCheckedI64Proof {
    Native,
    NonzeroDivision,
}

fn cfg_i64_constant(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<i64> {
    match cfg.value(id)?.constant.as_ref() {
        Some(ConstantValue::I64(value)) => Some(*value),
        _ => None,
    }
}

fn cfg_same_i64_value(
    cfg: &crate::ir::ControlFlowGraph,
    left: crate::ir::ControlFlowValueId,
    right: crate::ir::ControlFlowValueId,
) -> bool {
    if cfg_i64_constant(cfg, left)
        .zip(cfg_i64_constant(cfg, right))
        .is_some_and(|(left, right)| left == right)
    {
        return true;
    }
    match (
        &cfg.value(left).map(|value| &value.kind),
        &cfg.value(right).map(|value| &value.kind),
    ) {
        (
            Some(crate::ir::ControlFlowValueKind::NameRead {
                definitions: left_definitions,
                ..
            }),
            Some(crate::ir::ControlFlowValueKind::NameRead {
                definitions: right_definitions,
                ..
            }),
        ) => {
            !left_definitions.is_empty()
                && left_definitions.len() == 1
                && left_definitions == right_definitions
        }
        _ => false,
    }
}

fn cfg_definition_value_for_read(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<crate::ir::ControlFlowValueId> {
    let crate::ir::ControlFlowValueKind::NameRead { definitions, .. } = &cfg.value(id)?.kind else {
        return None;
    };
    let [definition] = definitions.as_slice() else {
        return None;
    };
    cfg.definition_value(*definition)
}

fn cfg_additive_shift(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<i64> {
    let crate::ir::ControlFlowValueKind::Binary { op, left, right } = &cfg.value(id)?.kind else {
        return None;
    };
    match op {
        BinOp::Add => match (cfg_i64_constant(cfg, *left), cfg_i64_constant(cfg, *right)) {
            (Some(shift), None) | (None, Some(shift)) => Some(shift),
            _ => None,
        },
        BinOp::Sub => cfg_i64_constant(cfg, *right).and_then(i64::checked_neg),
        _ => None,
    }
}

fn cfg_additive_shifts_compose_safely(inner_shift: i64, outer_shift: i64) -> bool {
    ((inner_shift > 0 && outer_shift < 0) || (inner_shift < 0 && outer_shift > 0))
        && outer_shift.unsigned_abs() <= inner_shift.unsigned_abs()
}

fn cfg_checked_i64_proof_for_value(
    cfg: &crate::ir::ControlFlowGraph,
    value: &crate::ir::ControlFlowValue,
) -> Option<CfgCheckedI64Proof> {
    if value.ty != Type::I64 || !cfg.is_value_reachable(value.id) {
        return None;
    }
    let crate::ir::ControlFlowValueKind::Binary { op, left, right } = value.kind else {
        return None;
    };
    let left_definition_value = cfg_definition_value_for_read(cfg, left);
    let right_definition_value = cfg_definition_value_for_read(cfg, right);

    match op {
        BinOp::Sub => {
            if let Some(inner_id) = left_definition_value {
                if let Some(inner) = cfg.value(inner_id) {
                    if let crate::ir::ControlFlowValueKind::Binary {
                        op: BinOp::Add,
                        left: inner_left,
                        right: inner_right,
                    } = inner.kind
                        && (cfg_same_i64_value(cfg, inner_left, right)
                            || cfg_same_i64_value(cfg, inner_right, right))
                    {
                        return Some(CfgCheckedI64Proof::Native);
                    }
                    if let Some(outer) = cfg_i64_constant(cfg, right)
                        && let Some(outer_shift) = outer.checked_neg()
                        && cfg_additive_shift(cfg, inner_id).is_some_and(|inner_shift| {
                            cfg_additive_shifts_compose_safely(inner_shift, outer_shift)
                        })
                    {
                        return Some(CfgCheckedI64Proof::Native);
                    }
                }
            }
            if let Some(inner_id) = right_definition_value
                && let Some(crate::ir::ControlFlowValue {
                    kind:
                        crate::ir::ControlFlowValueKind::Binary {
                            op: BinOp::Sub,
                            left: inner_left,
                            ..
                        },
                    ..
                }) = cfg.value(inner_id)
                && cfg_same_i64_value(cfg, left, *inner_left)
            {
                return Some(CfgCheckedI64Proof::Native);
            }
            None
        }
        BinOp::Add => {
            for (inner_read, other) in [(left, right), (right, left)] {
                let Some(inner_id) = cfg_definition_value_for_read(cfg, inner_read) else {
                    continue;
                };
                if let Some(crate::ir::ControlFlowValue {
                    kind:
                        crate::ir::ControlFlowValueKind::Binary {
                            op: BinOp::Sub,
                            right: inner_right,
                            ..
                        },
                    ..
                }) = cfg.value(inner_id)
                    && cfg_same_i64_value(cfg, *inner_right, other)
                {
                    return Some(CfgCheckedI64Proof::Native);
                }
                if let Some(outer_shift) = cfg_i64_constant(cfg, other)
                    && cfg_additive_shift(cfg, inner_id).is_some_and(|inner_shift| {
                        cfg_additive_shifts_compose_safely(inner_shift, outer_shift)
                    })
                {
                    return Some(CfgCheckedI64Proof::Native);
                }
            }
            None
        }
        BinOp::Mul => {
            for (inner_read, factor) in [(left, right), (right, left)] {
                let Some(inner_id) = cfg_definition_value_for_read(cfg, inner_read) else {
                    continue;
                };
                if let Some(crate::ir::ControlFlowValue {
                    kind:
                        crate::ir::ControlFlowValueKind::Binary {
                            op: BinOp::Div,
                            right: divisor,
                            ..
                        },
                    ..
                }) = cfg.value(inner_id)
                    && cfg_same_i64_value(cfg, *divisor, factor)
                {
                    return Some(CfgCheckedI64Proof::Native);
                }
            }
            None
        }
        BinOp::Div => {
            let inner_id = left_definition_value?;
            let crate::ir::ControlFlowValueKind::Binary {
                op: BinOp::Mul,
                left: inner_left,
                right: inner_right,
            } = cfg.value(inner_id)?.kind
            else {
                return None;
            };
            if !cfg_same_i64_value(cfg, inner_left, right)
                && !cfg_same_i64_value(cfg, inner_right, right)
            {
                return None;
            }
            match cfg_i64_constant(cfg, right) {
                Some(0) => None,
                Some(_) => Some(CfgCheckedI64Proof::Native),
                None => Some(CfgCheckedI64Proof::NonzeroDivision),
            }
        }
        _ => None,
    }
}

fn cfg_checked_i64_proofs(
    cfg: &crate::ir::ControlFlowGraph,
) -> HashMap<(u32, usize, usize, usize), CfgCheckedI64Proof> {
    cfg.values()
        .iter()
        .filter_map(|value| {
            cfg_checked_i64_proof_for_value(cfg, value)
                .map(|proof| (source_span_key(value.span), proof))
        })
        .collect()
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CfgListItemShape {
    Value((u32, usize, usize, usize)),
    Spread {
        span: (u32, usize, usize, usize),
        value: (u32, usize, usize, usize),
        optional: bool,
    },
    Optional {
        span: (u32, usize, usize, usize),
        value: (u32, usize, usize, usize),
    },
    Conditional {
        span: (u32, usize, usize, usize),
        condition: (u32, usize, usize, usize),
        binding: Option<String>,
        value: (u32, usize, usize, usize),
        else_value: Option<(u32, usize, usize, usize)>,
    },
}

impl CfgListItemShape {
    fn span(&self) -> (u32, usize, usize, usize) {
        match self {
            Self::Value(span)
            | Self::Spread { span, .. }
            | Self::Optional { span, .. }
            | Self::Conditional { span, .. } => *span,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CfgAggregateShape {
    List(Vec<CfgListItemShape>),
    ListComprehension {
        binding: String,
        iterable: (u32, usize, usize, usize),
        value: (u32, usize, usize, usize),
        condition: Option<(u32, usize, usize, usize)>,
    },
    Set(Vec<(u32, usize, usize, usize)>),
    Record(Vec<(Option<String>, (u32, usize, usize, usize))>),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CfgAggregateConstantKind {
    List(Vec<CfgAggregateValue>),
    Set(Vec<CfgAggregateValue>),
    Map(Vec<(ConstantValue, CfgAggregateValue)>),
    Record(Vec<(Option<String>, CfgAggregateValue)>),
    Struct {
        name: String,
        base: Option<CfgAggregateValue>,
        fields: Vec<(String, CfgAggregateValue)>,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CfgAggregateValue {
    Scalar(ConstantValue),
    Direct(CfgScalarExpr),
    EnumVariant {
        enum_name: String,
        variant: String,
        payloads: Vec<CfgAggregateValue>,
    },
    InterfacePack {
        interface: String,
        target: String,
        value: Box<CfgAggregateValue>,
    },
    AbsentOptional,
    Aggregate(Box<CfgAggregateConstant>),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CfgAggregateConstant {
    ty: Type,
    kind: CfgAggregateConstantKind,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CfgScalarExprKind {
    Name(String),
    Constant(ConstantValue),
    Nil,
    NoneLiteral,
    Aggregate(Box<CfgAggregateConstant>),
    Unary {
        op: UnaryOp,
        operand: Box<CfgScalarExpr>,
    },
    Binary {
        op: BinOp,
        left: Box<CfgScalarExpr>,
        right: Box<CfgScalarExpr>,
    },
    Conditional {
        condition: Box<CfgScalarExpr>,
        then_value: Box<CfgScalarExpr>,
        else_value: Box<CfgScalarExpr>,
    },
    Field {
        base: Box<CfgScalarExpr>,
        name: String,
        optional: bool,
    },
    Index {
        base: Box<CfgScalarExpr>,
        index: Box<CfgScalarExpr>,
        optional: bool,
    },
    Slice {
        base: Box<CfgScalarExpr>,
        start: Option<Box<CfgScalarExpr>>,
        end: Option<Box<CfgScalarExpr>>,
        step: Option<Box<CfgScalarExpr>>,
    },
    InterfacePack {
        interface: String,
        target: String,
        value: Box<CfgScalarExpr>,
    },
    Bind {
        span: SourceSpan,
        arguments: Vec<CfgScalarExpr>,
    },
    AnonymousFunction {
        span: SourceSpan,
        params: Vec<(String, Type)>,
        return_type: Option<Type>,
        body: Box<CfgScalarExpr>,
    },
    Call {
        callee: String,
        arguments: Vec<CfgScalarExpr>,
    },
    NamedCall {
        callee: String,
        arguments: Vec<(Option<String>, CfgScalarExpr)>,
    },
    Await {
        value: Box<CfgScalarExpr>,
    },
    QualifiedCall {
        namespace: String,
        name: String,
        arguments: Vec<CfgScalarExpr>,
    },
    NamedQualifiedCall {
        namespace: String,
        name: String,
        arguments: Vec<(Option<String>, CfgScalarExpr)>,
    },
    OptionalCascadeCall {
        optional: Box<CfgScalarExpr>,
        callee: String,
        arguments: Vec<CfgScalarExpr>,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CfgScalarExpr {
    ty: Type,
    kind: CfgScalarExprKind,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CfgMatchExprArm {
    pattern: crate::ir::ControlFlowMatchArmPattern,
    guard: Option<CfgScalarExpr>,
    value: CfgScalarExpr,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CfgMatchExpr {
    value: CfgScalarExpr,
    arms: Vec<CfgMatchExprArm>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CfgListMatchExprArm {
    pattern: crate::ir::ControlFlowListMatchPattern,
    guard: Option<CfgScalarExpr>,
    value: CfgScalarExpr,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CfgListMatchExpr {
    value: CfgScalarExpr,
    arms: Vec<CfgListMatchExprArm>,
}

#[derive(Debug, Clone, Default)]
struct CfgRewriteFacts {
    constants: HashMap<(u32, usize, usize, usize), ConstantValue>,
    aggregates: HashMap<(u32, usize, usize, usize), CfgAggregateShape>,
    aggregate_constants: HashMap<(u32, usize, usize, usize), CfgAggregateConstant>,
    scalar_exprs: HashMap<(u32, usize, usize, usize), CfgScalarExpr>,
    sequence_exprs: HashMap<(u32, usize, usize, usize), CfgScalarExpr>,
    multi_exprs: HashMap<(u32, usize, usize, usize), CfgScalarExpr>,
    match_exprs: HashMap<(u32, usize, usize, usize), CfgMatchExpr>,
    list_match_exprs: HashMap<(u32, usize, usize, usize), CfgListMatchExpr>,
}

fn cfg_literal_aggregate_value(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgAggregateValue> {
    if let Some(constant) = cfg.proven_scalar_constant(id) {
        return Some(CfgAggregateValue::Scalar(constant.clone()));
    }
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    if matches!(&value.kind, crate::ir::ControlFlowValueKind::Literal)
        && matches!(&value.ty, Type::Optional(inner) if **inner == Type::Void)
    {
        return Some(CfgAggregateValue::AbsentOptional);
    }
    if let crate::ir::ControlFlowValueKind::InterfacePack {
        interface,
        target,
        value: packed,
    } = &value.kind
        && value.ownership.is_copy()
        && matches!(&value.ty, Type::Named(returned) if returned == interface)
        && matches!(cfg.value(*packed).map(|value| &value.ty), Some(Type::Named(name)) if name == target)
    {
        return Some(CfgAggregateValue::InterfacePack {
            interface: interface.clone(),
            target: target.clone(),
            value: Box::new(cfg_literal_aggregate_value(cfg, *packed)?),
        });
    }
    if let crate::ir::ControlFlowValueKind::QualifiedCall {
        namespace,
        name,
        arguments,
    } = &value.kind
        && value.ownership.is_copy()
        && matches!(&value.ty, Type::Named(returned) if returned == namespace)
    {
        return Some(CfgAggregateValue::EnumVariant {
            enum_name: namespace.clone(),
            variant: name.clone(),
            payloads: arguments
                .iter()
                .map(|id| cfg_literal_aggregate_value(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        });
    }
    let kind = match &value.kind {
        crate::ir::ControlFlowValueKind::List { items } => CfgAggregateConstantKind::List(
            items
                .iter()
                .map(|id| cfg_literal_aggregate_value(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        ),
        crate::ir::ControlFlowValueKind::Set { items } => CfgAggregateConstantKind::Set(
            items
                .iter()
                .map(|id| cfg_literal_aggregate_value(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        ),
        crate::ir::ControlFlowValueKind::Map { entries } => CfgAggregateConstantKind::Map(
            entries
                .iter()
                .map(|(key, value)| {
                    Some((
                        cfg.proven_scalar_constant(*key)?.clone(),
                        cfg_literal_aggregate_value(cfg, *value)?,
                    ))
                })
                .collect::<Option<Vec<_>>>()?,
        ),
        crate::ir::ControlFlowValueKind::RecordLiteral { fields } if value.ownership.is_copy() => {
            CfgAggregateConstantKind::Record(
                fields
                    .iter()
                    .map(|(name, id)| Some((name.clone(), cfg_literal_aggregate_value(cfg, *id)?)))
                    .collect::<Option<Vec<_>>>()?,
            )
        }
        crate::ir::ControlFlowValueKind::StructLiteral { name, base, fields }
            if value.ownership.is_copy() =>
        {
            let base = match base {
                Some(id) => Some(cfg_literal_aggregate_value(cfg, *id)?),
                None => None,
            };
            CfgAggregateConstantKind::Struct {
                name: name.clone(),
                base,
                fields: fields
                    .iter()
                    .map(|(field, id)| {
                        Some((field.clone(), cfg_literal_aggregate_value(cfg, *id)?))
                    })
                    .collect::<Option<Vec<_>>>()?,
            }
        }
        _ if value.ownership.is_copy() => {
            let scalar = cfg_direct_scalar_expr(cfg, id)?;
            return cfg_scalar_expr_is_aggregate_reorder_safe(&scalar)
                .then_some(CfgAggregateValue::Direct(scalar));
        }
        _ => return None,
    };
    Some(CfgAggregateValue::Aggregate(Box::new(
        CfgAggregateConstant {
            ty: value.ty.clone(),
            kind,
        },
    )))
}

fn cfg_scalar_leaf(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    if matches!(value.kind, crate::ir::ControlFlowValueKind::Literal) {
        let kind = match &value.ty {
            Type::Error => Some(CfgScalarExprKind::Nil),
            Type::Optional(inner) if **inner == Type::Void => Some(CfgScalarExprKind::NoneLiteral),
            _ => None,
        };
        if let Some(kind) = kind {
            return Some(CfgScalarExpr {
                ty: value.ty.clone(),
                kind,
            });
        }
    }
    if !value.ownership.is_copy() {
        return None;
    }
    if let Some(constant) = cfg.proven_scalar_constant(id) {
        return Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind: CfgScalarExprKind::Constant(constant.clone()),
        });
    }
    let crate::ir::ControlFlowValueKind::NameRead { name, definitions } = &value.kind else {
        return None;
    };
    if definitions.is_empty() && !matches!(value.ty, Type::Function { .. }) {
        return None;
    }
    Some(CfgScalarExpr {
        ty: value.ty.clone(),
        kind: CfgScalarExprKind::Name(name.clone()),
    })
}

fn cfg_borrowed_index_base(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) || !value.ownership.is_borrow() {
        return None;
    }
    if matches!(&value.ty, Type::List(_)) {
        return cfg_borrowed_list_base(cfg, id);
    }
    let indexable = matches!(&value.ty, Type::Map(_, _))
        || matches!(&value.ty, Type::Optional(inner) if matches!(inner.as_ref(), Type::List(_) | Type::Map(_, _)));
    if !indexable {
        return None;
    }
    if matches!(&value.kind, crate::ir::ControlFlowValueKind::Map { .. }) {
        let CfgAggregateValue::Aggregate(aggregate) = cfg_literal_aggregate_value(cfg, id)? else {
            return None;
        };
        return Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind: CfgScalarExprKind::Aggregate(aggregate),
        });
    }
    let kind = match &value.kind {
        crate::ir::ControlFlowValueKind::NameRead { name, definitions }
            if !definitions.is_empty() =>
        {
            CfgScalarExprKind::Name(name.clone())
        }
        crate::ir::ControlFlowValueKind::Unary {
            op: UnaryOp::Borrow,
            operand,
        } => CfgScalarExprKind::Unary {
            op: UnaryOp::Borrow,
            operand: Box::new(cfg_borrowed_collection_value(cfg, *operand)?),
        },
        _ => return None,
    };
    Some(CfgScalarExpr {
        ty: value.ty.clone(),
        kind,
    })
}

fn cfg_borrowed_list_base(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id)
        || !value.ownership.is_borrow()
        || !matches!(&value.ty, Type::List(_))
    {
        return None;
    }
    let kind = match &value.kind {
        crate::ir::ControlFlowValueKind::NameRead { name, definitions }
            if !definitions.is_empty() =>
        {
            CfgScalarExprKind::Name(name.clone())
        }
        crate::ir::ControlFlowValueKind::Unary {
            op: UnaryOp::Borrow,
            operand,
        } => CfgScalarExprKind::Unary {
            op: UnaryOp::Borrow,
            operand: Box::new(cfg_borrowed_collection_value(cfg, *operand)?),
        },
        crate::ir::ControlFlowValueKind::List { .. } => {
            let CfgAggregateValue::Aggregate(aggregate) = cfg_literal_aggregate_value(cfg, id)?
            else {
                return None;
            };
            CfgScalarExprKind::Aggregate(aggregate)
        }
        crate::ir::ControlFlowValueKind::Index {
            base,
            index,
            optional,
        } => CfgScalarExprKind::Index {
            base: Box::new(cfg_borrowed_index_base(cfg, *base)?),
            index: Box::new(cfg_direct_scalar_expr(cfg, *index)?),
            optional: *optional,
        },
        crate::ir::ControlFlowValueKind::Field {
            base,
            name,
            optional,
        } => CfgScalarExprKind::Field {
            base: Box::new(cfg_borrowed_collection_field_base(cfg, *base)?),
            name: name.clone(),
            optional: *optional,
        },
        crate::ir::ControlFlowValueKind::Slice {
            base,
            start,
            end,
            step,
        } => {
            let direct_bound = |id: &Option<crate::ir::ControlFlowValueId>| match id {
                Some(id) => Some(Some(Box::new(cfg_direct_scalar_expr(cfg, *id)?))),
                None => Some(None),
            };
            CfgScalarExprKind::Slice {
                base: Box::new(cfg_borrowed_list_base(cfg, *base)?),
                start: direct_bound(start)?,
                end: direct_bound(end)?,
                step: direct_bound(step)?,
            }
        }
        crate::ir::ControlFlowValueKind::Call { callee, arguments }
            if matches!(crate::builtin_names::global_impl(callee), "take" | "skip") =>
        {
            CfgScalarExprKind::Call {
                callee: callee.clone(),
                arguments: arguments
                    .iter()
                    .map(|id| cfg_direct_scalar_expr(cfg, *id))
                    .collect::<Option<Vec<_>>>()?,
            }
        }
        _ => return None,
    };
    Some(CfgScalarExpr {
        ty: value.ty.clone(),
        kind,
    })
}

fn cfg_borrowed_collection_field_base(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) || !value.ownership.is_borrow() {
        return None;
    }
    if matches!(&value.ty, Type::List(_)) {
        return cfg_borrowed_list_base(cfg, id);
    }
    if !matches!(&value.ty, Type::Set(_) | Type::Map(_, _)) {
        return None;
    }
    if matches!(
        &value.kind,
        crate::ir::ControlFlowValueKind::Set { .. } | crate::ir::ControlFlowValueKind::Map { .. }
    ) {
        let CfgAggregateValue::Aggregate(aggregate) = cfg_literal_aggregate_value(cfg, id)? else {
            return None;
        };
        return Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind: CfgScalarExprKind::Aggregate(aggregate),
        });
    }
    let kind = match &value.kind {
        crate::ir::ControlFlowValueKind::NameRead { name, definitions }
            if !definitions.is_empty() =>
        {
            CfgScalarExprKind::Name(name.clone())
        }
        crate::ir::ControlFlowValueKind::Unary {
            op: UnaryOp::Borrow,
            operand,
        } => CfgScalarExprKind::Unary {
            op: UnaryOp::Borrow,
            operand: Box::new(cfg_borrowed_collection_value(cfg, *operand)?),
        },
        crate::ir::ControlFlowValueKind::Index {
            base,
            index,
            optional,
        } => CfgScalarExprKind::Index {
            base: Box::new(cfg_borrowed_index_base(cfg, *base)?),
            index: Box::new(cfg_direct_scalar_expr(cfg, *index)?),
            optional: *optional,
        },
        crate::ir::ControlFlowValueKind::Field {
            base,
            name,
            optional,
        } => CfgScalarExprKind::Field {
            base: Box::new(cfg_borrowed_collection_field_base(cfg, *base)?),
            name: name.clone(),
            optional: *optional,
        },
        _ => return None,
    };
    Some(CfgScalarExpr {
        ty: value.ty.clone(),
        kind,
    })
}

fn cfg_borrowed_collection_value(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) || !value.ownership.is_borrow() {
        return None;
    }
    match &value.ty {
        Type::List(_) | Type::Set(_) | Type::Map(_, _) => {
            cfg_borrowed_collection_field_base(cfg, id)
        }
        Type::Optional(inner)
            if matches!(
                inner.as_ref(),
                Type::List(_) | Type::Set(_) | Type::Map(_, _)
            ) =>
        {
            let kind = match &value.kind {
                crate::ir::ControlFlowValueKind::NameRead { name, definitions }
                    if !definitions.is_empty() =>
                {
                    CfgScalarExprKind::Name(name.clone())
                }
                crate::ir::ControlFlowValueKind::Unary {
                    op: UnaryOp::Borrow,
                    operand,
                } => CfgScalarExprKind::Unary {
                    op: UnaryOp::Borrow,
                    operand: Box::new(cfg_borrowed_collection_value(cfg, *operand)?),
                },
                crate::ir::ControlFlowValueKind::Index {
                    base,
                    index,
                    optional,
                } => CfgScalarExprKind::Index {
                    base: Box::new(cfg_borrowed_index_base(cfg, *base)?),
                    index: Box::new(cfg_direct_scalar_expr(cfg, *index)?),
                    optional: *optional,
                },
                crate::ir::ControlFlowValueKind::Field {
                    base,
                    name,
                    optional,
                } => CfgScalarExprKind::Field {
                    base: Box::new(cfg_borrowed_collection_field_base(cfg, *base)?),
                    name: name.clone(),
                    optional: *optional,
                },
                _ => return None,
            };
            Some(CfgScalarExpr {
                ty: value.ty.clone(),
                kind,
            })
        }
        _ => None,
    }
}

fn cfg_direct_scalar_expr(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    if let Some(leaf) = cfg_scalar_leaf(cfg, id) {
        return Some(leaf);
    }
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    if let crate::ir::ControlFlowValueKind::Unary {
        op: UnaryOp::Borrow,
        operand,
    } = &value.kind
        && value.ownership.is_borrow()
    {
        return Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind: CfgScalarExprKind::Unary {
                op: UnaryOp::Borrow,
                operand: Box::new(cfg_borrowed_collection_value(cfg, *operand)?),
            },
        });
    }
    if value.ownership.is_borrow()
        && matches!(
            &value.ty,
            Type::List(_) | Type::Set(_) | Type::Map(_, _) | Type::Optional(_)
        )
        && let Some(borrowed) = cfg_borrowed_collection_value(cfg, id)
    {
        return Some(borrowed);
    }
    if value.ownership.is_copy()
        && matches!(
            &value.kind,
            crate::ir::ControlFlowValueKind::RecordLiteral { .. }
                | crate::ir::ControlFlowValueKind::StructLiteral { .. }
        )
    {
        let CfgAggregateValue::Aggregate(aggregate) = cfg_literal_aggregate_value(cfg, id)? else {
            return None;
        };
        return Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind: CfgScalarExprKind::Aggregate(aggregate),
        });
    }
    let reconstructable_void_effect = value.ownership.is_effect_only()
        && matches!(
            &value.kind,
            crate::ir::ControlFlowValueKind::Await { .. }
                | crate::ir::ControlFlowValueKind::Call { .. }
                | crate::ir::ControlFlowValueKind::NamedCall { .. }
                | crate::ir::ControlFlowValueKind::QualifiedCall { .. }
                | crate::ir::ControlFlowValueKind::NamedQualifiedCall { .. }
                | crate::ir::ControlFlowValueKind::InterfaceDispatch { .. }
                | crate::ir::ControlFlowValueKind::NamedInterfaceDispatch { .. }
        );
    if !value.ownership.is_copy() && !reconstructable_void_effect {
        return None;
    }
    let kind = match &value.kind {
        crate::ir::ControlFlowValueKind::Unary { op, operand }
            if matches!(op, UnaryOp::Neg | UnaryOp::Not) =>
        {
            CfgScalarExprKind::Unary {
                op: *op,
                operand: Box::new(cfg_direct_scalar_expr(cfg, *operand)?),
            }
        }
        crate::ir::ControlFlowValueKind::Field {
            base,
            name,
            optional,
        } => {
            let base_value = cfg.value(*base)?;
            let base = if base_value.ownership.is_borrow() {
                cfg_borrowed_collection_value(cfg, *base)?
            } else {
                cfg_direct_scalar_expr(cfg, *base)?
            };
            CfgScalarExprKind::Field {
                base: Box::new(base),
                name: name.clone(),
                optional: *optional,
            }
        }
        crate::ir::ControlFlowValueKind::Index {
            base,
            index,
            optional,
        } => CfgScalarExprKind::Index {
            base: Box::new(cfg_borrowed_index_base(cfg, *base)?),
            index: Box::new(cfg_direct_scalar_expr(cfg, *index)?),
            optional: *optional,
        },
        crate::ir::ControlFlowValueKind::InterfacePack {
            interface,
            target,
            value: packed,
        } => {
            let packed_value = cfg.value(*packed)?;
            if !matches!(&packed_value.ty, Type::Named(name) if name == target) {
                return None;
            }
            CfgScalarExprKind::InterfacePack {
                interface: interface.clone(),
                target: target.clone(),
                value: Box::new(cfg_direct_scalar_expr(cfg, *packed)?),
            }
        }
        crate::ir::ControlFlowValueKind::AnonymousFunction {
            body,
            params,
            return_type,
        } => CfgScalarExprKind::AnonymousFunction {
            span: value.span,
            params: params.clone(),
            return_type: return_type.clone(),
            body: Box::new(cfg_direct_scalar_expr(cfg, *body)?),
        },
        crate::ir::ControlFlowValueKind::Await { value } => CfgScalarExprKind::Await {
            value: Box::new(cfg_direct_scalar_expr(cfg, *value)?),
        },
        crate::ir::ControlFlowValueKind::Call { callee, arguments } if callee == "bind" => {
            CfgScalarExprKind::Bind {
                span: value.span,
                arguments: arguments
                    .iter()
                    .map(|id| cfg_direct_scalar_expr(cfg, *id))
                    .collect::<Option<Vec<_>>>()?,
            }
        }
        crate::ir::ControlFlowValueKind::Call { callee, arguments } => CfgScalarExprKind::Call {
            callee: callee.clone(),
            arguments: arguments
                .iter()
                .map(|id| cfg_direct_scalar_expr(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::NamedCall {
            callee,
            arguments,
            argument_names,
        } if arguments.len() == argument_names.len() => CfgScalarExprKind::NamedCall {
            callee: callee.clone(),
            arguments: argument_names
                .iter()
                .cloned()
                .zip(arguments.iter().copied())
                .map(|(name, id)| cfg_direct_scalar_expr(cfg, id).map(|value| (name, value)))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::QualifiedCall {
            namespace,
            name,
            arguments,
        } => CfgScalarExprKind::QualifiedCall {
            namespace: namespace.clone(),
            name: name.clone(),
            arguments: arguments
                .iter()
                .map(|id| cfg_direct_scalar_expr(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::NamedQualifiedCall {
            namespace,
            name,
            arguments,
            argument_names,
        } if arguments.len() == argument_names.len() => CfgScalarExprKind::NamedQualifiedCall {
            namespace: namespace.clone(),
            name: name.clone(),
            arguments: argument_names
                .iter()
                .cloned()
                .zip(arguments.iter().copied())
                .map(|(name, id)| cfg_direct_scalar_expr(cfg, id).map(|value| (name, value)))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::InterfaceDispatch {
            interface,
            capability,
            arguments,
            ..
        } => CfgScalarExprKind::QualifiedCall {
            namespace: interface.clone(),
            name: capability.clone(),
            arguments: arguments
                .iter()
                .map(|id| cfg_direct_scalar_expr(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::NamedInterfaceDispatch {
            interface,
            capability,
            arguments,
            argument_names,
            ..
        } if arguments.len() == argument_names.len() => CfgScalarExprKind::NamedQualifiedCall {
            namespace: interface.clone(),
            name: capability.clone(),
            arguments: argument_names
                .iter()
                .cloned()
                .zip(arguments.iter().copied())
                .map(|(name, id)| cfg_direct_scalar_expr(cfg, id).map(|value| (name, value)))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::OptionalCascadeCall {
            optional,
            callee,
            arguments,
        } => CfgScalarExprKind::OptionalCascadeCall {
            optional: Box::new(cfg_direct_scalar_expr(cfg, *optional)?),
            callee: callee.clone(),
            arguments: arguments
                .iter()
                .map(|id| cfg_direct_scalar_expr(cfg, *id))
                .collect::<Option<Vec<_>>>()?,
        },
        crate::ir::ControlFlowValueKind::Binary { op, left, right }
            if matches!(
                op,
                BinOp::Add
                    | BinOp::Sub
                    | BinOp::Mul
                    | BinOp::Div
                    | BinOp::And
                    | BinOp::Or
                    | BinOp::Eq
                    | BinOp::Ne
                    | BinOp::Lt
                    | BinOp::Le
                    | BinOp::Gt
                    | BinOp::Ge
                    | BinOp::Coalesce
            ) =>
        {
            let left = cfg_direct_scalar_expr(cfg, *left)?;
            let right = cfg_direct_scalar_expr(cfg, *right)?;
            CfgScalarExprKind::Binary {
                op: *op,
                left: Box::new(left),
                right: Box::new(right),
            }
        }
        crate::ir::ControlFlowValueKind::Conditional {
            condition,
            then_value,
            else_value,
        } => CfgScalarExprKind::Conditional {
            condition: Box::new(cfg_direct_scalar_expr(cfg, *condition)?),
            then_value: Box::new(cfg_direct_scalar_expr(cfg, *then_value)?),
            else_value: Box::new(cfg_direct_scalar_expr(cfg, *else_value)?),
        },
        _ => return None,
    };
    Some(CfgScalarExpr {
        ty: value.ty.clone(),
        kind,
    })
}

fn cfg_direct_sequence_expr(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    let crate::ir::ControlFlowValueKind::Call { callee, arguments } = &value.kind else {
        return None;
    };
    if !matches!(
        crate::builtin_names::global_impl(callee),
        "map"
            | "filter"
            | "where"
            | "chunked"
            | "sorted"
            | "flatten"
            | "distinct"
            | "concat"
            | "fold"
            | "reduce"
    ) {
        return None;
    }
    let arguments = arguments
        .iter()
        .map(|id| cfg_direct_scalar_expr(cfg, *id).or_else(|| cfg_direct_sequence_expr(cfg, *id)))
        .collect::<Option<Vec<_>>>()?;
    Some(CfgScalarExpr {
        ty: value.ty.clone(),
        kind: CfgScalarExprKind::Call {
            callee: callee.clone(),
            arguments,
        },
    })
}

fn cfg_direct_multi_expr(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgScalarExpr> {
    fn direct_call(
        cfg: &crate::ir::ControlFlowGraph,
        id: crate::ir::ControlFlowValueId,
    ) -> Option<CfgScalarExpr> {
        let value = cfg.value(id)?;
        if !cfg.is_value_reachable(id) {
            return None;
        }
        let kind = match &value.kind {
            crate::ir::ControlFlowValueKind::Call { callee, arguments } => {
                CfgScalarExprKind::Call {
                    callee: callee.clone(),
                    arguments: arguments
                        .iter()
                        .map(|id| cfg_direct_scalar_expr(cfg, *id))
                        .collect::<Option<Vec<_>>>()?,
                }
            }
            crate::ir::ControlFlowValueKind::NamedCall {
                callee,
                arguments,
                argument_names,
            } if arguments.len() == argument_names.len() => CfgScalarExprKind::NamedCall {
                callee: callee.clone(),
                arguments: argument_names
                    .iter()
                    .cloned()
                    .zip(arguments.iter().copied())
                    .map(|(name, id)| cfg_direct_scalar_expr(cfg, id).map(|value| (name, value)))
                    .collect::<Option<Vec<_>>>()?,
            },
            crate::ir::ControlFlowValueKind::QualifiedCall {
                namespace,
                name,
                arguments,
            } => CfgScalarExprKind::QualifiedCall {
                namespace: namespace.clone(),
                name: name.clone(),
                arguments: arguments
                    .iter()
                    .map(|id| cfg_direct_scalar_expr(cfg, *id))
                    .collect::<Option<Vec<_>>>()?,
            },
            crate::ir::ControlFlowValueKind::NamedQualifiedCall {
                namespace,
                name,
                arguments,
                argument_names,
            } if arguments.len() == argument_names.len() => CfgScalarExprKind::NamedQualifiedCall {
                namespace: namespace.clone(),
                name: name.clone(),
                arguments: argument_names
                    .iter()
                    .cloned()
                    .zip(arguments.iter().copied())
                    .map(|(name, id)| cfg_direct_scalar_expr(cfg, id).map(|value| (name, value)))
                    .collect::<Option<Vec<_>>>()?,
            },
            crate::ir::ControlFlowValueKind::InterfaceDispatch {
                interface,
                capability,
                arguments,
                ..
            } => CfgScalarExprKind::QualifiedCall {
                namespace: interface.clone(),
                name: capability.clone(),
                arguments: arguments
                    .iter()
                    .map(|id| cfg_direct_scalar_expr(cfg, *id))
                    .collect::<Option<Vec<_>>>()?,
            },
            crate::ir::ControlFlowValueKind::NamedInterfaceDispatch {
                interface,
                capability,
                arguments,
                argument_names,
                ..
            } if arguments.len() == argument_names.len() => CfgScalarExprKind::NamedQualifiedCall {
                namespace: interface.clone(),
                name: capability.clone(),
                arguments: argument_names
                    .iter()
                    .cloned()
                    .zip(arguments.iter().copied())
                    .map(|(name, id)| cfg_direct_scalar_expr(cfg, id).map(|value| (name, value)))
                    .collect::<Option<Vec<_>>>()?,
            },
            _ => return None,
        };
        Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind,
        })
    }

    let value = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    match &value.kind {
        crate::ir::ControlFlowValueKind::Await { value: awaited } => Some(CfgScalarExpr {
            ty: value.ty.clone(),
            kind: CfgScalarExprKind::Await {
                value: Box::new(direct_call(cfg, *awaited)?),
            },
        }),
        _ => direct_call(cfg, id),
    }
}

fn cfg_list_item_shape(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgListItemShape> {
    let item = cfg.value(id)?;
    let span = source_span_key(item.span);
    match &item.kind {
        crate::ir::ControlFlowValueKind::ListSpread { value, optional } => {
            Some(CfgListItemShape::Spread {
                span,
                value: source_span_key(cfg.value(*value)?.span),
                optional: *optional,
            })
        }
        crate::ir::ControlFlowValueKind::ListOptional { value } => {
            Some(CfgListItemShape::Optional {
                span,
                value: source_span_key(cfg.value(*value)?.span),
            })
        }
        crate::ir::ControlFlowValueKind::ListIf {
            condition,
            binding,
            value,
            else_value,
        } => Some(CfgListItemShape::Conditional {
            span,
            condition: source_span_key(cfg.value(*condition)?.span),
            binding: binding.clone(),
            value: source_span_key(cfg.value(*value)?.span),
            else_value: match else_value {
                Some(id) => Some(source_span_key(cfg.value(*id)?.span)),
                None => None,
            },
        }),
        _ => Some(CfgListItemShape::Value(span)),
    }
}

fn cfg_direct_match_expr(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgMatchExpr> {
    let root = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    let crate::ir::ControlFlowValueKind::Match {
        value,
        guards,
        arms,
        arm_patterns,
    } = &root.kind
    else {
        return None;
    };
    if guards.len() != arms.len() || arms.len() != arm_patterns.len() {
        return None;
    }

    let mut lowered_arms = Vec::with_capacity(arms.len());
    for index in 0..arms.len() {
        let guard = match guards[index] {
            Some(guard) => Some(cfg_direct_scalar_expr(cfg, guard)?),
            None => None,
        };
        lowered_arms.push(CfgMatchExprArm {
            pattern: arm_patterns[index].clone(),
            guard,
            value: cfg_direct_scalar_expr(cfg, arms[index])?,
        });
    }

    Some(CfgMatchExpr {
        value: cfg_direct_scalar_expr(cfg, *value)?,
        arms: lowered_arms,
    })
}

fn cfg_direct_list_match_expr(
    cfg: &crate::ir::ControlFlowGraph,
    id: crate::ir::ControlFlowValueId,
) -> Option<CfgListMatchExpr> {
    let root = cfg.value(id)?;
    if !cfg.is_value_reachable(id) {
        return None;
    }
    let crate::ir::ControlFlowValueKind::ListMatch {
        value,
        guards,
        arms,
        arm_patterns,
    } = &root.kind
    else {
        return None;
    };
    if guards.len() != arms.len() || arms.len() != arm_patterns.len() {
        return None;
    }

    let mut lowered_arms = Vec::with_capacity(arms.len());
    for index in 0..arms.len() {
        let guard = match guards[index] {
            Some(guard) => Some(cfg_direct_scalar_expr(cfg, guard)?),
            None => None,
        };
        lowered_arms.push(CfgListMatchExprArm {
            pattern: arm_patterns[index].clone(),
            guard,
            value: cfg_direct_scalar_expr(cfg, arms[index])?,
        });
    }

    Some(CfgListMatchExpr {
        value: cfg_borrowed_collection_field_base(cfg, *value)?,
        arms: lowered_arms,
    })
}

fn cfg_rewrite_facts(cfg: &crate::ir::ControlFlowGraph) -> CfgRewriteFacts {
    let mut constants = HashMap::new();
    let mut ambiguous_constants = HashSet::new();
    // Consume constants from the typed value graph, not only from name reads.
    // A propagated scalar value is safe to inline here because the IR constant
    // pass records its complete expression under Flux's checked semantics.
    // Reconstructable short-circuit/coalescing trees are consumed through
    // scalar_exprs below; keep the span collision guard for every fact family:
    // a source span can occur in more than one CFG path, and differing values
    // must continue through the ordinary AST emitter.
    for (value, constant) in cfg.values().iter().filter_map(|value| {
        cfg.proven_scalar_constant(value.id)
            .map(|constant| (value, constant))
    }) {
        let span = source_span_key(value.span);
        if ambiguous_constants.contains(&span) {
            continue;
        }
        if let Some(existing) = constants.get(&span) {
            if existing != constant {
                constants.remove(&span);
                ambiguous_constants.insert(span);
            }
        } else {
            constants.insert(span, constant.clone());
        }
    }

    let mut aggregates = HashMap::new();
    let mut ambiguous_aggregates = HashSet::new();
    for value in cfg
        .values()
        .iter()
        .filter(|value| cfg.is_value_reachable(value.id))
    {
        let shape = match &value.kind {
            crate::ir::ControlFlowValueKind::List { items } => items
                .iter()
                .map(|id| cfg_list_item_shape(cfg, *id))
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateShape::List),
            crate::ir::ControlFlowValueKind::ListComprehension {
                binding,
                iterable,
                value,
                condition,
            } => (|| {
                Some(CfgAggregateShape::ListComprehension {
                    binding: binding.clone(),
                    iterable: source_span_key(cfg.value(*iterable)?.span),
                    value: source_span_key(cfg.value(*value)?.span),
                    condition: match condition {
                        Some(id) => Some(source_span_key(cfg.value(*id)?.span)),
                        None => None,
                    },
                })
            })(),
            crate::ir::ControlFlowValueKind::Set { items } => items
                .iter()
                .map(|id| cfg.value(*id).map(|item| source_span_key(item.span)))
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateShape::Set),
            crate::ir::ControlFlowValueKind::RecordLiteral { fields } => fields
                .iter()
                .map(|(name, id)| {
                    cfg.value(*id)
                        .map(|field| (name.clone(), source_span_key(field.span)))
                })
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateShape::Record),
            _ => None,
        };
        let Some(shape) = shape else {
            continue;
        };
        let span = source_span_key(value.span);
        if ambiguous_aggregates.contains(&span) {
            continue;
        }
        if let Some(existing) = aggregates.get(&span) {
            if existing != &shape {
                aggregates.remove(&span);
                ambiguous_aggregates.insert(span);
            }
        } else {
            aggregates.insert(span, shape);
        }
    }

    let mut aggregate_constants = HashMap::new();
    let mut ambiguous_aggregate_constants = HashSet::new();
    for value in cfg
        .values()
        .iter()
        .filter(|value| cfg.is_value_reachable(value.id))
    {
        let scalar = |id| cfg.proven_scalar_constant(id).cloned();
        let kind = match &value.kind {
            crate::ir::ControlFlowValueKind::List { items } => items
                .iter()
                .map(|id| cfg_literal_aggregate_value(cfg, *id))
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateConstantKind::List),
            crate::ir::ControlFlowValueKind::Set { items } => items
                .iter()
                .map(|id| cfg_literal_aggregate_value(cfg, *id))
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateConstantKind::Set),
            crate::ir::ControlFlowValueKind::Map { entries } => entries
                .iter()
                .map(|(key, value)| {
                    Some((scalar(*key)?, cfg_literal_aggregate_value(cfg, *value)?))
                })
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateConstantKind::Map),
            crate::ir::ControlFlowValueKind::RecordLiteral { fields } => fields
                .iter()
                .map(|(name, id)| Some((name.clone(), cfg_literal_aggregate_value(cfg, *id)?)))
                .collect::<Option<Vec<_>>>()
                .map(CfgAggregateConstantKind::Record),
            crate::ir::ControlFlowValueKind::StructLiteral { name, base, fields }
                if base.is_none() || value.ownership.is_copy() =>
            {
                let base = match base {
                    Some(id) => cfg_literal_aggregate_value(cfg, *id).map(Some),
                    None => Some(None),
                };
                base.and_then(|base| {
                    fields
                        .iter()
                        .map(|(field, id)| {
                            Some((field.clone(), cfg_literal_aggregate_value(cfg, *id)?))
                        })
                        .collect::<Option<Vec<_>>>()
                        .map(|fields| CfgAggregateConstantKind::Struct {
                            name: name.clone(),
                            base,
                            fields,
                        })
                })
            }
            _ => None,
        };
        let Some(kind) = kind else {
            continue;
        };
        let aggregate = CfgAggregateConstant {
            ty: value.ty.clone(),
            kind,
        };
        let span = source_span_key(value.span);
        if ambiguous_aggregate_constants.contains(&span) {
            continue;
        }
        if let Some(existing) = aggregate_constants.get(&span) {
            if existing != &aggregate {
                aggregate_constants.remove(&span);
                ambiguous_aggregate_constants.insert(span);
            }
        } else {
            aggregate_constants.insert(span, aggregate);
        }
    }

    let mut scalar_exprs = HashMap::new();
    let mut ambiguous_scalar_exprs = HashSet::new();
    for value in cfg
        .values()
        .iter()
        .filter(|value| cfg.is_value_reachable(value.id))
    {
        let Some(scalar) = cfg_direct_scalar_expr(cfg, value.id) else {
            continue;
        };
        let span = source_span_key(value.span);
        if ambiguous_scalar_exprs.contains(&span) {
            continue;
        }
        if let Some(existing) = scalar_exprs.get(&span) {
            if existing != &scalar {
                scalar_exprs.remove(&span);
                ambiguous_scalar_exprs.insert(span);
            }
        } else {
            scalar_exprs.insert(span, scalar);
        }
    }

    let mut sequence_exprs = HashMap::new();
    let mut ambiguous_sequence_exprs = HashSet::new();
    for value in cfg.values().iter().filter(|value| {
        cfg.is_value_reachable(value.id) && !value.result_index.is_some_and(|index| index > 0)
    }) {
        let Some(sequence) = cfg_direct_sequence_expr(cfg, value.id) else {
            continue;
        };
        let span = source_span_key(value.span);
        if ambiguous_sequence_exprs.contains(&span) {
            continue;
        }
        if let Some(existing) = sequence_exprs.get(&span) {
            if existing != &sequence {
                sequence_exprs.remove(&span);
                ambiguous_sequence_exprs.insert(span);
            }
        } else {
            sequence_exprs.insert(span, sequence);
        }
    }

    let multi_result_spans = cfg
        .values()
        .iter()
        .filter(|value| {
            cfg.is_value_reachable(value.id) && value.result_index.is_some_and(|index| index > 0)
        })
        .map(|value| source_span_key(value.span))
        .collect::<HashSet<_>>();
    let mut multi_exprs = HashMap::new();
    let mut ambiguous_multi_exprs = HashSet::new();
    for value in cfg.values().iter().filter(|value| {
        cfg.is_value_reachable(value.id)
            && value.result_index == Some(0)
            && multi_result_spans.contains(&source_span_key(value.span))
    }) {
        let Some(multi) = cfg_direct_multi_expr(cfg, value.id) else {
            continue;
        };
        let span = source_span_key(value.span);
        if ambiguous_multi_exprs.contains(&span) {
            continue;
        }
        if let Some(existing) = multi_exprs.get(&span) {
            if existing != &multi {
                multi_exprs.remove(&span);
                ambiguous_multi_exprs.insert(span);
            }
        } else {
            multi_exprs.insert(span, multi);
        }
    }

    let mut match_exprs = HashMap::new();
    let mut ambiguous_match_exprs = HashSet::new();
    let mut list_match_exprs = HashMap::new();
    let mut ambiguous_list_match_exprs = HashSet::new();
    for value in cfg
        .values()
        .iter()
        .filter(|value| cfg.is_value_reachable(value.id))
    {
        if let Some(match_expr) = cfg_direct_match_expr(cfg, value.id) {
            let span = source_span_key(value.span);
            if !ambiguous_match_exprs.contains(&span) {
                if let Some(existing) = match_exprs.get(&span) {
                    if existing != &match_expr {
                        match_exprs.remove(&span);
                        ambiguous_match_exprs.insert(span);
                    }
                } else {
                    match_exprs.insert(span, match_expr);
                }
            }
        }
        if let Some(list_match_expr) = cfg_direct_list_match_expr(cfg, value.id) {
            let span = source_span_key(value.span);
            if !ambiguous_list_match_exprs.contains(&span) {
                if let Some(existing) = list_match_exprs.get(&span) {
                    if existing != &list_match_expr {
                        list_match_exprs.remove(&span);
                        ambiguous_list_match_exprs.insert(span);
                    }
                } else {
                    list_match_exprs.insert(span, list_match_expr);
                }
            }
        }
    }

    CfgRewriteFacts {
        constants,
        aggregates,
        aggregate_constants,
        scalar_exprs,
        sequence_exprs,
        multi_exprs,
        match_exprs,
        list_match_exprs,
    }
}

fn emit_function(
    out: &mut String,
    function: &Function,
    signatures: &Signatures,
    cfg: &crate::ir::ControlFlowGraph,
    temp_counter: &mut usize,
    source_paths: &HashMap<SourceId, String>,
) -> Result<(), Diagnostic> {
    let reachable_spans = cfg
        .nodes()
        .iter()
        .filter(|node| cfg.is_reachable(node.id))
        .map(|node| source_span_key(node.span))
        .collect::<HashSet<_>>();
    let dead_assignment_spans = cfg
        .nodes()
        .iter()
        .filter(|node| cfg.is_reachable(node.id))
        .filter_map(|node| match &node.kind {
            crate::ir::ControlFlowNodeKind::Assignment { name }
                if cfg
                    .live_after(node.id)
                    .is_some_and(|state| !state.contains(name)) =>
            {
                Some(source_span_key(node.span))
            }
            _ => None,
        })
        .collect::<HashSet<_>>();
    let dead_var_initializer_spans = cfg
        .nodes()
        .iter()
        .filter(|node| cfg.is_reachable(node.id))
        .filter_map(|node| match &node.kind {
            crate::ir::ControlFlowNodeKind::Binding {
                name,
                mutable: true,
                ..
            } if cfg
                .live_after(node.id)
                .is_some_and(|state| !state.contains(name)) =>
            {
                Some(source_span_key(node.span))
            }
            _ => None,
        })
        .collect::<HashSet<_>>();
    let dead_let_binding_spans = cfg
        .nodes()
        .iter()
        .filter(|node| cfg.is_reachable(node.id))
        .filter_map(|node| match &node.kind {
            crate::ir::ControlFlowNodeKind::Binding {
                name,
                mutable: false,
                ..
            } if cfg
                .live_after(node.id)
                .is_some_and(|state| !state.contains(name)) =>
            {
                Some(source_span_key(node.span))
            }
            _ => None,
        })
        .collect::<HashSet<_>>();
    let dead_expression_spans = cfg
        .nodes()
        .iter()
        .filter(|node| cfg.is_reachable(node.id))
        .filter(|node| {
            matches!(
                node.kind,
                crate::ir::ControlFlowNodeKind::Evaluation(
                    crate::ir::ControlFlowEvaluationKind::ExpressionStatement
                )
            ) && !node.values.is_empty()
                && node
                    .values
                    .iter()
                    .all(|value| !cfg.is_value_reachable(*value))
        })
        .map(|node| source_span_key(node.span))
        .collect::<HashSet<_>>();
    let dead_non_escaping_let_binding_spans =
        cfg.nodes()
            .iter()
            .filter(|node| cfg.is_reachable(node.id))
            .filter_map(|node| match &node.kind {
                crate::ir::ControlFlowNodeKind::Binding {
                    name,
                    mutable: false,
                    ..
                } if cfg
                    .live_after(node.id)
                    .is_some_and(|state| !state.contains(name)) =>
                {
                    let initializer = cfg.incoming(node.id).find_map(|edge| {
                        let source = cfg.node(edge.from)?;
                        matches!(
                            source.kind,
                            crate::ir::ControlFlowNodeKind::Evaluation(
                                crate::ir::ControlFlowEvaluationKind::BindingInitializer
                            )
                        )
                        .then_some(source)
                    })?;
                    (!initializer.values.is_empty()
                        && initializer.values.iter().all(|value| {
                            !cfg.is_value_reachable(*value) && !cfg.value_escapes(*value)
                        }))
                    .then_some(source_span_key(node.span))
                }
                _ => None,
            })
            .collect::<HashSet<_>>();
    let dead_definition_names = cfg
        .nodes()
        .iter()
        .filter(|node| cfg.is_reachable(node.id))
        .filter(|node| !node.definitions.is_empty())
        .filter_map(|node| {
            let live_after = cfg.live_after(node.id)?;
            let dead = node
                .definitions
                .iter()
                .filter(|definition| !live_after.contains(&definition.name))
                .map(|definition| definition.name.clone())
                .collect::<HashSet<_>>();
            (!dead.is_empty()).then_some((source_span_key(node.span), dead))
        })
        .collect::<HashMap<_, _>>();
    let checked_i64_cfg_proofs = cfg_checked_i64_proofs(cfg);
    let cfg_rewrite_facts = cfg_rewrite_facts(cfg);
    let block_context = BlockEmitContext {
        current_function: function,
        source_paths,
        reachable_spans: &reachable_spans,
        dead_assignment_spans: &dead_assignment_spans,
        dead_var_initializer_spans: &dead_var_initializer_spans,
        dead_let_binding_spans: &dead_let_binding_spans,
        dead_expression_spans: &dead_expression_spans,
        dead_non_escaping_let_binding_spans: &dead_non_escaping_let_binding_spans,
        dead_definition_names: &dead_definition_names,
        checked_i64_cfg_proofs: &checked_i64_cfg_proofs,
        cfg_rewrite_facts: &cfg_rewrite_facts,
        async_state_machine: false,
        async_loop_control: None,
    };
    if function.asynchronous
        && let Some(plan) = async_continuation_plan(function, signatures, cfg)
    {
        emit_source_line(out, function.span, source_paths);
        emit_async_continuation_function(
            out,
            function,
            signatures,
            &plan,
            temp_counter,
            block_context,
        )?;
        emit_async_task_runtime(out, function, signatures, true);
        return Ok(());
    }
    emit_source_line(out, function.span, source_paths);
    if function.asynchronous {
        out.push_str(&async_body_prototype(function, signatures));
    } else {
        out.push_str(&function_prototype(function, signatures));
    }
    out.push_str(" {\n");
    let mut env = HashMap::new();
    if function.asynchronous {
        env.insert("flux__async_context".to_string(), Type::Bool);
    }
    for param in &function.params {
        env.insert(param.name.clone(), signatures.canonical_type(&param.ty));
    }
    let mut mutable = HashSet::new();
    emit_block(
        out,
        &function.body,
        1,
        &mut env,
        &mut mutable,
        signatures,
        temp_counter,
        block_context,
    )?;
    out.push_str("}\n");
    if function.asynchronous {
        emit_async_task_runtime(out, function, signatures, false);
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct AsyncLoopControlContext<'a> {
    continue_state: usize,
    break_state: usize,
    saved_locals: &'a [(String, Type)],
}

#[derive(Clone, Copy)]
struct BlockEmitContext<'a> {
    current_function: &'a Function,
    source_paths: &'a HashMap<SourceId, String>,
    reachable_spans: &'a HashSet<(u32, usize, usize, usize)>,
    dead_assignment_spans: &'a HashSet<(u32, usize, usize, usize)>,
    dead_var_initializer_spans: &'a HashSet<(u32, usize, usize, usize)>,
    dead_let_binding_spans: &'a HashSet<(u32, usize, usize, usize)>,
    dead_expression_spans: &'a HashSet<(u32, usize, usize, usize)>,
    dead_non_escaping_let_binding_spans: &'a HashSet<(u32, usize, usize, usize)>,
    dead_definition_names: &'a HashMap<(u32, usize, usize, usize), HashSet<String>>,
    checked_i64_cfg_proofs: &'a HashMap<(u32, usize, usize, usize), CfgCheckedI64Proof>,
    cfg_rewrite_facts: &'a CfgRewriteFacts,
    async_state_machine: bool,
    async_loop_control: Option<AsyncLoopControlContext<'a>>,
}

impl BlockEmitContext<'_> {
    fn without_async_loop_control(self) -> Self {
        Self {
            async_loop_control: None,
            ..self
        }
    }
}

#[derive(Clone, Copy)]
enum CheckedI64Reduction {
    Left,
    Right,
    Zero,
    ZeroAfterLeft,
    ZeroAfterRight,
    NegateLeft,
    NegateRight,
    DoubleAfterLeft,
    SquareAfterLeft,
    SelfDivide,
    DivideByConstant(i64),
}

fn checked_i64_reduction(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    signatures: &Signatures,
) -> Option<CheckedI64Reduction> {
    if matches!(
        (&left.kind, &right.kind),
        (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
    ) {
        if matches!(op, BinOp::Sub) {
            return Some(CheckedI64Reduction::Zero);
        }
        if matches!(op, BinOp::Div) {
            return Some(CheckedI64Reduction::SelfDivide);
        }
    }

    let same_checked_negated_binding = matches!(
        (&left.kind, &right.kind),
        (
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: left_inner,
            },
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: right_inner,
            }
        ) if matches!(
            (&left_inner.kind, &right_inner.kind),
            (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
        )
    );
    if same_checked_negated_binding {
        match op {
            BinOp::Add => return Some(CheckedI64Reduction::DoubleAfterLeft),
            BinOp::Sub => return Some(CheckedI64Reduction::ZeroAfterLeft),
            BinOp::Mul => return Some(CheckedI64Reduction::SquareAfterLeft),
            BinOp::Div => return Some(CheckedI64Reduction::SelfDivide),
            _ => {}
        }
    }

    if matches!(op, BinOp::Add) {
        if let Some(negated) = checked_negation_operand(right, signatures)
            && same_pure_i64_expression(left, negated, signatures)
        {
            return Some(CheckedI64Reduction::ZeroAfterRight);
        }
        if let Some(negated) = checked_negation_operand(left, signatures)
            && same_pure_i64_expression(negated, right, signatures)
        {
            return Some(CheckedI64Reduction::ZeroAfterLeft);
        }
    }

    let left_constant = typecheck::constant_primitive_value(left, signatures);
    let right_constant = typecheck::constant_primitive_value(right, signatures);
    match (op, left_constant, right_constant) {
        (BinOp::Add, Some(ConstantValue::I64(0)), _) => Some(CheckedI64Reduction::Right),
        (BinOp::Add | BinOp::Sub, _, Some(ConstantValue::I64(0))) => {
            Some(CheckedI64Reduction::Left)
        }
        (BinOp::Sub, Some(ConstantValue::I64(0)), _) => Some(CheckedI64Reduction::NegateRight),
        (BinOp::Mul, Some(ConstantValue::I64(0)), _) => Some(CheckedI64Reduction::ZeroAfterRight),
        (BinOp::Mul, _, Some(ConstantValue::I64(0))) => Some(CheckedI64Reduction::ZeroAfterLeft),
        (BinOp::Mul, Some(ConstantValue::I64(1)), _) => Some(CheckedI64Reduction::Right),
        (BinOp::Mul | BinOp::Div, _, Some(ConstantValue::I64(1))) => {
            Some(CheckedI64Reduction::Left)
        }
        (BinOp::Mul, Some(ConstantValue::I64(-1)), _) => Some(CheckedI64Reduction::NegateRight),
        (BinOp::Mul | BinOp::Div, _, Some(ConstantValue::I64(-1))) => {
            Some(CheckedI64Reduction::NegateLeft)
        }
        (BinOp::Div, _, Some(ConstantValue::I64(divisor))) if divisor != 0 => {
            Some(CheckedI64Reduction::DivideByConstant(divisor))
        }
        _ => None,
    }
}

fn same_binding_comparison_c(op: BinOp, left: &Expr, right: &Expr) -> Option<&'static str> {
    if !matches!(
        (&left.kind, &right.kind),
        (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
    ) {
        return None;
    }

    match op {
        BinOp::Eq | BinOp::Le | BinOp::Ge => Some("true"),
        BinOp::Ne | BinOp::Lt | BinOp::Gt => Some("false"),
        _ => None,
    }
}

fn checked_negation_operand<'a>(expr: &'a Expr, signatures: &Signatures) -> Option<&'a Expr> {
    let constant_i64 = |expr: &Expr| match typecheck::constant_primitive_value(expr, signatures) {
        Some(ConstantValue::I64(value)) => Some(value),
        _ => None,
    };

    match &expr.kind {
        ExprKind::Unary {
            op: UnaryOp::Neg,
            expr,
        } => Some(expr),
        ExprKind::Binary {
            left,
            op: BinOp::Sub,
            right,
        } if constant_i64(left) == Some(0) => Some(right),
        ExprKind::Binary {
            left,
            op: BinOp::Mul,
            right,
        } if constant_i64(left) == Some(-1) => Some(right),
        ExprKind::Binary {
            left,
            op: BinOp::Mul,
            right,
        } if constant_i64(right) == Some(-1) => Some(left),
        ExprKind::Binary {
            left,
            op: BinOp::Div,
            right,
        } if constant_i64(right) == Some(-1) => Some(left),
        _ => None,
    }
}

fn checked_i64_identity_operand<'a>(expr: &'a Expr, signatures: &Signatures) -> Option<&'a Expr> {
    let constant_i64 = |expr: &Expr| match typecheck::constant_primitive_value(expr, signatures) {
        Some(ConstantValue::I64(value)) => Some(value),
        _ => None,
    };

    match &expr.kind {
        ExprKind::Binary {
            left,
            op: BinOp::Add,
            right,
        } if constant_i64(left) == Some(0) => Some(right),
        ExprKind::Binary {
            left,
            op: BinOp::Add | BinOp::Sub,
            right,
        } if constant_i64(right) == Some(0) => Some(left),
        ExprKind::Binary {
            left,
            op: BinOp::Mul,
            right,
        } if constant_i64(left) == Some(1) => Some(right),
        ExprKind::Binary {
            left,
            op: BinOp::Mul | BinOp::Div,
            right,
        } if constant_i64(right) == Some(1) => Some(left),
        _ => None,
    }
}

fn same_pure_i64_expression(left: &Expr, right: &Expr, signatures: &Signatures) -> bool {
    if let (Some(ConstantValue::I64(left_value)), Some(ConstantValue::I64(right_value))) = (
        typecheck::constant_primitive_value(left, signatures),
        typecheck::constant_primitive_value(right, signatures),
    ) && left_value == right_value
    {
        return true;
    }

    if let (Some(left), Some(right)) = (
        checked_negation_operand(left, signatures),
        checked_negation_operand(right, signatures),
    ) {
        return same_pure_i64_expression(left, right, signatures);
    }
    if let Some(left) = checked_i64_identity_operand(left, signatures) {
        return same_pure_i64_expression(left, right, signatures);
    }
    if let Some(right) = checked_i64_identity_operand(right, signatures) {
        return same_pure_i64_expression(left, right, signatures);
    }

    match (&left.kind, &right.kind) {
        (ExprKind::Int(left), ExprKind::Int(right)) => left == right,
        (ExprKind::Var(left), ExprKind::Var(right)) => left == right,
        (
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: left,
            },
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: right,
            },
        ) => same_pure_i64_expression(left, right, signatures),
        (
            ExprKind::Binary {
                left: left_left,
                op: left_op,
                right: left_right,
            },
            ExprKind::Binary {
                left: right_left,
                op: right_op,
                right: right_right,
            },
        ) if left_op == right_op
            && matches!(left_op, BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div) =>
        {
            let same_order = same_pure_i64_expression(left_left, right_left, signatures)
                && same_pure_i64_expression(left_right, right_right, signatures);
            same_order
                || (matches!(left_op, BinOp::Add | BinOp::Mul)
                    && same_pure_i64_expression(left_left, right_right, signatures)
                    && same_pure_i64_expression(left_right, right_left, signatures))
        }
        _ => false,
    }
}

fn same_checked_i64_expression_arithmetic_c(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    left_code: &str,
    signatures: &Signatures,
) -> Option<String> {
    if !matches!(op, BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div)
        || !matches!(
            left.kind,
            ExprKind::Unary {
                op: UnaryOp::Neg,
                ..
            } | ExprKind::Binary {
                op: BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div,
                ..
            }
        )
        || !same_pure_i64_expression(left, right, signatures)
    {
        return None;
    }

    match op {
        BinOp::Add => Some(format!(
            "__extension__ ({{ int64_t flux__checked_reuse = {left_code}; flux_add_i64(flux__checked_reuse, flux__checked_reuse); }})"
        )),
        BinOp::Sub => Some(format!("((void)({left_code}), INT64_C(0))")),
        BinOp::Mul => Some(format!(
            "__extension__ ({{ int64_t flux__checked_reuse = {left_code}; flux_mul_i64(flux__checked_reuse, flux__checked_reuse); }})"
        )),
        BinOp::Div => Some(format!("flux_div_self_i64({left_code})")),
        _ => None,
    }
}

fn same_checked_i64_expression_comparison_c(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    left_code: &str,
    signatures: &Signatures,
) -> Option<String> {
    let checked_expression = |expr: &Expr| {
        matches!(
            expr.kind,
            ExprKind::Unary {
                op: UnaryOp::Neg,
                ..
            } | ExprKind::Binary {
                op: BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div,
                ..
            }
        )
    };
    if (!checked_expression(left) && !checked_expression(right))
        || !same_pure_i64_expression(left, right, signatures)
    {
        return None;
    }

    let result = match op {
        BinOp::Eq | BinOp::Le | BinOp::Ge => "true",
        BinOp::Ne | BinOp::Lt | BinOp::Gt => "false",
        _ => return None,
    };

    Some(format!("((void)({left_code}), {result})"))
}

fn same_checked_negated_binding_comparison_c(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    left_code: &str,
) -> Option<String> {
    if !matches!(
        (&left.kind, &right.kind),
        (
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: left_inner,
            },
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: right_inner,
            }
        ) if matches!(
            (&left_inner.kind, &right_inner.kind),
            (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
        )
    ) {
        return None;
    }

    let result = match op {
        BinOp::Eq | BinOp::Le | BinOp::Ge => "true",
        BinOp::Ne | BinOp::Lt | BinOp::Gt => "false",
        _ => return None,
    };
    Some(format!("((void)({left_code}), {result})"))
}

fn same_boolean_binding_term(left: &Expr, right: &Expr) -> bool {
    match (&left.kind, &right.kind) {
        (ExprKind::Var(left_name), ExprKind::Var(right_name)) => left_name == right_name,
        (
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: left_inner,
            },
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: right_inner,
            },
        ) => matches!(
            (&left_inner.kind, &right_inner.kind),
            (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
        ),
        _ => false,
    }
}

fn same_pure_boolean_expression(left: &Expr, right: &Expr, signatures: &Signatures) -> bool {
    if let (Some(ConstantValue::Bool(left_value)), Some(ConstantValue::Bool(right_value))) = (
        typecheck::constant_primitive_value(left, signatures),
        typecheck::constant_primitive_value(right, signatures),
    ) && left_value == right_value
    {
        return true;
    }

    match (&left.kind, &right.kind) {
        (ExprKind::Var(left_name), ExprKind::Var(right_name)) => left_name == right_name,
        (
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: left_inner,
            },
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: right_inner,
            },
        ) => same_pure_boolean_expression(left_inner, right_inner, signatures),
        (
            ExprKind::Binary {
                left: left_left,
                op: left_op,
                right: left_right,
            },
            ExprKind::Binary {
                left: right_left,
                op: right_op,
                right: right_right,
            },
        ) if left_op == right_op && matches!(left_op, BinOp::And | BinOp::Or) => {
            same_pure_boolean_expression(left_left, right_left, signatures)
                && same_pure_boolean_expression(left_right, right_right, signatures)
        }
        (
            ExprKind::Binary {
                left: left_left,
                op: left_op,
                right: left_right,
            },
            ExprKind::Binary {
                left: right_left,
                op: right_op,
                right: right_right,
            },
        ) if left_op == right_op
            && matches!(
                left_op,
                BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge
            ) =>
        {
            same_pure_i64_expression(left_left, right_left, signatures)
                && same_pure_i64_expression(left_right, right_right, signatures)
        }
        _ => false,
    }
}

fn complementary_pure_boolean_expression(
    left: &Expr,
    right: &Expr,
    signatures: &Signatures,
) -> bool {
    match (&left.kind, &right.kind) {
        (
            _,
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: right_inner,
            },
        ) => same_pure_boolean_expression(left, right_inner, signatures),
        (
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: left_inner,
            },
            _,
        ) => same_pure_boolean_expression(left_inner, right, signatures),
        _ => false,
    }
}

fn complementary_boolean_binding_term(left: &Expr, right: &Expr) -> bool {
    match (&left.kind, &right.kind) {
        (
            ExprKind::Var(left_name),
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: right_inner,
            },
        ) => matches!(&right_inner.kind, ExprKind::Var(right_name) if left_name == right_name),
        (
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: left_inner,
            },
            ExprKind::Var(right_name),
        ) => matches!(&left_inner.kind, ExprKind::Var(left_name) if left_name == right_name),
        _ => false,
    }
}

fn boolean_absorption_operand_is_discardable(expr: &Expr, signatures: &Signatures) -> bool {
    matches!(
        typecheck::constant_primitive_value(expr, signatures),
        Some(ConstantValue::Bool(_))
    ) || matches!(expr.kind, ExprKind::Var(_))
        || matches!(
            &expr.kind,
            ExprKind::Unary {
                op: UnaryOp::Not,
                expr: inner,
            } if matches!(inner.kind, ExprKind::Var(_))
        )
}

fn boolean_resolution_other<'a>(
    op: BinOp,
    left: &Expr,
    right: &'a Expr,
    signatures: &Signatures,
) -> Option<&'a Expr> {
    if !matches!(op, BinOp::And | BinOp::Or) {
        return None;
    }
    let ExprKind::Binary {
        left: nested_left,
        op: nested_op,
        right: nested_right,
    } = &right.kind
    else {
        return None;
    };
    if !matches!(
        (op, *nested_op),
        (BinOp::And, BinOp::Or) | (BinOp::Or, BinOp::And)
    ) {
        return None;
    }
    if complementary_pure_boolean_expression(left, nested_left, signatures) {
        Some(nested_right)
    } else if complementary_pure_boolean_expression(left, nested_right, signatures) {
        Some(nested_left)
    } else {
        None
    }
}

fn boolean_left_resolution_other<'a>(
    op: BinOp,
    left: &'a Expr,
    right: &Expr,
    signatures: &Signatures,
) -> Option<&'a Expr> {
    if !matches!(op, BinOp::And | BinOp::Or) {
        return None;
    }
    let ExprKind::Binary {
        left: nested_left,
        op: nested_op,
        right: nested_right,
    } = &left.kind
    else {
        return None;
    };
    if !matches!(
        (op, *nested_op),
        (BinOp::And, BinOp::Or) | (BinOp::Or, BinOp::And)
    ) {
        return None;
    }
    complementary_pure_boolean_expression(nested_left, right, signatures).then_some(nested_right)
}

fn boolean_identity_c(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    left_code: &str,
    right_code: &str,
    signatures: &Signatures,
) -> Option<String> {
    let left_constant = typecheck::constant_primitive_value(left, signatures);
    let right_constant = typecheck::constant_primitive_value(right, signatures);

    if matches!(op, BinOp::Eq | BinOp::Ne) {
        if complementary_boolean_binding_term(left, right) {
            return Some(
                if matches!(op, BinOp::Eq) {
                    "false"
                } else {
                    "true"
                }
                .to_string(),
            );
        }

        let same_negated_binding = match (&left.kind, &right.kind) {
            (
                ExprKind::Unary {
                    op: UnaryOp::Not,
                    expr: left_inner,
                },
                ExprKind::Unary {
                    op: UnaryOp::Not,
                    expr: right_inner,
                },
            ) => matches!(
                (&left_inner.kind, &right_inner.kind),
                (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
            ),
            _ => false,
        };
        if same_negated_binding {
            return Some(
                if matches!(op, BinOp::Eq) {
                    "true"
                } else {
                    "false"
                }
                .to_string(),
            );
        }

        if same_pure_boolean_expression(left, right, signatures) {
            let result = if matches!(op, BinOp::Eq) {
                "true"
            } else {
                "false"
            };
            return Some(format!("((void)({left_code}), {result})"));
        }
        if complementary_pure_boolean_expression(left, right, signatures) {
            let result = if matches!(op, BinOp::Eq) {
                "false"
            } else {
                "true"
            };
            return Some(format!("((void)({left_code}), {result})"));
        }

        let negate = |code: &str| format!("(!({code}))");
        return match (op, left_constant, right_constant) {
            (BinOp::Eq, Some(ConstantValue::Bool(true)), _)
            | (BinOp::Ne, Some(ConstantValue::Bool(false)), _) => Some(right_code.to_string()),
            (BinOp::Eq, Some(ConstantValue::Bool(false)), _)
            | (BinOp::Ne, Some(ConstantValue::Bool(true)), _) => Some(negate(right_code)),
            (BinOp::Eq, _, Some(ConstantValue::Bool(true)))
            | (BinOp::Ne, _, Some(ConstantValue::Bool(false))) => Some(left_code.to_string()),
            (BinOp::Eq, _, Some(ConstantValue::Bool(false)))
            | (BinOp::Ne, _, Some(ConstantValue::Bool(true))) => Some(negate(left_code)),
            _ => None,
        };
    }

    if !matches!(op, BinOp::And | BinOp::Or) {
        return None;
    }

    if same_boolean_binding_term(left, right) {
        return Some(left_code.to_string());
    }
    if same_pure_boolean_expression(left, right, signatures) {
        return Some(left_code.to_string());
    }

    let absorbed_nested_binding = match &right.kind {
        ExprKind::Binary {
            left: nested_left,
            op: nested_op,
            right: nested_right,
        } if matches!(
            (op, *nested_op),
            (BinOp::And, BinOp::Or) | (BinOp::Or, BinOp::And)
        ) =>
        {
            same_pure_boolean_expression(left, nested_left, signatures)
                || (same_pure_boolean_expression(left, nested_right, signatures)
                    && boolean_absorption_operand_is_discardable(nested_left, signatures))
        }
        _ => false,
    };
    if absorbed_nested_binding {
        return Some(left_code.to_string());
    }

    let absorbed_left_nested_binding = match &left.kind {
        ExprKind::Binary {
            left: nested_left,
            op: nested_op,
            right: nested_right,
        } if matches!(
            (op, *nested_op),
            (BinOp::And, BinOp::Or) | (BinOp::Or, BinOp::And)
        ) =>
        {
            (same_pure_boolean_expression(right, nested_left, signatures)
                && boolean_absorption_operand_is_discardable(nested_right, signatures))
                || (same_pure_boolean_expression(right, nested_right, signatures)
                    && boolean_absorption_operand_is_discardable(nested_left, signatures))
        }
        _ => false,
    };
    if absorbed_left_nested_binding {
        return Some(right_code.to_string());
    }

    let nested_complement_result = match &right.kind {
        ExprKind::Binary {
            left: nested_left,
            op: nested_op,
            right: nested_right,
        } if matches!(
            (op, *nested_op),
            (BinOp::And, BinOp::And) | (BinOp::Or, BinOp::Or)
        ) =>
        {
            let nested_complement_is_unconditionally_reached =
                complementary_pure_boolean_expression(left, nested_left, signatures);
            let nested_complement_follows_discardable_work =
                complementary_pure_boolean_expression(left, nested_right, signatures)
                    && boolean_absorption_operand_is_discardable(nested_left, signatures);
            if nested_complement_is_unconditionally_reached
                || nested_complement_follows_discardable_work
            {
                Some(matches!(op, BinOp::Or))
            } else {
                None
            }
        }
        _ => None,
    };
    if let Some(result) = nested_complement_result {
        return Some(format!("((void)({left_code}), {result})"));
    }

    if complementary_boolean_binding_term(left, right)
        || complementary_pure_boolean_expression(left, right, signatures)
    {
        let result = if matches!(op, BinOp::And) {
            "false"
        } else {
            "true"
        };
        return Some(format!("((void)({left_code}), {result})"));
    }

    match (op, left_constant, right_constant) {
        (BinOp::And, Some(ConstantValue::Bool(false)), _)
        | (BinOp::Or, Some(ConstantValue::Bool(true)), _) => Some(
            if matches!(op, BinOp::And) {
                "false"
            } else {
                "true"
            }
            .to_string(),
        ),
        (BinOp::And, Some(ConstantValue::Bool(true)), _)
        | (BinOp::Or, Some(ConstantValue::Bool(false)), _) => Some(right_code.to_string()),
        (BinOp::And, _, Some(ConstantValue::Bool(true)))
        | (BinOp::Or, _, Some(ConstantValue::Bool(false))) => Some(left_code.to_string()),
        (BinOp::And, _, Some(ConstantValue::Bool(false))) => {
            Some(format!("((void)({left_code}), false)"))
        }
        (BinOp::Or, _, Some(ConstantValue::Bool(true))) => {
            Some(format!("((void)({left_code}), true)"))
        }
        _ => None,
    }
}

fn i64_expr_result_excludes_min(expr: &Expr, signatures: &Signatures) -> bool {
    let constant_i64 = |expr: &Expr| match typecheck::constant_primitive_value(expr, signatures) {
        Some(ConstantValue::I64(value)) => Some(value),
        _ => None,
    };
    if let Some(value) = constant_i64(expr) {
        return value != i64::MIN;
    }

    match &expr.kind {
        ExprKind::Unary {
            op: UnaryOp::Neg, ..
        } => true,
        ExprKind::Binary {
            left,
            op: BinOp::Add,
            right,
        } => {
            constant_i64(left).is_some_and(|value| value > 0)
                || constant_i64(right).is_some_and(|value| value > 0)
        }
        ExprKind::Binary {
            left,
            op: BinOp::Sub,
            right,
        } => {
            constant_i64(left).is_some_and(|value| value >= 0)
                || constant_i64(right).is_some_and(|value| value < 0)
                || same_pure_i64_expression(left, right, signatures)
        }
        ExprKind::Binary {
            left,
            op: BinOp::Mul,
            right,
        } => {
            let constant_factor_excludes_min = |factor: i64| {
                factor == 0 || factor == -1 || !factor.unsigned_abs().is_power_of_two()
            };
            let equivalent_square = same_pure_i64_expression(left, right, signatures);
            equivalent_square
                || constant_i64(left).is_some_and(constant_factor_excludes_min)
                || constant_i64(right).is_some_and(constant_factor_excludes_min)
        }
        ExprKind::Binary {
            left,
            op: BinOp::Div,
            right,
        } => {
            same_pure_i64_expression(left, right, signatures)
                || constant_i64(right).is_some_and(|divisor| divisor != 0 && divisor != 1)
        }
        _ => false,
    }
}

fn checked_i64_identity_c(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    left_code: &str,
    right_code: &str,
    signatures: &Signatures,
) -> Option<String> {
    if let Some(code) = checked_i64_inverse_c(op, left, right, left_code, right_code, signatures) {
        return Some(code);
    }

    match checked_i64_reduction(op, left, right, signatures)? {
        CheckedI64Reduction::Left => Some(left_code.to_string()),
        CheckedI64Reduction::Right => Some(right_code.to_string()),
        CheckedI64Reduction::Zero => Some("INT64_C(0)".to_string()),
        CheckedI64Reduction::ZeroAfterLeft => Some(format!("((void)({left_code}), INT64_C(0))")),
        CheckedI64Reduction::ZeroAfterRight => Some(format!("((void)({right_code}), INT64_C(0))")),
        CheckedI64Reduction::NegateLeft if i64_expr_result_excludes_min(left, signatures) => {
            Some(format!("(-({left_code}))"))
        }
        CheckedI64Reduction::NegateRight if i64_expr_result_excludes_min(right, signatures) => {
            Some(format!("(-({right_code}))"))
        }
        CheckedI64Reduction::NegateLeft => Some(format!("flux_neg_i64({left_code})")),
        CheckedI64Reduction::NegateRight => Some(format!("flux_neg_i64({right_code})")),
        CheckedI64Reduction::DoubleAfterLeft => Some(format!(
            "__extension__ ({{ int64_t flux__checked_reuse = {left_code}; flux_add_i64(flux__checked_reuse, flux__checked_reuse); }})"
        )),
        CheckedI64Reduction::SquareAfterLeft => Some(format!(
            "__extension__ ({{ int64_t flux__checked_reuse = {left_code}; flux_mul_i64(flux__checked_reuse, flux__checked_reuse); }})"
        )),
        CheckedI64Reduction::SelfDivide => Some(format!("flux_div_self_i64({left_code})")),
        CheckedI64Reduction::DivideByConstant(divisor) => {
            Some(format!("(({left_code}) / INT64_C({divisor}))"))
        }
    }
}

fn checked_i64_inverse_c(
    op: BinOp,
    left: &Expr,
    right: &Expr,
    left_code: &str,
    right_code: &str,
    signatures: &Signatures,
) -> Option<String> {
    let same_binding = |left: &Expr, right: &Expr| {
        matches!(
            (&left.kind, &right.kind),
            (ExprKind::Var(left_name), ExprKind::Var(right_name)) if left_name == right_name
        )
    };
    let opposite_signed_binding = |left: &Expr, right: &Expr| match (&left.kind, &right.kind) {
        (
            ExprKind::Var(left_name),
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: right_inner,
            },
        ) => matches!(&right_inner.kind, ExprKind::Var(right_name) if left_name == right_name),
        (
            ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: left_inner,
            },
            ExprKind::Var(right_name),
        ) => matches!(&left_inner.kind, ExprKind::Var(left_name) if left_name == right_name),
        _ => false,
    };

    match op {
        BinOp::Sub => {
            if let ExprKind::Binary {
                left: inner_left,
                op: BinOp::Add,
                right: inner_right,
            } = &left.kind
                && (same_binding(inner_left, right) || same_binding(inner_right, right))
            {
                return Some(format!("(({left_code}) - ({right_code}))"));
            }
            if let ExprKind::Binary {
                left: _,
                op: BinOp::Sub,
                right: inner_right,
            } = &left.kind
                && opposite_signed_binding(inner_right, right)
            {
                return Some(format!("(({left_code}) - ({right_code}))"));
            }
            if let ExprKind::Binary {
                left: inner_left,
                op: BinOp::Sub,
                ..
            } = &right.kind
                && same_binding(left, inner_left)
            {
                return Some(format!("(({left_code}) - ({right_code}))"));
            }
        }
        BinOp::Add => {
            if let ExprKind::Binary {
                op: BinOp::Sub,
                right: inner_right,
                ..
            } = &left.kind
                && same_binding(inner_right, right)
            {
                return Some(format!("(({left_code}) + ({right_code}))"));
            }
            if let ExprKind::Binary {
                op: BinOp::Sub,
                right: inner_right,
                ..
            } = &right.kind
                && same_binding(left, inner_right)
            {
                return Some(format!("(({left_code}) + ({right_code}))"));
            }
            if let ExprKind::Binary {
                left: inner_left,
                op: BinOp::Add,
                right: inner_right,
            } = &left.kind
                && (opposite_signed_binding(inner_left, right)
                    || opposite_signed_binding(inner_right, right))
            {
                return Some(format!("(({left_code}) + ({right_code}))"));
            }
            if let ExprKind::Binary {
                left: inner_left,
                op: BinOp::Add,
                right: inner_right,
            } = &right.kind
                && (opposite_signed_binding(left, inner_left)
                    || opposite_signed_binding(left, inner_right))
            {
                return Some(format!("(({left_code}) + ({right_code}))"));
            }
        }
        _ => {}
    }

    let constant_i64 = |expr: &Expr| match typecheck::constant_primitive_value(expr, signatures) {
        Some(ConstantValue::I64(value)) if value != 0 => Some(value),
        _ => None,
    };
    let constants_cancel =
        |expr: &Expr, outer: i64| constant_i64(expr).and_then(i64::checked_neg) == Some(outer);
    let additive_shift = |expr: &Expr| match &expr.kind {
        ExprKind::Binary {
            left,
            op: BinOp::Add,
            right,
        } => match (constant_i64(left), constant_i64(right)) {
            (Some(shift), None) | (None, Some(shift)) => Some(shift),
            _ => None,
        },
        ExprKind::Binary {
            op: BinOp::Sub,
            right,
            ..
        } => constant_i64(right).and_then(i64::checked_neg),
        _ => None,
    };
    let additive_shift_composition_is_safe = |inner: &Expr, outer_shift: i64| {
        additive_shift(inner).is_some_and(|inner_shift| {
            ((inner_shift > 0 && outer_shift < 0) || (inner_shift < 0 && outer_shift > 0))
                && outer_shift.unsigned_abs() <= inner_shift.unsigned_abs()
        })
    };

    match op {
        BinOp::Sub => {
            if let Some(outer) = constant_i64(right)
                && let Some(outer_shift) = outer.checked_neg()
                && additive_shift_composition_is_safe(left, outer_shift)
            {
                return Some(format!("(({left_code}) - ({right_code}))"));
            }

            if let Some(outer) = constant_i64(right) {
                match &left.kind {
                    ExprKind::Binary {
                        left: inner_left,
                        op: BinOp::Add,
                        right: inner_right,
                    } if constant_i64(inner_left) == Some(outer)
                        || constant_i64(inner_right) == Some(outer) =>
                    {
                        return Some(format!("(({left_code}) - ({right_code}))"));
                    }
                    ExprKind::Binary {
                        op: BinOp::Sub,
                        right: inner_right,
                        ..
                    } if constants_cancel(inner_right, outer) => {
                        return Some(format!("(({left_code}) - ({right_code}))"));
                    }
                    _ => {}
                }
            }

            if let Some(outer) = constant_i64(left)
                && let ExprKind::Binary {
                    left: inner_left,
                    op: BinOp::Sub,
                    ..
                } = &right.kind
                && constant_i64(inner_left) == Some(outer)
            {
                return Some(format!("(({left_code}) - ({right_code}))"));
            }
            None
        }
        BinOp::Add => {
            if let Some(outer) = constant_i64(right)
                && additive_shift_composition_is_safe(left, outer)
            {
                return Some(format!("(({left_code}) + ({right_code}))"));
            }
            if let Some(outer) = constant_i64(left)
                && additive_shift_composition_is_safe(right, outer)
            {
                return Some(format!("(({left_code}) + ({right_code}))"));
            }

            if let Some(outer) = constant_i64(right) {
                match &left.kind {
                    ExprKind::Binary {
                        op: BinOp::Sub,
                        right: inner_right,
                        ..
                    } if constant_i64(inner_right) == Some(outer) => {
                        return Some(format!("(({left_code}) + ({right_code}))"));
                    }
                    ExprKind::Binary {
                        left: inner_left,
                        op: BinOp::Add,
                        right: inner_right,
                    } if constants_cancel(inner_left, outer)
                        || constants_cancel(inner_right, outer) =>
                    {
                        return Some(format!("(({left_code}) + ({right_code}))"));
                    }
                    _ => {}
                }
            }

            if let Some(outer) = constant_i64(left) {
                match &right.kind {
                    ExprKind::Binary {
                        op: BinOp::Sub,
                        right: inner_right,
                        ..
                    } if constant_i64(inner_right) == Some(outer) => {
                        return Some(format!("(({left_code}) + ({right_code}))"));
                    }
                    ExprKind::Binary {
                        left: inner_left,
                        op: BinOp::Add,
                        right: inner_right,
                    } if constants_cancel(inner_left, outer)
                        || constants_cancel(inner_right, outer) =>
                    {
                        return Some(format!("(({left_code}) + ({right_code}))"));
                    }
                    _ => {}
                }
            }
            None
        }
        BinOp::Mul => {
            if let ExprKind::Binary {
                op: BinOp::Div,
                right: inner_right,
                ..
            } = &left.kind
                && same_binding(inner_right, right)
            {
                return Some(format!("(({left_code}) * ({right_code}))"));
            }

            if let ExprKind::Binary {
                op: BinOp::Div,
                right: inner_right,
                ..
            } = &right.kind
                && same_binding(inner_right, left)
            {
                return Some(format!("(({left_code}) * ({right_code}))"));
            }

            if let Some(outer) = constant_i64(right) {
                if let ExprKind::Binary {
                    op: BinOp::Div,
                    right: inner_right,
                    ..
                } = &left.kind
                {
                    if constant_i64(inner_right) == Some(outer) {
                        return Some(format!("(({left_code}) * ({right_code}))"));
                    }
                }
            }

            if let Some(outer) = constant_i64(left) {
                if let ExprKind::Binary {
                    op: BinOp::Div,
                    right: inner_right,
                    ..
                } = &right.kind
                {
                    if constant_i64(inner_right) == Some(outer) {
                        return Some(format!("(({left_code}) * ({right_code}))"));
                    }
                }
            }
            None
        }
        BinOp::Div => {
            let ExprKind::Binary {
                left: inner_left,
                op: BinOp::Mul,
                right: inner_right,
            } = &left.kind
            else {
                return None;
            };

            if same_binding(inner_left, right) || same_binding(inner_right, right) {
                return Some(format!("flux_div_nonzero_i64({left_code}, {right_code})"));
            }

            let outer = constant_i64(right)?;
            if constant_i64(inner_left) == Some(outer) || constant_i64(inner_right) == Some(outer) {
                Some(format!("(({left_code}) / ({right_code}))"))
            } else {
                None
            }
        }
        _ => None,
    }
}

fn dead_store_rhs_is_discardable(
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
) -> bool {
    if typecheck::constant_primitive_value(expr, signatures).is_some()
        || matches!(expr.kind, ExprKind::Nil | ExprKind::Var(_))
    {
        return true;
    }

    match &expr.kind {
        ExprKind::AnonymousFunction { .. } => true,
        ExprKind::List(items) => items
            .iter()
            .all(|item| dead_store_rhs_is_discardable(item, env, signatures)),
        ExprKind::StructLiteral { base, fields, .. } => {
            base.as_deref()
                .is_none_or(|base| dead_store_rhs_is_discardable(base, env, signatures))
                && fields
                    .iter()
                    .all(|field| dead_store_rhs_is_discardable(&field.value, env, signatures))
        }
        ExprKind::Field { base, name, .. }
            if dead_store_rhs_is_discardable(base, env, signatures) =>
        {
            match type_of_expr(base, env, signatures)
                .ok()
                .map(|ty| signatures.canonical_type(&ty))
            {
                Some(Type::Named(_)) => true,
                Some(Type::List(_)) => {
                    let static_len = static_list_length(base, env, signatures).ok().flatten();
                    match crate::builtin_names::list_member_impl(name) {
                        "length" | "isEmpty" | "isNotEmpty" => true,
                        "first" | "last" => static_len.is_some_and(|len| len > 0),
                        "single" => static_len == Some(1),
                        _ => false,
                    }
                }
                _ => false,
            }
        }
        ExprKind::Index {
            base,
            index,
            optional,
        } => {
            !*optional
                && dead_store_rhs_is_discardable(base, env, signatures)
                && dead_store_rhs_is_discardable(index, env, signatures)
                && resolved_static_list_index(base, index, env, signatures)
                    .ok()
                    .flatten()
                    .is_some()
        }
        ExprKind::Conditional {
            then_expr,
            cond,
            else_expr,
        } => {
            dead_store_rhs_is_discardable(cond, env, signatures)
                && dead_store_rhs_is_discardable(then_expr, env, signatures)
                && dead_store_rhs_is_discardable(else_expr, env, signatures)
        }
        ExprKind::Unary {
            op: UnaryOp::Not,
            expr,
        } => dead_store_rhs_is_discardable(expr, env, signatures),
        ExprKind::Unary {
            op: UnaryOp::Neg,
            expr,
        } => {
            dead_store_rhs_is_discardable(expr, env, signatures)
                && i64_expr_result_excludes_min(expr, signatures)
        }
        ExprKind::Binary { left, op, right }
            if matches!(op, BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div) =>
        {
            if matches!(op, BinOp::Sub)
                && same_pure_i64_expression(left, right, signatures)
                && dead_store_rhs_is_discardable(left, env, signatures)
                && dead_store_rhs_is_discardable(right, env, signatures)
            {
                return true;
            }
            match checked_i64_reduction(*op, left, right, signatures) {
                Some(CheckedI64Reduction::Zero) => true,
                Some(
                    CheckedI64Reduction::Left
                    | CheckedI64Reduction::ZeroAfterLeft
                    | CheckedI64Reduction::DivideByConstant(_),
                ) => dead_store_rhs_is_discardable(left, env, signatures),
                Some(CheckedI64Reduction::Right | CheckedI64Reduction::ZeroAfterRight) => {
                    dead_store_rhs_is_discardable(right, env, signatures)
                }
                Some(CheckedI64Reduction::NegateLeft) => {
                    dead_store_rhs_is_discardable(left, env, signatures)
                        && i64_expr_result_excludes_min(left, signatures)
                }
                Some(CheckedI64Reduction::NegateRight) => {
                    dead_store_rhs_is_discardable(right, env, signatures)
                        && i64_expr_result_excludes_min(right, signatures)
                }
                Some(
                    CheckedI64Reduction::DoubleAfterLeft
                    | CheckedI64Reduction::SquareAfterLeft
                    | CheckedI64Reduction::SelfDivide,
                )
                | None => false,
            }
        }
        ExprKind::Binary { left, op, right }
            if matches!(
                op,
                BinOp::Eq
                    | BinOp::Ne
                    | BinOp::Lt
                    | BinOp::Le
                    | BinOp::Gt
                    | BinOp::Ge
                    | BinOp::And
                    | BinOp::Or
            ) =>
        {
            dead_store_rhs_is_discardable(left, env, signatures)
                && dead_store_rhs_is_discardable(right, env, signatures)
        }
        _ => false,
    }
}

fn optional_presence_promotion(
    cond: &Expr,
    env: &HashMap<String, Type>,
    mutable: &HashSet<String>,
    signatures: &Signatures,
) -> Option<(String, Type, bool)> {
    let ExprKind::Binary { left, op, right } = &cond.kind else {
        return None;
    };
    if !matches!(op, BinOp::Eq | BinOp::Ne) {
        return None;
    }
    let name = match (&left.kind, &right.kind) {
        (ExprKind::Var(name), ExprKind::None) | (ExprKind::None, ExprKind::Var(name)) => name,
        _ => return None,
    };
    if mutable.contains(name) {
        return None;
    }
    let Type::Optional(inner) = signatures.canonical_type(env.get(name)?) else {
        return None;
    };
    if *inner == Type::Void {
        return None;
    }
    Some((
        name.clone(),
        signatures.canonical_type(&inner),
        matches!(op, BinOp::Ne),
    ))
}

fn collect_mutable_struct_pattern_names(
    fields: &[StructPatternField],
    mutable: &mut HashSet<String>,
) {
    for field in fields {
        if field.binding.name != "_" {
            mutable.insert(field.binding.name.clone());
        }
        if let Some(nested) = &field.nested {
            collect_mutable_struct_pattern_names(&nested.fields, mutable);
        }
    }
}

fn record_mutable_declaration(stmt: &Stmt, mutable: &mut HashSet<String>) {
    match &stmt.kind {
        StmtKind::Var { name, .. } => {
            mutable.insert(name.clone());
        }
        StmtKind::LetDestructure {
            bindings,
            mutable: true,
            ..
        } => {
            mutable.extend(bindings.iter().map(|binding| binding.name.clone()));
        }
        StmtKind::LetMultiDestructure {
            bindings,
            mutable: true,
            ..
        }
        | StmtKind::LetListDestructure {
            bindings,
            mutable: true,
            ..
        } => {
            mutable.extend(
                bindings
                    .iter()
                    .filter(|binding| binding.name != "_")
                    .map(|binding| binding.name.clone()),
            );
            if let StmtKind::LetListDestructure {
                rest: Some(rest), ..
            } = &stmt.kind
                && rest.binding.name != "_"
            {
                mutable.insert(rest.binding.name.clone());
            }
        }
        StmtKind::LetStructDestructure {
            fields,
            mutable: true,
            ..
        } => collect_mutable_struct_pattern_names(fields, mutable),
        _ => {}
    }
}

fn emit_block(
    out: &mut String,
    body: &[Stmt],
    depth: usize,
    env: &mut HashMap<String, Type>,
    mutable: &mut HashSet<String>,
    signatures: &Signatures,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    for stmt in body {
        record_mutable_declaration(stmt, mutable);
        if !context
            .reachable_spans
            .contains(&source_span_key(stmt.span))
        {
            continue;
        }
        if let StmtKind::Assign { name, expr, .. } = &stmt.kind
            && context
                .dead_assignment_spans
                .contains(&source_span_key(stmt.span))
        {
            if dead_store_rhs_is_discardable(expr, env, signatures) {
                continue;
            }
            if !expr_contains_await(expr)
                && !matches!(
                    expr.kind,
                    ExprKind::Match { .. } | ExprKind::ListMatch { .. }
                )
            {
                emit_source_line(out, stmt.span, context.source_paths);
                let pad = "    ".repeat(depth);
                let expected = env.get(name).ok_or_else(|| {
                    diag(
                        expr.span,
                        "assignment target missing from code generation environment",
                    )
                })?;
                let value = emit_expr_for_expected_with_cfg_proofs(
                    expr,
                    expected,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}(void)({value});\n"));
                continue;
            }
        }
        if let StmtKind::Let { ty, expr, .. } = &stmt.kind
            && context
                .dead_let_binding_spans
                .contains(&source_span_key(stmt.span))
            && (signatures.is_copy_type(ty)
                || context
                    .dead_non_escaping_let_binding_spans
                    .contains(&source_span_key(stmt.span)))
        {
            if dead_store_rhs_is_discardable(expr, env, signatures) {
                continue;
            }
            if !expr_contains_await(expr)
                && !matches!(
                    expr.kind,
                    ExprKind::Match { .. } | ExprKind::ListMatch { .. }
                )
            {
                emit_source_line(out, stmt.span, context.source_paths);
                let pad = "    ".repeat(depth);
                let value = emit_expr_for_expected_with_cfg_proofs(
                    expr,
                    ty,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}(void)({value});\n"));
                continue;
            }
        }
        if matches!(stmt.kind, StmtKind::Expr(_))
            && context
                .dead_expression_spans
                .contains(&source_span_key(stmt.span))
        {
            continue;
        }
        emit_source_line(out, stmt.span, context.source_paths);
        let pad = "    ".repeat(depth);
        let dead_definitions = context
            .dead_definition_names
            .get(&source_span_key(stmt.span));
        let sequence_lowering = match &stmt.kind {
            StmtKind::Let { expr, .. } | StmtKind::Var { expr, .. } => {
                sequence_lowering_kind(expr, env, signatures, context.cfg_rewrite_facts)
            }
            _ => None,
        };
        match &stmt.kind {
            StmtKind::Var { name, ty, expr, .. }
                if !context.async_state_machine
                    && context
                        .dead_var_initializer_spans
                        .contains(&source_span_key(stmt.span))
                    && dead_store_rhs_is_discardable(expr, env, signatures) =>
            {
                out.push_str(&format!(
                    "{pad}{} {};\n",
                    c_type(ty, signatures),
                    local_c_name(name)
                ));
                env.insert(name.clone(), signatures.canonical_type(ty));
            }
            StmtKind::Let { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Chunked) =>
            {
                emit_sequence_chunked_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Sorted) =>
            {
                emit_sequence_sorted_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Flatten) =>
            {
                emit_sequence_flatten_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Distinct) =>
            {
                emit_sequence_distinct_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Concat) =>
            {
                emit_sequence_concat_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Transform) =>
            {
                emit_sequence_transform_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. } | StmtKind::Var { name, ty, expr, .. }
                if sequence_lowering == Some(SequenceLoweringKind::Reduction) =>
            {
                emit_sequence_reduction_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if list_literal_needs_builder(expr, context.cfg_rewrite_facts) =>
            {
                emit_list_builder_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. }
                if list_binding_is_comprehension(expr, context.cfg_rewrite_facts) =>
            {
                emit_list_comprehension_binding(
                    out,
                    &pad,
                    (name, ty),
                    expr,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                    temp_counter,
                )?;
            }
            StmtKind::Let { name, ty, expr, .. } | StmtKind::Var { name, ty, expr, .. }
                if match_expr_needs_specialized_lowering(
                    expr,
                    env,
                    signatures,
                    context.cfg_rewrite_facts,
                ) =>
            {
                let target = local_c_name(name);
                out.push_str(&format!("{pad}{} {target};\n", c_type(ty, signatures)));
                emit_match_expr_into(
                    out,
                    expr,
                    &target,
                    depth,
                    env,
                    signatures,
                    temp_counter,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                env.insert(name.clone(), signatures.canonical_type(ty));
            }
            StmtKind::Let { name, ty, expr, .. } | StmtKind::Var { name, ty, expr, .. } => {
                let value = emit_expr_for_expected_with_cfg_proofs(
                    expr,
                    ty,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!(
                    "{pad}{} {} = {};\n",
                    c_type(ty, signatures),
                    local_c_name(name),
                    value
                ));
                env.insert(name.clone(), signatures.canonical_type(ty));
            }
            StmtKind::Assign { name, expr, .. } => {
                let expected = env.get(name).ok_or_else(|| {
                    diag(
                        expr.span,
                        "assignment target missing from code generation environment",
                    )
                })?;
                let value = emit_expr_for_expected_with_cfg_proofs(
                    expr,
                    expected,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}{} = {};\n", local_c_name(name), value));
            }
            StmtKind::AssignMultiDestructure { bindings, expr } => {
                let (_, record_destructure) =
                    typecheck::positional_destructure_types_of_expr(expr, env, signatures)?;
                if record_destructure {
                    let expr_type = type_of_expr(expr, env, signatures)?;
                    let value = EmittedExpr {
                        code: emit_expr_for_expected_with_cfg_proofs(
                            expr,
                            &expr_type,
                            env,
                            signatures,
                            context.checked_i64_cfg_proofs,
                            context.cfg_rewrite_facts,
                        )?,
                        ty: expr_type,
                    };
                    let Type::Record(fields) = signatures.canonical_type(&value.ty) else {
                        return Err(diag(
                            stmt.span,
                            "record assignment pattern changed type after type checking",
                        ));
                    };
                    let record_ty = Type::Record(fields.clone());
                    let temp = format!("flux__record_assign_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!(
                        "{pad}{} {temp} = {};\n",
                        c_type(&record_ty, signatures),
                        value.code
                    ));
                    for (index, (binding, field)) in bindings.iter().zip(&fields).enumerate() {
                        if binding.name == "_"
                            || dead_definitions.is_some_and(|dead| dead.contains(&binding.name))
                        {
                            continue;
                        }
                        out.push_str(&format!(
                            "{pad}{} = {temp}.{};\n",
                            local_c_name(&binding.name),
                            record_field_c_name(field.name.as_deref(), index)
                        ));
                    }
                } else {
                    let (value, tag, actuals) =
                        emit_multi_expr(expr, env, signatures, context.cfg_rewrite_facts)?;
                    let temp = format!("flux__multi_assign_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!("{pad}struct {tag} {temp} = {value};\n"));
                    for (index, binding) in bindings.iter().enumerate() {
                        if binding.name == "_"
                            || dead_definitions.is_some_and(|dead| dead.contains(&binding.name))
                        {
                            continue;
                        }
                        actuals.get(index).ok_or_else(|| {
                            diag(
                                stmt.span,
                                "multi-value assignment arity changed after type checking",
                            )
                        })?;
                        out.push_str(&format!(
                            "{pad}{} = {temp}.v{index};\n",
                            local_c_name(&binding.name)
                        ));
                    }
                }
            }
            StmtKind::AssignListDestructure {
                bindings,
                rest,
                expr,
            } => {
                let expr_type = type_of_expr(expr, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        expr,
                        &expr_type,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: expr_type,
                };
                let Type::List(element) = &value.ty else {
                    return Err(diag(
                        stmt.span,
                        "list assignment code generation requires a list value",
                    ));
                };
                let temp = format!("flux__list_assign_{}", *temp_counter);
                *temp_counter += 1;
                let element_c = c_type(element, signatures);
                out.push_str(&format!(
                    "{pad}struct flux__list {temp} = {};\n",
                    value.code
                ));
                if rest.is_some() {
                    out.push_str(&format!(
                        "{pad}if ({temp}.len < {}) {{ fputs(\"Flux runtime error: list pattern requires at least {} elements\\n\", stderr); abort(); }}\n",
                        bindings.len(),
                        bindings.len()
                    ));
                } else {
                    out.push_str(&format!(
                        "{pad}if ({temp}.len != {}) {{ fputs(\"Flux runtime error: list pattern requires exactly {} elements\\n\", stderr); abort(); }}\n",
                        bindings.len(),
                        bindings.len()
                    ));
                }
                for (index, binding) in bindings.iter().enumerate() {
                    if binding.name == "_"
                        || dead_definitions.is_some_and(|dead| dead.contains(&binding.name))
                    {
                        continue;
                    }
                    let index_code = if let Some(rest) = rest {
                        if index < rest.index {
                            index.to_string()
                        } else {
                            format!("{temp}.len - {}", bindings.len() - index)
                        }
                    } else {
                        index.to_string()
                    };
                    out.push_str(&format!(
                        "{pad}{} = *(({element_c} *)flux_list_at_unchecked({temp}, {index_code}, sizeof({element_c})));\n",
                        local_c_name(&binding.name)
                    ));
                }
                if let Some(rest) = rest
                    && rest.binding.name != "_"
                    && !dead_definitions.is_some_and(|dead| dead.contains(&rest.binding.name))
                {
                    let rest_temp = format!("flux__list_assign_rest_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!(
                        "{pad}struct flux__list {rest_temp} = {{ .data = {temp}.data, .len = {temp}.len - {}, .stride = flux_list_stride({temp}, sizeof({element_c})) }};\n",
                        bindings.len()
                    ));
                    out.push_str(&format!(
                        "{pad}if ({rest_temp}.len != 0) {{ {rest_temp}.data = flux_list_at_unchecked({temp}, {}, sizeof({element_c})); }}\n",
                        rest.index
                    ));
                    out.push_str(&format!(
                        "{pad}{} = {rest_temp};\n",
                        local_c_name(&rest.binding.name)
                    ));
                }
            }
            StmtKind::AssignStructDestructure { fields, expr, .. } => {
                let expr_type = type_of_expr(expr, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        expr,
                        &expr_type,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: expr_type,
                };
                let Type::Named(struct_name) = &value.ty else {
                    return Err(diag(
                        stmt.span,
                        "struct assignment code generation requires a struct value",
                    ));
                };
                let temp = format!("flux__struct_assign_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}{} {temp} = {};\n",
                    c_type(&value.ty, signatures),
                    value.code
                ));
                emit_struct_pattern_assignments(
                    out,
                    &pad,
                    fields,
                    struct_name,
                    &temp,
                    signatures,
                    dead_definitions,
                )?;
            }
            StmtKind::LetDestructure {
                bindings,
                expr,
                else_return,
                ..
            } => {
                let (value, tag, _) =
                    emit_multi_expr(expr, env, signatures, context.cfg_rewrite_facts)?;
                let temp = format!("flux__multi_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!("{pad}struct {tag} {temp} = {value};\n"));
                if *else_return {
                    let error_index = bindings.len() - 1;
                    let return_tag = multi_return_struct_name(&context.current_function.name);
                    let return_temp = format!("flux__return_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!("{pad}if ({temp}.v{error_index} != NULL) {{\n"));
                    out.push_str(&format!("{pad}    struct {return_tag} {return_temp};\n"));
                    for index in 0..bindings.len() {
                        out.push_str(&format!(
                            "{pad}    {return_temp}.v{index} = {temp}.v{index};\n"
                        ));
                    }
                    if context.async_state_machine {
                        out.push_str(&format!(
                            "{pad}    flux__task->result = {return_temp};\n{pad}    {}(flux__task);\n{pad}    return;\n",
                            async_finish_c_name(&context.current_function.name)
                        ));
                    } else {
                        out.push_str(&format!("{pad}    return {return_temp};\n"));
                    }
                    out.push_str(&format!("{pad}}}\n"));
                }
                for (index, binding) in bindings.iter().enumerate() {
                    if dead_definitions.is_some_and(|dead| dead.contains(&binding.name)) {
                        continue;
                    }
                    out.push_str(&format!(
                        "{pad}{} {} = {temp}.v{index};\n",
                        c_type(&binding.ty, signatures),
                        local_c_name(&binding.name)
                    ));
                    env.insert(binding.name.clone(), signatures.canonical_type(&binding.ty));
                }
            }
            StmtKind::LetMultiDestructure {
                bindings,
                expr,
                else_return,
                mutable,
            } => {
                let (_, record_destructure) =
                    typecheck::positional_destructure_types_of_expr(expr, env, signatures)?;
                if record_destructure {
                    let expr_type = type_of_expr(expr, env, signatures)?;
                    let value = EmittedExpr {
                        code: emit_expr_for_expected_with_cfg_proofs(
                            expr,
                            &expr_type,
                            env,
                            signatures,
                            context.checked_i64_cfg_proofs,
                            context.cfg_rewrite_facts,
                        )?,
                        ty: expr_type,
                    };
                    let Type::Record(fields) = signatures.canonical_type(&value.ty) else {
                        return Err(diag(
                            stmt.span,
                            "record pattern changed type after type checking",
                        ));
                    };
                    let record_ty = Type::Record(fields.clone());
                    let temp = format!("flux__record_pattern_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!(
                        "{pad}{} {temp} = {};\n",
                        c_type(&record_ty, signatures),
                        value.code
                    ));
                    for (index, (binding, field)) in bindings.iter().zip(&fields).enumerate() {
                        if binding.name == "_" {
                            continue;
                        }
                        let ty = signatures.canonical_type(&field.ty);
                        if dead_definitions.is_some_and(|dead| dead.contains(&binding.name)) {
                            if *mutable {
                                out.push_str(&format!(
                                    "{pad}{} {};\n",
                                    c_type(&ty, signatures),
                                    local_c_name(&binding.name)
                                ));
                                env.insert(binding.name.clone(), ty);
                            }
                            continue;
                        }
                        out.push_str(&format!(
                            "{pad}{} {} = {temp}.{};\n",
                            c_type(&ty, signatures),
                            local_c_name(&binding.name),
                            record_field_c_name(field.name.as_deref(), index)
                        ));
                        env.insert(binding.name.clone(), ty);
                    }
                } else {
                    let (value, tag, actuals) =
                        emit_multi_expr(expr, env, signatures, context.cfg_rewrite_facts)?;
                    let temp = format!("flux__multi_pattern_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!("{pad}struct {tag} {temp} = {value};\n"));
                    if *else_return {
                        let error_index = bindings.len() - 1;
                        let return_tag = multi_return_struct_name(&context.current_function.name);
                        let return_temp = format!("flux__return_{}", *temp_counter);
                        *temp_counter += 1;
                        out.push_str(&format!("{pad}if ({temp}.v{error_index} != NULL) {{\n"));
                        out.push_str(&format!("{pad}    struct {return_tag} {return_temp};\n"));
                        for index in 0..bindings.len() {
                            out.push_str(&format!(
                                "{pad}    {return_temp}.v{index} = {temp}.v{index};\n"
                            ));
                        }
                        if context.async_state_machine {
                            out.push_str(&format!(
                                "{pad}    flux__task->result = {return_temp};\n{pad}    {}(flux__task);\n{pad}    return;\n",
                                async_finish_c_name(&context.current_function.name)
                            ));
                        } else {
                            out.push_str(&format!("{pad}    return {return_temp};\n"));
                        }
                        out.push_str(&format!("{pad}}}\n"));
                    }
                    for (index, binding) in bindings.iter().enumerate() {
                        if binding.name == "_"
                            || dead_definitions.is_some_and(|dead| dead.contains(&binding.name))
                        {
                            continue;
                        }
                        let ty = actuals.get(index).ok_or_else(|| {
                            diag(
                                stmt.span,
                                "multi-value pattern arity changed after type checking",
                            )
                        })?;
                        out.push_str(&format!(
                            "{pad}{} {} = {temp}.v{index};\n",
                            c_type(ty, signatures),
                            local_c_name(&binding.name)
                        ));
                        env.insert(binding.name.clone(), signatures.canonical_type(ty));
                    }
                }
            }
            StmtKind::LetListDestructure {
                bindings,
                rest,
                expr,
                ..
            } => {
                let expr_type = type_of_expr(expr, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        expr,
                        &expr_type,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: expr_type,
                };
                let Type::List(element) = &value.ty else {
                    return Err(diag(
                        stmt.span,
                        "list destructuring code generation requires a list value",
                    ));
                };
                let temp = format!("flux__list_pattern_{}", *temp_counter);
                *temp_counter += 1;
                let element_c = c_type(element, signatures);
                out.push_str(&format!(
                    "{pad}struct flux__list {temp} = {};\n",
                    value.code
                ));
                if rest.is_some() {
                    out.push_str(&format!(
                        "{pad}if ({temp}.len < {}) {{ fputs(\"Flux runtime error: list pattern requires at least {} elements\\n\", stderr); abort(); }}\n",
                        bindings.len(),
                        bindings.len()
                    ));
                } else {
                    out.push_str(&format!(
                        "{pad}if ({temp}.len != {}) {{ fputs(\"Flux runtime error: list pattern requires exactly {} elements\\n\", stderr); abort(); }}\n",
                        bindings.len(),
                        bindings.len()
                    ));
                }
                for (index, binding) in bindings.iter().enumerate() {
                    if binding.name == "_"
                        || dead_definitions.is_some_and(|dead| dead.contains(&binding.name))
                    {
                        continue;
                    }
                    let index_code = if let Some(rest) = rest {
                        if index < rest.index {
                            index.to_string()
                        } else {
                            format!("{temp}.len - {}", bindings.len() - index)
                        }
                    } else {
                        index.to_string()
                    };
                    out.push_str(&format!(
                        "{pad}{element_c} {} = *(({element_c} *)flux_list_at_unchecked({temp}, {index_code}, sizeof({element_c})));\n",
                        local_c_name(&binding.name)
                    ));
                    env.insert(binding.name.clone(), (**element).clone());
                }
                if let Some(rest) = rest
                    && rest.binding.name != "_"
                    && !dead_definitions.is_some_and(|dead| dead.contains(&rest.binding.name))
                {
                    let rest_name = local_c_name(&rest.binding.name);
                    out.push_str(&format!(
                        "{pad}struct flux__list {rest_name} = {{ .data = {temp}.data, .len = {temp}.len - {}, .stride = flux_list_stride({temp}, sizeof({element_c})) }};\n",
                        bindings.len()
                    ));
                    out.push_str(&format!(
                        "{pad}if ({rest_name}.len != 0) {{ {rest_name}.data = flux_list_at_unchecked({temp}, {}, sizeof({element_c})); }}\n",
                        rest.index
                    ));
                    env.insert(
                        rest.binding.name.clone(),
                        Type::List(Box::new((**element).clone())),
                    );
                }
            }
            StmtKind::LetStructDestructure { fields, expr, .. } => {
                let expr_type = type_of_expr(expr, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        expr,
                        &expr_type,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: expr_type,
                };
                let Type::Named(struct_name) = &value.ty else {
                    return Err(diag(
                        stmt.span,
                        "struct destructuring code generation requires a struct value",
                    ));
                };
                if signatures.struct_type(struct_name).is_none() {
                    return Err(diag(
                        stmt.span,
                        "struct destructuring code generation requires a struct value",
                    ));
                }
                let temp = format!("flux__destructure_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}{} {temp} = {};\n",
                    c_type(&value.ty, signatures),
                    value.code
                ));
                emit_struct_pattern_bindings(
                    out,
                    &pad,
                    fields,
                    struct_name,
                    &temp,
                    &mut PatternBindingEmitContext {
                        env,
                        signatures,
                        dead_definitions,
                    },
                )?;
            }
            StmtKind::Return(values) if values.is_empty() => {
                if context.async_state_machine {
                    out.push_str(&format!(
                        "{pad}{}(flux__task);\n{pad}return;\n",
                        async_finish_c_name(&context.current_function.name)
                    ));
                } else {
                    out.push_str(&format!("{pad}return;\n"));
                }
            }
            StmtKind::Return(values)
                if values.len() == 1 && context.current_function.returns.len() > 1 =>
            {
                let (value, source_tag, _) =
                    emit_multi_expr(&values[0], env, signatures, context.cfg_rewrite_facts)?;
                let source_temp = format!("flux__forward_{}", *temp_counter);
                *temp_counter += 1;
                let return_tag = multi_return_struct_name(&context.current_function.name);
                let return_temp = format!("flux__return_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}struct {source_tag} {source_temp} = {value};\n"
                ));
                out.push_str(&format!("{pad}struct {return_tag} {return_temp};\n"));
                for index in 0..context.current_function.returns.len() {
                    out.push_str(&format!(
                        "{pad}{return_temp}.v{index} = {source_temp}.v{index};\n"
                    ));
                }
                if context.async_state_machine {
                    out.push_str(&format!(
                        "{pad}flux__task->result = {return_temp};\n{pad}{}(flux__task);\n{pad}return;\n",
                        async_finish_c_name(&context.current_function.name)
                    ));
                } else {
                    out.push_str(&format!("{pad}return {return_temp};\n"));
                }
            }
            StmtKind::Return(values)
                if values.len() == 1
                    && match_expr_needs_specialized_lowering(
                        &values[0],
                        env,
                        signatures,
                        context.cfg_rewrite_facts,
                    ) =>
            {
                let result_ty = type_of_expr(&values[0], env, signatures)?;
                let target = format!("flux__match_result_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}{} {target};\n",
                    c_type(&result_ty, signatures)
                ));
                emit_match_expr_into(
                    out,
                    &values[0],
                    &target,
                    depth,
                    env,
                    signatures,
                    temp_counter,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                if context.async_state_machine {
                    out.push_str(&format!(
                        "{pad}flux__task->result = {target};\n{pad}{}(flux__task);\n{pad}return;\n",
                        async_finish_c_name(&context.current_function.name)
                    ));
                } else if context.current_function.name == "main" {
                    out.push_str(&format!("{pad}return flux__finish_main({target});\n"));
                } else {
                    out.push_str(&format!("{pad}return {target};\n"));
                }
            }
            StmtKind::Return(values) if values.len() == 1 => {
                let expected = &context.current_function.returns[0];
                let value = emit_expr_for_expected_with_cfg_proofs(
                    &values[0],
                    expected,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                if context.async_state_machine {
                    out.push_str(&format!(
                        "{pad}flux__task->result = {value};\n{pad}{}(flux__task);\n{pad}return;\n",
                        async_finish_c_name(&context.current_function.name)
                    ));
                } else if context.current_function.name == "main" {
                    out.push_str(&format!("{pad}return flux__finish_main({value});\n"));
                } else {
                    out.push_str(&format!("{pad}return {value};\n"));
                }
            }
            StmtKind::Return(values) => {
                let tag = multi_return_struct_name(&context.current_function.name);
                let temp = format!("flux__return_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!("{pad}struct {tag} {temp};\n"));
                for (index, expr) in values.iter().enumerate() {
                    let expected = &context.current_function.returns[index];
                    let value = emit_expr_for_expected_with_cfg_proofs(
                        expr,
                        expected,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?;
                    out.push_str(&format!("{pad}{temp}.v{index} = {value};\n"));
                }
                if context.async_state_machine {
                    out.push_str(&format!(
                        "{pad}flux__task->result = {temp};\n{pad}{}(flux__task);\n{pad}return;\n",
                        async_finish_c_name(&context.current_function.name)
                    ));
                } else {
                    out.push_str(&format!("{pad}return {temp};\n"));
                }
            }
            StmtKind::Break => {
                if let Some(loop_control) = context.async_loop_control {
                    emit_async_save_locals(
                        out,
                        &pad,
                        loop_control.saved_locals,
                        env,
                        signatures,
                        stmt.span,
                    )?;
                    out.push_str(&format!(
                        "{pad}flux__task->state = {};\n{pad}continue;\n",
                        loop_control.break_state
                    ));
                } else {
                    out.push_str(&format!("{pad}break;\n"));
                }
            }
            StmtKind::Continue => {
                if let Some(loop_control) = context.async_loop_control {
                    emit_async_save_locals(
                        out,
                        &pad,
                        loop_control.saved_locals,
                        env,
                        signatures,
                        stmt.span,
                    )?;
                    out.push_str(&format!(
                        "{pad}flux__task->state = {};\n{pad}continue;\n",
                        loop_control.continue_state
                    ));
                } else {
                    out.push_str(&format!("{pad}continue;\n"));
                }
            }
            StmtKind::Expr(expr) => {
                // Discarding an expression's result does not erase its
                // statically known shape. Keep this boundary on the same
                // typed-IR proof path as bindings, assignments, and returns.
                let expr_type = type_of_expr(expr, env, signatures)?;
                let value = emit_expr_for_expected_with_cfg_proofs(
                    expr,
                    &expr_type,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}{};\n", value));
            }
            StmtKind::Shell {
                expr,
                redirect,
                background,
            } => {
                let expr_type = type_of_expr(expr, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        expr,
                        &expr_type,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: expr_type,
                };
                let emit_command = |out: &mut String,
                                    command_pad: &str|
                 -> Result<(), Diagnostic> {
                    if let Some(redirect) = redirect {
                        let path = emit_expr_for_expected_with_cfg_proofs(
                            &redirect.path,
                            &Type::Str,
                            env,
                            signatures,
                            context.checked_i64_cfg_proofs,
                            context.cfg_rewrite_facts,
                        )?;
                        let helper = match value.ty {
                            Type::I64 => "flux_redirect_i64",
                            Type::Bool => "flux_redirect_bool",
                            Type::Str => "flux_redirect_str",
                            Type::Error => "flux_redirect_error",
                            _ => {
                                return Err(diag(
                                    expr.span,
                                    "redirection reached code generation with a non-scalar result",
                                ));
                            }
                        };
                        let append = matches!(redirect.mode, ShellRedirectMode::Append);
                        out.push_str(&format!(
                            "{command_pad}{helper}({}, {}, {});\n",
                            path,
                            if append { "true" } else { "false" },
                            value.code
                        ));
                    } else {
                        out.push_str(&format!("{command_pad}{};\n", value.code));
                    }
                    Ok(())
                };
                if *background {
                    let pid = format!("flux__bg_pid_{}", *temp_counter);
                    *temp_counter += 1;
                    let worker = format!("flux__bg_worker_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!("{pad}pid_t {pid} = fork();\n"));
                    out.push_str(&format!(
                        "{pad}if ({pid} < 0) {{ perror(\"fork\"); abort(); }}\n"
                    ));
                    out.push_str(&format!("{pad}if ({pid} == 0) {{\n"));
                    out.push_str(&format!("{pad}    pid_t {worker} = fork();\n"));
                    out.push_str(&format!("{pad}    if ({worker} < 0) _exit(127);\n"));
                    out.push_str(&format!("{pad}    if ({worker} > 0) _exit(0);\n"));
                    emit_command(out, &format!("{pad}    "))?;
                    out.push_str(&format!("{pad}    fflush(NULL);\n"));
                    out.push_str(&format!("{pad}    _exit(0);\n"));
                    out.push_str(&format!("{pad}}}\n"));
                    out.push_str(&format!(
                        "{pad}while (waitpid({pid}, NULL, 0) < 0 && errno == EINTR) {{}}\n"
                    ));
                } else {
                    emit_command(out, &pad)?;
                }
            }
            StmtKind::If {
                cond,
                binding,
                body,
                else_body,
                ..
            } => {
                if let Some(binding) = binding {
                    let optional_type = type_of_expr(cond, env, signatures)?;
                    let optional = EmittedExpr {
                        code: emit_expr_for_expected_with_cfg_proofs(
                            cond,
                            &optional_type,
                            env,
                            signatures,
                            context.checked_i64_cfg_proofs,
                            context.cfg_rewrite_facts,
                        )?,
                        ty: optional_type,
                    };
                    let optional_ty = signatures.canonical_type(&optional.ty);
                    let Type::Optional(inner) = optional_ty else {
                        return Err(diag(
                            cond.span,
                            "non-optional value reached optional pattern code generation",
                        ));
                    };
                    let inner = signatures.canonical_type(&inner);
                    let temp = format!("flux__optional_pattern_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!(
                        "{pad}{} {temp} = {};\n",
                        c_type(&Type::Optional(Box::new(inner.clone())), signatures),
                        optional.code
                    ));
                    out.push_str(&format!("{pad}if ({temp}.has_value) {{\n"));
                    let mut then_env = env.clone();
                    if binding.name != "_" {
                        out.push_str(&format!(
                            "{pad}    {} {} = {temp}.value;\n",
                            c_type(&inner, signatures),
                            local_c_name(&binding.name)
                        ));
                        then_env.insert(binding.name.clone(), inner);
                    }
                    let mut then_mutable = mutable.clone();
                    emit_block(
                        out,
                        body,
                        depth + 1,
                        &mut then_env,
                        &mut then_mutable,
                        signatures,
                        temp_counter,
                        context,
                    )?;
                    if else_body.is_empty() {
                        out.push_str(&format!("{pad}}}\n"));
                    } else {
                        out.push_str(&format!("{pad}}} else {{\n"));
                        let mut else_env = env.clone();
                        let mut else_mutable = mutable.clone();
                        emit_block(
                            out,
                            else_body,
                            depth + 1,
                            &mut else_env,
                            &mut else_mutable,
                            signatures,
                            temp_counter,
                            context,
                        )?;
                        out.push_str(&format!("{pad}}}\n"));
                    }
                } else if let Some((name, inner, present_in_then)) =
                    optional_presence_promotion(cond, env, mutable, signatures)
                {
                    let optional_ty = Type::Optional(Box::new(inner.clone()));
                    let temp = format!("flux__optional_promotion_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!(
                        "{pad}{} {temp} = {};\n",
                        c_type(&optional_ty, signatures),
                        local_c_name(&name)
                    ));
                    let condition = if present_in_then {
                        format!("{temp}.has_value")
                    } else {
                        format!("!{temp}.has_value")
                    };
                    out.push_str(&format!("{pad}if ({condition}) {{\n"));
                    let mut then_env = env.clone();
                    if present_in_then {
                        out.push_str(&format!(
                            "{pad}    {} {} = {temp}.value;\n",
                            c_type(&inner, signatures),
                            local_c_name(&name)
                        ));
                        then_env.insert(name.clone(), inner.clone());
                    }
                    let mut then_mutable = mutable.clone();
                    emit_block(
                        out,
                        body,
                        depth + 1,
                        &mut then_env,
                        &mut then_mutable,
                        signatures,
                        temp_counter,
                        context,
                    )?;
                    if else_body.is_empty() {
                        out.push_str(&format!("{pad}}}\n"));
                    } else {
                        out.push_str(&format!("{pad}}} else {{\n"));
                        let mut else_env = env.clone();
                        if !present_in_then {
                            out.push_str(&format!(
                                "{pad}    {} {} = {temp}.value;\n",
                                c_type(&inner, signatures),
                                local_c_name(&name)
                            ));
                            else_env.insert(name.clone(), inner.clone());
                        }
                        let mut else_mutable = mutable.clone();
                        emit_block(
                            out,
                            else_body,
                            depth + 1,
                            &mut else_env,
                            &mut else_mutable,
                            signatures,
                            temp_counter,
                            context,
                        )?;
                        out.push_str(&format!("{pad}}}\n"));
                    }
                } else if let Some(ConstantValue::Bool(condition)) =
                    fold_primitive_expr(cond, env, signatures)?
                {
                    let selected = if condition { body } else { else_body };
                    let mut nested = env.clone();
                    let mut nested_mutable = mutable.clone();
                    emit_block(
                        out,
                        selected,
                        depth,
                        &mut nested,
                        &mut nested_mutable,
                        signatures,
                        temp_counter,
                        context,
                    )?;
                } else {
                    let cond = emit_expr_for_expected_with_cfg_proofs(
                        cond,
                        &Type::Bool,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?;
                    out.push_str(&format!("{pad}if {} {{\n", c_condition(&cond)));
                    let mut then_env = env.clone();
                    let mut then_mutable = mutable.clone();
                    emit_block(
                        out,
                        body,
                        depth + 1,
                        &mut then_env,
                        &mut then_mutable,
                        signatures,
                        temp_counter,
                        context,
                    )?;
                    if else_body.is_empty() {
                        out.push_str(&format!("{pad}}}\n"));
                    } else {
                        out.push_str(&format!("{pad}}} else {{\n"));
                        let mut else_env = env.clone();
                        let mut else_mutable = mutable.clone();
                        emit_block(
                            out,
                            else_body,
                            depth + 1,
                            &mut else_env,
                            &mut else_mutable,
                            signatures,
                            temp_counter,
                            context,
                        )?;
                        out.push_str(&format!("{pad}}}\n"));
                    }
                }
            }
            StmtKind::While { cond, body } => {
                if matches!(
                    fold_primitive_expr(cond, env, signatures)?,
                    Some(ConstantValue::Bool(false))
                ) {
                    continue;
                }
                let cond = emit_expr_for_expected_with_cfg_proofs(
                    cond,
                    &Type::Bool,
                    env,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}while {} {{\n", c_condition(&cond)));
                let mut nested = env.clone();
                let mut nested_mutable = mutable.clone();
                emit_block(
                    out,
                    body,
                    depth + 1,
                    &mut nested,
                    &mut nested_mutable,
                    signatures,
                    temp_counter,
                    context.without_async_loop_control(),
                )?;
                out.push_str(&format!("{pad}}}\n"));
            }
            StmtKind::ForRange {
                name,
                start,
                end,
                inclusive,
                body,
                ..
            } => {
                let folded_start = fold_primitive_expr(start, env, signatures)?;
                let folded_end = fold_primitive_expr(end, env, signatures)?;
                if let (Some(ConstantValue::I64(start_value)), Some(ConstantValue::I64(end_value))) =
                    (&folded_start, &folded_end)
                    && if *inclusive {
                        start_value > end_value
                    } else {
                        start_value >= end_value
                    }
                {
                    continue;
                }
                let start = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        start,
                        &Type::I64,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: Type::I64,
                };
                let end = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        end,
                        &Type::I64,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: Type::I64,
                };
                let temp = format!("flux__end_{}", *temp_counter);
                *temp_counter += 1;
                let name_is_live = !dead_definitions.is_some_and(|dead| dead.contains(name));
                let c_name = if name_is_live {
                    local_c_name(name)
                } else {
                    let generated = format!("flux__range_index_{}", *temp_counter);
                    *temp_counter += 1;
                    generated
                };
                if *inclusive {
                    let done = format!("flux__range_done_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!(
                        "{pad}for (int64_t {c_name} = {}, {temp} = {}, {done} = 0; !{done} && {c_name} <= {temp}; {done} = ({c_name} == {temp}), {c_name} += !{done}) {{\n",
                        start.code, end.code
                    ));
                } else {
                    out.push_str(&format!(
                        "{pad}for (int64_t {c_name} = {}, {temp} = {}; {c_name} < {temp}; ++{c_name}) {{\n",
                        start.code, end.code
                    ));
                }
                let mut nested = env.clone();
                if name_is_live {
                    nested.insert(name.clone(), Type::I64);
                }
                let mut nested_mutable = mutable.clone();
                emit_block(
                    out,
                    body,
                    depth + 1,
                    &mut nested,
                    &mut nested_mutable,
                    signatures,
                    temp_counter,
                    context.without_async_loop_control(),
                )?;
                out.push_str(&format!("{pad}}}\n"));
            }
            StmtKind::ForEach {
                index_name,
                name,
                iterable,
                body,
                ..
            } => {
                let iterable_type = type_of_expr(iterable, env, signatures)?;
                let source = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        iterable,
                        &iterable_type,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: iterable_type,
                };
                let source_ty = signatures.canonical_type(&source.ty);
                let (map_key, element) = match source_ty {
                    Type::List(element) | Type::Set(element) => (None, element),
                    Type::Map(key, value) => (Some(key), value),
                    _ => {
                        return Err(diag(
                            stmt.span,
                            "for-loop code generation requires a list, set, or map source",
                        ));
                    }
                };
                let is_map = map_key.is_some();
                let source_c = if is_map {
                    "struct flux__map"
                } else {
                    "struct flux__list"
                };
                let source_name = format!("flux__iter_source_{}", *temp_counter);
                *temp_counter += 1;
                let index_is_live = index_name.as_ref().is_some_and(|index| {
                    !dead_definitions.is_some_and(|dead| dead.contains(index))
                });
                let index_c = if index_is_live && !is_map {
                    local_c_name(index_name.as_ref().expect("live index must be named"))
                } else {
                    let generated = format!("flux__iter_index_{}", *temp_counter);
                    *temp_counter += 1;
                    generated
                };
                let item_is_live = !dead_definitions.is_some_and(|dead| dead.contains(name));
                let item_c = local_c_name(name);
                let element_c = c_type(&element, signatures);
                out.push_str(&format!(
                    "{pad}{source_c} {source_name} = {};\n",
                    source.code
                ));
                out.push_str(&format!(
                    "{pad}for (int64_t {index_c} = 0; {index_c} < (int64_t){source_name}.{}.len; ++{index_c}) {{\n",
                    if is_map { "keys" } else { "len" }
                ));
                if index_is_live && let Some(index_name) = index_name {
                    let key_type = map_key
                        .as_ref()
                        .map(|key| key.as_ref().clone())
                        .unwrap_or(Type::I64);
                    let key_c = c_type(&key_type, signatures);
                    let key_source = if is_map {
                        format!("{source_name}.keys")
                    } else {
                        source_name.clone()
                    };
                    out.push_str(&format!(
                        "{pad}    {key_c} {} = *(({key_c} *)flux_list_at_unchecked({key_source}, (size_t){index_c}, sizeof({key_c})));\n",
                        local_c_name(index_name)
                    ));
                }
                if item_is_live {
                    let value_source = if is_map {
                        format!("{source_name}.values")
                    } else {
                        source_name.clone()
                    };
                    out.push_str(&format!(
                        "{pad}    {element_c} {item_c} = *(({element_c} *)flux_list_at_unchecked({value_source}, (size_t){index_c}, sizeof({element_c})));\n"
                    ));
                }
                let mut nested = env.clone();
                if index_is_live && let Some(index_name) = index_name {
                    nested.insert(
                        index_name.clone(),
                        map_key
                            .as_ref()
                            .map(|key| key.as_ref().clone())
                            .unwrap_or(Type::I64),
                    );
                }
                if item_is_live {
                    nested.insert(name.clone(), *element);
                }
                let mut nested_mutable = mutable.clone();
                emit_block(
                    out,
                    body,
                    depth + 1,
                    &mut nested,
                    &mut nested_mutable,
                    signatures,
                    temp_counter,
                    context.without_async_loop_control(),
                )?;
                out.push_str(&format!("{pad}}}\n"));
            }
            StmtKind::Match { value, arms } => {
                let value_ty = type_of_expr(value, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        value,
                        &value_ty,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: value_ty,
                };
                let Type::Named(enum_name) = &value.ty else {
                    return Err(diag(
                        stmt.span,
                        "match code generation requires an enum value",
                    ));
                };
                let definition = signatures.enum_type(enum_name).ok_or_else(|| {
                    diag(stmt.span, "match code generation requires an enum value")
                })?;
                let temp = format!("flux__match_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}struct {} {temp} = {};\n",
                    struct_c_name(enum_name),
                    value.code
                ));
                out.push_str(&format!("{pad}switch ({temp}.tag) {{\n"));
                for variant in &definition.variants {
                    let variant_arms = arms
                        .iter()
                        .filter(|arm| arm.variant == variant.name)
                        .collect::<Vec<_>>();
                    if variant_arms.is_empty() {
                        continue;
                    }
                    out.push_str(&format!(
                        "{pad}    case {}: {{\n",
                        enum_tag_value_name(enum_name, &variant.name)
                    ));
                    for arm in variant_arms {
                        out.push_str(&format!("{pad}        {{\n"));
                        let mut nested = env.clone();
                        let mut pattern_conditions = Vec::new();
                        let dead_arm_definitions = context
                            .dead_definition_names
                            .get(&source_span_key(arm.span));
                        for (index, (pattern, payload_ty)) in
                            arm.patterns.iter().zip(&variant.payloads).enumerate()
                        {
                            let payload_access = format!(
                                "{temp}.payload.{}.v{index}",
                                enum_payload_member_name(&arm.variant)
                            );
                            match pattern {
                                MatchPattern::Binding(binding) => {
                                    if binding.name == "_"
                                        || dead_arm_definitions
                                            .is_some_and(|dead| dead.contains(&binding.name))
                                    {
                                        continue;
                                    }
                                    out.push_str(&format!(
                                        "{pad}            {} {} = {payload_access};\n",
                                        c_type(payload_ty, signatures),
                                        local_c_name(&binding.name),
                                    ));
                                    nested.insert(binding.name.clone(), payload_ty.clone());
                                }
                                MatchPattern::Struct(pattern) => {
                                    let Type::Named(struct_name) =
                                        signatures.canonical_type(payload_ty)
                                    else {
                                        return Err(diag(
                                            pattern.struct_span,
                                            "match struct pattern code generation requires a struct value",
                                        ));
                                    };
                                    emit_struct_pattern_bindings(
                                        out,
                                        &format!("{pad}            "),
                                        &pattern.fields,
                                        &struct_name,
                                        &payload_access,
                                        &mut PatternBindingEmitContext {
                                            env: &mut nested,
                                            signatures,
                                            dead_definitions: dead_arm_definitions,
                                        },
                                    )?;
                                }
                                MatchPattern::Relational(_) | MatchPattern::Logical { .. } => {
                                    if let Some(condition) = emit_match_pattern_condition(
                                        pattern,
                                        &payload_access,
                                        payload_ty,
                                        &nested,
                                        signatures,
                                    )? {
                                        pattern_conditions.push(condition);
                                    }
                                }
                            }
                        }
                        if let Some(guard) = &arm.guard {
                            let guard = emit_expr_for_expected_with_cfg_proofs(
                                guard,
                                &Type::Bool,
                                &nested,
                                signatures,
                                context.checked_i64_cfg_proofs,
                                context.cfg_rewrite_facts,
                            )?;
                            pattern_conditions.push(c_condition(&guard));
                        }
                        let mut nested_mutable = mutable.clone();
                        if pattern_conditions.is_empty() {
                            emit_block(
                                out,
                                &arm.body,
                                depth + 3,
                                &mut nested,
                                &mut nested_mutable,
                                signatures,
                                temp_counter,
                                context,
                            )?;
                            out.push_str(&format!("{pad}            break;\n"));
                        } else {
                            out.push_str(&format!(
                                "{pad}            if ({}) {{\n",
                                pattern_conditions.join(" && ")
                            ));
                            emit_block(
                                out,
                                &arm.body,
                                depth + 4,
                                &mut nested,
                                &mut nested_mutable,
                                signatures,
                                temp_counter,
                                context,
                            )?;
                            out.push_str(&format!("{pad}                break;\n"));
                            out.push_str(&format!("{pad}            }}\n"));
                        }
                        out.push_str(&format!("{pad}        }}\n"));
                    }
                    out.push_str(&format!("{pad}    }}\n"));
                }
                out.push_str(&format!("{pad}}}\n"));
            }
            StmtKind::ListMatch { value, arms } => {
                let value_ty = type_of_expr(value, env, signatures)?;
                let value = EmittedExpr {
                    code: emit_expr_for_expected_with_cfg_proofs(
                        value,
                        &value_ty,
                        env,
                        signatures,
                        context.checked_i64_cfg_proofs,
                        context.cfg_rewrite_facts,
                    )?,
                    ty: value_ty,
                };
                if let Type::Map(key, mapped_value) = &value.ty {
                    return emit_map_match(
                        out,
                        &pad,
                        &value.code,
                        key,
                        mapped_value,
                        arms,
                        depth,
                        env,
                        mutable,
                        signatures,
                        temp_counter,
                        context,
                    );
                }
                let Type::List(element) = &value.ty else {
                    return Err(diag(
                        stmt.span,
                        "list match code generation requires a list value",
                    ));
                };
                let temp = format!("flux__list_match_{}", *temp_counter);
                *temp_counter += 1;
                out.push_str(&format!(
                    "{pad}struct flux__list {temp} = {};\n",
                    value.code
                ));
                if arms.iter().all(|arm| arm.guard.is_none()) {
                    for (arm_index, arm) in arms.iter().enumerate() {
                        let condition = list_match_condition(&arm.pattern, &temp);
                        if arm_index == 0 {
                            out.push_str(&format!("{pad}if ({condition}) {{\n"));
                        } else if matches!(arm.pattern, ListMatchPattern::Wildcard { .. }) {
                            out.push_str(&format!("{pad}else {{\n"));
                        } else {
                            out.push_str(&format!("{pad}else if ({condition}) {{\n"));
                        }
                        let mut nested = env.clone();
                        let dead_arm_definitions = context
                            .dead_definition_names
                            .get(&source_span_key(arm.span));
                        emit_list_match_pattern_bindings(
                            out,
                            &format!("{pad}    "),
                            &arm.pattern,
                            &temp,
                            element,
                            &mut PatternBindingEmitContext {
                                env: &mut nested,
                                signatures,
                                dead_definitions: dead_arm_definitions,
                            },
                        )?;
                        let mut nested_mutable = mutable.clone();
                        emit_block(
                            out,
                            &arm.body,
                            depth + 1,
                            &mut nested,
                            &mut nested_mutable,
                            signatures,
                            temp_counter,
                            context,
                        )?;
                        out.push_str(&format!("{pad}}}\n"));
                    }
                } else {
                    let matched = format!("flux__list_match_done_{}", *temp_counter);
                    *temp_counter += 1;
                    out.push_str(&format!("{pad}bool {matched} = false;\n"));
                    for arm in arms {
                        let condition = list_match_condition(&arm.pattern, &temp);
                        out.push_str(&format!("{pad}if (!{matched} && ({condition})) {{\n"));
                        let mut nested = env.clone();
                        let dead_arm_definitions = context
                            .dead_definition_names
                            .get(&source_span_key(arm.span));
                        emit_list_match_pattern_bindings(
                            out,
                            &format!("{pad}    "),
                            &arm.pattern,
                            &temp,
                            element,
                            &mut PatternBindingEmitContext {
                                env: &mut nested,
                                signatures,
                                dead_definitions: dead_arm_definitions,
                            },
                        )?;
                        if let Some(guard) = &arm.guard {
                            let guard = emit_expr_for_expected_with_cfg_proofs(
                                guard,
                                &Type::Bool,
                                &nested,
                                signatures,
                                context.checked_i64_cfg_proofs,
                                context.cfg_rewrite_facts,
                            )?;
                            out.push_str(&format!("{pad}    if ({}) {{\n", c_condition(&guard)));
                            out.push_str(&format!("{pad}        {matched} = true;\n"));
                            let mut nested_mutable = mutable.clone();
                            emit_block(
                                out,
                                &arm.body,
                                depth + 2,
                                &mut nested,
                                &mut nested_mutable,
                                signatures,
                                temp_counter,
                                context,
                            )?;
                            out.push_str(&format!("{pad}    }}\n"));
                        } else {
                            out.push_str(&format!("{pad}    {matched} = true;\n"));
                            let mut nested_mutable = mutable.clone();
                            emit_block(
                                out,
                                &arm.body,
                                depth + 1,
                                &mut nested,
                                &mut nested_mutable,
                                signatures,
                                temp_counter,
                                context,
                            )?;
                        }
                        out.push_str(&format!("{pad}}}\n"));
                    }
                }
            }
        }
    }
    Ok(())
}

struct EmittedExpr {
    code: String,
    ty: Type,
}

fn emit_map_match(
    out: &mut String,
    pad: &str,
    source_code: &str,
    key_ty: &Type,
    value_ty: &Type,
    arms: &[crate::ast::ListMatchArm],
    depth: usize,
    env: &HashMap<String, Type>,
    mutable: &HashSet<String>,
    signatures: &Signatures,
    temp_counter: &mut usize,
    context: BlockEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let map_name = format!("flux__map_match_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct flux__map {map_name} = {source_code};\n"
    ));
    let matched = format!("flux__map_match_done_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!("{pad}bool {matched} = false;\n"));
    let key_c = c_type(key_ty, signatures);
    let value_c = c_type(value_ty, signatures);
    for arm in arms {
        let ListMatchPattern::Map { entries, .. } = &arm.pattern else {
            if !matches!(arm.pattern, ListMatchPattern::Wildcard { .. }) {
                return Err(diag(arm.span, "map match requires map patterns or '_'"));
            }
            out.push_str(&format!("{pad}if (!{matched}) {{\n"));
            let mut nested = env.clone();
            let mut nested_mutable = mutable.clone();
            if let Some(guard) = &arm.guard {
                let guard = emit_expr_for_expected_with_cfg_proofs(
                    guard,
                    &Type::Bool,
                    &nested,
                    signatures,
                    context.checked_i64_cfg_proofs,
                    context.cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}    if ({}) {{\n", c_condition(&guard)));
                out.push_str(&format!("{pad}        {matched} = true;\n"));
                emit_block(
                    out,
                    &arm.body,
                    depth + 2,
                    &mut nested,
                    &mut nested_mutable,
                    signatures,
                    temp_counter,
                    context,
                )?;
                out.push_str(&format!("{pad}    }}\n"));
            } else {
                out.push_str(&format!("{pad}    {matched} = true;\n"));
                emit_block(
                    out,
                    &arm.body,
                    depth + 1,
                    &mut nested,
                    &mut nested_mutable,
                    signatures,
                    temp_counter,
                    context,
                )?;
            }
            out.push_str(&format!("{pad}}}\n"));
            continue;
        };
        let arm_match = format!("flux__map_arm_match_{}", *temp_counter);
        *temp_counter += 1;
        out.push_str(&format!(
            "{pad}if (!{matched}) {{\n{pad}    bool {arm_match} = true;\n"
        ));
        let dead = context
            .dead_definition_names
            .get(&source_span_key(arm.span));
        let mut binding_temps = Vec::new();
        for entry in entries {
            let key_code = emit_expr_for_expected_with_cfg_proofs(
                &entry.key,
                key_ty,
                env,
                signatures,
                context.checked_i64_cfg_proofs,
                context.cfg_rewrite_facts,
            )?;
            let found = format!("flux__map_key_found_{}", *temp_counter);
            *temp_counter += 1;
            let value_temp = format!("flux__map_value_{}", *temp_counter);
            *temp_counter += 1;
            out.push_str(&format!("{pad}    bool {found} = false;\n"));
            if entry.binding.name != "_"
                && !dead.is_some_and(|names| names.contains(&entry.binding.name))
            {
                out.push_str(&format!(
                    "{pad}    {value_c} {value_temp} = ({value_c}){{0}};\n"
                ));
                binding_temps.push((entry.binding.name.clone(), value_temp.clone()));
            }
            let equal = if *key_ty == Type::Str {
                format!(
                    "strcmp(*((const char **)flux_list_at_unchecked({map_name}.keys, flux__map_index, sizeof({key_c}))), {key_code}) == 0"
                )
            } else {
                format!(
                    "(*(({key_c} *)flux_list_at_unchecked({map_name}.keys, flux__map_index, sizeof({key_c}))) == {key_code})"
                )
            };
            out.push_str(&format!("{pad}    for (size_t flux__map_index = 0; flux__map_index < {map_name}.keys.len; ++flux__map_index) {{\n"));
            out.push_str(&format!(
                "{pad}        if ({equal}) {{\n{pad}            {found} = true;\n"
            ));
            if !binding_temps.is_empty()
                && binding_temps
                    .last()
                    .is_some_and(|(_, temp)| temp == &value_temp)
            {
                out.push_str(&format!("{pad}            {value_temp} = *(({value_c} *)flux_list_at_unchecked({map_name}.values, flux__map_index, sizeof({value_c})));\n"));
            }
            out.push_str(&format!("{pad}            break;\n{pad}        }}\n{pad}    }}\n{pad}    if (!{found}) {arm_match} = false;\n"));
        }
        out.push_str(&format!("{pad}    if ({arm_match}) {{\n"));
        let mut nested = env.clone();
        for (name, temp) in binding_temps {
            out.push_str(&format!(
                "{pad}        {value_c} {} = {temp};\n",
                local_c_name(&name)
            ));
            nested.insert(name, (*value_ty).clone());
        }
        if let Some(guard) = &arm.guard {
            let guard = emit_expr_for_expected_with_cfg_proofs(
                guard,
                &Type::Bool,
                &nested,
                signatures,
                context.checked_i64_cfg_proofs,
                context.cfg_rewrite_facts,
            )?;
            out.push_str(&format!("{pad}        if ({}) {{\n", c_condition(&guard)));
            out.push_str(&format!("{pad}            {matched} = true;\n"));
            let mut nested_mutable = mutable.clone();
            emit_block(
                out,
                &arm.body,
                depth + 3,
                &mut nested,
                &mut nested_mutable,
                signatures,
                temp_counter,
                context,
            )?;
            out.push_str(&format!("{pad}        }}\n"));
        } else {
            out.push_str(&format!("{pad}        {matched} = true;\n"));
            let mut nested_mutable = mutable.clone();
            emit_block(
                out,
                &arm.body,
                depth + 2,
                &mut nested,
                &mut nested_mutable,
                signatures,
                temp_counter,
                context,
            )?;
        }
        out.push_str(&format!("{pad}    }}\n{pad}}}\n"));
    }
    Ok(())
}

fn list_match_condition(pattern: &ListMatchPattern, temp: &str) -> String {
    match pattern {
        ListMatchPattern::Wildcard { .. } => "true".to_string(),
        ListMatchPattern::List { bindings, rest, .. } => {
            if rest.is_some() {
                format!("{temp}.len >= {}", bindings.len())
            } else {
                format!("{temp}.len == {}", bindings.len())
            }
        }
        ListMatchPattern::Map { .. } => "false".to_string(),
    }
}

struct PatternBindingEmitContext<'a> {
    env: &'a mut HashMap<String, Type>,
    signatures: &'a Signatures,
    dead_definitions: Option<&'a HashSet<String>>,
}

fn emit_list_match_pattern_bindings(
    out: &mut String,
    pad: &str,
    pattern: &ListMatchPattern,
    temp: &str,
    element: &Type,
    context: &mut PatternBindingEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let ListMatchPattern::List { bindings, rest, .. } = pattern else {
        return Ok(());
    };
    let element_c = c_type(element, context.signatures);
    for (index, binding) in bindings.iter().enumerate() {
        if binding.name == "_"
            || context
                .dead_definitions
                .is_some_and(|dead| dead.contains(&binding.name))
        {
            continue;
        }
        let index_code = if let Some(rest) = rest {
            if index < rest.index {
                index.to_string()
            } else {
                format!("{temp}.len - {}", bindings.len() - index)
            }
        } else {
            index.to_string()
        };
        out.push_str(&format!(
            "{pad}{element_c} {} = *(({element_c} *)flux_list_at_unchecked({temp}, {index_code}, sizeof({element_c})));\n",
            local_c_name(&binding.name)
        ));
        context.env.insert(binding.name.clone(), element.clone());
    }
    if let Some(rest) = rest
        && rest.binding.name != "_"
        && !context
            .dead_definitions
            .is_some_and(|dead| dead.contains(&rest.binding.name))
    {
        let rest_name = local_c_name(&rest.binding.name);
        out.push_str(&format!(
            "{pad}struct flux__list {rest_name} = {{ .data = {temp}.data, .len = {temp}.len - {}, .stride = flux_list_stride({temp}, sizeof({element_c})) }};\n",
            bindings.len()
        ));
        out.push_str(&format!(
            "{pad}if ({rest_name}.len != 0) {{ {rest_name}.data = flux_list_at_unchecked({temp}, {}, sizeof({element_c})); }}\n",
            rest.index
        ));
        context.env.insert(
            rest.binding.name.clone(),
            Type::List(Box::new(element.clone())),
        );
    }
    Ok(())
}

fn match_expr_needs_specialized_lowering(
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
) -> bool {
    if matches!(
        expr.kind,
        ExprKind::Match { .. } | ExprKind::ListMatch { .. }
    ) {
        return true;
    }
    let span = source_span_key(expr.span);
    rewrite_facts
        .match_exprs
        .get(&span)
        .is_some_and(|match_expr| {
            cfg_match_expr_calls_are_reconstructable(match_expr, env, signatures)
        })
        || rewrite_facts
            .list_match_exprs
            .get(&span)
            .is_some_and(|list_match_expr| {
                cfg_list_match_expr_calls_are_reconstructable(list_match_expr, env, signatures)
            })
}

fn emit_match_expr_into(
    out: &mut String,
    expr: &Expr,
    target: &str,
    depth: usize,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
    checked_i64_cfg_proofs: &HashMap<(u32, usize, usize, usize), CfgCheckedI64Proof>,
    cfg_rewrite_facts: &CfgRewriteFacts,
) -> Result<(), Diagnostic> {
    if cfg_rewrite_facts
        .list_match_exprs
        .get(&source_span_key(expr.span))
        .is_some_and(|list_match_expr| {
            cfg_list_match_expr_calls_are_reconstructable(list_match_expr, env, signatures)
        })
        || matches!(expr.kind, ExprKind::ListMatch { .. })
    {
        return emit_list_match_expr_into(
            out,
            expr,
            target,
            depth,
            env,
            signatures,
            temp_counter,
            checked_i64_cfg_proofs,
            cfg_rewrite_facts,
        );
    }
    if let Some(match_expr) = cfg_rewrite_facts
        .match_exprs
        .get(&source_span_key(expr.span))
        && cfg_match_expr_calls_are_reconstructable(match_expr, env, signatures)
    {
        let synthetic = cfg_match_expr_as_ast(match_expr);
        return emit_match_expr_into(
            out,
            &synthetic,
            target,
            depth,
            env,
            signatures,
            temp_counter,
            &HashMap::new(),
            &CfgRewriteFacts::default(),
        );
    }
    let ExprKind::Match { value, arms } = &expr.kind else {
        return Err(diag(
            expr.span,
            "expected match expression during code generation",
        ));
    };
    let value_ty = type_of_expr(value, env, signatures)?;
    let emitted_value = EmittedExpr {
        code: emit_expr_for_expected_with_cfg_proofs(
            value,
            &value_ty,
            env,
            signatures,
            checked_i64_cfg_proofs,
            cfg_rewrite_facts,
        )?,
        ty: value_ty,
    };
    let Type::Named(enum_name) = &emitted_value.ty else {
        return Err(diag(
            value.span,
            "match expression code generation requires an enum value",
        ));
    };
    let definition = signatures.enum_type(enum_name).ok_or_else(|| {
        diag(
            value.span,
            "match expression code generation requires an enum value",
        )
    })?;
    let temp = format!("flux__match_{}", *temp_counter);
    *temp_counter += 1;
    let pad = "    ".repeat(depth);
    out.push_str(&format!(
        "{pad}struct {} {temp} = {};\n",
        struct_c_name(enum_name),
        emitted_value.code
    ));
    out.push_str(&format!("{pad}switch ({temp}.tag) {{\n"));
    for variant in &definition.variants {
        let variant_arms = arms
            .iter()
            .filter(|arm| arm.variant == variant.name)
            .collect::<Vec<_>>();
        if variant_arms.is_empty() {
            continue;
        }
        out.push_str(&format!(
            "{pad}    case {}: {{\n",
            enum_tag_value_name(enum_name, &variant.name)
        ));
        for arm in variant_arms {
            out.push_str(&format!("{pad}        {{\n"));
            let mut nested = env.clone();
            let mut pattern_conditions = Vec::new();
            for (index, (pattern, payload_ty)) in
                arm.patterns.iter().zip(&variant.payloads).enumerate()
            {
                let payload_access = format!(
                    "{temp}.payload.{}.v{index}",
                    enum_payload_member_name(&arm.variant)
                );
                match pattern {
                    MatchPattern::Binding(binding) => {
                        if binding.name == "_" {
                            continue;
                        }
                        out.push_str(&format!(
                            "{pad}            {} {} = {payload_access};\n",
                            c_type(payload_ty, signatures),
                            local_c_name(&binding.name),
                        ));
                        nested.insert(binding.name.clone(), payload_ty.clone());
                    }
                    MatchPattern::Struct(pattern) => {
                        let Type::Named(struct_name) = signatures.canonical_type(payload_ty) else {
                            return Err(diag(
                                pattern.struct_span,
                                "match struct pattern code generation requires a struct value",
                            ));
                        };
                        emit_struct_pattern_bindings(
                            out,
                            &format!("{pad}            "),
                            &pattern.fields,
                            &struct_name,
                            &payload_access,
                            &mut PatternBindingEmitContext {
                                env: &mut nested,
                                signatures,
                                dead_definitions: None,
                            },
                        )?;
                    }
                    MatchPattern::Relational(_) | MatchPattern::Logical { .. } => {
                        if let Some(condition) = emit_match_pattern_condition(
                            pattern,
                            &payload_access,
                            payload_ty,
                            &nested,
                            signatures,
                        )? {
                            pattern_conditions.push(condition);
                        }
                    }
                }
            }
            if let Some(guard) = &arm.guard {
                let guard = emit_expr_for_expected_with_cfg_proofs(
                    guard,
                    &Type::Bool,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                pattern_conditions.push(c_condition(&guard));
            }
            let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
            if pattern_conditions.is_empty() {
                let arm_value = emit_expr_for_expected_with_cfg_proofs(
                    &arm.value,
                    &arm_ty,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}            {target} = {};\n", arm_value));
                out.push_str(&format!("{pad}            break;\n"));
            } else {
                out.push_str(&format!(
                    "{pad}            if ({}) {{\n",
                    pattern_conditions.join(" && ")
                ));
                let arm_value = emit_expr_for_expected_with_cfg_proofs(
                    &arm.value,
                    &arm_ty,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}                {target} = {};\n", arm_value));
                out.push_str(&format!("{pad}                break;\n"));
                out.push_str(&format!("{pad}            }}\n"));
            }
            out.push_str(&format!("{pad}        }}\n"));
        }
        out.push_str(&format!("{pad}    }}\n"));
    }
    out.push_str(&format!("{pad}}}\n"));
    Ok(())
}

fn emit_list_match_expr_into(
    out: &mut String,
    expr: &Expr,
    target: &str,
    depth: usize,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
    checked_i64_cfg_proofs: &HashMap<(u32, usize, usize, usize), CfgCheckedI64Proof>,
    cfg_rewrite_facts: &CfgRewriteFacts,
) -> Result<(), Diagnostic> {
    if let Some(list_match_expr) = cfg_rewrite_facts
        .list_match_exprs
        .get(&source_span_key(expr.span))
        && cfg_list_match_expr_calls_are_reconstructable(list_match_expr, env, signatures)
    {
        let synthetic = cfg_list_match_expr_as_ast(list_match_expr);
        return emit_list_match_expr_into(
            out,
            &synthetic,
            target,
            depth,
            env,
            signatures,
            temp_counter,
            &HashMap::new(),
            &CfgRewriteFacts::default(),
        );
    }
    let ExprKind::ListMatch { value, arms } = &expr.kind else {
        return Err(diag(
            expr.span,
            "expected list match expression during code generation",
        ));
    };
    let value_ty = type_of_expr(value, env, signatures)?;
    let emitted_value = EmittedExpr {
        code: emit_expr_for_expected_with_cfg_proofs(
            value,
            &value_ty,
            env,
            signatures,
            checked_i64_cfg_proofs,
            cfg_rewrite_facts,
        )?,
        ty: value_ty,
    };
    if let Type::Map(key, mapped_value) = &emitted_value.ty {
        return emit_map_match_expr_into(
            out,
            target,
            depth,
            &emitted_value.code,
            key,
            mapped_value,
            arms,
            env,
            signatures,
            temp_counter,
            checked_i64_cfg_proofs,
            cfg_rewrite_facts,
        );
    }
    let Type::List(element) = &emitted_value.ty else {
        return Err(diag(
            value.span,
            "collection match expression code generation requires a list or map value",
        ));
    };
    let temp = format!("flux__list_match_{}", *temp_counter);
    *temp_counter += 1;
    let pad = "    ".repeat(depth);
    out.push_str(&format!(
        "{pad}struct flux__list {temp} = {};\n",
        emitted_value.code
    ));
    if arms.iter().all(|arm| arm.guard.is_none()) {
        for (arm_index, arm) in arms.iter().enumerate() {
            let condition = list_match_condition(&arm.pattern, &temp);
            if arm_index == 0 {
                out.push_str(&format!("{pad}if ({condition}) {{\n"));
            } else if matches!(arm.pattern, ListMatchPattern::Wildcard { .. }) {
                out.push_str(&format!("{pad}else {{\n"));
            } else {
                out.push_str(&format!("{pad}else if ({condition}) {{\n"));
            }
            let mut nested = env.clone();
            emit_list_match_pattern_bindings(
                out,
                &format!("{pad}    "),
                &arm.pattern,
                &temp,
                element,
                &mut PatternBindingEmitContext {
                    env: &mut nested,
                    signatures,
                    dead_definitions: None,
                },
            )?;
            let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
            let arm_value = emit_expr_for_expected_with_cfg_proofs(
                &arm.value,
                &arm_ty,
                &nested,
                signatures,
                checked_i64_cfg_proofs,
                cfg_rewrite_facts,
            )?;
            out.push_str(&format!("{pad}    {target} = {};\n", arm_value));
            out.push_str(&format!("{pad}}}\n"));
        }
    } else {
        let matched = format!("flux__list_match_done_{}", *temp_counter);
        *temp_counter += 1;
        out.push_str(&format!("{pad}bool {matched} = false;\n"));
        for arm in arms {
            let condition = list_match_condition(&arm.pattern, &temp);
            out.push_str(&format!("{pad}if (!{matched} && ({condition})) {{\n"));
            let mut nested = env.clone();
            emit_list_match_pattern_bindings(
                out,
                &format!("{pad}    "),
                &arm.pattern,
                &temp,
                element,
                &mut PatternBindingEmitContext {
                    env: &mut nested,
                    signatures,
                    dead_definitions: None,
                },
            )?;
            if let Some(guard) = &arm.guard {
                let guard = emit_expr_for_expected_with_cfg_proofs(
                    guard,
                    &Type::Bool,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}    if ({}) {{\n", c_condition(&guard)));
                let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
                let arm_value = emit_expr_for_expected_with_cfg_proofs(
                    &arm.value,
                    &arm_ty,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}        {target} = {};\n", arm_value));
                out.push_str(&format!("{pad}        {matched} = true;\n"));
                out.push_str(&format!("{pad}    }}\n"));
            } else {
                let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
                let arm_value = emit_expr_for_expected_with_cfg_proofs(
                    &arm.value,
                    &arm_ty,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!("{pad}    {target} = {};\n", arm_value));
                out.push_str(&format!("{pad}    {matched} = true;\n"));
            }
            out.push_str(&format!("{pad}}}\n"));
        }
    }
    Ok(())
}

fn emit_map_match_expr_into(
    out: &mut String,
    target: &str,
    depth: usize,
    source_code: &str,
    key_ty: &Type,
    value_ty: &Type,
    arms: &[crate::ast::ListMatchExprArm],
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
    checked_i64_cfg_proofs: &HashMap<(u32, usize, usize, usize), CfgCheckedI64Proof>,
    cfg_rewrite_facts: &CfgRewriteFacts,
) -> Result<(), Diagnostic> {
    let pad = "    ".repeat(depth);
    let map_name = format!("flux__map_match_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct flux__map {map_name} = {source_code};
"
    ));
    let matched = format!("flux__map_match_done_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}bool {matched} = false;
"
    ));
    let key_c = c_type(key_ty, signatures);
    let value_c = c_type(value_ty, signatures);

    for arm in arms {
        let ListMatchPattern::Map { entries, .. } = &arm.pattern else {
            if !matches!(arm.pattern, ListMatchPattern::Wildcard { .. }) {
                return Err(diag(
                    arm.span,
                    "map match expression requires map patterns or '_'",
                ));
            }
            out.push_str(&format!(
                "{pad}if (!{matched}) {{
"
            ));
            let nested = env.clone();
            if let Some(guard) = &arm.guard {
                let guard = emit_expr_for_expected_with_cfg_proofs(
                    guard,
                    &Type::Bool,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!(
                    "{pad}    if ({}) {{
",
                    c_condition(&guard)
                ));
                let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
                let arm_value = emit_expr_for_expected_with_cfg_proofs(
                    &arm.value,
                    &arm_ty,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!(
                    "{pad}        {target} = {arm_value};
"
                ));
                out.push_str(&format!(
                    "{pad}        {matched} = true;
"
                ));
                out.push_str(&format!(
                    "{pad}    }}
"
                ));
            } else {
                let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
                let arm_value = emit_expr_for_expected_with_cfg_proofs(
                    &arm.value,
                    &arm_ty,
                    &nested,
                    signatures,
                    checked_i64_cfg_proofs,
                    cfg_rewrite_facts,
                )?;
                out.push_str(&format!(
                    "{pad}    {target} = {arm_value};
"
                ));
                out.push_str(&format!(
                    "{pad}    {matched} = true;
"
                ));
            }
            out.push_str(&format!(
                "{pad}}}
"
            ));
            continue;
        };

        let arm_match = format!("flux__map_arm_match_{}", *temp_counter);
        *temp_counter += 1;
        out.push_str(&format!(
            "{pad}if (!{matched}) {{
{pad}    bool {arm_match} = true;
"
        ));
        let mut binding_temps = Vec::new();
        for entry in entries {
            let key_code = emit_expr_for_expected_with_cfg_proofs(
                &entry.key,
                key_ty,
                env,
                signatures,
                checked_i64_cfg_proofs,
                cfg_rewrite_facts,
            )?;
            let found = format!("flux__map_key_found_{}", *temp_counter);
            *temp_counter += 1;
            let value_temp = format!("flux__map_value_{}", *temp_counter);
            *temp_counter += 1;
            out.push_str(&format!(
                "{pad}    bool {found} = false;
"
            ));
            if entry.binding.name != "_" {
                out.push_str(&format!(
                    "{pad}    {value_c} {value_temp} = ({value_c}){{0}};
"
                ));
                binding_temps.push((entry.binding.name.clone(), value_temp.clone()));
            }
            let equal = if *key_ty == Type::Str {
                format!(
                    "strcmp(*((const char **)flux_list_at_unchecked({map_name}.keys, flux__map_index, sizeof({key_c}))), {key_code}) == 0"
                )
            } else {
                format!(
                    "(*(({key_c} *)flux_list_at_unchecked({map_name}.keys, flux__map_index, sizeof({key_c}))) == {key_code})"
                )
            };
            out.push_str(&format!(
                "{pad}    for (size_t flux__map_index = 0; flux__map_index < {map_name}.keys.len; ++flux__map_index) {{
"
            ));
            out.push_str(&format!(
                "{pad}        if ({equal}) {{
{pad}            {found} = true;
"
            ));
            if entry.binding.name != "_" {
                out.push_str(&format!(
                    "{pad}            {value_temp} = *(({value_c} *)flux_list_at_unchecked({map_name}.values, flux__map_index, sizeof({value_c})));
"
                ));
            }
            out.push_str(&format!(
                "{pad}            break;
{pad}        }}
{pad}    }}
{pad}    if (!{found}) {arm_match} = false;
"
            ));
        }

        out.push_str(&format!(
            "{pad}    if ({arm_match}) {{
"
        ));
        let mut nested = env.clone();
        for (name, temp) in binding_temps {
            out.push_str(&format!(
                "{pad}        {value_c} {} = {temp};
",
                local_c_name(&name)
            ));
            nested.insert(name, value_ty.clone());
        }
        if let Some(guard) = &arm.guard {
            let guard = emit_expr_for_expected_with_cfg_proofs(
                guard,
                &Type::Bool,
                &nested,
                signatures,
                checked_i64_cfg_proofs,
                cfg_rewrite_facts,
            )?;
            out.push_str(&format!(
                "{pad}        if ({}) {{
",
                c_condition(&guard)
            ));
            let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
            let arm_value = emit_expr_for_expected_with_cfg_proofs(
                &arm.value,
                &arm_ty,
                &nested,
                signatures,
                checked_i64_cfg_proofs,
                cfg_rewrite_facts,
            )?;
            out.push_str(&format!(
                "{pad}            {target} = {arm_value};
"
            ));
            out.push_str(&format!(
                "{pad}            {matched} = true;
"
            ));
            out.push_str(&format!(
                "{pad}        }}
"
            ));
        } else {
            let arm_ty = type_of_expr(&arm.value, &nested, signatures)?;
            let arm_value = emit_expr_for_expected_with_cfg_proofs(
                &arm.value,
                &arm_ty,
                &nested,
                signatures,
                checked_i64_cfg_proofs,
                cfg_rewrite_facts,
            )?;
            out.push_str(&format!(
                "{pad}        {target} = {arm_value};
"
            ));
            out.push_str(&format!(
                "{pad}        {matched} = true;
"
            ));
        }
        out.push_str(&format!(
            "{pad}    }}
{pad}}}
"
        ));
    }
    Ok(())
}

fn emit_struct_pattern_assignments(
    out: &mut String,
    pad: &str,
    fields: &[StructPatternField],
    struct_name: &str,
    base: &str,
    signatures: &Signatures,
    dead_definitions: Option<&HashSet<String>>,
) -> Result<(), Diagnostic> {
    let definition = signatures
        .struct_type(struct_name)
        .expect("type checking guarantees struct assignment pattern type exists");
    for field in fields {
        let field_signature = definition
            .field(&field.field)
            .expect("type checking guarantees struct assignment pattern fields exist");
        let access = format!("{base}.{}", field_c_name(&field.field));
        if let Some(nested) = &field.nested {
            let Type::Named(nested_name) = signatures.canonical_type(&field_signature.ty) else {
                return Err(diag(
                    nested.struct_span,
                    "nested struct assignment code generation requires a struct value",
                ));
            };
            emit_struct_pattern_assignments(
                out,
                pad,
                &nested.fields,
                &nested_name,
                &access,
                signatures,
                dead_definitions,
            )?;
            continue;
        }
        if field.binding.name == "_"
            || dead_definitions.is_some_and(|dead| dead.contains(&field.binding.name))
        {
            continue;
        }
        out.push_str(&format!(
            "{pad}{} = {access};\n",
            local_c_name(&field.binding.name),
        ));
    }
    Ok(())
}

fn emit_struct_pattern_bindings(
    out: &mut String,
    pad: &str,
    fields: &[StructPatternField],
    struct_name: &str,
    base: &str,
    context: &mut PatternBindingEmitContext<'_>,
) -> Result<(), Diagnostic> {
    let definition = context
        .signatures
        .struct_type(struct_name)
        .expect("type checking guarantees struct pattern type exists");
    for field in fields {
        let field_signature = definition
            .field(&field.field)
            .expect("type checking guarantees struct pattern fields exist");
        let access = format!("{base}.{}", field_c_name(&field.field));
        if let Some(nested) = &field.nested {
            let Type::Named(nested_name) = context.signatures.canonical_type(&field_signature.ty)
            else {
                return Err(diag(
                    nested.struct_span,
                    "nested struct pattern code generation requires a struct value",
                ));
            };
            emit_struct_pattern_bindings(out, pad, &nested.fields, &nested_name, &access, context)?;
            continue;
        }
        if field.binding.name == "_"
            || context
                .dead_definitions
                .is_some_and(|dead| dead.contains(&field.binding.name))
        {
            continue;
        }
        out.push_str(&format!(
            "{pad}{} {} = {access};\n",
            c_type(&field_signature.ty, context.signatures),
            local_c_name(&field.binding.name),
        ));
        context
            .env
            .insert(field.binding.name.clone(), field_signature.ty.clone());
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SequenceLoweringKind {
    Chunked,
    Sorted,
    Flatten,
    Distinct,
    Concat,
    Transform,
    Reduction,
}

fn cfg_sequence_expr_calls_are_reconstructable(
    expr: &CfgScalarExpr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
) -> bool {
    let CfgScalarExprKind::Call { callee, arguments } = &expr.kind else {
        return false;
    };
    if !matches!(
        crate::builtin_names::global_impl(callee),
        "map"
            | "filter"
            | "where"
            | "chunked"
            | "sorted"
            | "flatten"
            | "distinct"
            | "concat"
            | "fold"
            | "reduce"
    ) {
        return false;
    }
    arguments.iter().all(|argument| {
        if matches!(
            &argument.kind,
            CfgScalarExprKind::Call { callee, .. }
                if matches!(
                    crate::builtin_names::global_impl(callee),
                    "map"
                        | "filter"
                        | "where"
                        | "chunked"
                        | "sorted"
                        | "flatten"
                        | "distinct"
                        | "concat"
                        | "fold"
                        | "reduce"
                )
        ) {
            cfg_sequence_expr_calls_are_reconstructable(argument, env, signatures)
        } else {
            cfg_scalar_expr_calls_are_reconstructable(argument, env, signatures)
        }
    })
}

fn sequence_expr_for_lowering(
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
) -> Expr {
    let Some(sequence) = rewrite_facts
        .sequence_exprs
        .get(&source_span_key(expr.span))
    else {
        return expr.clone();
    };
    if !cfg_sequence_expr_calls_are_reconstructable(sequence, env, signatures) {
        return expr.clone();
    }
    let mut reconstructed = cfg_scalar_expr_as_ast(sequence);
    reconstructed.line = expr.line;
    reconstructed.span = expr.span;
    reconstructed
}

fn sequence_lowering_kind(
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
) -> Option<SequenceLoweringKind> {
    let expr = sequence_expr_for_lowering(expr, env, signatures, rewrite_facts);
    if sequence_chunked(&expr).is_some() {
        Some(SequenceLoweringKind::Chunked)
    } else if sequence_sorted(&expr).is_some() {
        Some(SequenceLoweringKind::Sorted)
    } else if sequence_flatten(&expr).is_some() {
        Some(SequenceLoweringKind::Flatten)
    } else if sequence_distinct(&expr).is_some() {
        Some(SequenceLoweringKind::Distinct)
    } else if sequence_concat(&expr).is_some() {
        Some(SequenceLoweringKind::Concat)
    } else if sequence_transform(&expr).is_some() {
        Some(SequenceLoweringKind::Transform)
    } else if sequence_reduction(&expr).is_some() {
        Some(SequenceLoweringKind::Reduction)
    } else {
        None
    }
}

enum SequenceTransform<'a> {
    Map { list: &'a Expr, callback: &'a Expr },
    Filter { list: &'a Expr, callback: &'a Expr },
}

fn sequence_transform(expr: &Expr) -> Option<SequenceTransform<'_>> {
    match &expr.kind {
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && crate::builtin_names::global_impl(name) == "map"
            && args.len() == 2 =>
        {
            Some(SequenceTransform::Map {
                list: &args[0],
                callback: &args[1],
            })
        }
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && matches!(crate::builtin_names::global_impl(name), "filter" | "where")
            && args.len() == 2 =>
        {
            Some(SequenceTransform::Filter {
                list: &args[0],
                callback: &args[1],
            })
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if crate::builtin_names::global_impl(name) == "map" && args.len() == 1 => {
            Some(SequenceTransform::Map {
                list: input,
                callback: &args[0],
            })
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if matches!(crate::builtin_names::global_impl(name), "filter" | "where")
            && args.len() == 1 =>
        {
            Some(SequenceTransform::Filter {
                list: input,
                callback: &args[0],
            })
        }
        _ => None,
    }
}

fn sequence_chunked(expr: &Expr) -> Option<(&Expr, &Expr)> {
    match &expr.kind {
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && crate::builtin_names::global_impl(name) == "chunked"
            && args.len() == 2 =>
        {
            Some((&args[0], &args[1]))
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if crate::builtin_names::global_impl(name) == "chunked" && args.len() == 1 => {
            Some((input, &args[0]))
        }
        _ => None,
    }
}

fn sequence_sorted(expr: &Expr) -> Option<&Expr> {
    match &expr.kind {
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && crate::builtin_names::global_impl(name) == "sorted"
            && args.len() == 1 =>
        {
            Some(&args[0])
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if crate::builtin_names::global_impl(name) == "sorted" && args.is_empty() => Some(input),
        _ => None,
    }
}

fn sequence_flatten(expr: &Expr) -> Option<&Expr> {
    match &expr.kind {
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && crate::builtin_names::global_impl(name) == "flatten"
            && args.len() == 1 =>
        {
            Some(&args[0])
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if crate::builtin_names::global_impl(name) == "flatten" && args.is_empty() => Some(input),
        _ => None,
    }
}

fn sequence_distinct(expr: &Expr) -> Option<&Expr> {
    match &expr.kind {
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && crate::builtin_names::global_impl(name) == "distinct"
            && args.len() == 1 =>
        {
            Some(&args[0])
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if crate::builtin_names::global_impl(name) == "distinct" && args.is_empty() => {
            Some(input)
        }
        _ => None,
    }
}

fn sequence_concat(expr: &Expr) -> Option<(&Expr, &Expr)> {
    match &expr.kind {
        ExprKind::Call {
            name,
            args,
            named_args,
        } if named_args.is_empty()
            && crate::builtin_names::global_impl(name) == "concat"
            && args.len() == 2 =>
        {
            Some((&args[0], &args[1]))
        }
        ExprKind::Pipe {
            input, name, args, ..
        } if crate::builtin_names::global_impl(name) == "concat" && args.len() == 1 => {
            Some((input, &args[0]))
        }
        _ => None,
    }
}

fn emit_sequence_list_value(
    out: &mut String,
    pad: &str,
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<EmittedExpr, Diagnostic> {
    if sequence_transform(expr).is_some() {
        emit_sequence_transform_value(out, pad, expr, env, signatures, temp_counter)
    } else if sequence_chunked(expr).is_some() {
        emit_sequence_chunked_value(out, pad, expr, env, signatures, temp_counter)
    } else if sequence_concat(expr).is_some() {
        emit_sequence_concat_value(out, pad, expr, env, signatures, temp_counter)
    } else if sequence_distinct(expr).is_some() {
        emit_sequence_distinct_value(out, pad, expr, env, signatures, temp_counter)
    } else if sequence_flatten(expr).is_some() {
        emit_sequence_flatten_value(out, pad, expr, env, signatures, temp_counter)
    } else if sequence_sorted(expr).is_some() {
        emit_sequence_sorted_value(out, pad, expr, env, signatures, temp_counter)
    } else {
        emit_expr(expr, env, signatures)
    }
}

fn emit_sequence_chunked_binding(
    out: &mut String,
    pad: &str,
    target: (&str, &Type),
    expr: &Expr,
    env: &mut HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
    temp_counter: &mut usize,
) -> Result<(), Diagnostic> {
    let (name, declared_ty) = target;
    let rewritten = sequence_expr_for_lowering(expr, env, signatures, rewrite_facts);
    let expr = &rewritten;
    let value = emit_sequence_chunked_value(out, pad, expr, env, signatures, temp_counter)?;
    let result_ty = signatures.canonical_type(declared_ty);
    if value.ty != result_ty {
        return Err(diag(
            expr.span,
            "chunked binding type mismatch reached code generation",
        ));
    }
    out.push_str(&format!(
        "{pad}{} {} = {};\n",
        c_type(declared_ty, signatures),
        local_c_name(name),
        value.code
    ));
    env.insert(name.to_string(), result_ty);
    Ok(())
}

fn emit_sequence_chunked_value(
    out: &mut String,
    pad: &str,
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<EmittedExpr, Diagnostic> {
    let (source_expr, size_expr) = sequence_chunked(expr)
        .ok_or_else(|| diag(expr.span, "invalid chunked call reached code generation"))?;
    let source = emit_sequence_list_value(out, pad, source_expr, env, signatures, temp_counter)?;
    let source_ty = signatures.canonical_type(&source.ty);
    let Type::List(_) = &source_ty else {
        return Err(diag(expr.span, "chunked source must be a list"));
    };
    let size = emit_expr(size_expr, env, signatures)?;
    if size.ty != Type::I64 {
        return Err(diag(expr.span, "chunked size must be i64"));
    }
    let result_ty = signatures.canonical_type(&type_of_expr(expr, env, signatures)?);
    if result_ty != Type::List(Box::new(source_ty.clone())) {
        return Err(diag(
            expr.span,
            "chunked result type mismatch reached code generation",
        ));
    }
    let source_name = format!("flux__chunked_source_{}", *temp_counter);
    *temp_counter += 1;
    let size_name = format!("flux__chunked_size_{}", *temp_counter);
    *temp_counter += 1;
    let size_unsigned_name = format!("flux__chunked_size_u_{}", *temp_counter);
    *temp_counter += 1;
    let count_name = format!("flux__chunked_count_{}", *temp_counter);
    *temp_counter += 1;
    let buffer_name = format!("flux__chunked_buffer_{}", *temp_counter);
    *temp_counter += 1;
    let index_name = format!("flux__chunked_index_{}", *temp_counter);
    *temp_counter += 1;
    let start_name = format!("flux__chunked_start_{}", *temp_counter);
    *temp_counter += 1;
    let remaining_name = format!("flux__chunked_remaining_{}", *temp_counter);
    *temp_counter += 1;
    let len_name = format!("flux__chunked_len_{}", *temp_counter);
    *temp_counter += 1;
    let result_name = format!("flux__chunked_result_{}", *temp_counter);
    *temp_counter += 1;
    out.push_str(&format!(
        "{pad}struct flux__list {source_name} = {};\n{pad}int64_t {size_name} = {};\n",
        source.code, size.code
    ));
    out.push_str(&format!(
        "{pad}if ({size_name} <= 0) {{ fputs(\"Flux runtime error: chunked size must be greater than zero\\n\", stderr); abort(); }}\n{pad}size_t {size_unsigned_name} = (size_t){size_name};\n"
    ));
    out.push_str(&format!(
        "{pad}size_t {count_name} = ({source_name}.len / {size_unsigned_name}) + (({source_name}.len % {size_unsigned_name}) != 0);\n{pad}struct flux__list {buffer_name}[{count_name} > 0 ? {count_name} : 1];\n"
    ));
    out.push_str(&format!(
        "{pad}for (size_t {index_name} = 0; {index_name} < {count_name}; ++{index_name}) {{\n{pad}    size_t {start_name} = {index_name} * {size_unsigned_name};\n{pad}    size_t {remaining_name} = {source_name}.len - {start_name};\n{pad}    size_t {len_name} = {remaining_name} < {size_unsigned_name} ? {remaining_name} : {size_unsigned_name};\n{pad}    {buffer_name}[{index_name}] = (struct flux__list){{ .data = (void *)((unsigned char *){source_name}.data + (ptrdiff_t){start_name} * {source_name}.stride), .len = {len_name}, .stride = {source_name}.stride }};\n{pad}}}\n"
    ));
    out.push_str(&format!(
        "{pad}struct flux__list {result_name} = (struct flux__list){{ .data = (void *){buffer_name}, .len = {count_name}, .stride = sizeof(struct flux__list) }};\n"
    ));
    Ok(EmittedExpr {
        code: result_name,
        ty: result_ty,
    })
}

fn sorted_less(left: &str, right: &str, ty: &Type) -> Option<String> {
    match ty {
        Type::I64 | Type::Bool => Some(format!("({left} < {right})")),
        Type::Str => Some(format!("(strcmp({left}, {right}) < 0)")),
        _ => None,
    }
}

fn emit_sequence_sorted_binding(
    out: &mut String,
    pad: &str,
    target: (&str, &Type),
    expr: &Expr,
    env: &mut HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
    temp_counter: &mut usize,
) -> Result<(), Diagnostic> {
    let (name, declared_ty) = target;
    let rewritten = sequence_expr_for_lowering(expr, env, signatures, rewrite_facts);
    let expr = &rewritten;
    let value = emit_sequence_sorted_value(out, pad, expr, env, signatures, temp_counter)?;
    let result_ty = signatures.canonical_type(declared_ty);
    if value.ty != result_ty {
        return Err(diag(
            expr.span,
            "sorted binding type mismatch reached code generation",
        ));
    }
    out.push_str(&format!(
        "{pad}{} {} = {};\n",
        c_type(declared_ty, signatures),
        local_c_name(name),
        value.code
    ));
    env.insert(name.to_string(), result_ty);
    Ok(())
}

fn emit_sequence_sorted_value(
    out: &mut String,
    pad: &str,
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<EmittedExpr, Diagnostic> {
    let source_expr = sequence_sorted(expr)
        .ok_or_else(|| diag(expr.span, "invalid sorted call reached code generation"))?;
    let source = emit_sequence_list_value(out, pad, source_expr, env, signatures, temp_counter)?;
    let result_ty = signatures.canonical_type(&type_of_expr(expr, env, signatures)?);
    let Type::List(element) = &result_ty else {
        return Err(diag(expr.span, "sorted result must have a list type"));
    };
    if signatures.canonical_type(&source.ty) != result_ty {
        return Err(diag(
            expr.span,
            "sorted input type mismatch reached code generation",
        ));
    }
    let element_ty = signatures.canonical_type(element);
    let source_name = format!("flux__sorted_source_{}", *temp_counter);
    *temp_counter += 1;
    let buffer_name = format!("flux__sorted_buffer_{}", *temp_counter);
    *temp_counter += 1;
    let index_name = format!("flux__sorted_index_{}", *temp_counter);
    *temp_counter += 1;
    let key_name = format!("flux__sorted_key_{}", *temp_counter);
    *temp_counter += 1;
    let cursor_name = format!("flux__sorted_cursor_{}", *temp_counter);
    *temp_counter += 1;
    let result_name = format!("flux__sorted_result_{}", *temp_counter);
    *temp_counter += 1;
    let element_c = c_type(element, signatures);
    let less = sorted_less(
        &key_name,
        &format!("{buffer_name}[{cursor_name} - 1]"),
        &element_ty,
    )
    .ok_or_else(|| diag(expr.span, "sorted requires ordered scalar elements"))?;
    out.push_str(&format!(
        "{pad}struct flux__list {source_name} = {};\n",
        source.code
    ));
    out.push_str(&format!(
        "{pad}{element_c} {buffer_name}[{source_name}.len > 0 ? {source_name}.len : 1];\n"
    ));
    out.push_str(&format!(
        "{pad}for (size_t {index_name} = 0; {index_name} < {source_name}.len; ++{index_name}) {{ {buffer_name}[{index_name}] = *(({element_c} *)flux_list_at_unchecked({source_name}, {index_name}, sizeof({element_c}))); }}\n"
    ));
    out.push_str(&format!(
        "{pad}for (size_t {index_name} = 1; {index_name} < {source_name}.len; ++{index_name}) {{\n{pad}    {element_c} {key_name} = {buffer_name}[{index_name}];\n{pad}    size_t {cursor_name} = {index_name};\n{pad}    while ({cursor_name} > 0 && {less}) {{ {buffer_name}[{cursor_name}] = {buffer_name}[{cursor_name} - 1]; --{cursor_name}; }}\n{pad}    {buffer_name}[{cursor_name}] = {key_name};\n{pad}}}\n"
    ));
    out.push_str(&format!(
        "{pad}struct flux__list {result_name} = (struct flux__list){{ .data = (void *){buffer_name}, .len = {source_name}.len, .stride = sizeof({element_c}) }};\n"
    ));
    Ok(EmittedExpr {
        code: result_name,
        ty: result_ty,
    })
}

fn emit_sequence_flatten_binding(
    out: &mut String,
    pad: &str,
    target: (&str, &Type),
    expr: &Expr,
    env: &mut HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
    temp_counter: &mut usize,
) -> Result<(), Diagnostic> {
    let (name, declared_ty) = target;
    let rewritten = sequence_expr_for_lowering(expr, env, signatures, rewrite_facts);
    let expr = &rewritten;
    let value = emit_sequence_flatten_value(out, pad, expr, env, signatures, temp_counter)?;
    let result_ty = signatures.canonical_type(declared_ty);
    if value.ty != result_ty {
        return Err(diag(
            expr.span,
            "flatten binding type mismatch reached code generation",
        ));
    }
    out.push_str(&format!(
        "{pad}{} {} = {};\n",
        c_type(declared_ty, signatures),
        local_c_name(name),
        value.code
    ));
    env.insert(name.to_string(), result_ty);
    Ok(())
}

fn emit_sequence_flatten_value(
    out: &mut String,
    pad: &str,
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<EmittedExpr, Diagnostic> {
    let source_expr = sequence_flatten(expr)
        .ok_or_else(|| diag(expr.span, "invalid flatten call reached code generation"))?;
    let source = emit_sequence_list_value(out, pad, source_expr, env, signatures, temp_counter)?;
    let source_ty = signatures.canonical_type(&source.ty);
    let Type::List(outer_element) = source_ty else {
        return Err(diag(expr.span, "flatten source must be a nested list"));
    };
    let outer_element = signatures.canonical_type(&outer_element);
    let Type::List(inner_element) = outer_element else {
        return Err(diag(expr.span, "flatten source elements must be lists"));
    };
    let result_ty = signatures.canonical_type(&type_of_expr(expr, env, signatures)?);
    if result_ty != Type::List(inner_element.clone()) {
        return Err(diag(
            expr.span,
            "flatten result type mismatch reached code generation",
        ));
    }
    let source_name = format!("flux__flatten_source_{}", *temp_counter);
    *temp_counter += 1;
    let capacity_name = format!("flux__flatten_capacity_{}", *temp_counter);
    *temp_counter += 1;
    let outer_index = format!("flux__flatten_outer_{}", *temp_counter);
    *temp_counter += 1;
    let inner_name = format!("flux__flatten_inner_{}", *temp_counter);
    *temp_counter += 1;
    let buffer_name = format!("flux__flatten_buffer_{}", *temp_counter);
    *temp_counter += 1;
    let count_name = format!("flux__flatten_count_{}", *temp_counter);
    *temp_counter += 1;
    let inner_index = format!("flux__flatten_index_{}", *temp_counter);
    *temp_counter += 1;
    let result_name = format!("flux__flatten_result_{}", *temp_counter);
    *temp_counter += 1;
    let element_c = c_type(&inner_element, signatures);
    out.push_str(&format!(
        "{pad}struct flux__list {source_name} = {};\n{pad}size_t {capacity_name} = 0;\n",
        source.code
    ));
    out.push_str(&format!(
        "{pad}for (size_t {outer_index} = 0; {outer_index} < {source_name}.len; ++{outer_index}) {{ struct flux__list {inner_name} = *((struct flux__list *)flux_list_at_unchecked({source_name}, {outer_index}, sizeof(struct flux__list))); if (SIZE_MAX - {capacity_name} < {inner_name}.len) {{ fputs(\"Flux runtime error: flattened list is too large\\n\", stderr); abort(); }} {capacity_name} += {inner_name}.len; }}\n"
    ));
    out.push_str(&format!(
        "{pad}{element_c} {buffer_name}[{capacity_name} > 0 ? {capacity_name} : 1];\n{pad}size_t {count_name} = 0;\n"
    ));
    out.push_str(&format!(
        "{pad}for (size_t {outer_index} = 0; {outer_index} < {source_name}.len; ++{outer_index}) {{\n{pad}    struct flux__list {inner_name} = *((struct flux__list *)flux_list_at_unchecked({source_name}, {outer_index}, sizeof(struct flux__list)));\n{pad}    for (size_t {inner_index} = 0; {inner_index} < {inner_name}.len; ++{inner_index}) {{ {buffer_name}[{count_name}++] = *(({element_c} *)flux_list_at_unchecked({inner_name}, {inner_index}, sizeof({element_c}))); }}\n{pad}}}\n"
    ));
    out.push_str(&format!(
        "{pad}struct flux__list {result_name} = (struct flux__list){{ .data = (void *){buffer_name}, .len = {count_name}, .stride = sizeof({element_c}) }};\n"
    ));
    Ok(EmittedExpr {
        code: result_name,
        ty: result_ty,
    })
}

fn distinct_equality(left: &str, right: &str, ty: &Type) -> Option<String> {
    match ty {
        Type::I64 | Type::Bool => Some(format!("({left} == {right})")),
        Type::Str => Some(format!("(strcmp({left}, {right}) == 0)")),
        Type::Error => Some(format!("flux_error_eq({left}, {right})")),
        _ => None,
    }
}

fn emit_sequence_distinct_binding(
    out: &mut String,
    pad: &str,
    target: (&str, &Type),
    expr: &Expr,
    env: &mut HashMap<String, Type>,
    signatures: &Signatures,
    rewrite_facts: &CfgRewriteFacts,
    temp_counter: &mut usize,
) -> Result<(), Diagnostic> {
    let (name, declared_ty) = target;
    let rewritten = sequence_expr_for_lowering(expr, env, signatures, rewrite_facts);
    let expr = &rewritten;
    let value = emit_sequence_distinct_value(out, pad, expr, env, signatures, temp_counter)?;
    let result_ty = signatures.canonical_type(declared_ty);
    if value.ty != result_ty {
        return Err(diag(
            expr.span,
            "distinct binding type mismatch reached code generation",
        ));
    }
    out.push_str(&format!(
        "{pad}{} {} = {};\n",
        c_type(declared_ty, signatures),
        local_c_name(name),
        value.code
    ));
    env.insert(name.to_string(), result_ty);
    Ok(())
}

fn emit_sequence_distinct_value(
    out: &mut String,
    pad: &str,
    expr: &Expr,
    env: &HashMap<String, Type>,
    signatures: &Signatures,
    temp_counter: &mut usize,
) -> Result<EmittedExpr, Diagnostic> {
    let source_expr = sequence_distinct(expr)
        .ok_or_else(|| diag(expr.span, "invalid distinct call reached code generation"))?;
    let source = emit_sequence_list_value(out, pad, source_expr, env, signatures, temp_counter)?;
    let result_ty = signatures.canonical_type(&type_of_expr(expr, env, signatures)?);
    let Type::List(element) = &result_ty else {
        return Err(diag(expr.span, "distinct result must have a list type"));
    };
    if signatures.canonical_type(&source.ty) != result_ty {
        return Err(diag(
            expr.span,
            "distinct input type mismatch reached code generation",
        ));
    }
    let element_ty = signatures.canonical_type(element);
    let source_name = format!("flux__distinct_source_{}", *temp_counter);
    *temp_counter += 1;
    let buffer_name = format!("flux__distinct_buffer_{}", *temp_counter);
    *temp_counter += 1;
    let count_name = format!("flux__distinct_count_{}", *temp_counter);
    *temp_counter += 1;
    let index_name = format!("flux__distinct_index_{}", *temp_counter);
    *temp_counter += 1;
    let seen_name = format!("flux__distinct_seen_{}", *temp_counter);
    *temp_counter += 1;
    let item_name = format!("flux__distinct_item_{}", *temp_counter);
    *temp_counter += 1;
    let duplicate_name = format!("flux__distinct_duplicate_{}", *temp_counter);
    *temp_counter += 1;
    let result_name = format!("flux__distinct_result_{}", *temp_counter);
    *temp_counter += 1;
    let element_c = c_type(element, signatures);
    let equality = distinct_equality(
        &format!("{buffer_name}[{seen_name}]"),
        &item_name,
        &element_ty,
    )
    .ok_or_else(|| diag(expr.span, "distinct requires scalar equality"))?;
    out.push_str(&format!(
        "{pad}struct flux__list {source_name} = {};\n",
        source.code
    ));
    out.push_str(&format!(
        "{pad}{element_c} {buffer_name}[{source_name}.len > 0 ? {source_name}.len : 1];\n{pad}size_t {count_name} = 0;\n"
    ));
    out.push_str(&format!(
        "{pad}for (size_t {index_name} = 0; {index_name} < {source_name}.len; ++{index_name}) {{\n"
    ));
    out.push_str(&format!(
        "{pad}    {element_c} {item_name} = *(({element_c} *)flux_list_at_unchecked({source_name}, {index_name}, sizeof({element_c})));\n{pad}    bool {duplicate_name} = false;\n"
    ));
    out.push_str(&format!(
        "{pad}    for (size_t {seen_name} = 0; {seen_name} < {count_name}; ++{seen_name}) {{ if ({equality}) {{ {duplicate_name} = true; break; }} }}\n"
    ));
    out.push_str(&format!(
        "{pad}    if (!{duplicate_name}) {buffer_name}[{count_name}++] = {item_name};\n{pad}}}\n"
    ));
    out.push_str(&format!(
        "{pad}struct flux__list {result_name} = (struct flux__list){{ .data = (void *){buffer_name}, .len = {count_name}, .stride = sizeof({element_c}) }};\n"
    ));
    Ok(EmittedExpr {
        code: result_name,
        ty: result_ty,
    })
}

