    #[test]
    fn typed_ir_aggregate_shapes_drive_set_and_record_rewrite_order() {
        let first = int_expr(1, 1, 3);
        let second = int_expr(2, 1, 6);
        let set_span = SourceSpan::new(1, 1, 8).with_source(SourceId::new(4242));
        let set = Expr {
            line: 1,
            span: set_span,
            kind: ExprKind::Set(vec![first.clone(), second.clone()]),
        };
        let mut set_facts = CfgRewriteFacts::default();
        set_facts.aggregates.insert(
            source_span_key(set_span),
            CfgAggregateShape::Set(vec![
                source_span_key(second.span),
                source_span_key(first.span),
            ]),
        );
        let rewritten_set = substitute_direct_ir_constant_arguments(&set, &set_facts);
        let ExprKind::Set(items) = rewritten_set.kind else {
            panic!("set rewrite should preserve the set expression shape");
        };
        assert!(matches!(items[0].kind, ExprKind::Int(2)));
        assert!(matches!(items[1].kind, ExprKind::Int(1)));

        let left = crate::ast::RecordLiteralField {
            name: Some("left".to_string()),
            name_span: Some(SourceSpan::new(2, 2, 4).with_source(SourceId::new(4242))),
            value: int_expr(10, 2, 8),
        };
        let right = crate::ast::RecordLiteralField {
            name: Some("right".to_string()),
            name_span: Some(SourceSpan::new(2, 12, 5).with_source(SourceId::new(4242))),
            value: int_expr(20, 2, 19),
        };
        let record_span = SourceSpan::new(2, 1, 21).with_source(SourceId::new(4242));
        let record = Expr {
            line: 2,
            span: record_span,
            kind: ExprKind::RecordLiteral {
                fields: vec![left.clone(), right.clone()],
            },
        };
        let mut record_facts = CfgRewriteFacts::default();
        record_facts.aggregates.insert(
            source_span_key(record_span),
            CfgAggregateShape::Record(vec![
                (right.name.clone(), source_span_key(right.value.span)),
                (left.name.clone(), source_span_key(left.value.span)),
            ]),
        );
        let rewritten_record = substitute_direct_ir_constant_arguments(&record, &record_facts);
        let ExprKind::RecordLiteral { fields } = rewritten_record.kind else {
            panic!("record rewrite should preserve the record expression shape");
        };
        assert_eq!(fields[0].name.as_deref(), Some("right"));
        assert_eq!(fields[1].name.as_deref(), Some("left"));
    }

    #[test]
    fn plain_aggregate_shapes_emit_without_checked_ast_children() {
        let source = SourceId::new(4246);
        let left_span = SourceSpan::new(1, 2, 4).with_source(source);
        let right_span = SourceSpan::new(1, 8, 5).with_source(source);
        let set_span = SourceSpan::new(1, 1, 14).with_source(source);
        let env = HashMap::from([
            ("left".to_string(), Type::I64),
            ("right".to_string(), Type::I64),
        ]);
        let mut set_facts = CfgRewriteFacts::default();
        set_facts
            .constants
            .insert(source_span_key(left_span), ConstantValue::I64(1));
        set_facts
            .constants
            .insert(source_span_key(right_span), ConstantValue::I64(2));
        set_facts.aggregates.insert(
            source_span_key(set_span),
            CfgAggregateShape::Set(vec![
                source_span_key(right_span),
                source_span_key(left_span),
            ]),
        );
        let fake_set = Expr {
            line: 1,
            span: set_span,
            kind: ExprKind::Str("checked-ast-set".to_string()),
        };
        let set_code = emit_expr_for_expected_with_cfg_proofs(
            &fake_set,
            &Type::Set(Box::new(Type::I64)),
            &env,
            &Signatures::default(),
            &HashMap::new(),
            &set_facts,
        )
        .expect("set shape should emit from typed IR children");
        assert!(set_code.contains("INT64_C(2)"));
        assert!(set_code.contains("INT64_C(1)"));
        assert!(set_code.find("INT64_C(2)") < set_code.find("INT64_C(1)"));
        assert!(!set_code.contains("checked-ast-set"));

        let record_span = SourceSpan::new(2, 1, 20).with_source(source);
        let mut record_facts = CfgRewriteFacts::default();
        for (span, name) in [(left_span, "left"), (right_span, "right")] {
            record_facts.scalar_exprs.insert(
                source_span_key(span),
                CfgScalarExpr {
                    ty: Type::I64,
                    kind: CfgScalarExprKind::Name(name.to_string()),
                },
            );
        }
        record_facts.aggregates.insert(
            source_span_key(record_span),
            CfgAggregateShape::Record(vec![
                (Some("right".to_string()), source_span_key(right_span)),
                (Some("left".to_string()), source_span_key(left_span)),
            ]),
        );
        let record_ty = Type::Record(vec![
            crate::ast::RecordTypeField {
                name: Some("right".to_string()),
                ty: Type::I64,
            },
            crate::ast::RecordTypeField {
                name: Some("left".to_string()),
                ty: Type::I64,
            },
        ]);
        let fake_record = Expr {
            line: 2,
            span: record_span,
            kind: ExprKind::Str("checked-ast-record".to_string()),
        };
        let record_code = emit_expr_for_expected_with_cfg_proofs(
            &fake_record,
            &record_ty,
            &env,
            &Signatures::default(),
            &HashMap::new(),
            &record_facts,
        )
        .expect("record shape should emit from typed IR children");
        assert!(record_code.contains(&local_c_name("right")));
        assert!(record_code.contains(&local_c_name("left")));
        assert!(!record_code.contains("checked-ast-record"));
    }

    #[test]
    fn flat_typed_ir_aggregate_constants_bypass_ast_child_rebuilds() {
        let first = int_expr(1, 4, 3);
        let second = int_expr(2, 4, 6);
        let list_span = SourceSpan::new(4, 1, 8).with_source(SourceId::new(4242));
        let list = Expr {
            line: 4,
            span: list_span,
            kind: ExprKind::List(vec![first, second]),
        };
        let expected = Type::List(Box::new(Type::I64));
        let mut facts = CfgRewriteFacts::default();
        facts.aggregate_constants.insert(
            source_span_key(list_span),
            CfgAggregateConstant {
                ty: expected.clone(),
                kind: CfgAggregateConstantKind::List(vec![
                    CfgAggregateValue::Scalar(ConstantValue::I64(7)),
                    CfgAggregateValue::Scalar(ConstantValue::I64(8)),
                ]),
            },
        );
        let signatures = Signatures::default();
        let generated = emit_expr_for_expected_with_cfg_proofs(
            &list,
            &expected,
            &HashMap::new(),
            &signatures,
            &HashMap::new(),
            &facts,
        )
        .expect("typed-IR aggregate constant should emit directly");
        assert!(generated.contains("INT64_C(7)"));
        assert!(generated.contains("INT64_C(8)"));
        assert!(!generated.contains("INT64_C(1)"));
        assert!(!generated.contains("INT64_C(2)"));

        let map = CfgAggregateConstant {
            ty: Type::Map(Box::new(Type::I64), Box::new(Type::Bool)),
            kind: CfgAggregateConstantKind::Map(vec![
                (
                    ConstantValue::I64(3),
                    CfgAggregateValue::Scalar(ConstantValue::Bool(true)),
                ),
                (
                    ConstantValue::I64(4),
                    CfgAggregateValue::Scalar(ConstantValue::Bool(false)),
                ),
            ]),
        };
        let rendered = emit_cfg_aggregate_constant(&map, &map.ty, &HashMap::new(), &signatures)
            .expect("flat typed-IR map constant should emit directly");
        assert!(rendered.contains("INT64_C(3)"));
        assert!(rendered.contains("INT64_C(4)"));
        assert!(rendered.contains("true"));
        assert!(rendered.contains("false"));

        let record_ty = Type::Record(vec![
            crate::ast::RecordTypeField {
                name: Some("left".to_string()),
                ty: Type::I64,
            },
            crate::ast::RecordTypeField {
                name: Some("right".to_string()),
                ty: Type::Bool,
            },
        ]);
        let record = CfgAggregateConstant {
            ty: record_ty.clone(),
            kind: CfgAggregateConstantKind::Record(vec![
                (
                    Some("left".to_string()),
                    CfgAggregateValue::Scalar(ConstantValue::I64(9)),
                ),
                (
                    Some("right".to_string()),
                    CfgAggregateValue::Scalar(ConstantValue::Bool(true)),
                ),
            ]),
        };
        let rendered =
            emit_cfg_aggregate_constant(&record, &record_ty, &HashMap::new(), &signatures)
                .expect("flat typed-IR record constant should emit directly");
        assert!(rendered.contains("INT64_C(9)"));
        assert!(rendered.contains("true"));

        let nested_record_ty = Type::Record(vec![crate::ast::RecordTypeField {
            name: Some("value".to_string()),
            ty: Type::I64,
        }]);
        let nested_record = CfgAggregateConstant {
            ty: nested_record_ty.clone(),
            kind: CfgAggregateConstantKind::Record(vec![(
                Some("value".to_string()),
                CfgAggregateValue::Scalar(ConstantValue::I64(42)),
            )]),
        };
        let list_of_records = CfgAggregateConstant {
            ty: Type::List(Box::new(nested_record_ty.clone())),
            kind: CfgAggregateConstantKind::List(vec![CfgAggregateValue::Aggregate(Box::new(
                nested_record,
            ))]),
        };
        let rendered = emit_cfg_aggregate_constant(
            &list_of_records,
            &list_of_records.ty,
            &HashMap::new(),
            &signatures,
        )
        .expect("typed-IR list should render nested Copy record values");
        assert!(rendered.contains("INT64_C(42)"));

        let inner_list_ty = Type::List(Box::new(Type::I64));
        let nested_lists = CfgAggregateConstant {
            ty: Type::List(Box::new(inner_list_ty.clone())),
            kind: CfgAggregateConstantKind::List(vec![CfgAggregateValue::Aggregate(Box::new(
                CfgAggregateConstant {
                    ty: inner_list_ty,
                    kind: CfgAggregateConstantKind::List(vec![
                        CfgAggregateValue::Scalar(ConstantValue::I64(11)),
                        CfgAggregateValue::Scalar(ConstantValue::I64(12)),
                    ]),
                },
            ))]),
        };
        let rendered = emit_cfg_aggregate_constant(
            &nested_lists,
            &nested_lists.ty,
            &HashMap::new(),
            &signatures,
        )
        .expect("typed-IR nested list literals should render recursively");
        assert!(rendered.contains("INT64_C(11)"));
        assert!(rendered.contains("INT64_C(12)"));
        assert!(rendered.contains("sizeof(struct flux__list)"));
    }

    #[test]
    fn nested_copy_aggregate_facts_and_renderer_preserve_typed_ir_tree() {
        let source = r#"
struct Address {
    city: str
    number: i64
}
struct User {
    name: str
    address: Address
}
fn main() -> i64 {
    let input: i64 = 5
    let user: User = User { name: "Ada", address: Address { city: "Auckland", number: input + 2 } }
    print(user.address.number)
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("nested Copy aggregate fixture should typecheck");
        let graph = database
            .control_flow_graph("main")
            .expect("main CFG should exist");
        let user_value = graph
            .values()
            .iter()
            .find(|value| {
                matches!(
                    &value.kind,
                    crate::ir::ControlFlowValueKind::StructLiteral { name, base, .. }
                        if name == "User" && base.is_none()
                )
            })
            .expect("typed IR should retain the User literal");
        let facts = cfg_rewrite_facts(graph);
        let aggregate = facts
            .aggregate_constants
            .get(&source_span_key(user_value.span))
            .expect("nested Copy struct should produce a direct aggregate fact");
        let CfgAggregateConstantKind::Struct { name, fields, .. } = &aggregate.kind else {
            panic!("User fact should remain a typed struct");
        };
        assert_eq!(name, "User");
        let address = fields
            .iter()
            .find(|(field, _)| field == "address")
            .map(|(_, value)| value)
            .expect("User aggregate should retain its address field");
        let CfgAggregateValue::Aggregate(address) = address else {
            panic!("nested Address should remain an aggregate rather than an AST fallback");
        };
        let CfgAggregateConstantKind::Struct { name, fields, .. } = &address.kind else {
            panic!("nested aggregate should retain the Address struct shape");
        };
        assert_eq!(name, "Address");
        assert!(fields.iter().any(|(field, value)| {
            field == "number" && matches!(value, CfgAggregateValue::Scalar(ConstantValue::I64(7)))
        }));

        let inner_ty = Type::Record(vec![crate::ast::RecordTypeField {
            name: Some("value".to_string()),
            ty: Type::I64,
        }]);
        let outer_ty = Type::Record(vec![crate::ast::RecordTypeField {
            name: Some("inner".to_string()),
            ty: inner_ty.clone(),
        }]);
        let nested = CfgAggregateConstant {
            ty: outer_ty.clone(),
            kind: CfgAggregateConstantKind::Record(vec![(
                Some("inner".to_string()),
                CfgAggregateValue::Aggregate(Box::new(CfgAggregateConstant {
                    ty: inner_ty,
                    kind: CfgAggregateConstantKind::Record(vec![(
                        Some("value".to_string()),
                        CfgAggregateValue::Scalar(ConstantValue::I64(42)),
                    )]),
                })),
            )]),
        };
        let rendered = emit_cfg_aggregate_constant(
            &nested,
            &outer_ty,
            &HashMap::new(),
            &Signatures::default(),
        )
        .expect("nested Copy record should render recursively");
        assert!(rendered.contains("INT64_C(42)"));
    }

    #[test]
    fn direct_typed_ir_scalar_structure_bypasses_checked_ast_rebuild() {
        let source = r#"
fn less(value: i64, limit: i64) -> bool {
    return value < limit
}
fn equalInt(left: i64, right: i64) -> bool {
    return left == right
}
fn equalBool(left: bool, right: bool) -> bool {
    return left != right
}
fn equalText(left: str, right: str) -> bool {
    return left == right
}
fn add(left: i64, right: i64) -> i64 {
    return left + right
}
fn subtract(left: i64, right: i64) -> i64 {
    return left - right
}
fn multiply(left: i64, right: i64) -> i64 {
    return left * right
}
fn divide(left: i64, right: i64) -> i64 {
    return left / right
}
fn addIdentity(value: i64) -> i64 {
    return value + 0
}
fn booleanIdentity(value: bool) -> bool {
    return value && true
}
fn nestedArithmetic(left: i64, right: i64, factor: i64) -> i64 {
    return (left + right) * factor
}
fn nestedComparison(left: i64, right: i64, limit: i64) -> bool {
    return left + right < limit
}
fn nestedNegation(value: i64, offset: i64) -> i64 {
    return -(value + offset)
}
fn both(left: bool, right: bool) -> bool {
    return left && right
}
fn either(left: bool, right: bool) -> bool {
    return left || right
}
fn nestedLogic(left: bool, right: bool, other: bool) -> bool {
    return (left && right) || other
}
fn passthrough(value: bool) -> bool {
    return value
}
fn guardedCall(left: bool) -> bool {
    return left && passthrough(left)
}
fn guardedOrCall(left: bool) -> bool {
    return left || passthrough(left)
}
fn negate(value: i64) -> i64 {
    return -value
}
fn main() -> i64 {
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("direct scalar IR fixture should typecheck");

        let less = database
            .control_flow_graph("less")
            .expect("less CFG should exist");
        let comparison = less
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Binary { op: BinOp::Lt, .. }
                )
            })
            .expect("typed IR should retain the dynamic comparison");
        let less_facts = cfg_rewrite_facts(less);
        let fake_comparison = Expr {
            line: comparison.span.line,
            span: comparison.span,
            kind: ExprKind::Bool(false),
        };
        let env = HashMap::from([
            ("value".to_string(), Type::I64),
            ("limit".to_string(), Type::I64),
        ]);
        let emitted = emit_expr_for_expected_with_cfg_proofs(
            &fake_comparison,
            &Type::Bool,
            &env,
            &Signatures::default(),
            &HashMap::new(),
            &less_facts,
        )
        .expect("dynamic comparison should emit from typed IR");
        assert_eq!(
            emitted,
            format!("({} < {})", local_c_name("value"), local_c_name("limit"))
        );

        for (function, op, expected) in [
            (
                "equalInt",
                BinOp::Eq,
                format!("({} == {})", local_c_name("left"), local_c_name("right")),
            ),
            (
                "equalBool",
                BinOp::Ne,
                format!("({} != {})", local_c_name("left"), local_c_name("right")),
            ),
            (
                "equalText",
                BinOp::Eq,
                format!(
                    "(strcmp({}, {}) == 0)",
                    local_c_name("left"),
                    local_c_name("right")
                ),
            ),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("equality CFG should exist");
            let comparison = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Binary {
                            op: actual,
                            ..
                        } if actual == op
                    )
                })
                .expect("typed IR should retain the dynamic equality");
            let facts = cfg_rewrite_facts(graph);
            let fake_comparison = Expr {
                line: comparison.span.line,
                span: comparison.span,
                kind: ExprKind::Bool(false),
            };
            let parameter_ty = match function {
                "equalInt" => Type::I64,
                "equalBool" => Type::Bool,
                "equalText" => Type::Str,
                _ => unreachable!(),
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake_comparison,
                &Type::Bool,
                &HashMap::from([
                    ("left".to_string(), parameter_ty.clone()),
                    ("right".to_string(), parameter_ty),
                ]),
                &Signatures::default(),
                &HashMap::new(),
                &facts,
            )
            .expect("dynamic equality should emit from typed IR");
            assert_eq!(emitted, expected);
        }

        for (function, op, helper) in [
            ("add", BinOp::Add, "flux_add_i64"),
            ("subtract", BinOp::Sub, "flux_sub_i64"),
            ("multiply", BinOp::Mul, "flux_mul_i64"),
            ("divide", BinOp::Div, "flux_div_i64"),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("arithmetic CFG should exist");
            let arithmetic = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Binary {
                            op: actual,
                            ..
                        } if actual == op
                    )
                })
                .expect("typed IR should retain the dynamic arithmetic");
            let facts = cfg_rewrite_facts(graph);
            let fake_arithmetic = Expr {
                line: arithmetic.span.line,
                span: arithmetic.span,
                kind: ExprKind::Int(0),
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake_arithmetic,
                &Type::I64,
                &HashMap::from([
                    ("left".to_string(), Type::I64),
                    ("right".to_string(), Type::I64),
                ]),
                &Signatures::default(),
                &HashMap::new(),
                &facts,
            )
            .expect("dynamic arithmetic should emit from typed IR");
            assert_eq!(
                emitted,
                format!(
                    "{helper}({}, {})",
                    local_c_name("left"),
                    local_c_name("right")
                )
            );
        }

        for (function, expected_ty, parameter_ty, fake_kind) in [
            ("addIdentity", Type::I64, Type::I64, ExprKind::Int(99)),
            (
                "booleanIdentity",
                Type::Bool,
                Type::Bool,
                ExprKind::Bool(false),
            ),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("identity CFG should exist");
            let root = graph
                .values()
                .iter()
                .find(|value| matches!(value.kind, crate::ir::ControlFlowValueKind::Binary { .. }))
                .expect("typed IR should retain the identity expression");
            let facts = cfg_rewrite_facts(graph);
            let fake = Expr {
                line: root.span.line,
                span: root.span,
                kind: fake_kind,
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake,
                &expected_ty,
                &HashMap::from([("value".to_string(), parameter_ty)]),
                &Signatures::default(),
                &HashMap::new(),
                &facts,
            )
            .expect("typed IR identity should emit independently of source AST children");
            assert_eq!(emitted, local_c_name("value"));
        }

        let nested_arithmetic = database
            .control_flow_graph("nestedArithmetic")
            .expect("nested arithmetic CFG should exist");
        let nested_arithmetic_root = nested_arithmetic
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Binary { op: BinOp::Mul, .. }
                )
            })
            .expect("typed IR should retain the nested arithmetic root");
        let nested_arithmetic_facts = cfg_rewrite_facts(nested_arithmetic);
        let fake_nested_arithmetic = Expr {
            line: nested_arithmetic_root.span.line,
            span: nested_arithmetic_root.span,
            kind: ExprKind::Int(0),
        };
        let emitted_nested_arithmetic = emit_expr_for_expected_with_cfg_proofs(
            &fake_nested_arithmetic,
            &Type::I64,
            &HashMap::from([
                ("left".to_string(), Type::I64),
                ("right".to_string(), Type::I64),
                ("factor".to_string(), Type::I64),
            ]),
            &Signatures::default(),
            &HashMap::new(),
            &nested_arithmetic_facts,
        )
        .expect("nested arithmetic should emit from typed IR");
        assert_eq!(
            emitted_nested_arithmetic,
            format!(
                "flux_mul_i64(flux_add_i64({}, {}), {})",
                local_c_name("left"),
                local_c_name("right"),
                local_c_name("factor")
            )
        );

        let nested_comparison = database
            .control_flow_graph("nestedComparison")
            .expect("nested comparison CFG should exist");
        let nested_comparison_root = nested_comparison
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Binary { op: BinOp::Lt, .. }
                )
            })
            .expect("typed IR should retain the nested comparison root");
        let nested_comparison_facts = cfg_rewrite_facts(nested_comparison);
        let fake_nested_comparison = Expr {
            line: nested_comparison_root.span.line,
            span: nested_comparison_root.span,
            kind: ExprKind::Bool(false),
        };
        let emitted_nested_comparison = emit_expr_for_expected_with_cfg_proofs(
            &fake_nested_comparison,
            &Type::Bool,
            &HashMap::from([
                ("left".to_string(), Type::I64),
                ("right".to_string(), Type::I64),
                ("limit".to_string(), Type::I64),
            ]),
            &Signatures::default(),
            &HashMap::new(),
            &nested_comparison_facts,
        )
        .expect("nested comparison should emit from typed IR");
        assert_eq!(
            emitted_nested_comparison,
            format!(
                "(flux_add_i64({}, {}) < {})",
                local_c_name("left"),
                local_c_name("right"),
                local_c_name("limit")
            )
        );

        let nested_negation = database
            .control_flow_graph("nestedNegation")
            .expect("nested negation CFG should exist");
        let nested_negation_root = nested_negation
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Unary {
                        op: UnaryOp::Neg,
                        ..
                    }
                )
            })
            .expect("typed IR should retain the nested negation root");
        let nested_negation_facts = cfg_rewrite_facts(nested_negation);
        let fake_nested_negation = Expr {
            line: nested_negation_root.span.line,
            span: nested_negation_root.span,
            kind: ExprKind::Int(0),
        };
        let emitted_nested_negation = emit_expr_for_expected_with_cfg_proofs(
            &fake_nested_negation,
            &Type::I64,
            &HashMap::from([
                ("value".to_string(), Type::I64),
                ("offset".to_string(), Type::I64),
            ]),
            &Signatures::default(),
            &HashMap::new(),
            &nested_negation_facts,
        )
        .expect("nested negation should emit from typed IR");
        assert_eq!(
            emitted_nested_negation,
            format!(
                "flux_neg_i64(flux_add_i64({}, {}))",
                local_c_name("value"),
                local_c_name("offset")
            )
        );

        for (function, op, expected) in [
            (
                "both",
                BinOp::And,
                format!("({} && {})", local_c_name("left"), local_c_name("right")),
            ),
            (
                "either",
                BinOp::Or,
                format!("({} || {})", local_c_name("left"), local_c_name("right")),
            ),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("short-circuit CFG should exist");
            let boolean = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Binary {
                            op: actual,
                            ..
                        } if actual == op
                    )
                })
                .expect("typed IR should retain the dynamic short-circuit value");
            let facts = cfg_rewrite_facts(graph);
            let fake_boolean = Expr {
                line: boolean.span.line,
                span: boolean.span,
                kind: ExprKind::Bool(false),
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake_boolean,
                &Type::Bool,
                &HashMap::from([
                    ("left".to_string(), Type::Bool),
                    ("right".to_string(), Type::Bool),
                ]),
                &Signatures::default(),
                &HashMap::new(),
                &facts,
            )
            .expect("dynamic short-circuit boolean should emit from typed IR");
            assert_eq!(emitted, expected);
        }

        let nested_logic = database
            .control_flow_graph("nestedLogic")
            .expect("nested logic CFG should exist");
        let nested_logic_root = nested_logic
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Binary { op: BinOp::Or, .. }
                )
            })
            .expect("typed IR should retain the nested logic root");
        let nested_logic_facts = cfg_rewrite_facts(nested_logic);
        let fake_nested_logic = Expr {
            line: nested_logic_root.span.line,
            span: nested_logic_root.span,
            kind: ExprKind::Bool(false),
        };
        let emitted_nested_logic = emit_expr_for_expected_with_cfg_proofs(
            &fake_nested_logic,
            &Type::Bool,
            &HashMap::from([
                ("left".to_string(), Type::Bool),
                ("right".to_string(), Type::Bool),
                ("other".to_string(), Type::Bool),
            ]),
            &Signatures::default(),
            &HashMap::new(),
            &nested_logic_facts,
        )
        .expect("nested short-circuit boolean should emit from typed IR");
        assert_eq!(
            emitted_nested_logic,
            format!(
                "(({} && {}) || {})",
                local_c_name("left"),
                local_c_name("right"),
                local_c_name("other")
            )
        );

        for (function, op, operator) in [
            ("guardedCall", BinOp::And, "&&"),
            ("guardedOrCall", BinOp::Or, "||"),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("guarded call CFG should exist");
            let root = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Binary { op: actual, .. }
                            if actual == op
                    )
                })
                .expect("typed IR should retain the guarded call");
            let facts = cfg_rewrite_facts(graph);
            let scalar = facts
                .scalar_exprs
                .get(&source_span_key(root.span))
                .expect("short-circuit call should be reconstructable from typed IR");
            assert!(matches!(
                scalar.kind,
                CfgScalarExprKind::Binary { op: actual, .. } if actual == op
            ));
            let fake = Expr {
                line: root.span.line,
                span: root.span,
                kind: ExprKind::Str("checked-ast-short-circuit-call".to_string()),
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake,
                &Type::Bool,
                &HashMap::from([("left".to_string(), Type::Bool)]),
                database.signatures(),
                &HashMap::new(),
                &facts,
            )
            .expect("short-circuit call should emit from typed IR");
            assert!(emitted.contains(operator), "{emitted}");
            assert!(
                emitted.contains(&function_c_name("passthrough")),
                "{emitted}"
            );
            assert!(emitted.contains(&local_c_name("left")), "{emitted}");
            assert!(!emitted.contains("checked-ast-short-circuit-call"));
        }

        let negate = database
            .control_flow_graph("negate")
            .expect("negate CFG should exist");
        let negation = negate
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Unary {
                        op: UnaryOp::Neg,
                        ..
                    }
                )
            })
            .expect("typed IR should retain checked negation");
        let negate_facts = cfg_rewrite_facts(negate);
        let fake_negation = Expr {
            line: negation.span.line,
            span: negation.span,
            kind: ExprKind::Int(123),
        };
        let emitted = emit_expr_for_expected_with_cfg_proofs(
            &fake_negation,
            &Type::I64,
            &HashMap::from([("value".to_string(), Type::I64)]),
            &Signatures::default(),
            &HashMap::new(),
            &negate_facts,
        )
        .expect("dynamic negation should emit from typed IR");
        assert_eq!(emitted, format!("flux_neg_i64({})", local_c_name("value")));
    }

    #[test]
    fn checked_i64_cfg_proofs_emit_from_typed_ir_without_ast_operands() {
        let source = r#"
fn cancelAdd(value: i64, delta: i64) -> i64 {
    let added: i64 = value + delta
    return added - delta
}

fn cancelMul(value: i64, factor: i64) -> i64 {
    let product: i64 = value * factor
    return product / factor
}

fn main() -> i64 {
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("checked i64 proof fixture should typecheck");

        for (function, op, expected_proof, env, expected) in [
            (
                "cancelAdd",
                BinOp::Sub,
                CfgCheckedI64Proof::Native,
                HashMap::from([
                    ("value".to_string(), Type::I64),
                    ("delta".to_string(), Type::I64),
                    ("added".to_string(), Type::I64),
                ]),
                format!(
                    "(({}) - ({}))",
                    local_c_name("added"),
                    local_c_name("delta")
                ),
            ),
            (
                "cancelMul",
                BinOp::Div,
                CfgCheckedI64Proof::NonzeroDivision,
                HashMap::from([
                    ("value".to_string(), Type::I64),
                    ("factor".to_string(), Type::I64),
                    ("product".to_string(), Type::I64),
                ]),
                format!(
                    "flux_div_nonzero_i64({}, {})",
                    local_c_name("product"),
                    local_c_name("factor")
                ),
            ),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("checked i64 proof CFG should exist");
            let root = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Binary { op: actual, .. }
                            if actual == op
                    )
                })
                .expect("checked i64 proof root should remain in typed IR");
            let proofs = cfg_checked_i64_proofs(graph);
            assert_eq!(
                proofs.get(&source_span_key(root.span)),
                Some(&expected_proof)
            );
            let facts = cfg_rewrite_facts(graph);
            assert!(matches!(
                facts.scalar_exprs.get(&source_span_key(root.span)),
                Some(CfgScalarExpr {
                    kind: CfgScalarExprKind::Binary { op: actual, .. },
                    ..
                }) if *actual == op
            ));

            let fake = Expr {
                line: root.span.line,
                span: root.span,
                kind: ExprKind::Str("checked-ast-proof-root".to_string()),
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake,
                &Type::I64,
                &env,
                database.signatures(),
                &proofs,
                &facts,
            )
            .expect("checked i64 proof should emit from typed IR");
            assert_eq!(emitted, expected);
            assert!(!emitted.contains("checked-ast-proof-root"));
        }
    }

    #[test]
    fn dynamic_coalescing_lowers_from_typed_ir_without_eager_calls() {
        let source = r#"
fn choose(value: i64?, fallback: i64) -> i64 {
    return value ?? fallback
}

fn fallback() -> i64 {
    return 7
}

fn chooseCall(value: i64?) -> i64 {
    return value ?? fallback()
}

fn main() -> i64 {
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("coalescing IR fixture should typecheck");

        let choose = database
            .control_flow_graph("choose")
            .expect("choose CFG should exist");
        let coalesce = choose
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Binary {
                        op: BinOp::Coalesce,
                        ..
                    }
                )
            })
            .expect("typed IR should retain dynamic coalescing");
        let facts = cfg_rewrite_facts(choose);
        let scalar = facts
            .scalar_exprs
            .get(&source_span_key(coalesce.span))
            .expect("pure dynamic coalescing should be reconstructable from typed IR");
        assert!(matches!(
            scalar.kind,
            CfgScalarExprKind::Binary {
                op: BinOp::Coalesce,
                ..
            }
        ));

        let fake = Expr {
            line: coalesce.span.line,
            span: coalesce.span,
            kind: ExprKind::Int(999),
        };
        let emitted = emit_expr_for_expected_with_cfg_proofs(
            &fake,
            &Type::I64,
            &HashMap::from([
                ("value".to_string(), Type::Optional(Box::new(Type::I64))),
                ("fallback".to_string(), Type::I64),
            ]),
            database.signatures(),
            &HashMap::new(),
            &facts,
        )
        .expect("dynamic coalescing should emit from typed IR");
        assert!(emitted.contains("flux__coalesce_value"));
        assert!(emitted.contains(&local_c_name("value")));
        assert!(emitted.contains(&local_c_name("fallback")));
        assert!(!emitted.contains("999"));

        let choose_call = database
            .control_flow_graph("chooseCall")
            .expect("chooseCall CFG should exist");
        let call_coalesce = choose_call
            .values()
            .iter()
            .find(|value| {
                matches!(
                    value.kind,
                    crate::ir::ControlFlowValueKind::Binary {
                        op: BinOp::Coalesce,
                        ..
                    }
                )
            })
            .expect("typed IR should retain call-backed coalescing");
        let call_facts = cfg_rewrite_facts(choose_call);
        let scalar = call_facts
            .scalar_exprs
            .get(&source_span_key(call_coalesce.span))
            .expect("call-backed coalescing should be reconstructable from typed IR");
        assert!(matches!(
            scalar.kind,
            CfgScalarExprKind::Binary {
                op: BinOp::Coalesce,
                ..
            }
        ));
        let fake = Expr {
            line: call_coalesce.span.line,
            span: call_coalesce.span,
            kind: ExprKind::Int(999),
        };
        let emitted = emit_expr_for_expected_with_cfg_proofs(
            &fake,
            &Type::I64,
            &HashMap::from([("value".to_string(), Type::Optional(Box::new(Type::I64)))]),
            database.signatures(),
            &HashMap::new(),
            &call_facts,
        )
        .expect("call-backed coalescing should emit from typed IR");
        assert!(emitted.contains("flux__coalesce_value"), "{emitted}");
        assert!(emitted.contains(&function_c_name("fallback")), "{emitted}");
        assert!(
            emitted.contains("? flux__coalesce_value.value :"),
            "{emitted}"
        );
        assert!(!emitted.contains("999"));
    }

    #[test]
    fn dynamic_conditional_lowers_from_typed_ir_without_ast_shape() {
        let source = SourceId::new(4251);
        let span = SourceSpan::new(1, 1, 24).with_source(source);
        let facts = CfgRewriteFacts {
            scalar_exprs: HashMap::from([(
                source_span_key(span),
                CfgScalarExpr {
                    ty: Type::I64,
                    kind: CfgScalarExprKind::Conditional {
                        condition: Box::new(CfgScalarExpr {
                            ty: Type::Bool,
                            kind: CfgScalarExprKind::Name("enabled".to_string()),
                        }),
                        then_value: Box::new(CfgScalarExpr {
                            ty: Type::I64,
                            kind: CfgScalarExprKind::Name("value".to_string()),
                        }),
                        else_value: Box::new(CfgScalarExpr {
                            ty: Type::I64,
                            kind: CfgScalarExprKind::Name("fallback".to_string()),
                        }),
                    },
                },
            )]),
            ..CfgRewriteFacts::default()
        };
        let fake = Expr {
            line: span.line,
            span,
            kind: ExprKind::Str("checked-ast-conditional-root".to_string()),
        };
        let emitted = emit_expr_for_expected_with_cfg_proofs(
            &fake,
            &Type::I64,
            &HashMap::from([
                ("enabled".to_string(), Type::Bool),
                ("value".to_string(), Type::I64),
                ("fallback".to_string(), Type::I64),
            ]),
            &Signatures::default(),
            &HashMap::new(),
            &facts,
        )
        .expect("dynamic conditional should emit from typed IR");

        assert!(emitted.contains(&local_c_name("enabled")), "{emitted}");
        assert!(emitted.contains(&local_c_name("value")), "{emitted}");
        assert!(emitted.contains(&local_c_name("fallback")), "{emitted}");
        assert!(emitted.contains('?'), "{emitted}");
        assert!(emitted.contains(':'), "{emitted}");
        assert!(!emitted.contains("checked-ast-conditional-root"));
    }

