    #[test]
    fn direct_typed_ir_field_projections_bypass_checked_ast_rebuild() {
        let source = r#"
struct Point {
    x: i64
}

fn direct(point: Point) -> i64 {
    return point.x
}

fn optional(point: Point?) -> i64? {
    return point?.x
}

fn main() -> i64 {
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("field projection IR fixture should typecheck");

        for (function, expected_optional) in [("direct", false), ("optional", true)] {
            let graph = database
                .control_flow_graph(function)
                .expect("field projection CFG should exist");
            let field = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Field { optional, .. }
                            if optional == expected_optional
                    )
                })
                .expect("typed IR should retain the field projection");
            let facts = cfg_rewrite_facts(graph);
            let fake = Expr {
                line: field.span.line,
                span: field.span,
                kind: ExprKind::Int(0),
            };
            let point_ty = Type::Named("Point".to_string());
            let expected = if expected_optional {
                Type::Optional(Box::new(Type::I64))
            } else {
                Type::I64
            };
            let parameter_ty = if expected_optional {
                Type::Optional(Box::new(point_ty))
            } else {
                point_ty
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake,
                &expected,
                &HashMap::from([("point".to_string(), parameter_ty)]),
                database.signatures(),
                &HashMap::new(),
                &facts,
            )
            .expect("dynamic field projection should emit from typed IR");

            assert!(emitted.contains(&local_c_name("point")));
            assert!(emitted.contains(&field_c_name("x")));
            if expected_optional {
                assert!(emitted.contains("flux__optional_access_value"));
                assert!(emitted.contains(".has_value"));
            } else {
                assert_eq!(
                    emitted,
                    format!("({}).{}", local_c_name("point"), field_c_name("x"))
                );
            }
        }
    }

    #[test]
    fn direct_typed_ir_list_indexes_bypass_checked_ast_rebuild() {
        let source = r#"
fn direct(values: i64[], at: i64) -> i64 {
    return values[at]
}

fn borrowed(values: i64[], at: i64) -> i64 {
    return (borrow values)[at]
}

fn optional(values: i64[]?, at: i64) -> i64? {
    return values?[at]
}

fn temporary(at: i64) -> i64 {
    return [1, 2][at]
}

fn main() -> i64 {
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("list index IR fixture should typecheck");

        for (function, expected_optional, expected_borrow) in [
            ("direct", false, false),
            ("borrowed", false, true),
            ("optional", true, false),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("list index CFG should exist");
            let index = graph
                .values()
                .iter()
                .find(|value| {
                    matches!(
                        value.kind,
                        crate::ir::ControlFlowValueKind::Index { optional, .. }
                            if optional == expected_optional
                    )
                })
                .expect("typed IR should retain the list index");
            let facts = cfg_rewrite_facts(graph);
            assert!(matches!(
                facts.scalar_exprs.get(&source_span_key(index.span)),
                Some(CfgScalarExpr {
                    kind: CfgScalarExprKind::Index { optional, .. },
                    ..
                }) if *optional == expected_optional
            ));
            if expected_borrow {
                assert!(matches!(
                    facts.scalar_exprs.get(&source_span_key(index.span)),
                    Some(CfgScalarExpr {
                        kind: CfgScalarExprKind::Index { base, .. },
                        ..
                    }) if matches!(
                        base.kind,
                        CfgScalarExprKind::Unary {
                            op: UnaryOp::Borrow,
                            ..
                        }
                    )
                ));
            }

            let fake = Expr {
                line: index.span.line,
                span: index.span,
                kind: ExprKind::Str("checked-ast-index".to_string()),
            };
            let list_ty = Type::List(Box::new(Type::I64));
            let expected = if expected_optional {
                Type::Optional(Box::new(Type::I64))
            } else {
                Type::I64
            };
            let values_ty = if expected_optional {
                Type::Optional(Box::new(list_ty))
            } else {
                list_ty
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake,
                &expected,
                &HashMap::from([
                    ("values".to_string(), values_ty),
                    ("at".to_string(), Type::I64),
                ]),
                database.signatures(),
                &HashMap::new(),
                &facts,
            )
            .expect("dynamic list index should emit from typed IR");

            assert!(emitted.contains(&local_c_name("values")));
            assert!(emitted.contains(&local_c_name("at")));
            assert!(emitted.contains("flux_list_at("));
            assert!(!emitted.contains("checked-ast-index"));
            if expected_optional {
                assert!(emitted.contains("flux__optional_index_base.has_value"));
            }
        }

        let temporary = database
            .control_flow_graph("temporary")
            .expect("temporary list index CFG should exist");
        let index = temporary
            .values()
            .iter()
            .find(|value| matches!(value.kind, crate::ir::ControlFlowValueKind::Index { .. }))
            .expect("temporary list index should have typed IR");
        let facts = cfg_rewrite_facts(temporary);
        assert!(matches!(
            facts.scalar_exprs.get(&source_span_key(index.span)),
            Some(CfgScalarExpr {
                kind: CfgScalarExprKind::Index { base, .. },
                ..
            }) if matches!(base.kind, CfgScalarExprKind::Aggregate(_))
        ));
        let fake = Expr {
            line: index.span.line,
            span: index.span,
            kind: ExprKind::Str("checked-ast-temporary-list-index".to_string()),
        };
        let emitted = emit_expr_for_expected_with_cfg_proofs(
            &fake,
            &Type::I64,
            &HashMap::from([("at".to_string(), Type::I64)]),
            database.signatures(),
            &HashMap::new(),
            &facts,
        )
        .expect("temporary list index should emit from typed IR");
        assert!(emitted.contains(&local_c_name("at")));
        assert!(emitted.contains("flux_list_at("));
        assert!(emitted.contains("INT64_C(1)"));
        assert!(emitted.contains("INT64_C(2)"));
        assert!(!emitted.contains("checked-ast-temporary-list-index"));
    }

