    #[test]
    fn async_continuation_plan_selects_direct_await_from_typed_ir() {
        let source = r#"
async fn ping() -> i64 {
    return 41
}

async fn exercise() -> i64 {
    return await ping()
}

async fn main() -> i64 {
    return await exercise()
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("async continuation typed-IR fixture should typecheck");
        let graph = database
            .control_flow_graph("exercise")
            .expect("exercise CFG should exist");
        let facts = cfg_rewrite_facts(graph);

        let mut program = crate::parser::parse_with_source(source, SourceId::UNKNOWN)
            .expect("async continuation fixture should parse");
        let function = program
            .functions
            .iter_mut()
            .find(|function| function.name == "exercise")
            .expect("exercise function should exist");
        let StmtKind::Return(values) = &mut function.body[0].kind else {
            panic!("exercise should contain one return statement");
        };
        let await_expr = &mut values[0];
        let await_span = await_expr.span;
        await_expr.kind = ExprKind::Int(0);

        assert!(direct_await_expr(&function.body[0]).is_none());
        let selected = direct_await_expr_with_facts(&function.body[0], &facts)
            .expect("typed IR should select the direct await despite the fake AST root");
        assert_eq!(selected.span, await_span);
        assert_eq!(direct_await_callee(selected, &facts), Some("ping"));
        let selected = selected.clone();

        let plan = async_continuation_plan(function, database.signatures(), graph)
            .expect("typed IR should keep straight-line continuation lowering eligible");
        assert!(cfg_direct_await_expr(&selected, &plan.cfg_rewrite_facts).is_some());

        let mut out = String::new();
        emit_async_suspend_expr(
            &mut out,
            "",
            &selected,
            selected.span,
            1,
            function,
            &plan,
            &HashMap::new(),
            database.signatures(),
        )
        .expect("typed IR should emit the suspended call despite the fake AST root");
        assert!(out.contains(&async_start_cont_c_name("ping")), "{out}");
    }

    #[test]
    fn async_branch_plan_selects_nested_direct_await_from_typed_ir() {
        let source = r#"
async fn ping(value: i64) -> i64 {
    return value
}

async fn exercise(flag: bool) -> i64 {
    if flag:
        return await ping(41)
    else:
        return 0
}

async fn main() -> i64 {
    return await exercise(true)
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("async branch typed-IR fixture should typecheck");
        let graph = database
            .control_flow_graph("exercise")
            .expect("exercise CFG should exist");
        let facts = cfg_rewrite_facts(graph);

        let mut program = crate::parser::parse_with_source(source, SourceId::UNKNOWN)
            .expect("async branch fixture should parse");
        let function = program
            .functions
            .iter_mut()
            .find(|function| function.name == "exercise")
            .expect("exercise function should exist");
        let StmtKind::If { body, .. } = &mut function.body[0].kind else {
            panic!("exercise should contain one if statement");
        };
        let StmtKind::Return(values) = &mut body[0].kind else {
            panic!("then branch should contain one return statement");
        };
        let await_expr = &mut values[0];
        let await_span = await_expr.span;
        await_expr.kind = ExprKind::Int(0);

        assert!(!stmt_contains_await(&function.body[0]));
        assert!(stmt_contains_await_with_facts(&function.body[0], &facts));
        let plan = async_branch_await_plan(function, &facts)
            .expect("typed IR should keep branch continuation lowering eligible");
        assert_eq!(plan.statement_index, 0);
        assert_eq!(plan.then_await_indices, vec![0]);
        assert!(plan.else_await_indices.is_empty());

        let selected = direct_await_expr_with_facts(
            match &function.body[0].kind {
                StmtKind::If { body, .. } => &body[0],
                _ => unreachable!(),
            },
            &facts,
        )
        .expect("typed IR should recover the nested direct await");
        assert_eq!(selected.span, await_span);
        assert_eq!(direct_await_callee(selected, &facts), Some("ping"));
        async_continuation_plan(function, database.signatures(), graph)
            .expect("typed IR should preserve the full async continuation plan");
    }

    #[test]
    fn direct_typed_ir_await_calls_bypass_checked_ast_rebuild() {
        let source = r#"
async fn delay(value: i64) -> i64 {
    return value
}

async fn adjust(value: i64, *, delta: i64) -> i64 {
    return value + delta
}

async fn directAwait() -> i64 {
    return await delay(4)
}

async fn namedAwait() -> i64 {
    return await adjust(4, delta: 3)
}

fn main() -> i64 {
    return 0
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("await IR fixture should typecheck");

        for (function, callee, expected) in [
            (
                "directAwait",
                "delay",
                format!(
                    "{}({}(INT64_C(4)))",
                    async_await_c_name("delay"),
                    async_start_c_name("delay")
                ),
            ),
            (
                "namedAwait",
                "adjust",
                format!(
                    "{}({}(INT64_C(4), INT64_C(3)))",
                    async_await_c_name("adjust"),
                    async_start_c_name("adjust")
                ),
            ),
        ] {
            let graph = database
                .control_flow_graph(function)
                .expect("await CFG should exist");
            let awaited = graph
                .values()
                .iter()
                .find(|value| matches!(value.kind, crate::ir::ControlFlowValueKind::Await { .. }))
                .expect("typed IR should retain the await boundary");
            let facts = cfg_rewrite_facts(graph);
            let scalar = facts
                .scalar_exprs
                .get(&source_span_key(awaited.span))
                .expect("await should have reconstructable typed-IR facts");
            let CfgScalarExprKind::Await { value } = &scalar.kind else {
                panic!("await root should reconstruct directly from typed IR");
            };
            assert!(matches!(
                &value.kind,
                CfgScalarExprKind::Call {
                    callee: value_callee,
                    ..
                } | CfgScalarExprKind::NamedCall {
                    callee: value_callee,
                    ..
                } if value_callee == callee
            ));

            let fake = Expr {
                line: awaited.span.line,
                span: awaited.span,
                kind: ExprKind::Str("checked-ast-await".to_string()),
            };
            let emitted = emit_expr_for_expected_with_cfg_proofs(
                &fake,
                &Type::I64,
                &HashMap::new(),
                database.signatures(),
                &HashMap::new(),
                &facts,
            )
            .expect("await should emit from typed IR");
            assert_eq!(emitted, expected);
            assert!(!emitted.contains("checked-ast-await"));
        }
    }

    #[test]
    fn dynamic_typed_ir_enum_matches_bypass_checked_ast_rebuild() {
        let source = r#"
enum Choice {
    One(i64)
    None
}

fn choose(choice: Choice, floor: i64) -> i64 {
    return match choice:
        Choice.One(value) if value > floor: value + 1
        Choice.One(< 0): -1
        Choice.One(_): 0
        Choice.None(): 2
}

fn main() -> i64 {
    return choose(Choice.One(3), 1)
}
"#;
        let database = crate::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
            .expect("enum match IR fixture should typecheck");
        let graph = database
            .control_flow_graph("choose")
            .expect("choose CFG should exist");
        let matched = graph
            .values()
            .iter()
            .find(|value| matches!(value.kind, crate::ir::ControlFlowValueKind::Match { .. }))
            .expect("typed IR should retain the match root");
        let facts = cfg_rewrite_facts(graph);
        let match_expr = facts
            .match_exprs
            .get(&source_span_key(matched.span))
            .expect("enum match should have reconstructable typed-IR facts");
        assert_eq!(match_expr.arms.len(), 4);

        let fake = Expr {
            line: matched.span.line,
            span: matched.span,
            kind: ExprKind::Str("checked-ast-match".to_string()),
        };
        let env = HashMap::from([
            ("choice".to_string(), Type::Named("Choice".to_string())),
            ("floor".to_string(), Type::I64),
        ]);
        assert!(match_expr_needs_specialized_lowering(
            &fake,
            &env,
            database.signatures(),
            &facts,
        ));
        let mut out = String::new();
        let mut temp_counter = 0;
        emit_match_expr_into(
            &mut out,
            &fake,
            "flux__typed_match_result",
            1,
            &env,
            database.signatures(),
            &mut temp_counter,
            &HashMap::new(),
            &facts,
        )
        .expect("enum match should emit from typed IR");

        assert!(out.contains("switch ("));
        assert!(out.contains(&local_c_name("choice")));
        assert!(out.contains(&local_c_name("floor")));
        assert!(out.contains(&local_c_name("value")));
        assert!(!out.contains("checked-ast-match"));
    }

